        end

        return Decision
    end

    -- MIND BEGIN (source: tools/assistantbench/mind/*.lua, spliced by tools/assistantbench/splice.py)
    -- Mind composes replies for questions no template covers. It parses a frame (act, topic, register, domain evidence),
    -- runs real skills (string ops, dice, picks, counting) and realises sentences from parts that echo the user's own words.
    -- Its own function so its locals do not count against the 200 of the assistant body.
    Brain.Mind = (function()
        local Mind = {History = {}, Recent = {}, Frame = nil}

        -- ---------------------------------------------------------------- text helpers

        function Mind.Hash(Text: string): number
            local Value: number = 5381
            for i: number = 1, #Text do
                Value = (Value * 33 + Text:byte(i)) % 2147483647
            end

            return Value
        end

        -- Normalised word list of a message: lowercase, curly quotes folded, punctuation dropped, apostrophes kept.
        function Mind.Clean(Text: string): string
            Text = Text:lower():gsub("[\u{2018}\u{2019}]", "'"):gsub("[^%w'%s]", " "):gsub("%s+", " ")
            return (Text:match("^%s*(.-)%s*$"))
        end

        function Mind.WordsOf(Clean: string): {string}
            local List: {string} = {}
            for Word: string in Clean:gmatch("%S+") do
                table.insert(List, Word)
            end

            return List
        end

        function Mind.Trim(Text: string): string
            Text = Text:gsub("^%s+", ""):gsub("%s+$", "")
            Text = Text:gsub("^the ", ""):gsub("^a ", ""):gsub("^an ", ""):gsub("^just ", ""):gsub("^using ", ""):gsub("^use ", ""):gsub("^to ", "")
            return Text
        end

        -- Distinct words of a key string, so a word listed twice does not count twice.
        function Mind.Unique(Keys: string): string
            local Seen, List = {}, {}
            for Word: string in Keys:gmatch("%S+") do
                if not Seen[Word] then
                    Seen[Word] = true
                    table.insert(List, Word)
                end
            end

            return table.concat(List, " ")
        end

        function Mind.Cap(Text: string): string
            return (Text:gsub("^%l", string.upper))
        end

        function Mind.Lower(Text: string): string
            return (Text:gsub("^(%u)(%l)", function(First: string, Second: string): string
                return First:lower() .. Second
