                local Previous: string = (Words[i - 1] or ""):lower()
                local Turned: string? = Pronouns[Low]
                if Low == "i" then
                    Turned = "you"
                elseif Low == "you" then
                    local Inverted: boolean = Previous == "are" or Previous == "were" or Previous == "do" or Previous == "does" or Previous == "did" or Previous == "can" or Previous == "could" or Previous == "would" or Previous == "will" or Previous == "should" or Previous == "have" or Previous == "has" or Previous == "may" or Previous == "might"
