        -- Choose one of the arguments. Avoids repeating something said in the last few replies.
        function Mind.Any(...)
            local Options = {...}
            if #Options == 1 then
                return Options[1]
            end

            for _ = 1, 6 do
                local Choice = Options[math.random(1, #Options)]
                if type(Choice) ~= "string" or not table.find(Mind.Recent, Choice) then
                    if type(Choice) == "string" then
                        table.insert(Mind.Recent, Choice)
                        if #Mind.Recent > 40 then
