        -- Stitch parts into prose: skips empty parts, fixes spacing and capitals after sentence ends.
        function Mind.Join(...): string
            local Parts = {...}
            local Text: string = ""
            for i: number = 1, select("#", ...) do
                local Part = Parts[i]
                if type(Part) == "string" and Part ~= "" then
                    Text = Text == "" and Part or `{Text} {Part}`
                end
            end

            Text = Text:gsub("%s+([,%.!%?;:])", "%1"):gsub("([,;:])([^%s%d])", "%1 %2"):gsub("  +", " ")
