        -- ---------------------------------------------------------------- numbers as words

        local Ones = {[0] = "zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"}
        local Tens = {[2] = "twenty", [3] = "thirty", [4] = "forty", [5] = "fifty", [6] = "sixty", [7] = "seventy", [8] = "eighty", [9] = "ninety"}

        function Mind.NumberWords(Value: number): string
            if Value ~= math.floor(Value) then
                return tostring(Value)
            elseif Value < 0 then
                return `minus {Mind.NumberWords(-Value)}`
            elseif Value < 20 then
                return Ones[Value]
            elseif Value < 100 then
                local Rest: number = Value % 10
                return Tens[math.floor(Value / 10)] .. (Rest > 0 and `-{Ones[Rest]}` or "")
            elseif Value < 1000 then
                local Rest: number = Value % 100
                return `{Ones[math.floor(Value / 100)]} hundred` .. (Rest > 0 and ` {Mind.NumberWords(Rest)}` or "")
            elseif Value < 1000000 then
                local Rest: number = Value % 1000
                return `{Mind.NumberWords(math.floor(Value / 1000))} thousand` .. (Rest > 0 and ` {Mind.NumberWords(Rest)}` or "")
            end

