            end

            local Total: number, Seen: boolean = 0, false
            for Word: string in Text:gsub("%-", " "):gmatch("%a+") do
                if Word == "hundred" and Seen then
                    Total = Total * 100
                elseif Word ~= "and" and WordNumbers[Word] and Word ~= "a" then
                    Total += WordNumbers[Word]
                    Seen = true
                elseif Word ~= "and" then
                    return nil
                end
            end

            return Seen and Total or nil
        end

        -- ---------------------------------------------------------------- syllables (for haiku and rhymes)

        function Mind.Syllables(Word: string): number
            Word = Word:lower():gsub("[^%a]", "")
            if Word == "" then
                return 0
            end

            local Count: number = 0
            local Previous: boolean = false
            for i: number = 1, #Word do
                local Vowel: boolean = Word:sub(i, i):match("[aeiouy]") ~= nil
                if Vowel and not Previous then
                    Count += 1
                end

                Previous = Vowel
            end

            if Word:match("[^aeiouy]e$") and not Word:match("[^aeiouy]le$") and Count > 1 then
                Count -= 1
            end

            if Word:match("[^aeiouy]ed$") and not Word:match("[td]ed$") and Count > 1 then
                Count -= 1
            end

            if Word:match("[^aeiouysxzcg]es$") and not Word:match("[sc]hes$") and not Word:match("[^l]les$") and Count > 1 then
                Count -= 1
            end

            return math.max(Count, 1)
        end

        function Mind.PhraseSyllables(Phrase: string): number
