                ))
            elseif C:match("^forget") or C:match("^start over") or C:match("^reset yourself") or C:match("^clear your memory") then
                table.clear(Mind.History)
                Brain.ResetContext()
                return Mind.Reply(Mind.Any("Done, I dropped everything I was keeping in mind from this chat, so ask me like it's the first time. The old messages stay on screen though, the pencil icon starts a fresh window.", "Okay, memory wiped. I won't remember what we just talked about, though the messages above stay visible until you click the pencil icon for a new chat."))
            elseif C:match("^do you remember") or C:match("^have we talked") or C:match("^do you know me") then
                if Last then
                    return Mind.Reply(Mind.Join(`I remember this chat, the last thing you said was "{Last.Q}".`, Mind.Any("Anything from before this window is gone unless you reopen it from the clock icon.", "Older chats I can only see if you reopen them from the clock icon.")))
                end

                return Mind.Reply(Mind.Any("Not yet, this is the first thing you've said in this chat. I only remember what's been said in the window you have open.", "We haven't talked in this window yet. If we did before, reopen that chat from the clock icon and I'll have it back."))
            end

            if not Last then
                return Mind.Reply(Mind.Any("We haven't said anything yet, you're starting with this message.", "Nothing yet, this is the first message in this chat."))
            end

            if C:match("^why") or C:match("^where did you get") then
                local Why: string = Last.Why or "it looked like the closest thing I knew about"
                return Mind.Reply(Mind.Join(
                    `You asked "{Last.Q}", and I answered because {Why}.`,
                    Mind.Any("If that wasn't what you meant, say it another way and I'll try again.", "Tell me what you were really after and I'll take another run at it.")
                ), {"Let me rephrase"})
            elseif C:match("^what") and (C:match("ask") or C:match("say") or C:match("question") or C:match("last") or C:match("just")) and not C:match("^what was that") then
                return Mind.Reply(Mind.Join(
                    `You asked "{Last.Q}".`,
                    Last.A and #Last.A > 0 and `I answered: {Sentences(Last.A)[1] or Last.A:sub(1, 120)}` or ""
                ))
            end

            local Answer: string = Last.A or ""
            if Answer == "" then
                return Mind.Reply("I don't have anything to repeat yet.")
            elseif Frame.Set.slower or Frame.Set.slowly or Frame.Set.slow then
                local Parts = Sentences(Answer)
                return Mind.Reply(`{Mind.Any("Okay, one piece at a time:", "Slowly then:", "Sure, bit by bit:")}\n\n{table.concat(Parts, "\n")}`)
            elseif Frame.Set.shorter or Frame.Set.shorten or Frame.Set.short or Frame.Set.tldr then
                return Mind.Reply(Sentences(Answer)[1] or Answer)
            elseif Frame.Set.louder or Frame.Set.loud then
                return Mind.Reply(Plain(Answer):upper())
            elseif Frame.Set.simpler or Frame.Set.simple then
                return Mind.Reply(Mind.Join("Simpler version:", Sentences(Answer)[1] or Answer))
            end

            return Mind.Reply(`{Mind.Any("Sure, here it is again:", "Of course:", "Once more:")}\n\n{Answer}`, Last.Chips)
        end)

        -- ---------------------------------------------------------------- text and counting skills

        local function Payload(Frame): string?
            local Text: string? = Frame.Raw:match("^%s*[Ss][Aa][Yy]%s+(.+)$") or Frame.Raw:match("^%s*[Rr]epeat after me[:,]?%s*(.+)$") or Frame.Raw:match("^%s*[Tt]ype%s+(.+)$") or Frame.Raw:match("^%s*[Rr]epeat%s+(.+)$") or Frame.Raw:match("^%s*[Ss]ay the word%s+(.+)$")
            if not Text then
                return nil
            end

            Text = Text:gsub("^[\"'\u{201C}\u{2018}]", ""):gsub("[\"'\u{201D}\u{2019}]$", "")
            return Text
        end

        local function Reverse(Text: string): string
            local Out: {string} = {}
            for _, Code: number in utf8.codes(Text) do
                table.insert(Out, 1, utf8.char(Code))
            end

            return table.concat(Out)
        end

        local function Subject(Frame, Text: string): string
            Text = Text:gsub("^the word ", ""):gsub("^the name ", ""):gsub("^word ", "")
            if Text == "your name" or Text == "you name" or Text == "ur name" then
                return AssistantName
            end

            return Text
        end

        Act("Text", function(Frame): boolean
            local C = Frame.Clean
            local Spoken = Payload(Frame)
            return (Spoken ~= nil and (Frame.Count <= 8 or Frame.Lower:find("repeat after me") ~= nil) and Frame.Evidence < 3 and not C:match("^say what") and not C:match("^say hi to") and not C:match("^say hello to") and not C:match("^say something") and not C:match("^say a "))
                or C:match("backwards?$") ~= nil or C:match("backwards? ") ~= nil or C:match("^reverse ") ~= nil
                or C:match("^how many %a+ in ") ~= nil or C:match("^how many %a+'?s? are in") ~= nil or C:match("^how many letters") ~= nil or C:match("^how many vowels") ~= nil or C:match("^how many consonants") ~= nil or C:match("^how many times does") ~= nil
                or C:match("^what'?s? the %a+ letter") ~= nil or C:match("^count to ") ~= nil or C:match("^count up to ") ~= nil or C:match("^count down from") ~= nil or C:match("^count from ") ~= nil or C:match("palindrome") ~= nil
                or C:match("alphabet") ~= nil or C:match("^uppercase ") ~= nil or C:match("^lowercase ") ~= nil or C:match("^capitalize ") ~= nil or C:match("^shout ") ~= nil
                or C:match("answer in words") ~= nil or C:match("answer in letters") ~= nil or C:match("in words$") ~= nil and C:match("%d") ~= nil
        end, function(Frame)
            local C = Frame.Clean
            local Raw = Frame.Raw

            -- spelling a number out: "what is 2+2 but answer in letters"
            local L = Frame.Lower:gsub("[%?%.!]", "")
            local Sum: string? = L:match("^(.-),? but answer in %a+") or L:match("^(.-),? answer in %a+") or L:match("^(.-) in words$") or L:match("^(.-) in letters$") or L:match("^(.-),? but spell it out")
            if Sum then
                local Value = Brain.Calculate(Sum:gsub("^what'?s? ", ""):gsub("^what is ", ""):gsub("^whats ", ""):gsub("^calculate ", ""))
                if Value then
                    return Mind.Reply(Mind.Join(Mind.Any("In words, that's", "Spelled out:", "In letters it's"), `{Mind.NumberWords(Value)}.`, `(That's {Value % 1 == 0 and string.format("%d", Value) or tostring(Value)}.)`))
                end
            end

            -- spelling or reversing
            local Target: string? = C:match("^spell (.+) backwards?$") or C:match("^say (.+) backwards?$") or C:match("^write (.+) backwards?$") or C:match("^type (.+) backwards?$") or C:match("^reverse (.+)$") or C:match("^(.+) backwards?$")
            if Target then
                local Thing: string = Subject(Frame, Target)
                local Original = Raw:lower():find(Thing:lower(), 1, true) and Raw:sub(Raw:lower():find(Thing:lower(), 1, true)) or Thing
                Thing = Thing == AssistantName and AssistantName or Original:sub(1, #Thing)
                if #Thing > 0 and #Thing <= 80 then
                    local Flipped: string = Reverse(Thing)
                    if Mind.Unsafe(Flipped) or Mind.Unsafe(Thing) then
                        return Mind.Reply("I'll pass on spelling that one. Pick another word and I'll flip it.")
                    end

                    return Mind.Reply(Mind.Join(`Backwards, "{Thing}" is "{Flipped}".`, Mind.Chance(0.4) and Mind.Any("Sounds like a spell.", "Looks alien, doesn't it?", "That one reads better forwards.") or ""))
                end
            end

            -- echo requests
            local Spoken = Payload(Frame)
            if Spoken and (Frame.Count <= 8 or Frame.Lower:find("repeat after me")) and not C:match("backwards?") and not C:match("^say what") then
                if Mind.Unsafe(Spoken) then
                    return Mind.Reply(Mind.Any("I'll skip saying that one, but I'll repeat anything friendlier.", "Not that one, pick something else and I'll say it."))
                end

                local Short: boolean = #Spoken <= 20
                return Mind.Reply(Short and Mind.Any(Spoken, `{Spoken}.`, `"{Spoken}"`) or Mind.Join(`"{Spoken}"`, Mind.Any("There you go.", "Said it.")))
            end

            -- counting letters
            local Letter, Word = C:match("^how many (%a)'?s? are in the word (.+)$")
            if not Letter then
                Letter, Word = C:match("^how many (%a)'?s? are there in (.+)$")
            end
            if not Letter then
                Letter, Word = C:match("^how many (%a)'?s? are in (.+)$")
            end
            if not Letter then
                Letter, Word = C:match("^how many (%a)'?s? in the word (.+)$")
            end
            if not Letter then
                Letter, Word = C:match("^how many (%a)'?s? in (.+)$")
            end
            if not Letter then
                Letter, Word = C:match("^how many times does the letter (%a) appear in (.+)$")
            end
            if not Letter then
                Letter, Word = C:match("^how many times does (%a) appear in (.+)$")
            end

            if Letter and Word then
                Word = Subject(Frame, Word)
                local Count: number = select(2, Word:gsub(Letter, ""))
                local Many: string = Count == 0 and "no" or tostring(Count)
                return Mind.Reply(Mind.Join(
                    `There {Count == 1 and "is" or "are"} {Many} "{Letter}"{Count == 1 and "" or "s"} in "{Word}".`,
                    Count >= 3 and Mind.Any("Tricky one!", "Easy to miscount that.") or ""
                ))
            end

            local Kind, Thing = C:match("^how many (%a+) are in (.+)$")
            if not Kind then
                Kind, Thing = C:match("^how many (%a+) in (.+)$")
            end
            if not Kind then
                Kind, Thing = C:match("^how many (%a+) does (.+) have$")
            end
            if Kind == "letters" or Kind == "vowels" or Kind == "consonants" then
                Thing = Subject(Frame, Thing:gsub("^the word ", ""))
                local Letters: string = Thing:lower():gsub("[^%a]", "")
                local Vowels: number = select(2, Letters:gsub("[aeiou]", ""))
                local Total: number = #Letters
                local Count: number = Kind == "letters" and Total or Kind == "vowels" and Vowels or Total - Vowels
                return Mind.Reply(Mind.Join(`"{Thing}" has {Count} {Count == 1 and Kind:gsub("s$", "") or Kind}.`))
            end

            -- nth letter
            local Ordinal, Subject2 = C:match("^what'?s? the (%a+) letter of (.+)$")
            if not Ordinal then
                Ordinal, Subject2 = C:match("^what'?s? the (%a+) letter in (.+)$")
            end
            if Ordinal and Subject2 then
                local Words = {first = 1, second = 2, third = 3, fourth = 4, fifth = 5, sixth = 6, seventh = 7, eighth = 8, ninth = 9, tenth = 10, last = -1}
                local Position: number? = Words[Ordinal]
                local Thing2: string = Subject(Frame, Subject2:gsub("^the word ", "")):gsub("%s", "")
                if Position and #Thing2 > 0 then
                    local Index2: number = Position < 0 and #Thing2 or Position
                    if Index2 <= #Thing2 then
                        return Mind.Reply(`The {Ordinal} letter of "{Thing2}" is "{Thing2:sub(Index2, Index2)}".`)
                    end

                    return Mind.Reply(`"{Thing2}" only has {#Thing2} letters, so there's no {Ordinal} one.`)
                end
            end

            -- counting out loud
            local From, Direction, Limit = nil, nil, nil
            local A, B = C:match("^count from (%d+) to (%d+)")
            if A then
                From, Limit = tonumber(A), tonumber(B)
            else
                Limit = C:match("^count up to (%d+)") or C:match("^count to (%d+)")
                Limit = Limit and tonumber(Limit) or nil
                if not Limit then
                    local Word2 = C:match("^count to (%a+)") or C:match("^count up to (%a+)")
                    Limit = Word2 and Mind.ParseNumber(Word2)
                end

                if not Limit then
                    local Down = C:match("^count down from (%d+)") or C:match("^count down from (%a+)")
                    Down = Down and Mind.ParseNumber(Down)
                    if Down then
                        From, Limit, Direction = Down, 1, "down"
                    end
                end

                From = From or 1
            end

            if Limit and From then
                if C:find("backwards?") and Direction ~= "down" then
                    From, Limit, Direction = Limit, From, "down"
                end

                if math.abs(Limit - From) > 40 then
                    return Mind.Reply(Mind.Join(`That's a lot of numbers, so I'll stop at forty.`, "Ask for a smaller range and I'll count it all out."))
                end

                local List: {string} = {}
                local Step: number = Limit >= From and 1 or -1
                for Value: number = From, Limit, Step do
                    table.insert(List, tostring(Value))
                end

                return Mind.Reply(Mind.Join(table.concat(List, ", ") .. ".", Mind.Chance(0.5) and Mind.Any("Counted.", "All of them.", "No skips.") or ""))
            end

            if C:find("alphabet") then
                local Letters: {string} = {}
                for Code: number = 97, 122 do
                    table.insert(Letters, string.char(Code))
                end

                if C:find("backwards?") or C:find("reverse") then
                    local Out: {string} = {}
                    for i: number = #Letters, 1, -1 do
                        table.insert(Out, Letters[i])
                    end

                    Letters = Out
                end

                return Mind.Reply(Mind.Join(table.concat(Letters, " ")))
            end

            local Word3: string? = C:match("^is (.+) a palindrome$") or C:match("^is the word (.+) a palindrome$")
            if Word3 then
                local Flat: string = Word3:gsub("%s", "")
                local Same: boolean = Flat == Reverse(Flat) and #Flat > 0
                return Mind.Reply(Same and Mind.Join(`Yes, "{Word3}" reads the same backwards, "{Reverse(Word3)}".`) or Mind.Join(`No, "{Word3}" backwards is "{Reverse(Word3)}".`))
            end

            local Case: string?, Text: string? = Raw:match("^%s*(%a+)%s+(.+)$")
            Case = Case and Case:lower()
            if Text and (Case == "uppercase" or Case == "shout") then
                return Mind.Reply(Text:upper())
            elseif Text and Case == "lowercase" then
                return Mind.Reply(Text:lower())
            elseif Text and Case == "capitalize" then
                return Mind.Reply((Text:gsub("(%a)(%a*)", function(First: string, Rest: string): string
                    return First:upper() .. Rest
                end)))
            end

            return nil
        end)

        -- ---------------------------------------------------------------- chance: coins, dice, numbers

        Act("Chance", function(Frame): boolean
            local C = Frame.Clean
            return C:find("flip a coin", 1, true) ~= nil or C:find("flip coin", 1, true) ~= nil or C:find("toss a coin", 1, true) ~= nil or C:match("^heads or tails") ~= nil or C:match("^coin flip") ~= nil or C:match("^coinflip") ~= nil
                or C:match("^roll a ") ~= nil or C:match("^roll an? ?d%d+") ~= nil or C:match("^roll %d+ ?dice") ~= nil or C:match("^roll the dice") ~= nil or C:match("^roll dice") ~= nil or C:match("^roll d%d+") ~= nil or C:match("^throw a dice") ~= nil
                or C:match("random number") ~= nil or C:match("^pick a number") ~= nil or C:match("^choose a number") ~= nil or C:match("^give me a number") ~= nil or C:match("^number between") ~= nil
        end, function(Frame)
            local C = Frame.Clean
            if C:find("coin") or C:match("^heads or tails") then
                local Heads: boolean = math.random() < 0.5
                local Result: string = Heads and "Heads" or "Tails"
                local WhenHeads, WhenTails = C:match("heads (.-) tails (.+)$")
                if not WhenHeads then
                    WhenTails, WhenHeads = C:match("tails (.-) heads (.+)$")
                end

                local Chosen: string? = Heads and WhenHeads or WhenTails
                if C:match("heads (.-) tails") == nil and C:match("tails (.-) heads") ~= nil then
                    Chosen = Heads and WhenHeads or WhenTails
                end

                if Chosen then
                    Chosen = Chosen:gsub("^i ", ""):gsub("^we ", ""):gsub("^then ", ""):gsub("^use ", "use ")
                    return Mind.Reply(Mind.Join(`*flips* {Result}.`, Mind.Any(`So the coin says {Mind.Turn(Chosen)}.`, `That means {Mind.Turn(Chosen)}, as you set it up.`, `Per your rules, that's {Mind.Turn(Chosen)}.`)))
                end

                return Mind.Reply(Mind.Join(`*flips* {Result}.`, Mind.Chance(0.5) and Mind.Any("Fair and square.", "No weighted coins here.", "Best of three?") or ""), {"Flip again"})
            end

            if C:find("dice") or C:find("die") or C:match("^roll") then
                local Sides: number = tonumber(C:match("d(%d+)")) or 6
                local Count: number = tonumber(C:match("^roll (%d+)")) or 1
                Sides = math.clamp(Sides, 2, 1000)
                Count = math.clamp(Count, 1, 10)
                local Rolls, Total = {}, 0
                for _ = 1, Count do
                    local Value: number = math.random(1, Sides)
                    Total += Value
                    table.insert(Rolls, tostring(Value))
                end

                if Count == 1 then
                    return Mind.Reply(Mind.Join(`Rolled a d{Sides}: {Rolls[1]}.`, Rolls[1] == tostring(Sides) and "Max roll!" or Rolls[1] == "1" and "Ouch, the lowest it gets." or ""), {"Roll again"})
                end

                return Mind.Reply(Mind.Join(`Rolled {Count} d{Sides}: {table.concat(Rolls, ", ")}, that's {Total} in total.`), {"Roll again"})
            end

            local Low, High = C:match("between (%d+) and (%d+)")
            if not Low then
                Low, High = C:match("from (%d+) to (%d+)")
            end
            if not Low then
                Low, High = C:match("(%d+) to (%d+)")
            end
            if not Low then
                Low, High = C:match("(%d+) and (%d+)")
            end
            if not Low then
                Low, High = Frame.Lower:match("(%d+)%s*%-%s*(%d+)")
            end

            local Lo, Hi = tonumber(Low) or 1, tonumber(High) or 100
            if Lo > Hi then
                Lo, Hi = Hi, Lo
            end

            return Mind.Reply(Mind.Join(`Picking between {Lo} and {Hi}: {math.random(Lo, Hi)}.`), {"Pick another"})
        end)
        end

        -- ---------------------------------------------------------------- long-term memory

        -- What the user tells the assistant about themselves outlives the chat window: a small profile saved to the CatVape profiles folder.
        -- It only ever holds what the user said (plus counts of modules they asked about), is clipped and sanitised on the way in and out,
        -- and "forget" removes it. Passwords, tokens and contact details are never stored.
        do
        local Memory = {Loaded = false, Dirty = false, Wiping = false, Batch = {}, Greeted = false, Warned = {}}
        Mind.Memory = Memory
        Memory.File = `{vape.Directory}/profiles/assistantmind.json`

        local Singles = {"platform", "skill", "style", "game", "kit", "goal"}
        local Lists = {Notes = 12, Likes = 8, Dislikes = 8}

        function Memory.Clip(Text: any, Limit: number): string
            if type(Text) ~= "string" then
                return ""
            end

            Text = Text:gsub("[%c<>]", " "):gsub("%s+", " ")
            Text = Text:match("^%s*(.-)%s*$")
            if #Text > Limit then
                local Success, Cut = pcall(utf8.offset, Text, Limit + 1)
                Text = Text:sub(1, Success and Cut and Cut - 1 or Limit)
            end

            return Text
        end

        function Memory.Blank()
            return {Version = 1, Visits = 0, Facts = {}, Notes = {}, Likes = {}, Dislikes = {}, Interest = {}, Sessions = {}, Lessons = {Alias = {}, Fixes = {}}}
        end

        -- Rebuilds a profile from whatever was on disk: unknown fields dropped, wrong types dropped, everything clipped.
        function Memory.Sanitize(Saved: any)
            local Profile = Memory.Blank()
            if type(Saved) ~= "table" then
                return Profile
            end

            local Name: string = Memory.Clip(Saved.Name, 20)
            Profile.Name = Name ~= "" and Name or nil
            Profile.Visits = type(Saved.Visits) == "number" and math.clamp(math.floor(Saved.Visits), 0, 100000) or 0
            Profile.Told = Saved.Told == true
            Profile.Paused = Saved.Paused == true
            for _, Key: string in Singles do
                local Fact = type(Saved.Facts) == "table" and Saved.Facts[Key]
                local Value: string = type(Fact) == "table" and Memory.Clip(Fact.Value, 60) or ""
                if Value ~= "" then
                    Profile.Facts[Key] = {Value = Value, At = type(Fact.At) == "number" and Fact.At or 0}
                end
            end

            for Field: string, Limit: number in Lists do
                for _, Item: any in type(Saved[Field]) == "table" and Saved[Field] or {} do
                    local Text: string = Memory.Clip(type(Item) == "table" and Item.Text or Item, 90)
                    if Text ~= "" and #Profile[Field] < Limit then
                        table.insert(Profile[Field], {Text = Text, At = type(Item) == "table" and type(Item.At) == "number" and Item.At or 0})
                    end
                end
            end

            local Count: number = 0
            for Name2: any, Score: any in type(Saved.Interest) == "table" and Saved.Interest or {} do
                if type(Name2) == "string" and type(Score) == "number" and Score > 0.2 and Count < 60 then
                    Profile.Interest[Memory.Clip(Name2, 40)] = math.min(Score, 50)
                    Count += 1
                end
            end

            for _, Session: any in type(Saved.Sessions) == "table" and Saved.Sessions or {} do
                if type(Session) == "table" and #Profile.Sessions < 10 then
                    local Topics: {string} = {}
                    for _, Topic: any in type(Session.Topics) == "table" and Session.Topics or {} do
                        local Clean: string = Memory.Clip(Topic, 40)
                        if Clean ~= "" and #Topics < 8 then
                            table.insert(Topics, Clean)
                        end
                    end

                    local Open: string = Memory.Clip(Session.Open, 40)
                    table.insert(Profile.Sessions, {At = type(Session.At) == "number" and Session.At or 0, Turns = type(Session.Turns) == "number" and Session.Turns or 0, Topics = Topics, Open = Open ~= "" and Open or nil})
                end
            end

            local Lessons = type(Saved.Lessons) == "table" and Saved.Lessons or {}
            local Total: number = 0
            for Phrase: any, Alias: any in type(Lessons.Alias) == "table" and Lessons.Alias or {} do
                local To: string = type(Alias) == "table" and Memory.Clip(Alias.To, 120) or ""
                if type(Phrase) == "string" and #Phrase <= 120 and To ~= "" and Total < 200 then
                    Profile.Lessons.Alias[Phrase] = {To = To, Hits = type(Alias.Hits) == "number" and math.clamp(Alias.Hits, 1, 1000) or 1}
                    Total += 1
                end
            end

            Total = 0
            for Key: any, Fix: any in type(Lessons.Fixes) == "table" and Lessons.Fixes or {} do
                local Text: string = type(Fix) == "table" and Memory.Clip(Fix.Text, 160) or ""
                if type(Key) == "string" and #Key <= 60 and Text ~= "" and Total < 60 then
                    Profile.Lessons.Fixes[Key] = {Text = Text, Hits = type(Fix.Hits) == "number" and math.clamp(Fix.Hits, 1, 1000) or 1}
                    Total += 1
                end
            end

            local Saved2 = type(Saved.Plan) == "table" and Saved.Plan or nil
            if Saved2 and (Saved2.Style == "legit" or Saved2.Style == "closet" or Saved2.Style == "blatant") and type(Saved2.Names) == "table" then
                local Names: {string} = {}
                local Skipped: {string} = {}
                for _, Name: any in Saved2.Names do
                    local Text: string = Memory.Clip(Name, 40)
                    if Text ~= "" and #Names < 8 then
                        table.insert(Names, Text)
                    end
                end

                for _, Name: any in type(Saved2.Skipped) == "table" and Saved2.Skipped or {} do
                    local Text: string = Memory.Clip(Name, 40)
                    if Text ~= "" and #Skipped < 8 then
                        table.insert(Skipped, Text)
                    end
                end

                if #Names > 0 then
                    Profile.Plan = {Style = Saved2.Style, Names = Names, Skipped = Skipped}
                end
            end

            return Profile
        end

        -- First use in a session: read the file, count the visit, fade old interests and open this session's record.
        function Memory.Ensure()
            if Memory.Loaded then
                return Memory.Profile
            end

            Memory.Loaded = true
            local Saved: any = nil
            if isfile(Memory.File) then
                local Success, Data = pcall(LoadJSON, Memory.File)
                Saved = Success and Data or nil
            end

            local Profile = Memory.Sanitize(Saved)
            Memory.Profile = Profile
            Memory.Previous = Profile.Sessions[#Profile.Sessions]
            Memory.Greeted = false
            Profile.Visits += 1
            for Name: string, Score: number in Profile.Interest do
                Profile.Interest[Name] = Score * 0.9 > 0.2 and Score * 0.9 or nil
            end

            Memory.Session = {At = os.time(), Turns = 0, Topics = {}}
            table.insert(Profile.Sessions, Memory.Session)
            while #Profile.Sessions > 10 do
                table.remove(Profile.Sessions, 1)
            end

            return Profile
        end

        function Memory.Save()
            if not Memory.Dirty or not Memory.Profile then
                return
            end

            Memory.Dirty = false
            local Success = pcall(WriteJSON, Memory.File, Memory.Profile)
            if not Success then
                Memory.Dirty = true
            end
        end

        function Memory.Restart()
            Memory.Loaded, Memory.Dirty, Memory.Wiping, Memory.Welcomed, Memory.Profile, Memory.Previous, Memory.Session, Memory.NameTurn = false, false, false, false, nil, nil, nil, nil
            Memory.Refusal = nil
            table.clear(Memory.Batch)
            table.clear(Memory.Warned)
        end

        function Mind.Restart()
            table.clear(Mind.History)
            Mind.Persona, Mind.Playing = nil, nil
            Memory.Restart()
        end

        -- ---------------------------------------------------------------- reading what the user says about themselves

        local NotNames = Brain.Set("a an the new back here good fine ok okay not so very really just still also now tired bored sorry ready done sure lost stuck confused banned trying playing using on in at for to from with without kind sort sad mad happy angry excited curious wondering looking going getting having making asking glad afraid scared worried sick hungry late early alone online offline legit blatant pro noob beginner mobile pc")
        local NotKits = Brain.Set("a an the kit kits my bedwars legit blatant mobile pc both any different random whatever nothing no one two all many most some every this that it them him her on in")
        local Platforms = {celular = "mobile", movil = "mobile", telefono = "mobile", telefone = "mobile", handy = "mobile", computadora = "PC", ordenador = "PC", ordinateur = "PC", computador = "PC", mobile = "mobile", phone = "mobile", iphone = "mobile", ipad = "mobile", tablet = "mobile", android = "mobile", ios = "mobile", pc = "PC", computer = "PC", laptop = "PC", desktop = "PC", windows = "PC", mac = "PC", console = "console", xbox = "console", playstation = "console", ps4 = "console", ps5 = "console"}
        local Games = {bedwars = "BedWars", ["bed wars"] = "BedWars", soccer = "Illegal Soccer", ["illegal soccer"] = "Illegal Soccer", ["tower of hell"] = "Tower of Hell", toh = "Tower of Hell"}
        local Fillers = Brain.Set("hey hi hello yo sup actually also oh well so ok okay and btw um uh fyi right")
        local Lead = Brain.Set("what how why when where which who whose can could should would will do does did is are am tell show help explain give turn enable disable open set make list find compare toggle bind unbind remove delete add create switch use whats hows check run start stop tweak fix")
        local Secret = Brain.Set("password passwords passcode token tokens cookie cookies roblosecurity secret ssn cvv iban")
        local BeginnerWords = Brain.Set("new newbie noob beginner rookie learning")
        local ExpertWords = Brain.Set("pro expert veteran experienced vet advanced")
        local Adverbs = Brain.Set("a an pretty kinda very quite still really totally completely just fairly mostly")

        local function Normal(Text: string): string
            Text = (" " .. Text .. " "):lower():gsub("[\u{2018}\u{2019}]", "'")
            Text = Text:gsub("%f[%a]i'm%f[%A]", "i am"):gsub("%f[%a]im%f[%A]", "i am"):gsub("%f[%a]i've%f[%A]", "i have"):gsub("%f[%a]ive%f[%A]", "i have")
            Text = Text:gsub("%f[%a]what's%f[%A]", "what is"):gsub("%f[%a]whats%f[%A]", "what is"):gsub("%f[%a]who's%f[%A]", "who is")
            Text = Text:gsub("%f[%a]name's%f[%A]", "name is"):gsub("%f[%a]dont%f[%A]", "do not"):gsub("%f[%a]don't%f[%A]", "do not"):gsub("%f[%a]cant%f[%A]", "can not"):gsub("%f[%a]can't%f[%A]", "can not"):gsub("%f[%a]wont%f[%A]", "will not")
            Text = Text:gsub("n't%f[%A]", " not"):gsub("(%a)'s%f[%A]", "%1 is")
            for _, Short: string in {"didnt", "doesnt", "isnt", "wasnt", "arent", "couldnt", "shouldnt", "wouldnt", "havent", "hasnt", "werent"} do
                Text = Text:gsub(`%f[%a]{Short}%f[%A]`, Short:sub(1, -3) .. " not")
            end

            Text = Text:gsub("[^%w%s]", " "):gsub("%s+", " ")
            return (Text:match("^%s*(.-)%s*$"))
        end

        Memory.Normal = Normal

        local Typos = {recomend = "recommend", reccomend = "recommend", recommed = "recommend", recomended = "recommended", sugest = "suggest", suggets = "suggest", wat = "what", wht = "what", shud = "should", shld = "should", wich = "which", abit = "a bit", ur = "your", u = "you", abt = "about", bout = "about", thx = "thanks", pls = "please", plz = "please"}
        local Openers = Brain.Set("hey hi hello yo sup ok okay so well hmm hm uh um ugh oh ah lol lmao bro dude man btw actually also and but wait alright right please pls plz nvm nevermind now then")

        -- Normal form without the interjections at the front and with the usual typos of key words fixed: "ugh. recomend something for me".
        function Memory.Core(Text: string): string
            local Words: {string} = {}
            local Leading: boolean = true
            for Word: string in Normal(Text):gmatch("%S+") do
                if not (Leading and Openers[Word]) then
                    Leading = false
                    table.insert(Words, Typos[Word] or Word)
                end
            end

            local Trailing = Brain.Set("btw lol lmao haha tho though bro dude man pls please thanks ty thx")
            while #Words > 2 and Trailing[Words[#Words]] do
                table.remove(Words)
            end

            local Tail: string = `{Words[#Words - 1] or ""} {Words[#Words] or ""}`
            if #Words > 3 and (Tail == "i guess" or Tail == "i think" or Tail == "i suppose" or Tail == "i mean" or Tail == "you know") then
                table.remove(Words)
                table.remove(Words)
            end

            return table.concat(Words, " ")
        end

        local Selfish = Brain.Set("my i im i'm we our me ive i've")
        local Starters = Brain.Set("what_should what_do what_can what_would how_do how_can how_should can_you could_you tell_me show_me which_one which_modules which_module")
        for Pair: string in pairs(Starters) do
            Starters[Pair:gsub("_", " ")] = true
        end

        -- Splits a message into clauses and marks the ones that ask or command: "my name is Dee, what does killaura do" is two.
        function Memory.Clauses(Raw: string): {{Raw: string, Ask: boolean}}
            local List = {}
            for Piece: string in Raw:gmatch("[^%.!%?;\n]+[%.!%?;]*") do
                local Marked: boolean = Piece:find("%?") ~= nil
                local Words: {string} = {}
                for Word: string in Piece:gsub("[%.!%?;]+$", ""):gmatch("%S+") do
                    table.insert(Words, Word)
                end

                local Start: number = 1
                for i: number = 2, #Words do
                    local Low: string = Words[i]:lower():gsub("[^%w']", "")
                    local Before: string = Words[i - 1]:lower()
                    local Joined: boolean = Before:sub(-1) == "," or Before == "and" or Before == "then" or Before == "but" or Before == "so"
                    local Starter: string = `{Low} {(Words[i + 1] or ""):lower():gsub("[^%w']", "")}`
                    if not Joined and i - Start >= 2 and Starters[Starter] then
                        table.insert(List, {Raw = table.concat(Words, " ", Start, i - 1), Ask = false})
                        Start = i
                    elseif Joined and Lead[Low] and Low ~= "use" and i - Start >= 2 then
                        local Last: number = (Before == "and" or Before == "then" or Before == "but" or Before == "so") and i - 2 or i - 1
                        table.insert(List, {Raw = (table.concat(Words, " ", Start, Last):gsub(",$", "")), Ask = false})
                        Start = i
                    end
                end

                table.insert(List, {Raw = table.concat(Words, " ", Start), Ask = Marked})
            end

            for _, Clause in List do
                local Lows = Clause.Raw:lower()
                local First: string = Lows:match("^[%w']+") or ""
                while Fillers[First] do
                    Lows = Lows:gsub("^[%w']+[%s,]*", "")
                    First = Lows:match("^[%w']+") or ""
                end

                Clause.Ask = (Clause.Ask and not Selfish[First]) or Lead[First] == true
            end

            return List
        end

        local function WordsOf(C: string): {string}
            local List: {string} = {}
            for Word: string in C:gmatch("%S+") do
                table.insert(List, Word)
            end

            return List
        end

        -- Skips filler words and returns the word after "head", e.g. "i am pretty new" -> "new".
        local function After(C: string, Head: string): string?
            local _, Stop = C:find(`%f[%a]{Head}%f[%A]`)
            if not Stop then
                return nil
            end

            for Word: string in C:sub(Stop + 1):gmatch("%a+") do
                if not Adverbs[Word] then
                    return Word
                end
            end

            return nil
        end

        local function Display(Raw: string, Low: string): string
            local At, End = Raw:lower():find(Low, 1, true)
            local Typed: string = At and Raw:sub(At, End) or Low
            return Typed:match("%u") and Typed or Mind.Cap(Typed)
        end

        local NamePatterns = {"ich bin (%a+)", "me llamo (%a+)", "mi nombre es (%a+)", "je m appelle (%a+)", "me chamo (%a+)", "meu nome e (%a+)", "ich heisse (%a+)", "my name is (%a+)", "name is (%a+)", "call me (%a+)", "you can call me (%a+)", "i go by (%a+)", "people call me (%a+)", "everyone calls me (%a+)", "i am called (%a+)", "i am known as (%a+)"}

        -- Facts about the user in one declarative clause. Returns nil when the clause is not a statement about themselves.
        function Memory.Extract(Raw: string)
            local C: string = Memory.Core(Raw)
            local Found = {}
            local Taken: {[string]: boolean} = {}
            local function Add(Kind: string, Key: string?, Value: string)
                Value = Memory.Clip(Value, Kind == "note" and 90 or 60)
                if Value ~= "" and not Taken[`{Kind}{Key}`] then
                    Taken[`{Kind}{Key}`] = true
                    table.insert(Found, {Kind = Kind, Key = Key, Value = Value})
                end
            end

            if C:find("do not call me", 1, true) then
                return nil
            end

            local Words = WordsOf(C)
            local Person: boolean = (` {C} `):find(" i ") ~= nil or (` {C} `):find(" my ") ~= nil or (` {C} `):find(" me ") ~= nil or #Words <= 8
            if not Person then
                return nil
            end

            for _, Pattern: string in NamePatterns do
                local Name: string? = C:match(Pattern)
                if Name and not NotNames[Name] and #Name >= 2 and #Name <= 20 then
                    Add("name", nil, Display(Raw, Name))
                    break
                end
            end

            if #Found == 0 then
                local Typed: string? = Raw:match("^%s*[Ii]'?[Mm] ([A-Z][a-z]+)%s*[%.!]?%s*$") or Raw:match("^%s*[Ii] [Aa][Mm] ([A-Z][a-z]+)%s*[%.!]?%s*$")
                local Comma: string? = Raw:match("^%s*[Ii]'?[Mm] (%a+)%s*,") or Raw:match("^%s*[Ii] [Aa][Mm] (%a+)%s*,")
                local Plain: string? = Comma and Comma:lower() or C:match("^i am (%a+)$") or C:match("^i am (%a+) and ") or C:match("^i am (%a+) i ") or C:match("^i am (%a+) from ")
                Typed = Typed or Plain
                if Typed and not NotNames[Typed:lower()] and not Platforms[Typed:lower()] and not Games[Typed:lower()] and #Typed >= 2 and #Typed <= 20 then
                    Add("name", nil, Display(Raw, Typed:lower()))
                end
            end

            for i: number, Word: string in Words do
                local Before: string = Words[i - 1] or ""
                local Next: string = Words[i + 1] or ""
                if Platforms[Word] and (#Found >= 1 and #Words <= 8 or i == 1 and #Words <= 6 or Before == "on" or Before == "en" or Before == "no" or Before == "na" or Before == "sur" or Before == "auf" or Before == "using" or Before == "use" or Before == "from" or Before == "play" or Before == "playing" or Next == "player" or Next == "gamer" or (#Words <= 5 and (Before == "my" or Before == "a" or Before == "an"))) then
                    Add("fact", "platform", Platforms[Word])
                end
            end

            local Skill: string? = After(C, "i am") or After(C, "i have")
            if Skill and BeginnerWords[Skill] or C:find("i have just started", 1, true) or C:find("i just started", 1, true) or C:find("first time", 1, true) or C:find("i have never played", 1, true) then
                Add("fact", "skill", "beginner")
            elseif Skill and ExpertWords[Skill] or C:find("i have been playing for years", 1, true) then
                Add("fact", "skill", "experienced")
            end

            local Style: string? = nil
            for j: number, Word: string in Words do
                local Kind: string? = (Word == "legit" or Word == "subtle") and "legit" or Word == "closet" and "closet" or (Word == "blatant" or Word == "rage" or Word == "raging") and "blatant" or nil
                if Kind then
                    local Warm: boolean = false
                    local Cold: boolean = false
                    for k: number = math.max(1, j - 3), j - 1 do
                        local Before: string = Words[k]
                        Warm = Warm or Before == "suppose" or Before == "guess" or Before == "think" or Before == "choose" or Before == "pick" or Before == "style" or Before == "mode" or Before == "right" or Before == "like" or Before == "prefer" or Before == "love" or Before == "want" or Before == "play" or Before == "playing" or Before == "use" or Before == "go" or Before == "mostly" or Before == "only" or Before == "always" or Before == "keep" or Before == "stay" or Before == "pure" or Before == "full"
                        Cold = Cold or Before == "not" or Before == "never" or Before == "dont" or Before == "heard" or Before == "boring" or Before == "hate"
                    end

                    local After: string = Words[j + 1] or ""
                    Warm = Warm or After == "it" or After == "then" or After == "please" or After == "is" or After == "would" or After == "all" or After == "only" or After == "player" or After == "mode" or After == "play" or After == "always" or j == #Words and (#Words <= 3 or #Found >= 1)
                    if Warm and not Cold then
                        Style = Kind
                    end
                end
            end

            for _, Verb: string in {"like", "prefer", "love", "want", "play", "use", "go"} do
                for _, Wanted: string in {"legit", "subtle"} do
                    for _, Form: string in {"%s %s", "%s to %s", "%s to play %s", "%s play %s"} do
                        if C:find(`i {Form:format(Verb, Wanted)}`, 1, true) then
                            Style = "legit"
                        end
                    end
                end

                for _, Form: string in {"%s closet", "%s to closet", "%s to play closet", "%s play closet"} do
                    if C:find(`i {Form:format(Verb)}`, 1, true) then
                        Style = "closet"
                    end
                end

                for _, Wanted: string in {"blatant", "rage", "raging", "obvious"} do
                    for _, Form: string in {"%s %s", "%s to %s", "%s to play %s", "%s play %s"} do
                        if C:find(`i {Form:format(Verb, Wanted)}`, 1, true) then
                            Style = "blatant"
                        end
                    end
                end
            end

            for _, Phrase: string in {"nothing risky", "do not want to get banned", "do not want to be banned", "do not wanna get banned", "do not wanna be banned", "do not wanna get flagged", "do not want bans", "do not want to get flagged", "do not want to look suspicious", "keep it legit", "keep things legit", "keep it safe", "keep things safe", "stay legit", "stay safe", "legit only", "legit all the way", "play it safe", "under the radar", "not too obvious", "legit player", "legit stuff"} do
                if C:find(Phrase, 1, true) then
                    Style = Style or "legit"
                end
            end

            for _, Phrase: string in {"do not care about bans", "do not care if i get banned", "do not care about getting banned", "ban risk does not matter"} do
                if C:find(Phrase, 1, true) then
                    Style = "blatant"
                end
            end

            if Style then
                Add("fact", "style", Style)
            end

            for i: number, Word: string in Words do
                local Before: string = Words[i - 1] or ""
                if (Word == "play" or Word == "playing") and (Before == "i" or Adverbs[Before] or Before == "only" or Before == "usually" or Before == "always" or Before == "normally" or Before == "mainly") then
                    for Size: number = 3, 1, -1 do
                        local Game: string? = Games[table.concat(Words, " ", i + 1, math.min(#Words, i + Size))]
                        if Game then
                            Add("fact", "game", Game)
                            break
                        end
                    end
                end
            end

            for Key: string, Game: string in Games do
                if C:find(`i am here for {Key}`, 1, true) or C:find(`i am a {Key} player`, 1, true) then
                    Add("fact", "game", Game)
                end
            end

            local Kit: string? = C:match("^(%a+) main$") or C:match("^i am an? (%a+) main") or C:match("(%a+) is my main") or C:match("(%a+) is my kit") or C:match("i main (%a+)") or C:match("main kit is (%a+)") or C:match("^kit (%a+)$") or C:match(" kit (%a+)$") or C:match("my kit is (%a+)") or C:match("^kit is (%a+)") or C:match("^main is (%a+)") or C:match("my main is (%a+)") or C:match("my main kit is (%a+)") or C:match("my favou?rite kit is (%a+)") or C:match("my go to kit is (%a+)") or C:match("i always use (%a+) kit") or C:match("i always play (%a+) kit") or C:match("i always use (%a+)$") or C:match("i play (%a+) kit") or C:match("i use (%a+) kit") or C:match("i use the (%a+) kit")
            if Kit and not NotKits[Kit] and #Kit >= 3 and #Kit <= 20 and not Platforms[Kit] and not Games[Kit] and #Mind.Mentions({Kit}) == 0 then
                Add("fact", "kit", Display(Raw, Kit))
            end

            local Goal: string? = C:match("my goal is to (.+)") or C:match("my goal is (.+)") or C:match("i am trying to (.+)") or C:match("i want to get better at (.+)") or C:match("i want to (win more.*)") or C:match("i want to (rank up.*)") or C:match("i want to (improve.*)") or C:match("i want to (get good.*)") or C:match("i want to (climb.*)") or C:match("i want to (stop dying.*)") or C:match("i want to (stop losing.*)")
            local Stated: boolean = C:find("my goal is", 1, true) ~= nil
            if Goal and not Goal:find("but ", 1, true) and not Goal:find("not working", 1, true) and not Goal:find("will not", 1, true) and not Goal:find("can not", 1, true) and (Stated or #Memory.Strong(Mind.Mentions(WordsOf(Goal))) == 0) then
                Add("fact", "goal", Goal)
            end

            local Hate: string? = C:match("i really do not like (.+)") or C:match("i do not really like (.+)") or C:match("i really hate (.+)") or C:match("i hate (.+)") or C:match("i do not like (.+)") or C:match("i dislike (.+)") or C:match("i can not stand (.+)")
            local Love: string? = C:match("i really love (.+)") or C:match("i love (.+)") or C:match("i really like (.+)") or C:match("i like (.+)") or C:match("i enjoy (.+)")
            for _, Cut in {" it ", " because ", " cause ", " coz ", " since ", " lol", " lmao", " tbh", " so "} do
                Hate = Hate and Hate:gsub(Cut .. ".*$", "") or nil
                Love = Love and Love:gsub(Cut .. ".*$", "") or nil
            end

            if Hate and not Style then
                Add("dislike", nil, Hate)
            elseif Love and not Style and not Love:find("%f[%a]you%f[%A]") and not Love:find("%f[%a]your%f[%A]") and not Love:find("%f[%a]this%f[%A]") and not Love:find("%f[%a]that%f[%A]") and not Love:find("%f[%a]it%f[%A]") and not Love:find("chat") and not Love:find("talking") and not Taken["factkit"] and not Taken["factgame"] and not Love:find("^to ") and not Love:find("^how ") and not Love:find("^that ") and not Love:find("^is ") and #Love > 2 then
                Add("like", nil, Love)
            end

            local Never: string? = C:match("do not suggest (.-) to me") or C:match("do not suggest (.-) ever") or C:match("do not suggest (.+)") or C:match("never suggest (.+)") or C:match("do not recommend (.+)") or C:match("never recommend (.+)")
            if Never then
                Never = Never:gsub(" ever$", ""):gsub(" to me$", "")
                Add("dislike", nil, `being suggested {Never}`)
            end

            if #Found == 0 then
                local Hardware: boolean = C:find("%d+%s?gb") ~= nil or C:find("%d+%s?hz") ~= nil or C:find("windows %d") ~= nil or C:find("%f[%a]ram%f[%A]") ~= nil or C:find("%f[%a]rtx%f[%A]") ~= nil or C:find("%f[%a]gtx%f[%A]") ~= nil or C:find("%f[%a]ryzen%f[%A]") ~= nil or C:find("samsung", 1, true) ~= nil
                local Hours: boolean = C:find("i only ever play ", 1, true) ~= nil or C:find("i usually play late", 1, true) ~= nil or C:find("i mostly play late", 1, true) ~= nil or C:find("i play at night", 1, true) ~= nil or C:find("i play after school", 1, true) ~= nil
                if (Hardware and #Words <= 10) or Hours then
                    Add("note", nil, Raw)
                end
            end

            if #Found == 0 then
                return nil
            end

            return Found
        end

        -- Mentions of words that are also ordinary English ("reach the top", "fly") do not make a message about a module.
        function Memory.Strong(Mentions)
            local List = {}
            for _, Mention in Mentions do
                if not Mention.English then
                    table.insert(List, Mention)
                end
            end

            return List
        end

        local Trouble = Brain.Set("keeps broken bug bugs lag lags lagging crash crashes error errors help please but how why when what which fix stuck freezes freezing")

        -- A statement that also asks for something ("i am on mobile and killaura isn't working") must still be answered.
        function Memory.Mixed(Raw: string, TalksAboutModule: boolean?): boolean
            local Flat: string = Normal(Raw)
            local Words = WordsOf(Flat)
            if #Memory.Strong(Mind.Mentions(Words)) > 0 and not TalksAboutModule then
                return true
            end

            for _, Verb: string in {"work", "load", "show", "turn", "start", "open", "run", "respond", "connect", "reel", "hit", "place", "break", "move"} do
                if Flat:find(`not {Verb}`, 1, true) or Flat:find(`n't {Verb}`, 1, true) then
                    return true
                end
            end

            for _, Word: string in Words do
                if Trouble[Word] then
                    return true
                end
            end

            return false
        end

        local Boiler = {}
        for Word: string in ("name called call main mainly play playing played mostly usually always only normally really like love hate prefer enjoy dislike favorite favourite kit goal trying want new beginner noob experienced pro legit blatant safe risky mobile pc phone console device platform remember note keep mind forget bedwars soccer mostly only always stay pure full all day player gamer mode banned ban bans care btw tho though lol pls please like wanna dont flagged suspicious quietly quiet suppose right style think guess choose pick subtle careful carefully"):gmatch("%a+") do
            Boiler[Word] = true
            Boiler[Mind.Stemmed(Word)] = true
        end

        -- How many meaningful words of a clause the extracted facts do not account for; a lot means the clause was about something else.
        function Memory.Leftover(Raw: string, Found): number
            local Used: {[string]: boolean} = {}
            for _, Item in Found do
                for Word: string in Item.Value:lower():gmatch("%a+") do
                    Used[Word] = true
                    Used[Mind.Stemmed(Word)] = true
                end
            end

            local Count: number = 0
            for _, Word: string in Mind.Content(WordsOf(Normal(Raw))) do
                if not Used[Word] and not Boiler[Word] then
                    Count += 1
                end
            end

            return Count
        end

        function Memory.Personal(Raw: string): boolean
            local C: string = ` {Normal(Raw)} `
            return C:find(" i ", 1, true) ~= nil or C:find(" my ", 1, true) ~= nil or C:find(" me ", 1, true) ~= nil
        end

        function Memory.IsSecret(Raw: string): boolean
            local C: string = Normal(Raw)
            for Word: string in C:gmatch("%S+") do
                if Secret[Word] then
                    return true
                end
            end

            return C:find("credit card", 1, true) ~= nil or C:find("phone number", 1, true) ~= nil or C:find("home address", 1, true) ~= nil or C:find("my address", 1, true) ~= nil
                or Raw:find("[%w%.]+@[%w%.]+%.%a%a") ~= nil or Raw:find("%d%d%d%d%d%d%d%d") ~= nil
        end

        -- ---------------------------------------------------------------- storing

        function Memory.Apply(Item)
            local Profile = Memory.Ensure()
            Item.Old = nil
            if Item.Kind == "name" then
                Item.Old = Profile.Name
                Profile.Name = Item.Value
            elseif Item.Kind == "fact" then
                local Old = Profile.Facts[Item.Key]
                Item.Old = Old and Old.Value
                Profile.Facts[Item.Key] = {Value = Item.Value, At = os.time()}
            else
                local Field: string = Item.Kind == "note" and "Notes" or Item.Kind == "like" and "Likes" or "Dislikes"
                local List = Profile[Field]
                for _, Existing in List do
                    if Existing.Text:lower() == Item.Value:lower() then
                        Item.Old = Existing.Text
                        return
                    end
                end

                table.insert(List, {Text = Item.Value, At = os.time()})
                while #List > Lists[Field] do
                    table.remove(List, 1)
                end
            end

            Memory.Dirty = true
        end

        function Memory.Get(Key: string): string?
            local Profile = Memory.Ensure()
            local Fact = Profile.Facts[Key]
            return Fact and Fact.Value or nil
        end

        function Memory.Address(): string?
            return Memory.Ensure().Name
        end

        local Tails = {
            platform = function(Value: string): string?
                return Value == "mobile" and "On mobile you can hold a module for a second to pin a button for it on your screen." or nil
            end,
            skill = function(Value: string): string?
                return Value == "beginner" and "I'll keep the explanations simple and skip the deep settings unless you ask." or nil
            end,
            style = function(Value: string): string?
                return Value == "legit" and "I'll point you at the safer modules and warn you before anything Blatant." or Value == "closet" and "I'll suggest quieter settings and tell you where the risk is." or "Fine by me, I'll still tell you which modules are the most likely to get you flagged."
            end,
            kit = function(Value: string): string?
                return `Ask me to tune things around {Value} whenever you want.`
            end,
            goal = function(Value: string): string?
                return "I'll keep that in mind when you ask what to turn on."
            end
        }

        local Phrases = {
            game = function(Value: string): string return `play {Value}` end,
            platform = function(Value: string): string return `are on {Value}` end,
            kit = function(Value: string): string return `main {Value}` end,
            skill = function(Value: string): string return Value == "beginner" and "are fairly new" or "know your way around" end,
            style = function(Value: string): string return Value == "legit" and "like to keep things legit" or Value == "closet" and "play closet" or "play blatant" end,
            goal = function(Value: string): string return `have a goal: {Value}` end
        }

        local Order = {"game", "platform", "kit", "skill", "style", "goal"}

        -- One sentence saying what was understood, e.g. "you play BedWars, are on mobile and main Isabel".
        function Memory.Understood(Items): string
            local Facts = {}
            local Extra: {string} = {}
            for _, Item in Items do
                if Item.Kind == "fact" then
                    Facts[Item.Key] = Item.Value
                elseif Item.Kind == "like" then
                    table.insert(Extra, `like {Item.Value}`)
                elseif Item.Kind == "dislike" then
                    table.insert(Extra, `don't like {Item.Value}`)
                end
            end

            local Parts: {string} = {}
            for _, Key: string in Order do
                if Facts[Key] then
                    table.insert(Parts, Phrases[Key](Facts[Key]))
                end
            end

            for _, Part: string in Extra do
                table.insert(Parts, Part)
            end

            if #Parts == 0 then
                return ""
            end

            local Text: string = `you {Mind.Oxford(Parts)}`
            return (Text:gsub("^you are ", "you're "))
        end

        function Memory.Ack(Items, Short: boolean)
            local Profile = Memory.Ensure()
            local Greeting: string = ""
            local Understood: string = Memory.Understood(Items)
            local Tail: string? = nil
            for _, Item in Items do
                if Item.Kind == "name" then
                    if Item.Old == Item.Value then
                        Greeting = `Yep, I've got you down as {Item.Value}.`
                    elseif Item.Old then
                        Greeting = Mind.Any(`Got it, {Item.Value} instead of {Item.Old} from now on.`, `Okay, {Item.Value} it is. I dropped {Item.Old}.`)
                    else
                        Greeting = Short and Mind.Any(`Nice to meet you, {Item.Value}.`, `Hi {Item.Value}.`) or Mind.Any(`Nice to meet you, {Item.Value}!`, `Good to meet you, {Item.Value}.`, `Hey {Item.Value}, nice to meet you.`)
                    end
                elseif Item.Kind == "fact" and not Tail and not Short and Item.Old ~= Item.Value and Tails[Item.Key] then
                    Tail = Tails[Item.Key](Item.Value)
                end
            end

            local Remembered: string = ""
            if Understood ~= "" then
                Remembered = Mind.Any(`I'll remember that {Understood}.`, `Noted, {Understood}.`, `Got it, {Understood}.`)
            end

            for _, Item in Items do
                if Item.Kind == "note" then
                    Remembered = Mind.Join(Remembered, Mind.Any(`I'll remember: "{Item.Value}".`, `Saved: "{Item.Value}".`))
                end
            end

            local Privacy: string = ""
            if not Profile.Told and not Short then
                Profile.Told = true
                Memory.Dirty = true
                Privacy = "This stays on your computer, and you can say \"forget everything\" any time."
            end

            return Mind.Join(Greeting, Remembered, Tail or "", Privacy)
        end

        -- Items from a message that is only a statement about the user, or the clauses to keep answering. Returns (reply or nil, rest or nil).
        local Aside = Brain.Set("idk lol haha hm hmm ok okay btw lmao ya yeah yep thanks")
        local Pointers = {["that"] = true, ["this"] = true, ["it"] = true, ["me"] = true, ["all that"] = true, ["all of that"] = true, ["that please"] = true, ["this please"] = true, ["it please"] = true, ["that ok"] = true, ["that okay"] = true, ["all that ok"] = true, ["please"] = true, ["pls"] = true, ["ok"] = true, ["okay"] = true, ["thanks"] = true, ["that pls"] = true}

        local Corrections = {"^no (%a+)$", "^nope (%a+)$", "^no its (%a+)$", "^no it is (%a+)$", "^its (%a+)$", "^it is (%a+)$", "^i meant (%a+)$", "^no i meant (%a+)$", "^no i am (%a+)$", "^no my name is (%a+)$", "^sorry its (%a+)$", "^sorry it is (%a+)$", "^no sorry its (%a+)$", "^oops its (%a+)$", "^no call me (%a+)$"}

        -- "wait no its alexa" right after the name was stored: the name changes, nothing else.
        function Memory.Correction(Raw: string)
            if not Memory.NameTurn or Mind.Dialog.Turn - Memory.NameTurn > 2 then
                return nil
            end

            local C: string = Memory.Core(Raw):gsub("^wait ", ""):gsub("^no wait ", "no ")
            for _, Pattern: string in Corrections do
                local Name: string? = C:match(Pattern)
                if Name and not NotNames[Name] and not Platforms[Name] and #Name >= 2 and #Name <= 20 then
                    return {Kind = "name", Value = Display(Raw, Name)}
                end
            end

            return nil
        end

        function Memory.Observe(Raw: string)
            Brain.Ready()
            if Memory.Ensure().Paused then
                return nil, nil
            end

            if Mind.Dialog.StyleFollow(Raw) then
                return nil, nil
            end

            local Fix = Memory.Correction(Raw)
            if Fix then
                Memory.Apply(Fix)
                Memory.NameTurn = Mind.Dialog.Turn
                table.clear(Memory.Batch)
                table.insert(Memory.Batch, Fix)
                return Memory.Ack({Fix}, false), nil
            end

            local Items, Rest = {}, {}
            local Refused: boolean = false
            local Confirmed: boolean = false
            local Clauses = Memory.Clauses(Raw)
            for _, Clause in Clauses do
                local Text: string = Clause.Raw
                local Courteous: string = Text:gsub("^%s*[Oo][Kk][Aa]?[Yy]?,?%s+", ""):gsub("^%s*[Pp]lease,?%s+", ""):gsub("^%s*[Cc]ould you%s+", ""):gsub("^%s*[Cc]an you%s+", ""):gsub("^%s*[Ww]ill you%s+", ""):gsub("^%s*[Pp]ls%s+", ""):gsub("^%s*[Nn]ote:%s*", "note that ")
                Courteous = Courteous:gsub("^%s*[Gg]reat,?%s+", ""):gsub("^%s*[Cc]ool,?%s+", ""):gsub("^%s*[Nn]ice,?%s+", ""):gsub("^%s*[Pp]erfect,?%s+", ""):gsub("^%s*[Gg]ood,?%s+", "")
                local Asking: boolean = Clause.Ask and Courteous == Text
                local Remembering: string? = nil
                if not Asking then
                    Remembering = Courteous:match("^%s*[Rr]emember that (.+)$") or Courteous:match("^%s*[Rr]emember (.+)$") or Courteous:match("^%s*[Nn]ote that (.+)$") or Courteous:match("^%s*[Kk]eep in mind that (.+)$") or Courteous:match("^%s*[Kk]eep in mind (.+)$") or Courteous:match("^%s*[Dd]on'?t forget that (.+)$") or Courteous:match("^%s*[Dd]on'?t forget (.+)$") or Courteous:match("^%s*[Mm]ake a note that (.+)$")
                end

                if Remembering and Pointers[(Remembering:lower():gsub("[%.!?,]", ""):gsub("^%s+", ""):gsub("%s+$", ""))] then
                    Remembering = nil
                    Courteous = "ok"
                    Asking = true
                    Text = ""
                    Confirmed = true
                end

                local Found = nil
                if not Asking then
                    local Payload: string = Remembering or Text
                    if Memory.IsSecret(Payload) and (Remembering or Memory.Personal(Payload)) then
                        Refused = true
                        Memory.Refusal = Mind.Dialog.Turn
                    else
                        Found = Memory.Extract(Payload)
                        if not Found and Remembering and #Memory.Clip(Remembering, 90) >= 3 then
                            Found = {{Kind = "note", Value = Memory.Clip(Remembering, 90)}}
                        end
                    end
                end

                if Found then
                    local Opinion: boolean = true
                    for _, Item in Found do
                        Opinion = Opinion and (Item.Kind == "like" or Item.Kind == "dislike" or Item.Kind == "fact" and Item.Key == "goal")
                    end

                    local Quiet: boolean = not Remembering and (Memory.Mixed(Text, Opinion) or not Opinion and Memory.Leftover(Text, Found) > 3)
                    for _, Item in Found do
                        Memory.Apply(Item)
                        if Item.Kind == "name" then
                            Memory.NameTurn = Mind.Dialog.Turn
                        end

                        Item.Quiet = Quiet
                        table.insert(Items, Item)
                    end

                    if Quiet then
                        table.insert(Rest, Text)
                    end
                elseif Text ~= "" and (not Refused or Clause.Ask) and not (#Items > 0 and Aside[Memory.Core(Text)]) then
                    table.insert(Rest, Text)
                end
            end

            if #Items == 0 and not Refused and Confirmed and #Rest == 0 then
                local Said: string = #Memory.Batch > 0 and Memory.Understood(Memory.Batch) or ""
                return Said ~= "" and `Yes, I've got it: {Said}.` or "I keep what you tell me automatically. To add a note, say \"remember that ...\".", nil
            end

            if #Items == 0 and not Refused then
                return nil, nil
            end

            table.clear(Memory.Batch)
            for _, Item in Items do
                table.insert(Memory.Batch, Item)
            end

            local Short: boolean = #Rest > 0
            local Spoken = {}
            for _, Item in Items do
                if not Item.Quiet or Item.Kind == "name" then
                    table.insert(Spoken, Item)
                end
            end

            local Ack: string = #Spoken > 0 and Memory.Ack(Spoken, Short) or ""
            if Ack == "" and not Refused and #Rest == 0 then
                Ack = Memory.Ack(Items, false)
            end
            if Refused then
                Ack = Mind.Join(Ack, Mind.Any("I won't keep passwords or private details like that, and it's safer not to type them in any chat.", "Nothing like that gets saved, I don't store passwords, tokens or contact details."))
            end

            return Ack, #Rest > 0 and table.concat(Rest, ". ") or nil
        end
        end

        -- ---------------------------------------------------------------- recalling and forgetting

        do
        local Act = Mind.Act
        local Memory = Mind.Memory
        local Normal = Memory.Normal

        function Memory.Ago(At: number): string
            local Days: number = math.floor((os.time() - At) / 86400)
            return Days < 1 and "earlier today" or Days == 1 and "yesterday" or Days < 7 and "a few days ago" or "a while back"
        end

        function Memory.Known(): number
            local Profile = Memory.Ensure()
            local Count: number = Profile.Name and 1 or 0
            for _ in Profile.Facts do
                Count += 1
            end

            return Count + #Profile.Notes + #Profile.Likes + #Profile.Dislikes
        end

        local function Texts(List): {string}
            local Out: {string} = {}
            for _, Item in List do
                table.insert(Out, Item.Text)
            end

            return Out
        end

        -- Modules the user keeps asking about, strongest first. Learned from the questions, not from anything they said about themselves.
        function Memory.Favourites(Limit: number): {string}
            local Ranked = {}
            for Name: string, Score: number in Memory.Ensure().Interest do
                if Score >= 2 then
                    table.insert(Ranked, {Name = Name, Score = Score})
                end
            end

            table.sort(Ranked, function(a, b)
                return a.Score > b.Score or a.Score == b.Score and a.Name < b.Name
            end)

            local Names: {string} = {}
            for i: number = 1, math.min(Limit, #Ranked) do
                table.insert(Names, Ranked[i].Name)
            end

            return Names
        end

        function Memory.Summary(): string
            local Profile = Memory.Ensure()
            local F = Profile.Facts
            local Lines: {string} = {}
            if Profile.Name then
                table.insert(Lines, `Your name is {Profile.Name}.`)
            end

            local Parts: {string} = {}
            if F.game then
                table.insert(Parts, `play {F.game.Value}` .. (F.platform and ` on {F.platform.Value}` or ""))
            elseif F.platform then
                table.insert(Parts, `are on {F.platform.Value}`)
            end

            if F.kit then
                table.insert(Parts, `main {F.kit.Value}`)
            end

            if #Parts > 0 then
                table.insert(Lines, `You {Mind.Oxford(Parts)}.`)
            end

            if F.skill then
                table.insert(Lines, F.skill.Value == "beginner" and "You told me you're fairly new." or "You told me you know your way around.")
            end

            if F.style then
                table.insert(Lines, F.style.Value == "legit" and "You like to keep things legit." or F.style.Value == "closet" and "You play closet." or "You play blatant.")
            end

            if F.goal then
                table.insert(Lines, `Your goal: {F.goal.Value}.`)
            end

            if #Profile.Likes > 0 then
                table.insert(Lines, `You like {Mind.Oxford(Texts(Profile.Likes))}.`)
            end

            if #Profile.Dislikes > 0 then
                table.insert(Lines, `You don't like {Mind.Oxford(Texts(Profile.Dislikes))}.`)
            end

            if #Profile.Notes > 0 then
                local Quoted: {string} = {}
                for _, Note in Profile.Notes do
                    table.insert(Quoted, `"{Note.Text}"`)
                end

                table.insert(Lines, `You asked me to remember: {table.concat(Quoted, "; ")}.`)
            end

            local Favourites = Memory.Favourites(3)
            if #Favourites > 0 then
                table.insert(Lines, `From what you've asked, I'd say you care most about {Mind.Oxford(Favourites)}.`)
            end

            return table.concat(Lines, " ")
        end

        local NothingYet = {
            "Not much yet, we've barely met. Tell me your name, what you play and what you play on, and I'll remember it next time.",
            "Nothing yet. Say something like \"I'm Alex, I play BedWars on mobile\" and I'll keep it for next time.",
            "I don't know anything about you yet. Tell me your name or what you like to play and I'll remember it."
        }

        local function Asked(N: string, Patterns: {string}): boolean
            for _, Pattern: string in Patterns do
                if N:find(Pattern) then
                    return true
                end
            end

            return false
        end

        local Properties = {
            platform = {"platform", "device", "system", "phone"},
            kit = {"kit", "main"},
            game = {"game"},
            style = {"style", "playstyle", "play style"},
            skill = {"skill", "level"},
            goal = {"goal", "goals"}
        }

        local ProfileAsks = {"what do you know", "what have you learned", "what do you remember", "tell me about myself", "what did i tell you", "show my profile", "show me my profile", "what is in your memory", "what is in my profile", "what do you have on me", "did i tell you", "do you know anything about me", "what else do you know", "what else have i told you", "what have i told you", "remember anything", "know anything", "you have noted", "you have saved", "you have stored", "you noted", "about me so far", "know about me", "you have on me"}
        local NoteAsks = {"what notes", "my notes", "any notes", "what did i ask you to remember", "what did i say to remember", "what did i tell you to remember", "what did i ask you to note"}
        local EarlierAsks = {"what did we talk", "what did we discuss", "what did we do", "what did we cover", "what did we work on", "what did i ask you last", "what did i ask you about last", "what did i ask you yesterday", "what did i ask you before", "what did i ask you earlier", "where did we leave off", "where were we", "what were we working on", "what were we doing", "continue where we left off", "pick up where we left off", "last time we", "what did i ask last time", "from before", "was i asking", "what i asked before", "what did i ask last"}
        local KnowsAsks = {"do you remember me", "do you know me", "remember me", "have we talked", "have we spoken", "have we met", "have we chatted", "its me again", "it is me again", "i am back", "im back", "back again", "do you recognize me", "recognise me", "forgot me", "forgotten me"}
        local NameAsks = {"say my name", "tell me my name", "what is my name", "who am i", "my name again", "know my name", "remember my name", "what do you call me", "what should you call me", "do you know who i am", "what was my name", "forgot my name", "what is my name again"}

        local ConfirmAsks = {"did you save", "did you store", "did u save", "did you actually", "did u actually", "did it save", "is it saved", "prove it", "did you delete", "did you forget", "did you do it", "did you remember it", "is it gone", "is that saved"}
        local ShortKeys = {notes = "notes", note = "notes", name = "name", kit = "kit", main = "kit", platform = "platform", device = "platform", style = "style", playstyle = "style", goal = "goal", goals = "goal", skill = "skill", game = "game"}

        local function Has(N: string, Patterns: {string}): boolean
            local Padded: string = ` {N}`
            for _, Pattern: string in Patterns do
                if Padded:find(` {Pattern}`, 1, true) then
                    return true
                end
            end

            return false
        end

        local function Whole(N: string, Phrase: string): boolean
            return (` {N} `):find(` {Phrase} `, 1, true) ~= nil
        end

        -- Which question about the saved profile this is: ("name" | "profile" | "notes" | "about" | "earlier" | "knows" | "single", detail).
        local function Classify(Frame)
            local N: string = Memory.Core(Frame.Raw)
            if N:find("^delete ") or N:find("^forget ") or N:find("^erase ") or N:find("^clear ") or N:find("^wipe ") or N:find("^remove ") then
                return nil
            end

            local Alone: string = N:gsub("^and ", ""):gsub("^my ", ""):gsub("^play style$", "playstyle")
            local Short: string? = Alone:match("^(%a+)$") or Alone:match("^what (%a+)$") or Alone:match("^which (%a+)$") or Alone:match("^what (%a+) do i have$")
            if Short and ShortKeys[Short] and (Frame.Raw:find("%?") or N:find("^my ") or N:find("^and ") or N:find("^what ") or N:find("^which ")) then
                return Short == "name" and "name" or ShortKeys[Short] == "notes" and "notes" or "single", ShortKeys[Short]
            end

            if Has(N, ConfirmAsks) then
                return "confirm"
            end

            local Who: string? = N:match("who is (%a+)") or N:match("do you still remember (%a+)") or N:match("do you remember (%a+)") or N:match("what do you know about (%a+)")
            if Who and not (Who == "me" or Who == "my" or Who == "you" or Who == "i" or Who == "it" or Who == "that" or Who == "this" or Who == "what" or Who == "everything" or Who == "anything" or Who == "the" or Who == "about" or Who == "us" or Who == "whats") then
                return "about", Who
            end

            local Topic: string? = N:match("did i tell you about (.+)$") or N:match("did i say anything about (.+)$") or N:match("did i mention (.+)$") or N:match("did i say something about (.+)$") or N:match("did i tell you anything about (.+)$")
            if Topic then
                return "about", Topic
            elseif Has(N, NoteAsks) then
                return "notes"
            elseif Has(N, NameAsks) then
                return "name"
            end

            local Questioning: boolean = Whole(N, "what") or Whole(N, "which") or Whole(N, "do you") or Whole(N, "did you") or Whole(N, "still") or Whole(N, "remember") or Whole(N, "am i")
            if Questioning then
                for Key: string, Words in Properties do
                    for _, Word: string in Words do
                        if Whole(N, `my {Word}`) or Whole(N, `{Word} did i`) or Whole(N, `{Word} do i`) or Whole(N, `{Word} am i`) or Whole(N, `{Word} was it`) then
                            return "single", Key
                        end
                    end
                end

                if N:find("am i new", 1, true) or N:find("am i a beginner", 1, true) then
                    return "single", "skill"
                elseif N:find("what do i play on", 1, true) or N:find("what am i on", 1, true) or N:find("what am i using", 1, true) then
                    return "single", "platform"
                elseif N:find("what do i main", 1, true) or N:find("who do i main", 1, true) then
                    return "single", "kit"
                end
            end

            if Has(N, EarlierAsks) then
                return "earlier"
            elseif Has(N, KnowsAsks) then
                return "knows"
            elseif Has(N, ProfileAsks) then
                return "profile"
            end

            return nil
        end

        local function Say(Key: string, Value: string?): string
            if not Value then
                return Mind.Any("You haven't told me yet. Want to?", "I don't have that one yet, you haven't said.")
            elseif Key == "platform" then
                return `You're on {Value}.`
            elseif Key == "kit" then
                return `You main {Value}.`
            elseif Key == "game" then
                return `You play {Value}.`
            elseif Key == "style" then
                return Value == "legit" and "You like to keep things legit." or Value == "closet" and "You play closet." or "You play blatant."
            elseif Key == "skill" then
                return Value == "beginner" and "You told me you're fairly new." or "You told me you know your way around."
            end

            return `Your goal: {Value}.`
        end

        Act("Recall", function(Frame): boolean
            return Classify(Frame) ~= nil
        end, function(Frame)
            local Kind: string, Detail: string? = Classify(Frame)
            local Profile = Memory.Ensure()
            local Last = Memory.Previous
            if Kind == "name" then
                if Profile.Name then
                    return Mind.Reply(Mind.Any(`You're {Profile.Name}.`, `Your name is {Profile.Name}.`, `I've got you down as {Profile.Name}.`))
                end

                return Mind.Reply(Mind.Any("You haven't told me your name yet. What should I call you?", "I don't know it yet, you haven't said. What do you go by?"))
            elseif Kind == "single" then
                local Fact = Profile.Facts[Detail]
                return Mind.Reply(Say(Detail, Fact and Fact.Value))
            elseif Kind == "confirm" then
                local Here = Mind.History[#Mind.History]
                if Memory.Refusal and Mind.Dialog.Turn - Memory.Refusal <= 2 then
                    return Mind.Reply("No, I didn't keep it. I never store passwords, tokens or contact details.")
                elseif Here and Here.Act == "Forget" then
                    return Mind.Reply(Memory.Known() == 0 and "Yes, it's gone. I have nothing saved about you now." or `Yes. I still have {Memory.Known()} other thing{Memory.Known() == 1 and "" or "s"} about you, say "forget everything" to clear it all.`)
                elseif Here and Here.Act == "Remember" and #Memory.Batch > 0 then
                    local Said: string = Memory.Understood(Memory.Batch)
                    return Mind.Reply(Said ~= "" and `Yes, I saved it: {Said}.` or "Yes, I saved it.")
                end

                return Mind.Reply(Memory.Known() == 0 and "There's nothing saved about you right now." or `Here's what I have: {Memory.Summary()}`)
            elseif Kind == "notes" then
                if #Profile.Notes == 0 then
                    return Mind.Reply("You haven't asked me to remember anything yet. Say \"remember that ...\" and I'll keep it.")
                end

                local Quoted: {string} = {}
                for _, Note in Profile.Notes do
                    table.insert(Quoted, `"{Note.Text}"`)
                end

                return Mind.Reply(`You asked me to remember: {table.concat(Quoted, "; ")}.`)
            elseif Kind == "about" then
                local Word: string = Detail:match("^(%a+)") or Detail
                local Found: {string} = {}
                for _, List in {Profile.Notes, Profile.Likes, Profile.Dislikes} do
                    for _, Item in List do
                        if Item.Text:lower():find(Word, 1, true) then
                            table.insert(Found, `"{Item.Text}"`)
                        end
                    end
                end

                if #Found > 0 then
                    return Mind.Reply(`Yes, you told me: {table.concat(Found, "; ")}.`)
                end

                local Score: number = 0
                for Name: string, Value: number in Profile.Interest do
                    if Name:lower() == Word then
                        Score = Value
                    end
                end

                return Mind.Reply(Score >= 2 and `Nothing you told me directly, but you've asked about it a few times.` or `Nothing that I know of. You haven't told me anything about {Word}.`)
            elseif Kind == "earlier" then
                local Here = Mind.History[#Mind.History]
                if Last and Last.Turns >= 2 and (#Last.Topics > 0 or Last.Open) then
                    local About: string = #Last.Topics > 0 and Mind.Oxford({table.unpack(Last.Topics, 1, 3)}) or Last.Open
                    return Mind.Reply(Mind.Join(`{Mind.Cap(Memory.Ago(Last.At))} we talked about {About}.`, Last.Open and `You were sorting out {Last.Open}, is that fixed?` or "Want to pick that up?"))
                elseif Here and #Mind.History >= 2 then
                    return Mind.Reply(`Before this you asked "{Mind.History[#Mind.History - 1].Q}".`)
                end

                return Mind.Reply(Mind.Any("I don't have an earlier chat to go back to, this is the first one I've kept.", "Nothing from before yet, this is the first time I've saved anything about us."))
            elseif Kind == "knows" then
                if Memory.Known() == 0 and not (Last and Last.Turns >= 2) then
                    return Mind.Reply(Mind.Any("Not that I can tell, you haven't told me anything yet. I'm happy to start now.", "I don't think so, I've got nothing saved about you. Tell me your name and what you play and I'll remember it."))
                end

                return Mind.Reply(Mind.Join(
                    Profile.Name and `Welcome back, {Profile.Name}.` or "Yes, welcome back.",
                    Memory.Callback() or (Last and Last.Turns >= 2 and #Last.Topics > 0 and `{Mind.Cap(Memory.Ago(Last.At))} you were asking about {Mind.Oxford({table.unpack(Last.Topics, 1, 3)})}.` or "")
                ))
            end

            local Summary: string = Memory.Summary()
            if Summary == "" then
                return Mind.Reply(Mind.From(NothingYet))
            end

            return Mind.Reply(Mind.Join(Mind.Any("Here's what I've got.", "This is what I know so far."), Summary, "Say \"forget my name\" or \"forget everything\" and I'll drop it."), {"Forget everything about me"})
        end)

        local Fields = {
            name = {"name"}, platform = {"platform", "device"}, skill = {"skill", "level"}, style = {"style", "play style", "playstyle"}, game = {"game"}, kit = {"kit", "main"}, goal = {"goal", "goals"},
            notes = {"notes", "note"}, likes = {"likes"}, dislikes = {"dislikes"}
        }

        function Memory.Wipe()
            Memory.Ensure()
            local Fresh = Memory.Blank()
            Fresh.Visits = 1
            Memory.Profile = Fresh
            Memory.Session = {At = os.time(), Turns = 0, Topics = {}}
            Fresh.Sessions = {Memory.Session}
            Memory.Previous = nil
            table.clear(Memory.Batch)
            Memory.Dirty = true
            Memory.Save()
        end

        function Memory.Forget(Field: string): boolean
            local Profile = Memory.Ensure()
            local Had: boolean = false
            if Field == "name" then
                Had = Profile.Name ~= nil
                Profile.Name = nil
            elseif Field == "notes" or Field == "likes" or Field == "dislikes" then
                local List = Profile[Field:sub(1, 1):upper() .. Field:sub(2)]
                Had = #List > 0
                table.clear(List)
            else
                Had = Profile.Facts[Field] ~= nil
                Profile.Facts[Field] = nil
            end

            Memory.Dirty = Memory.Dirty or Had
            return Had
        end

        local Skip = Brain.Set("thing things note notes stuff one that this the about thingy bit")

        -- Drops the notes, likes and dislikes that share a meaningful word with a description like "the alt account thing".
        function Memory.ForgetLike(Description: string): number
            local Profile = Memory.Ensure()
            local Wanted: {string} = {}
            for Word: string in Description:gmatch("%a+") do
                if #Word >= 3 and not Skip[Word] then
                    table.insert(Wanted, Word)
                end
            end

            local Removed: number = 0
            for _, List in {Profile.Notes, Profile.Likes, Profile.Dislikes} do
                for i: number = #List, 1, -1 do
                    local Low: string = List[i].Text:lower()
                    for _, Word: string in Wanted do
                        if Low:find(Word, 1, true) then
                            table.remove(List, i)
                            Removed += 1
                            break
                        end
                    end
                end
            end

            Memory.Dirty = Memory.Dirty or Removed > 0
            return Removed
        end

        local WipePatterns = {"^forget everything", "^forget all", "^forget me", "^forget about me", "^wipe ", "^delete my data", "^delete my profile", "^delete my info", "^delete everything", "^clear my profile", "^clear my data", "^erase everything", "^erase my data", "^reset my profile"}

        Act("Forget", function(Frame): boolean
            local N: string = Memory.Core(Frame.Raw)
            if Mind.Plan and Mind.Plan.Talk and (Mind.Plan.Active or Mind.Plan.Stored()) and Mind.Plan.Talk(N) then
                return false
            end

            return Asked(N, {"^wipe everything", "^wipe all", "^wipe it", "^delete everything", "^delete all", "^erase all", "^clear everything", "^forget the ", "^forget about ", "^delete the ", "^remove the ", "^forget my ", "^forget that", "^forget this", "^forget what i", "^forget everything", "^forget all", "^forget me", "^forget about me", "^wipe my ", "^wipe your memory", "^delete my ", "^clear my ", "^erase my ", "^erase everything", "^reset my profile", "^please forget"})
        end, function(Frame)
            local N: string = (Memory.Core(Frame.Raw):gsub("^please ", ""))
            local Profile = Memory.Ensure()
            if Asked(N, WipePatterns) then
                if Memory.Known() == 0 and #Profile.Sessions <= 1 then
                    return Mind.Reply("There's nothing saved about you, so there's nothing to forget.")
                end

                Memory.Wiping = true
                local Count: number = Memory.Known()
                return Mind.Reply(Mind.Join(`Just to be sure: this wipes everything I keep about you ({Count} thing{Count == 1 and "" or "s"} you told me, plus what you've been asking about).`, "Yes to confirm?"), {"Yes, forget everything", "No, keep it"})
            end

            for Field: string, Words in Fields do
                for _, Word: string in Words do
                    if N == `forget my {Word}` or N:find(`^forget my {Word} `) or N == `delete my {Word}` or N == `clear my {Word}` or N == `erase my {Word}` or N == `forget {Word}` then
                        return Mind.Reply(Memory.Forget(Field) and Mind.Any(`Forgot your {Word}.`, `Done, your {Word} is gone from my memory.`, `Dropped your {Word}.`) or `I didn't have your {Word} anyway.`)
                    end
                end
            end

            local Which: string? = N:match("^forget the (.+)$") or N:match("^forget about (.+)$") or N:match("^delete the (.+)$") or N:match("^remove the (.+)$")
            if Which then
                local Removed: number = Memory.ForgetLike(Which)
                return Mind.Reply(Removed > 0 and Mind.Any("Done, I dropped it.", "Okay, that's out of my memory.") or `I don't have anything saved that matches "{Memory.Clip(Which, 40)}".`)
            end

            if #Memory.Batch > 0 and (N:find("^forget that") or N:find("^forget this") or N:find("^forget it") or N:find("^forget what i")) then
                for _, Item in Memory.Batch do
                    if Item.Kind == "name" then
                        Profile.Name = Item.Old
                    elseif Item.Kind == "fact" then
                        Profile.Facts[Item.Key] = Item.Old and {Value = Item.Old, At = os.time()} or nil
                    else
                        local List = Profile[Item.Kind == "note" and "Notes" or Item.Kind == "like" and "Likes" or "Dislikes"]
                        for i: number = #List, 1, -1 do
                            if List[i].Text == Item.Value then
                                table.remove(List, i)
                            end
                        end
                    end
                end

                table.clear(Memory.Batch)
                Memory.Dirty = true
                return Mind.Reply(Mind.Any("Okay, I forgot that.", "Done, that's out of my memory.", "Dropped it."))
            end

            return Mind.Reply("I'm not sure which part you mean. Say \"forget my name\", \"forget my notes\" or \"forget everything\".", {"What do you know about me?"})
        end)

        local Yes = Brain.Set("yes yeah yep yup sure confirm ok okay y")
        local No = Brain.Set("no nope nah cancel stop n")

        -- A "yes" right after the wipe question is the answer to it, not something for the rest of the assistant to interpret.
        function Memory.Hold(Raw: string)
            if not Memory.Wiping then
                return nil
            end

            Memory.Wiping = false
            local N: string = Normal(Raw)
            local First: string = N:match("^%a+") or ""
            if Yes[First] or N == "do it" or N == "go ahead" then
                Memory.Wipe()
                return Mind.Reply(Mind.Any("Done, I forgot everything about you. We can start fresh.", "All gone. I don't know anything about you now."))
            elseif No[First] or N:find("^keep") or N == "never mind" or N == "nevermind" then
                return Mind.Reply(Mind.Any("Okay, I'm keeping it.", "Alright, nothing changed."))
            end

            return nil
        end

        -- ---------------------------------------------------------------- what happened this session

        function Memory.Touch(Frame)
            local Profile = Memory.Ensure()
            local Session = Memory.Session
            if not Session or not Frame or Profile.Paused then
                return
            end

            Session.Turns += 1
            for _, Mention in Frame.Mentions do
                local Name: string = Mention.Entry.Name
                Profile.Interest[Name] = math.min((Profile.Interest[Name] or 0) + 1, 50)
                if #Session.Topics < 8 and not table.find(Session.Topics, Name) then
                    table.insert(Session.Topics, Name)
                end
            end

            Memory.Dirty = true
            Memory.Save()
        end

        -- One line for the greeting when this is a return visit: what we were on last time, and whether a problem was left open.
        function Memory.Callback(): string?
            Memory.Ensure()
            local Last = Memory.Previous
            if Memory.Greeted or not Last or Last.Turns < 2 then
                return nil
            end

            Memory.Greeted = true
            if Last.Open then
                return Mind.Any(`{Mind.Cap(Memory.Ago(Last.At))} you were sorting out {Last.Open}. Did that get fixed?`, `Last time you had {Last.Open} going on, is it better now?`)
            elseif #Last.Topics > 0 then
                return Mind.Any(`Last time we got into {Mind.Oxford({table.unpack(Last.Topics, 1, 3)})}.`, `{Mind.Cap(Memory.Ago(Last.At))} we looked at {Mind.Oxford({table.unpack(Last.Topics, 1, 3)})}.`)
            end

            return nil
        end

        -- Saving can be paused: nothing new is kept until it is turned back on, and what is already saved stays until "forget everything".
        local PauseAsks = {"^stop remembering", "^do not remember", "^dont remember", "^pause memory", "^turn off memory", "^stop saving", "^no more remembering", "^do not save anything", "^stop learning about me", "^disable memory"}
        local ResumeAsks = {"^start remembering", "^resume memory", "^turn on memory", "^remember things again", "^you can remember again", "^enable memory", "^start saving", "^unpause memory", "^resume remembering"}

        Act("MemorySwitch", function(Frame): boolean
            local N: string = Memory.Core(Frame.Raw)
            return Asked(N, PauseAsks) or Asked(N, ResumeAsks)
        end, function(Frame)
            local Profile = Memory.Ensure()
            local Pausing: boolean = Asked(Memory.Core(Frame.Raw), PauseAsks)
            Profile.Paused = Pausing
            Memory.Dirty = true
            Memory.Save()
            if Pausing then
                return Mind.Reply(Mind.Join("Okay, I'll stop keeping anything new about you.", Memory.Known() > 0 and "What I already have stays until you say \"forget everything\"." or "", "Say \"start remembering\" to turn it back on."))
            end

            return Mind.Reply("Okay, I'm remembering again. I'll keep what you tell me from now on.")
        end)
        end

        -- ---------------------------------------------------------------- numbers: puzzles, units, sequences, word problems

        do
        local Act = Mind.Act

        local function Show(Value: number): string
            if Value == math.floor(Value) and math.abs(Value) < 1e15 then
                return string.format("%d", Value)
            end

            local Text: string = string.format("%.4f", Value)
            Text = Text:gsub("0+$", ""):gsub("%.$", "")
            return Text
        end

        local function Numbers(Text: string): {number}
            local List: {number} = {}
            for Match: string in Text:gmatch("%-?%d[%d,]*%.?%d*") do
                local Value: number? = tonumber((Match:gsub(",", ""):gsub("%.$", "")))
                if Value then
                    table.insert(List, Value)
                end
            end

            return List
        end

        local function IsPrime(Value: number): boolean
            if Value < 2 or Value ~= math.floor(Value) then
                return false
            end

            for Divisor: number = 2, math.floor(math.sqrt(Value)) do
                if Value % Divisor == 0 then
                    return false, Divisor
                end
            end

            return true
        end

        local function Gcd(A: number, B: number): number
            while B ~= 0 do
                A, B = B, A % B
            end

            return math.abs(A)
        end

        -- length units to metres, mass units to kilograms, time units to seconds
        local Units = {
            km = {"length", 1000}, kilometer = {"length", 1000}, kilometers = {"length", 1000}, mile = {"length", 1609.344}, miles = {"length", 1609.344}, mi = {"length", 1609.344},
            m = {"length", 1}, meter = {"length", 1}, meters = {"length", 1}, ft = {"length", 0.3048}, foot = {"length", 0.3048}, feet = {"length", 0.3048},
            inch = {"length", 0.0254}, inches = {"length", 0.0254}, ["in"] = {"length", 0.0254}, cm = {"length", 0.01}, centimeter = {"length", 0.01}, centimeters = {"length", 0.01}, mm = {"length", 0.001},
            kg = {"mass", 1}, kilogram = {"mass", 1}, kilograms = {"mass", 1}, g = {"mass", 0.001}, gram = {"mass", 0.001}, grams = {"mass", 0.001}, lb = {"mass", 0.45359237}, lbs = {"mass", 0.45359237}, pound = {"mass", 0.45359237}, pounds = {"mass", 0.45359237}, oz = {"mass", 0.0283495}, ounce = {"mass", 0.0283495}, ounces = {"mass", 0.0283495},
            second = {"time", 1}, seconds = {"time", 1}, sec = {"time", 1}, secs = {"time", 1}, minute = {"time", 60}, minutes = {"time", 60}, min = {"time", 60}, mins = {"time", 60},
            hour = {"time", 3600}, hours = {"time", 3600}, hr = {"time", 3600}, hrs = {"time", 3600}, day = {"time", 86400}, days = {"time", 86400}, week = {"time", 604800}, weeks = {"time", 604800}, year = {"time", 31536000}, years = {"time", 31536000}
        }
        local Temperatures = {c = "c", celsius = "c", centigrade = "c", f = "f", fahrenheit = "f", k = "k", kelvin = "k"}

        local function Convert(Value: number, From: string, To: string): number?
            local A, B = Temperatures[From], Temperatures[To]
            if A and B then
                local Celsius: number = A == "c" and Value or A == "f" and (Value - 32) * 5 / 9 or Value - 273.15
                return B == "c" and Celsius or B == "f" and Celsius * 9 / 5 + 32 or Celsius + 273.15
            end

            local Source, Target = Units[From], Units[To]
            if Source and Target and Source[1] == Target[1] then
                return Value * Source[2] / Target[2]
            end

            return nil
        end

        local SequenceNext
        local function Sequence(List: {number}): (number?, string?)
            if #List < 3 then
                return nil
            end

            local Step: number = List[2] - List[1]
            local Arithmetic: boolean = true
            for i: number = 2, #List do
                Arithmetic = Arithmetic and List[i] - List[i - 1] == Step
            end

            if Arithmetic then
                return List[#List] + Step, `it goes up by {Show(Step)} each time`
            end

            if List[1] ~= 0 then
                local Ratio: number = List[2] / List[1]
                local Geometric: boolean = true
                for i: number = 2, #List do
                    Geometric = Geometric and List[i - 1] ~= 0 and math.abs(List[i] / List[i - 1] - Ratio) < 1e-9
                end

                if Geometric then
                    return List[#List] * Ratio, `each number is {Show(Ratio)} times the one before`
                end
            end

            -- second differences constant (squares and friends)
            if #List >= 4 then
                local First = {}
                for i: number = 2, #List do
                    table.insert(First, List[i] - List[i - 1])
                end

                local Second: number = First[2] - First[1]
                local Quadratic: boolean = true
                for i: number = 2, #First do
                    Quadratic = Quadratic and First[i] - First[i - 1] == Second
                end

                if Quadratic then
                    local NextDifference: number = First[#First] + Second
                    return List[#List] + NextDifference, "the gaps between numbers grow by the same amount each step"
                end
            end

            -- each number is the sum of the two before (fibonacci-like)
            local Sums: boolean = #List >= 4
            for i: number = 3, #List do
                Sums = Sums and List[i] == List[i - 1] + List[i - 2]
            end

            if Sums then
                return List[#List] + List[#List - 1], "each number is the sum of the two before it"
            end

            return nil
        end

        -- "i think of a number, double it, add 10, halve it, get 12": undo the steps from the end
        local function Undo(Text: string): (number?, string?)
            local Steps = {}
            local Result: number? = tonumber(Text:match("get (%-?%d+%.?%d*)")) or tonumber(Text:match("result is (%-?%d+%.?%d*)")) or tonumber(Text:match("end up with (%-?%d+%.?%d*)")) or tonumber(Text:match("answer is (%-?%d+%.?%d*)")) or tonumber(Text:match("and get (%-?%d+%.?%d*)")) or tonumber(Text:match("i get (%-?%d+%.?%d*)")) or tonumber(Text:match("equals? (%-?%d+%.?%d*)"))
            if not Result then
                return nil
            end

            for Clause: string in (Text:gsub("^.-number,?%s*", "")):gmatch("[^,]+") do
                Clause = Clause:gsub("^%s*and%s+", ""):gsub("^%s*then%s+", "")
                local Word: string = Clause:match("^%s*(%a+)") or ""
                local Amount: number? = tonumber(Clause:match("(%-?%d+%.?%d*)"))
                if Word == "double" or Word == "doubled" then
                    table.insert(Steps, {"*", 2, "double"})
                elseif Word == "triple" then
                    table.insert(Steps, {"*", 3, "triple"})
                elseif Word == "halve" or Word == "half" then
                    table.insert(Steps, {"/", 2, "halve"})
                elseif Word == "add" and Amount then
                    table.insert(Steps, {"+", Amount, `add {Show(Amount)}`})
                elseif (Word == "subtract" or Word == "minus" or Word == "take") and Amount then
                    table.insert(Steps, {"-", Amount, `subtract {Show(Amount)}`})
                elseif (Word == "multiply" or Word == "times") and Amount then
                    table.insert(Steps, {"*", Amount, `multiply by {Show(Amount)}`})
                elseif (Word == "divide" or Word == "split") and Amount then
                    table.insert(Steps, {"/", Amount, `divide by {Show(Amount)}`})
                end
            end

            if #Steps == 0 then
                return nil
            end

            local Value: number = Result
            for i: number = #Steps, 1, -1 do
                local Operator, Amount = Steps[i][1], Steps[i][2]
                Value = Operator == "*" and Value / Amount or Operator == "/" and Value * Amount or Operator == "+" and Value - Amount or Value + Amount
            end

            return Value, `starting from {Show(Result)} at the end`
        end

        -- "square root of 144 plus 3 cubed" -> 144 sqrt, + 27
        local function Phrase(L: string): (number?, string?)
            local E: string = " " .. L .. " "
            E = E:gsub("[%?%!,]", " "):gsub(" whats ", " "):gsub(" what is ", " "):gsub(" what's ", " "):gsub(" calculate ", " "):gsub(" compute ", " "):gsub(" solve ", " "):gsub(" evaluate ", " ")
            E = E:gsub(" the ", " "):gsub(" answer ", " ")
            E = E:gsub("square root of (%d+%.?%d*)", "@%1"):gsub("(%d+%.?%d*) squared", "(%1^2)"):gsub("(%d+%.?%d*) cubed", "(%1^3)")
            E = E:gsub("(%d+%.?%d*) percent of (%d+%.?%d*)", "(%1/100*%2)")
            E = E:gsub(" plus ", " + "):gsub(" minus ", " - "):gsub(" times ", " * "):gsub(" multiplied by ", " * "):gsub(" divided by ", " / "):gsub(" over ", " / "):gsub(" to the power of ", " ^ ")
            E = E:gsub("%s+", " "):gsub("^ ", ""):gsub(" $", "")
            if E:find("%d") and E:find("[%+%-%*/%^@%%]") then
                -- unit words after numbers ("240 emeralds") are not part of the sum
                E = E:gsub("(%d)%s+%a+", "%1"):gsub("%s+%a+$", "")
            end

            if not E:find("%d") or not E:match("^[%d%.%s%+%-%*/%^%(%)@]+$") or not E:find("[%+%-%*/%^@]") then
                return nil
            end

            local Value: number? = Brain.Arithmetic(E)
            return Value, E
        end

        -- "i have 3 beds and break 2 how many are left, but one respawns" and "a diamond costs 4 emeralds, i have 27, how many"
        local function WordProblem(L: string): string?
            local Cost: string?, Have: string? = L:match("costs? (%d+)"), nil
            Have = L:match("i have (%d+)") or L:match("have (%d+)") or L:match("with (%d+)")
            if Cost and Have and L:find("how many", 1, true) then
                local Price: number, Money: number = tonumber(Cost) or 1, tonumber(Have) or 0
                if Price > 0 then
                    return `You can afford {math.floor(Money / Price)} ({Show(Money)} / {Show(Price)}), with {Show(Money % Price)} left over.`
                end
            end

            local A, B, C, Unit, D, E = L:match("(%d+) %a+ %a+ (%d+) %a+ in (%d+) (%a+),? how long for (%d+) %a+ to %a+ (%d+)")
            if A and tonumber(A) == tonumber(B) and tonumber(D) == tonumber(E) then
                return `The same {C} {Unit}: every player is still breaking one bed in the {C} {Unit} it took {A} players to break {B}, so it scales evenly.`
            end

            -- distance over speed
            local Speed: string?, Distance: string? = L:match("(%d+%.?%d*) %a+ per second"), L:match("(%d+%.?%d*) %a+ long")
            if Speed and Distance and (L:find("how long", 1, true) or L:find("how many seconds", 1, true)) then
                local Seconds: number = (tonumber(Distance) :: number) / (tonumber(Speed) :: number)
                return `At {Show(tonumber(Speed) :: number)} per second, {Show(tonumber(Distance) :: number)} takes {Show(math.floor(Seconds * 100 + 0.5) / 100)} seconds.`
            end

            -- something that appears every N seconds, and a price in that thing
            local Every: string?, Price: string? = L:match("every (%d+%.?%d*) seconds?"), L:match("costs? (%d+)")
            if Every and Price and (L:find("how many seconds", 1, true) or L:find("how long", 1, true)) then
                local Total: number = (tonumber(Every) :: number) * (tonumber(Price) :: number)
                return `You need {Show(tonumber(Price) :: number)} of them, one every {Show(tonumber(Every) :: number)} seconds, so it takes {Show(Total)} seconds ({Show(Total / 60)} minutes).`
            end

            -- hours of play to reach a number of wins
            local Length: string? = L:match("match is (%d+) minutes")
            local Wins: string?, Of: string? = L:match("win (%d+) out of (%d+)")
            local Goal: string? = L:match("reach (%d+)") or L:match("get (%d+) wins")
            if Length and Wins and Of and Goal then
                local Matches: number = (tonumber(Goal) :: number) * (tonumber(Of) :: number) / (tonumber(Wins) :: number)
                local Minutes: number = Matches * (tonumber(Length) :: number)
                return `You'd need about {Show(math.ceil(Matches))} matches to win {Goal}, and at {Length} minutes each that's roughly {Show(math.floor(Minutes / 60 * 10 + 0.5) / 10)} hours of play.`
            end

            -- spikes of some milliseconds, some per minute, for some time
            local Spike: string?, PerMinute: string? = L:match("(%d+) ?ms"), L:match("get (%d+) a minute") or L:match("(%d+) per minute")
            if Spike and PerMinute and L:find("how many seconds", 1, true) then
                local Hours: number = L:find("one hour", 1, true) and 1 or tonumber(L:match("(%d+) hours?")) or 1
                local Seconds: number = (tonumber(Spike) :: number) * (tonumber(PerMinute) :: number) * 60 * Hours / 1000
                return `That's {Spike} ms times {PerMinute} a minute times {60 * Hours} minutes, so {Show(Seconds)} seconds of lag in {Hours == 1 and "an hour" or `{Hours} hours`}.`
            end

            if (L:find("left", 1, true) or L:find("remain", 1, true)) and L:find("how many", 1, true) then
                local Total: number? = tonumber(L:match("have (%d+)") or L:match("had (%d+)") or L:match("got (%d+)") or L:match("start with (%d+)"))
                if Total then
                    local Value: number = Total
                    for Verb: string, Amount: string in L:gmatch("(%a+) (%d+)") do
                        if Verb == "break" or Verb == "lose" or Verb == "lost" or Verb == "spend" or Verb == "use" or Verb == "eat" or Verb == "give" or Verb == "sell" or Verb == "drop" or Verb == "kill" or Verb == "remove" or Verb == "take" or Verb == "broke" or Verb == "destroy" then
                            Value -= tonumber(Amount) :: number
                        elseif Verb == "get" or Verb == "find" or Verb == "buy" or Verb == "gain" or Verb == "earn" or Verb == "collect" or Verb == "win" or Verb == "add" then
                            Value += tonumber(Amount) :: number
                        end
                    end

                    if L:find("respawn", 1, true) or L:find("comes back", 1, true) or L:find("grows back", 1, true) then
                        Value += 1
                    end

                    return `You'd have {Show(Value)} left.`
                end
            end

            return nil
        end

        local Holidays = {christmas = {12, 25}, ["new year"] = {1, 1}, halloween = {10, 31}, valentines = {2, 14}, ["valentine's"] = {2, 14}, ["valentine"] = {2, 14}, ["independence day"] = {7, 4}, ["new years"] = {1, 1}}

        local function IsLeap(Year: number): boolean
            return (Year % 4 == 0 and Year % 100 ~= 0) or Year % 400 == 0
        end

        local function Calendar(L: string): string?
            local Now = os.date("*t")
            if L:find("leap year", 1, true) then
                local Year: number = Now.year
                if L:find("next year", 1, true) then
                    Year += 1
                elseif L:find("last year", 1, true) then
                    Year -= 1
                elseif tonumber(L:match("(%d%d%d%d)")) then
                    Year = tonumber(L:match("(%d%d%d%d)")) :: number
                end

                return `{Year} {IsLeap(Year) and "is" or "is not"} a leap year{IsLeap(Year) and ", February has 29 days" or ""}.`
            end

            if L:find("days until", 1, true) or L:find("days till", 1, true) or L:find("days to", 1, true) or L:find("until christmas", 1, true) or L:find("how long until", 1, true) or L:find("how many days", 1, true) then
                for Name: string, Date in Holidays do
                    if L:find(Name, 1, true) then
                        local Today: number = os.time({year = Now.year, month = Now.month, day = Now.day, hour = 12})
                        local Target: number = os.time({year = Now.year, month = Date[1], day = Date[2], hour = 12})
                        if Target < Today then
                            Target = os.time({year = Now.year + 1, month = Date[1], day = Date[2], hour = 12})
                        end

                        local Days: number = math.floor((Target - Today) / 86400 + 0.5)
                        return Days == 0 and `It's {Name} today!` or `There {Days == 1 and "is" or "are"} {Days} day{Days == 1 and "" or "s"} until {Name}.`
                    end
                end
            end

            return nil
        end

        Act("Math", function(Frame): boolean
            local L = Frame.Lower
            if Calendar(L) then
                return true
            end

            if L:find("%d") and WordProblem(L) then
                return true
            end

            if L:find("%d") and (L:find("square root", 1, true) or L:find("cubed", 1, true) or L:find("squared", 1, true) or L:find("percent of", 1, true)) and Phrase(L) then
                return true
            end

            if L:match("which is heavier") or L:match("what weighs more") or L:match("which weighs more") then
                return true
            end

            if Frame.Evidence >= 3 and not L:find("%d") then
                return false
            end

            if L:match("how many %a+ in an? %a+") ~= nil or L:match("how many %a+ are in an? %a+") ~= nil then
                local Unit, Per = L:match("how many (%a+) in an? (%a+)")
                if not Unit then
                    Unit, Per = L:match("how many (%a+) are in an? (%a+)")
                end

                return Units[Unit] ~= nil and Units[Per] ~= nil
            end

            return L:find("%d") ~= nil and (
                L:match("prime") ~= nil or L:match("factorial") ~= nil or L:match("%d%s*!") ~= nil or L:match("squared") ~= nil or L:match("cubed") ~= nil or L:match("to the power") ~= nil or L:match("%^") ~= nil
                or L:match("average") ~= nil or L:match("mean of") ~= nil or L:match("sum of") ~= nil or L:match("product of") ~= nil or L:match("%f[%a]gcd%f[%A]") ~= nil or L:match("%f[%a]lcm%f[%A]") ~= nil or L:match("divisible") ~= nil
                or L:match("%f[%a]even%f[%A]") ~= nil or L:match("%f[%a]odd%f[%A]") ~= nil or L:match("what comes next") ~= nil or L:match("next number") ~= nil or L:match("what'?s next") ~= nil or L:match("pattern") ~= nil
                or L:match("convert") ~= nil or L:match("%d%s*[%a]+%s+to%s+%a+") ~= nil or L:match("%d%s*[%a]+%s+in%s+%a+") ~= nil or L:match("how many %a+ in") ~= nil
                or L:match("think of a number") ~= nil or L:match("%f[%a]bigger%f[%A]") ~= nil or L:match("%f[%a]larger%f[%A]") ~= nil or L:match("%f[%a]smaller%f[%A]") ~= nil or L:match("%f[%a]greater%f[%A]") ~= nil or L:match("%f[%a]largest%f[%A]") ~= nil or L:match("%f[%a]smallest%f[%A]") ~= nil
                or L:match("how long") ~= nil and L:match("per second") ~= nil or L:match("how long") ~= nil and L:match("times a second") ~= nil or L:match("how many hits") ~= nil or L:match("%f[%a]round%f[%A]") ~= nil or L:match("%f[%a]half of%f[%A]") ~= nil or L:match("%f[%a]double%f[%A]") ~= nil
            ) or L:match("celsius to fahrenheit") ~= nil or L:match("fahrenheit to celsius") ~= nil or L:match("which is heavier") ~= nil or L:match("what weighs more") ~= nil or L:match("which weighs more") ~= nil
        end, function(Frame)
            local L = Frame.Lower:gsub("[%?%!]", ""):gsub("94~", "")
            local Found = Numbers(L)

            local Dated: string? = Calendar(L)
            if Dated then
                return Mind.Reply(Dated)
            end

            local Solved: string? = WordProblem(L)
            if Solved then
                return Mind.Reply(Solved)
            end

            local Calculated, Shown = Phrase(L)
            if Calculated and (L:find("square root", 1, true) or L:find("cubed", 1, true) or L:find("squared", 1, true) or L:find("percent of", 1, true)) then
                return Mind.Reply(Mind.Join(`That's {Show(Calculated)}.`, `(I read it as {Shown:gsub("@", "sqrt ")}.)`))
            end

            -- formulas asked without numbers
            if L:find("celsius to fahrenheit", 1, true) and #Found == 0 then
                return Mind.Reply("Multiply the Celsius number by 9/5 (1.8) and add 32. For example 20 C is 20 x 1.8 + 32 = 68 F.")
            elseif L:find("fahrenheit to celsius", 1, true) and #Found == 0 then
                return Mind.Reply("Take away 32 from the Fahrenheit number, then multiply by 5/9. For example 68 F is (68 - 32) x 5/9 = 20 C.")
            end

            -- riddles with equal weights
            local Left, Right = L:match("heavier,? an? (%a+) of ([%a ]+) or an? (%a+) of ([%a ]+)")
            if not Left then
                Left, Right = L:match("weighs more,? an? (%a+) of ([%a ]+) or an? (%a+) of ([%a ]+)")
            end

            if Left then
                local A, ThingA, B, ThingB = L:match("an? (%a+) of ([%a ]+) or an? (%a+) of ([%a ]+)")
                if A and A == B then
                    return Mind.Reply(Mind.Join(`They weigh exactly the same, a {A} is a {A} whether it's {ThingA:gsub("%s+$", "")} or {ThingB:gsub("%s+$", "")}.`, "The difference is only in how much space each takes up."))
                end
            end

            -- number puzzle
            if L:find("think of a number") or L:find("pick a number") then
                local Value, How = Undo(L)
                if Value then
                    return Mind.Reply(Mind.Join(`The number was {Show(Value)}.`, `I got there by reversing each step, {How}.`, `Check: run your steps on {Show(Value)} and you land on the result.`))
                end
            end

            -- primes, even/odd, divisibility
            local Value: number? = Found[1]
            if L:match("prime") and Value then
                local Prime, Divisor = IsPrime(Value)
                return Mind.Reply(Prime and Mind.Join(`Yes, {Show(Value)} is prime, nothing but 1 and itself divides it.`) or Mind.Join(`No, {Show(Value)} isn't prime, it divides by {Divisor} ({Show(Value)} / {Divisor} = {Show(Value / Divisor)}).`))
            elseif (L:match("%f[%a]even%f[%A]") or L:match("%f[%a]odd%f[%A]")) and Value and L:match("^is ") then
                local Even: boolean = Value % 2 == 0
                return Mind.Reply(`{Show(Value)} is {Even and "even" or "odd"}.`)
            elseif L:match("divisible") and Found[2] then
                local Yes: boolean = Found[1] % Found[2] == 0
                return Mind.Reply(Yes and `Yes, {Show(Found[1])} / {Show(Found[2])} = {Show(Found[1] / Found[2])}.` or `No, {Show(Found[1])} divided by {Show(Found[2])} leaves a remainder of {Show(Found[1] % Found[2])}.`)
            elseif (L:match("factorial") or L:match("%d%s*!")) and Value and Value >= 0 and Value <= 20 and Value == math.floor(Value) then
                local Result: number = 1
                for i: number = 2, Value do
                    Result *= i
                end

                return Mind.Reply(`{Show(Value)}! = {Show(Result)}.`)
            elseif L:match("squared") and Value then
                return Mind.Reply(`{Show(Value)} squared is {Show(Value * Value)}.`)
            elseif L:match("cubed") and Value then
                return Mind.Reply(`{Show(Value)} cubed is {Show(Value ^ 3)}.`)
            elseif (L:match("to the power") or L:match("%^")) and Found[2] then
                return Mind.Reply(`{Show(Found[1])} to the power of {Show(Found[2])} is {Show(Found[1] ^ Found[2])}.`)
            elseif (L:match("%f[%a]gcd%f[%A]") or L:match("greatest common")) and Found[2] then
                return Mind.Reply(`The greatest common divisor of {Show(Found[1])} and {Show(Found[2])} is {Show(Gcd(Found[1], Found[2]))}.`)
            elseif L:match("%f[%a]lcm%f[%A]") and Found[2] then
                return Mind.Reply(`The lowest common multiple of {Show(Found[1])} and {Show(Found[2])} is {Show(Found[1] * Found[2] / Gcd(Found[1], Found[2]))}.`)
            end

            -- lists: average, sum, product, biggest, smallest
            if #Found >= 2 then
                local Sum, Product, Biggest, Smallest = 0, 1, Found[1], Found[1]
                for _, Number: number in Found do
                    Sum += Number
                    Product *= Number
                    Biggest = math.max(Biggest, Number)
                    Smallest = math.min(Smallest, Number)
                end

                if L:match("average") or L:match("mean of") then
                    return Mind.Reply(`The average of those {#Found} numbers is {Show(Sum / #Found)} ({Show(Sum)} / {#Found}).`)
                elseif L:match("sum of") then
                    return Mind.Reply(`They add up to {Show(Sum)}.`)
                elseif L:match("product of") then
                    return Mind.Reply(`Multiplied together they make {Show(Product)}.`)
                elseif L:match("what comes next") or L:match("next number") or L:match("what'?s next") or L:match("pattern") then
                    local NextValue, Reason = Sequence(Found)
                    if NextValue then
                        return Mind.Reply(Mind.Join(`The next number is {Show(NextValue)}, {Reason}.`))
                    end

                    return Mind.Reply("I can't spot a pattern in those, they don't go up by a steady step or a steady multiple. Can you give me one more number?")
                elseif L:match("%f[%a]bigger%f[%A]") or L:match("%f[%a]larger%f[%A]") or L:match("%f[%a]greater%f[%A]") or L:match("%f[%a]largest%f[%A]") or L:match("%f[%a]biggest%f[%A]") then
                    return Mind.Reply(`{Show(Biggest)} is the bigger one.`)
                elseif L:match("%f[%a]smaller%f[%A]") or L:match("%f[%a]smallest%f[%A]") or L:match("%f[%a]less%f[%A]") then
                    return Mind.Reply(`{Show(Smallest)} is the smaller one.`)
                end
            end

            -- unit conversion and time in units
            local Amount, From, To = L:match("(%-?%d[%d%.]*)%s*%s*([%a]+)%s+to%s+([%a]+)")
            if not Amount then
                Amount, From, To = L:match("(%-?%d[%d%.]*)%s*%s*([%a]+)%s+in%s+([%a]+)")
            end

            if not Amount then
                Amount, From, To = L:match("convert%s+(%-?%d[%d%.]*)%s*%s*([%a]+)%s+to%s+([%a]+)")
            end

            if Amount and From and To then
                local Result = Convert(tonumber(Amount) or 0, From, To)
                if Result then
                    return Mind.Reply(`{Amount} {From} is about {Show(math.floor(Result * 1000 + 0.5) / 1000)} {To}.`)
                end
            end

            local Unit, Per = L:match("how many (%a+) in an? (%a+)")
            if not Unit then
                Unit, Per = L:match("how many (%a+) are in an? (%a+)")
            end

            if Unit and Per and Units[Unit] and Units[Per] and Units[Unit][1] == Units[Per][1] then
                local Ratio: number = Units[Per][2] / Units[Unit][2]
                return Mind.Reply(`There are {Show(Ratio)} {Unit} in a {Per}.`)
            end

            -- how long to kill: hits per second x damage against health
            if L:match("how long") and (L:match("per second") or L:match("times a second") or L:match("times per second") or L:match("a second")) and #Found >= 3 then
                local Rate, Damage, Health = Found[1], Found[2], Found[3]
                for _, Number: number in Found do
                    Health = math.max(Health, Number)
                end

                if Rate > 0 and Damage > 0 then
                    local Hits: number = math.ceil(Health / Damage)
                    local Seconds: number = Hits / Rate
                    return Mind.Reply(Mind.Join(`You need {Hits} hits ({Show(Health)} / {Show(Damage)}, rounded up), and at {Show(Rate)} hits a second that takes {Show(math.floor(Seconds * 100 + 0.5) / 100)} seconds.`, "That ignores armour, knockback and misses, so real fights run a bit longer."))
                end
            end

            -- half, double
            if L:match("%f[%a]half of%f[%A]") and Value then
                return Mind.Reply(`Half of {Show(Value)} is {Show(Value / 2)}.`)
            elseif L:match("%f[%a]double%f[%A]") and Value and Frame.Count <= 6 then
                return Mind.Reply(`Double {Show(Value)} is {Show(Value * 2)}.`)
            elseif L:match("%f[%a]round%f[%A]") and Value then
                return Mind.Reply(`{Show(Value)} rounds to {Show(math.floor(Value + 0.5))}.`)
            end

            return nil
        end)
        table.insert(Mind.Acts, 1, table.remove(Mind.Acts))
        end
        -- ---------------------------------------------------------------- several questions in one message

        do
        local Act = Mind.Act

        -- One message, answered the way a typed message would be (strong acts, old pipeline, then the checks), without recording history.
        function Mind.Answer(Raw: string)
            local Early = Mind.Pre(Raw)
            if Early then
                return Early
            end

            Brain.LastDecision = nil
            local Result = Brain.ThinkCore(Raw, true)
            return Mind.Post(Raw, Result, Brain.LastDecision) or Result
        end

        local Joiners = {" and tell me ", " and give me ", " and explain ", " and show me ", " and name ", " and list ", " and rate ", " then explain ", " then tell me ", " then give me ", ", then ", " and also ", " also ", " plus ", " one more thing ", " and then ", ", and ", " and whats ", " and what's ", " and how ", " and why ", " and who ", " and can ", " and do ", " and is ", " and are ", " and should ", " and which ", " and where ", ", turn on ", ", turn off ", " and turn on ", " and turn off ", ", enable ", ", disable "}
        local Asking = Brain.Set("what whats how why who which when where do does did can could would should will is are am")

        local function Pieces(Raw: string): {string}
            local Parts: {string} = {}

            -- numbered lists: "1) a 2) b"
            if select(2, Raw:gsub("%d[%)%.]%s", "")) >= 2 then
                local Text: string = " " .. Raw
                local Starts = {}
                for Position: number in Text:gmatch("()%s%d[%)%.]%s") do
                    table.insert(Starts, Position)
                end

                for i: number, Start: number in Starts do
                    local Stop: number = (Starts[i + 1] or #Text + 1) - 1
                    local Piece: string = Text:sub(Start, Stop):gsub("^%s*%d[%)%.]%s*", ""):gsub("%s+$", "")
                    if #Piece > 1 then
                        table.insert(Parts, Piece)
                    end
                end

                if #Parts >= 2 then
                    return Parts
                end

                Parts = {}
            end

            -- split at sentence ends, then at joiners that start a new clause
            local Sentences: {string} = {}
            local Rest: string = Raw
            while true do
                local Piece, After = Rest:match("^(.-[%?%.!]+)%s+(.*)$")
                if not Piece then
                    break
                end

                table.insert(Sentences, Piece)
                Rest = After
            end

            if Rest ~= "" then
                table.insert(Sentences, Rest)
            end

            for _, Sentence: string in Sentences do
                local Cut: {string} = {Sentence}
                for _, Joiner: string in Joiners do
                    local Next: {string} = {}
                    for _, Chunk: string in Cut do
                        local Padded: string = ` {Chunk:lower()} `
                        local Start = Padded:find(Joiner, 1, true)
                        if Start and Start > 6 then
                            table.insert(Next, (Chunk:sub(1, Start - 1):gsub("%s+$", "")))
                            local Remainder: string = Chunk:sub(Start + #Joiner - 1):gsub("^%s+", "")
                            local Lead: string? = Joiner:match("^ and (.+) $") or Joiner:match("^ then (.+) $") or Joiner:match("^, (turn o.+) $") or Joiner:match("^, (enable) $") or Joiner:match("^, (disable) $")
                            if Joiner:match("^ and (also)") or Joiner:match("^ and then") then
                                Lead = nil
                            end

                            if Lead then
                                Remainder = `{Lead} {Remainder}`
                            end

                            table.insert(Next, Remainder)
                        else
                            table.insert(Next, Chunk)
                        end
                    end

                    Cut = Next
                end

                for _, Chunk: string in Cut do
                    Chunk = Chunk:match("^%s*(.-)%s*$")
                    if #Chunk > 1 then
                        table.insert(Parts, Chunk)
                    end
                end
            end

            return Parts
        end

        Act("Multi", function(Frame): boolean
            if Frame.Count < 6 then
                return false
            end

            local Parts = Pieces(Frame.Raw)
            if #Parts < 2 or #Parts > 5 then
                return false
            end

            local Real: number = 0
            for _, Part: string in Parts do
                if #Mind.WordsOf(Mind.Clean(Part)) >= 2 then
                    Real += 1
                end
            end

            local Marks: number = select(2, Frame.Raw:gsub("%?", ""))
            local Numbered: number = select(2, Frame.Raw:gsub("%d[%)%.]%s", ""))
            local Linked: boolean = false
            for _, Joiner: string in {" and tell me ", " and give me ", " and explain ", " and show me ", " and name ", " and list ", " and rate ", " then explain ", " then tell me ", " then give me ", ", then ", " and is ", " and are ", " and does ", " and do ", " and can ", " and how ", " and what ", " and why ", " and which ", " and should ", " and will ", ", turn on ", ", turn off ", " and turn on ", " and turn off ", ", enable ", ", disable "} do
                Linked = Linked or (` {Frame.Lower} `):find(Joiner, 1, true) ~= nil
            end

            return Real >= 2 and (Marks >= 2 or Numbered >= 2 or Linked or Frame.Lower:find("also", 1, true) ~= nil or Frame.Lower:find("one more thing", 1, true) ~= nil)
        end, function(Frame)
            local Parts = Pieces(Frame.Raw)
            local Answers: {string} = {}
            local Chips
            for i: number, Part: string in Parts do
                Part = Mind.Dialog.Resolve(Part) or Part
                local Result = Mind.Answer(Part)
                Mind.Dialog.Remember(Mind.Frame, Result)
                Mind.Frame = Frame
                local Sentences = Mind.Sentences(Result.Text)
                local Short: string = table.concat(Sentences, " ", 1, math.min(#Sentences, 3))
                if Result.Act == "Creative" then
                    Short = (Result.Text:gsub("^[^\n]*\n\n", ""))
                end
                if #Short > 320 then
                    Short = Short:sub(1, 317):gsub("%s+%S*$", "") .. "..."
                end

                table.insert(Answers, `{i}. {Short ~= "" and Short or Result.Text}`)
                Chips = Result.Actions or Chips
            end

            return {Text = Mind.Lines(Mind.Any(`That's {#Parts} things, so one at a time:`, `{#Parts} questions in one, let me take them in order:`, "Okay, taking those in order:"), table.concat(Answers, "\n\n")), Actions = Chips}
        end)
        table.insert(Mind.Acts, 1, table.remove(Mind.Acts))
        end

        -- ---------------------------------------------------------------- more text tasks, checked before the first text act

        do
        local Act = Mind.Act

        local Fillers = {" no cheating", " please", " pls", " lol", " tho", " though", " thanks", " thx", " fast", " now", " for me", " quickly"}

        local function Strip(Text: string): string
            for _, Filler: string in Fillers do
                Text = Text:gsub(Filler .. "$", "")
            end

            Text = Text:gsub("^the word ", ""):gsub("^the name ", ""):gsub("^word ", "")
            return Text
        end

        local Ordinals = {first = 1, second = 2, third = 3, fourth = 4, fifth = 5, sixth = 6, seventh = 7, eighth = 8, ninth = 9, tenth = 10, last = -1}

        local function Polite(C: string): string
            return (C:gsub("^can you ", ""):gsub("^could you ", ""):gsub("^would you ", ""):gsub("^will you ", ""):gsub("^please ", ""):gsub("^pls ", ""):gsub("^hey ", ""):gsub("^can u ", ""))
        end

        Act("Text2", function(Frame): boolean
            local C = Polite(Frame.Clean)
            return C:match("^count the %a+ in ") ~= nil or C:match("^how many %a+ are in ") ~= nil and (Frame.Set.letters or Frame.Set.vowels or Frame.Set.consonants) or C:match("^how many letters in ") ~= nil or C:match("^how many vowels in ") ~= nil or C:match("^how many consonants in ") ~= nil
                or C:match("the %d+%a%a letter") ~= nil or C:match("^count to %d+ backwards?") ~= nil or C:match("^count backwards? from") ~= nil or C:match("^count down") ~= nil
                or C:find("abc order", 1, true) ~= nil or C:find("alphabetical order", 1, true) ~= nil or C:find("alphabetically", 1, true) ~= nil
                or (C:find("alphabet", 1, true) ~= nil and (C:find("skip", 1, true) ~= nil or C:find("without", 1, true) ~= nil))
                or (C:match("^say .+ %d+ times") ~= nil) or C:match("^repeat .+ %d+ times") ~= nil
        end, function(Frame)
            local C = Polite(Frame.Clean)

            -- count the vowels / how many letters in a word
            local Kind: string?, Thing: string? = C:match("^count the (%a+) in (.+)$")
            if not Kind then
                Kind, Thing = C:match("^how many (%a+) are in (.+)$")
            end

            if not Kind then
                Kind, Thing = C:match("^how many (%a+) in (.+)$")
            end

            if Kind and Thing and (Kind == "letters" or Kind == "vowels" or Kind == "consonants") then
                Thing = Strip(Thing)
                if Thing == "your name" then
                    Thing = AssistantName
                end

                local Letters: string = Thing:lower():gsub("[^%a]", "")
                local Vowels: number = select(2, Letters:gsub("[aeiou]", ""))
                local Count: number = Kind == "letters" and #Letters or Kind == "vowels" and Vowels or #Letters - Vowels
                return Mind.Reply(Mind.Join(`"{Thing}" has {Count} {Kind}.`, Kind == "vowels" and Count > 0 and `They are {(Letters:gsub("[^aeiou]", ""):gsub(".", "%0 "):gsub(" $", ""))}.` or ""))
            end

            -- nth letter with digits or words
            local Digits: string?, Subject2: string? = C:match("the (%d+)%a%a letter of (.+)$")
            if not Digits then
                Digits, Subject2 = C:match("the (%d+)%a%a letter in (.+)$")
            end

            if Digits and Subject2 then
                local Word: string = Strip(Subject2):gsub("%s", "")
                local Position: number = tonumber(Digits) or 1
                if Position >= 1 and Position <= #Word then
                    return Mind.Reply(`The {Digits}{Position == 1 and "st" or Position == 2 and "nd" or Position == 3 and "rd" or "th"} letter of "{Word}" is "{Word:sub(Position, Position)}".`)
                end

                return Mind.Reply(`"{Word}" only has {#Word} letters, so there's no letter number {Digits}.`)
            end

            -- counting down
            local From: string? = C:match("^count to (%d+) backwards?") or C:match("^count down from (%d+)") or C:match("^count backwards? from (%d+)")
            if not From then
                local Spelled = C:match("^count to (%a+) backwards?") or C:match("^count down from (%a+)")
                From = Spelled and tostring(Mind.ParseNumber(Spelled) or "") or nil
            end

            if From and tonumber(From) then
                local Start: number = math.clamp(tonumber(From) :: number, 1, 40)
                local List = {}
                for Value: number = Start, 1, -1 do
                    table.insert(List, tostring(Value))
                end

                return Mind.Reply(Mind.Join(table.concat(List, ", ") .. ".", Mind.Chance(0.5) and "Liftoff." or ""))
            end

            -- sorting a list
            if C:find("abc order") or C:find("alphabetical order") or C:find("alphabetically") then
                local Source: string = Frame.Raw:match("[:]%s*(.+)$") or Frame.Raw:match("[Oo]rder%s+(.+)$") or ""
                local Items = {}
                for Piece: string in Source:gmatch("[^,]+") do
                    Piece = Piece:gsub("^%s*and%s+", ""):gsub("^%s+", ""):gsub("%s+$", ""):gsub("[%.%?]$", "")
                    if Piece ~= "" then
                        table.insert(Items, Piece)
                    end
                end

                if #Items >= 2 then
                    table.sort(Items, function(A, B)
                        return A:lower() < B:lower()
                    end)

                    return Mind.Reply(Mind.Join("In alphabetical order:", table.concat(Items, ", ") .. "."))
                end
            end

            -- alphabet without something
            if C:find("alphabet") then
                local Skip: string = (C:find("vowel") and "[aeiou]") or (C:find("consonant") and "[^aeiou]") or ""
                if Skip ~= "" then
                    local Letters = {}
                    for Code: number = 97, 122 do
                        local Letter: string = string.char(Code)
                        if not Letter:match(Skip) then
                            table.insert(Letters, Letter)
                        end
                    end

                    return Mind.Reply(table.concat(Letters, " "))
                end
            end

            -- say something several times
            local What: string?, Times: string? = C:match("^say (.+) (%d+) times")
            if not What then
                What, Times = C:match("^repeat (.+) (%d+) times")
            end

            if What and Times then
                What = Strip(What:gsub(" fast$", ""))
                if What == "your name" then
                    What = AssistantName
                end

                local N: number = math.clamp(tonumber(Times) or 1, 1, 10)
                if Mind.Unsafe(What) then
                    return Mind.Reply("I'll pass on that one, but pick another word and I'll say it as many times as you like.")
                end

                local Parts = {}
                for _ = 1, N do
                    table.insert(Parts, What)
                end

                return Mind.Reply(table.concat(Parts, " ") .. (C:find("fast") and "! Whew, that was fast." or "."))
            end

            return nil
        end)
        table.insert(Mind.Acts, 1, table.remove(Mind.Acts))

        -- ---------------------------------------------------------------- about the chat so far

        Act("Meta2", function(Frame): boolean
            local C = Frame.Clean
            return C:find("how many messages", 1, true) ~= nil or C:find("stop repeating", 1, true) ~= nil or C:find("keep repeating", 1, true) ~= nil or C:find("repeating yourself", 1, true) ~= nil or C:find("repeating urself", 1, true) ~= nil or C:find("contradict", 1, true) ~= nil or C:find("scroll up", 1, true) ~= nil or C:find("mentioned earlier", 1, true) ~= nil
                or (C:find("summar", 1, true) ~= nil and (C:find("conversation", 1, true) ~= nil or C:find("chat", 1, true) ~= nil)) or C:find("first thing i ever said", 1, true) ~= nil or C:find("first thing i said", 1, true) ~= nil or C:find("i didnt ask for that", 1, true) ~= nil or C:find("answer the question i actually asked", 1, true) ~= nil
        end, function(Frame)
            local C = Frame.Clean
            local History = Mind.History
            local Last = History[#History]
            if C:find("how many messages") then
                return Mind.Reply(Mind.Join(`Counting this one, you've sent {#History + 1} message{#History == 0 and "" or "s"} and I've sent {#History} repl{#History == 1 and "y" or "ies"}, so {#History * 2 + 1} in this chat.`, #History == 0 and "So we're just getting started." or ""))
            elseif C:find("repeating") then
                return Mind.Reply(Mind.Join(Mind.Any("Sorry, I do that when I can't find a better answer.", "You're right, I'm looping a bit."), "Rephrase it, or tell me what you're really after, and I'll try a different route."))
            elseif C:find("contradict") then
                return Mind.Reply(Mind.Join("Sorry about that.", Last and `My last answer started with: "{(Mind.Sentences(Last.A)[1] or Last.A):sub(1, 100)}".` or "", "Tell me which part conflicts. For anything about your own settings, trust the live values I read, they're always current."))
            elseif C:find("scroll up") or C:find("mentioned earlier") then
                local Seen, Names = {}, {}
                for _, Entry in History do
                    for _, Name: string in Entry.Names or {} do
                        if not Seen[Name] then
                            Seen[Name] = true
                            table.insert(Names, Name)
                        end
                    end
                end

                if #Names > 0 then
                    return Mind.Reply(Mind.Join(`The modules we've talked about in this chat: {Mind.Oxford(Names)}.`, "Is it one of those?"))
                end

                return Mind.Reply("I haven't mentioned a specific module yet in this chat, so I can't point you to one. Which one are you thinking of?")
            elseif C:find("summar") then
                local N: number = tonumber(C:match("in (%d+) words")) or Mind.ParseNumber(C:match("in (%a+) words") or "") or 8
                local Words = {}
                for _, Entry in History do
                    for _, Word: string in Mind.Content(Mind.WordsOf(Mind.Clean(Entry.Q))) do
                        if not table.find(Words, Word) then
                            table.insert(Words, Word)
                        end
                    end
                end

                if #Words == 0 then
                    return Mind.Reply("There's nothing to summarise yet, we've only just started.")
                end

                local Picked = {}
                for i: number = 1, math.min(N, #Words) do
                    table.insert(Picked, Words[i])
                end

                return Mind.Reply(Mind.Join(`In {#Picked} words:`, Mind.Cap(table.concat(Picked, " ")) .. "."))
            elseif C:find("first thing") then
                local First = History[1]
                return Mind.Reply(First and `The first thing you said to me was "{First.Q:sub(1, 100)}".` or "You haven't said anything before this, this is your first message.")
            end

            return Mind.Reply(Mind.Join(Mind.Any("Sorry, my mistake.", "Fair, I missed it."), Last and `You asked "{Last.Q:sub(1, 80)}".` or "", "Say it again in a different way and I'll answer that exactly."))
        end)
        table.insert(Mind.Acts, 1, table.remove(Mind.Acts))

        -- ---------------------------------------------------------------- short vague replies with nothing behind them

        Act("VagueCold", function(Frame): boolean
            local C = Frame.Clean
            if Frame.Count > 6 or Frame.Evidence >= 2 or Mind.History[#Mind.History] or Mind.Plan and (Mind.Plan.Active or Mind.Plan.Stored()) then
                return false
            end

            return C:match("^wait which") ~= nil or C:match("^which one") ~= nil or C:match("^how much though") ~= nil or C:match("^and the other") ~= nil or C:match("^the other") ~= nil or C:match("^nah the other") ~= nil or C:match("^like what") ~= nil or C:match("^what next") ~= nil or C:match("^alright what") ~= nil or C == "why though" or C == "how though" or C == "why" or C == "and" or C == "but why" or C:match("^and if it") ~= nil or C:match("^can u do that again") ~= nil or C:match("^can you do that again") ~= nil or C:match("^but why") ~= nil
        end, function(Frame)
            return Mind.Reply(Mind.Join(
                Mind.Any("We haven't talked about anything yet, so I'm not sure what you're pointing at.", "I don't have anything earlier in this chat to go on.", "That sounds like a follow-up, but this is the first thing in our chat."),
                Mind.Any("Tell me the module or the topic and I'll answer.", "Which module or question do you mean?")
            ), {"What can you do?"})
        end)
        end

        do
        local Act = Mind.Act
        -- ---------------------------------------------------------------- topics and small generators

        local TopicStops = Brain.Set("a an the my your our their his her its this that these those some any please pls plz lol lmao haha now then too also again just really very")

        -- What a request is about: "poem about killaura" -> "killaura". Falls back to a module in the message.
        function Mind.TopicOf(Frame): (string?, any)
            local Topic: string? = nil
            for _, Marker: string in {"about", "on", "for", "of", "regarding", "featuring", "involving", "with"} do
                local Found: string? = Frame.Clean:match(`%f[%a]{Marker}%f[%A] (.+)$`)
                if Found then
                    Topic = Found
                    break
                end
            end

            local Entry = Frame.Mentions[1] and Frame.Mentions[1].Entry or nil
            if Topic then
                local Words: {string} = Mind.WordsOf(Topic)
                while #Words > 0 and TopicStops[Words[#Words]] do
                    table.remove(Words)
                end

                while #Words > 0 and TopicStops[Words[1]] do
                    table.remove(Words, 1)
                end

                for i: number, Word: string in Words do
                    if i > 1 and (Word == "and" or Word == "then" or Word == "but" or Word == "also") then
                        Words = table.move(Words, 1, i - 1, 1, {})
                        break
                    end
                end

                if #Words > 5 then
                    Words = table.move(Words, 1, 5, 1, {})
                end

                Topic = table.concat(Words, " ")
            end

            if (not Topic or Topic == "") and Entry then
                Topic = Entry.Name
            end

            return Topic ~= "" and Topic or nil, Entry
        end

        local function Title(Text: string): string
            return (Text:gsub("(%a)(%a*)", function(First: string, Rest: string): string
                return First:upper() .. Rest
            end))
        end

        -- A line of exactly Target syllables built from three slot pools. Topic, when given, leads the first slot.
        local function FitLine(Target: number, Slots: {{string}}, Lead: string?): string?
            for _ = 1, 400 do
                local Parts, Total = {}, 0
                for i: number, Pool in Slots do
                    local Part: string? = i == 1 and Lead or nil
                    if not Part and (i ~= #Slots or math.random() < 0.8 or Total == 0) then
                        Part = Pool[math.random(1, #Pool)]
                    end

                    if Part then
                        table.insert(Parts, Part)
                        Total += Mind.PhraseSyllables(Part)
                    end
                end

                if Total == Target then
                    return table.concat(Parts, " ")
                end
            end

            return nil
        end

        local HaikuSubjects = {"the bed", "a lone cat", "soft menu glow", "the void", "iron ingots", "my last block", "midnight lobby", "the old map", "quiet footsteps", "a bridge", "the sword", "pink wool", "the diamond", "one more game", "a tired thumb"}
        local HaikuVerbs = {"waits", "falls", "glows", "sings", "hums softly", "dreams of rain", "keeps watch", "breaks apart", "shines", "fades slowly", "learns to jump", "stays awake", "starts to run", "rests", "sleeps"}
        local HaikuPlaces = {"in the dark", "above the void", "at first light", "on the island", "where we spawned", "beyond the wall", "once again", "by the bed", "tonight", "under stars", "after the win", "in the rain", "without a sound"}

        local function DescriptionChunk(Entry, Target: number): string?
            if not Entry then
                return nil
            end

            local Words = Mind.WordsOf(Mind.Clean(Mind.Describe(Entry)))
            for Start: number = 1, #Words do
                local Total: number = 0
                for Stop: number = Start, #Words do
                    Total += Mind.Syllables(Words[Stop])
                    if Total == Target then
                        return table.concat(Words, " ", Start, Stop)
                    elseif Total > Target then
                        break
                    end
                end
            end

            return nil
        end

        local function Haiku(Topic: string?, Entry): string
            local Lead: string? = Topic and Mind.PhraseSyllables(Topic) <= 3 and Topic or nil
            local First: string = FitLine(5, {HaikuSubjects, HaikuVerbs, HaikuPlaces}, Lead) or `{Title(Topic or "the bed")} waits tonight`
            local Second: string = DescriptionChunk(Entry, 7) or FitLine(7, {HaikuSubjects, HaikuVerbs, HaikuPlaces}) or "the iron keeps on falling"
            local Third: string = FitLine(5, {HaikuSubjects, HaikuVerbs, HaikuPlaces}) or "the night is long"
            return `{Mind.Cap(First)},\n{Mind.Cap(Second)},\n{Mind.Cap(Third)}.`
        end

        -- Couplets are written as two lines that rhyme, with {T} for the topic.
        local PoemOpeners = {
            {"{T} showed up one quiet night,", "and suddenly the game felt right."},
            {"In the lobby, {T} on my mind,", "the best of all I hoped to find."},
            {"Some say {T} is only code,", "but it has walked a lonely road."},
            {"Whenever {T} shows up on screen,", "it's the best thing I have seen."},
            {"I opened up the menu wide,", "and {T} was waiting there inside."},
            {"They told me {T} is just a tool,", "but it's the one that makes me cool."}
        }
        local PoemMiddles = {
            {"The beds go down, the iron flows,", "and no one knows how far it goes."},
            {"A bridge of wool, a bed to guard,", "the game is fun, the win is hard."},
            {"One more game, then I will quit,", "(said the one who never did it)."},
            {"The generators hum all day,", "and nobody can look away."},
            {"We rush across the void so thin,", "the only goal is how to win."},
            {"A tiny block, a sword, a dream,", "we work together as a team."}
        }
        local PoemClosers = {
            {"So here's my rhyme, it's nearly done,", "go load a game and have some fun."},
            {"That's all I've got, my poem's through,", "now go and win one, just for you."},
            {"The sun goes down, the lobby's still,", "I'll keep on playing, and I will."},
            {"And when the final bed is gone,", "we'll queue again and carry on."}
        }

        local RapBars = {
            {"I walk in the lobby with {T} on my side,", "the whole server knows I came here with pride."},
            {"{T} on the beat, I'm bridging so fast,", "they blink and they miss it, the moment is past."},
            {"Iron in my pocket, emeralds in sight,", "I break their bed down and I run off in the night."},
            {"Say what you want, I'm still in the game,", "{T} on my screen, nobody the same."},
            {"Bed's on the island, guarded with wool,", "I'm chilling at spawn but my config is cool."},
            {"They talk about skill but they don't know the plan,", "{T} in the menu, I'm the best that I can."}
        }

        local function Rhyme(Banks: {{{string}}}, Topic: string, Count: number): string
            local Lines: {string} = {}
            local Used = {}
            for _ = 1, Count do
                local Pair
                for _ = 1, 8 do
                    Pair = Mind.From(Banks[math.random(1, #Banks)])
                    if not Used[Pair] then
                        break
                    end
                end

                Used[Pair] = true
                for _, Line: string in Pair do
                    table.insert(Lines, (Line:gsub("{T}", Topic)))
                end
            end

            return table.concat(Lines, "\n")
        end

        local NickPrefix = {"Shadow", "Turbo", "Mega", "Captain", "Sir", "Lord", "Neon", "Pixel", "Iron", "Void", "Sweaty", "Clutch", "Ghost", "Frost", "Thunder", "Cosmic", "Tiny", "Royal", "Lucky", "Sneaky"}
        local NickCore = {"Paw", "Whisker", "Fox", "Wolf", "Pilot", "Sniper", "Baron", "Knight", "Wizard", "Raider", "Nomad", "Cat", "Tiger", "Falcon", "Ninja"}
        local NickSuffix = {"", "", "", "_YT", "99", "Jr", "Prime", "Pro", "XD", "_"}

        local function NickNames(Seeds: {string}): {string}
            local Names: {string} = {}
            for _ = 1, 5 do
                local Seed: string = #Seeds > 0 and Title(Seeds[math.random(1, #Seeds)]) or ""
                local Style: number = math.random(1, 4)
                local Name: string
                if Seed ~= "" and Style == 1 then
                    Name = `{Seed}{Mind.From(NickCore)}`
                elseif Seed ~= "" and Style == 2 then
                    Name = `{Mind.From(NickPrefix)}{Seed}`
                elseif Style == 3 then
                    Name = `{Mind.From(NickPrefix)}{Mind.From(NickCore)}`
                else
                    Name = `{Mind.From(NickCore)}{math.random(2, 99)}`
                end

                table.insert(Names, Name .. Mind.From(NickSuffix))
            end

            return Names
        end

        local SloganFrames = {
            "{T}: {B}.", "{T}. {B}.", "Get {T}. {B}.", "{T} means {B}.", "Think {T}. Think {B}.", "{B}, thanks to {T}.", "Nobody does it like {T}."
        }
        local SloganBenefits = {"play like you mean it", "the island is yours", "every game is a good game", "built for the grind", "your bed is safer than you think", "made for people who hate losing", "clutch is a lifestyle", "less thinking, more winning"}

        local StoryOpeners = {
            "On a foggy night over the BedWars islands,", "In a lobby that smelled like fresh wool,", "Nobody remembers how the match began, but", "At the very edge of the void,", "While everyone else was queuing up,"
        }
        local StoryHeroes = {"a tiny player", "a sleepy cat", "a kid with one iron sword", "a lone bridger", "a player with a very old config"}
        local StoryTurns = {
            "found out that the enemy bed had no blocks around it at all",
            "heard footsteps coming from every side at once",
            "lost the last of the iron to a very unlucky fall",
            "noticed the whole team had gone silent",
            "realised the generator was making emeralds twice as fast"
        }
        local StoryEnds = {
            "In the end, the bed fell, the team cheered, and the cat on the menu purred.",
            "They won anyway, mostly by being stubborn, and queued again right after.",
            "It did not go to plan, but it was the best game of the week.",
            "Nobody could explain it, so everybody just called it clutch.",
            "And that is why you should always check behind you."
        }

        -- {W} is the subject, {play} style words are conjugated for it, {X} is the thing they keep doing when the user said one.
        local RoastFrames = {
            "{W} {play} like the bed is a suggestion.",
            "{W} {bridge} like the void owes {them} money.",
            "{W} {bring} a wool block to a diamond sword fight, and honestly it works about half the time.",
            "{W} {check} the shop more often than the minimap.",
            "{W} {see} an open bed and somehow still {find} a way to run into the void."
        }
        local RoastClauseFrames = {
            "{W} {X}? That's not a skill issue, that's a lifestyle.",
            "If {W} {X}, honestly the void should start charging rent.",
            "{W} {X}. Impressive consistency, at least.",
            "{W} {X}, and somehow the rest of the lobby is the one that gets blamed."
        }
        local RoastClosers = {"All love though, you'd roast me too.", "Said with respect.", "That's the nicest roast I know."}

        local JokeFrames = {
            "I asked {T} for advice. It said \"maybe turn me off first.\"",
            "Why did {T} get kicked from the party? It kept leaving at the worst moment.",
            "{T} walked into a lobby and everyone went quiet. That's how you know it was good.",
            "What do you call {T} with no config? A very confused beginner.",
            "My friend says {T} is overrated. He also says he's \"just bad at the game,\" which checks out."
        }

        Act("Creative", function(Frame): boolean
            local C = Frame.Clean
            local Verb: boolean = Frame.Set.write or Frame.Set.make or Frame.Set.compose or Frame.Set.create or Frame.Set.give or Frame.Set.tell or Frame.Set.generate or Frame.Set.come or Frame.Set.need or Frame.Set.got or Frame.Set.drop or Frame.Set.rap
            if C:find("clan name", 1, true) or C:find("team name", 1, true) or C:find("guild", 1, true) or C:find("squad name", 1, true) or C:find("crew name", 1, true) or C:find("kit idea", 1, true) or C:find("new kit", 1, true) or C:find("invent", 1, true) or C:find("name for my team", 1, true) then
                return false
            end

            local Wants: boolean = Frame.Set.give or Frame.Set.make or Frame.Set.need or Frame.Set.suggest or Frame.Set.generate or Frame.Set.think or Frame.Set.come or Frame.Set.can or Frame.Set.could or Frame.Set.help or Frame.Set.pick
            local Naming: boolean = Wants and not Frame.Set.hide and not Frame.Set.change and not Frame.Set.spoof and (Frame.Set.name or Frame.Set.names) and (C:find("name for", 1, true) ~= nil or C:find("names for", 1, true) ~= nil or C:find("name my", 1, true) ~= nil or C:find("name the", 1, true) ~= nil or C:find("a name", 1, true) ~= nil or Frame.Set.username or Frame.Set.usernames)
            local Kind: boolean = Frame.Set.poem or Frame.Set.haiku or Frame.Set.rap or Frame.Set.limerick or Frame.Set.slogan or Frame.Set.nickname or Frame.Set.story or Frame.Set.roast or Frame.Set.song or Frame.Set.lyrics or Naming or Frame.Set.joke or Frame.Set.verse or Frame.Set.sonnet or Frame.Set.tagline
            local Asks: boolean = Verb or C:match("^can you") ~= nil or C:match("^could you") ~= nil or C:match("^roast") ~= nil
            if Frame.Set.your and (Frame.Set.name or Frame.Set.names) then
                return false
            end

            if Kind and Frame.Count <= 14 and (C:match("^an? %a+ about ") or C:match("^an? %a+ for ") or C:match("^%a+ about ")) and not C:match("what does") then
                return true
            end

            return (Asks and Kind and not C:match("what does")) or C:match("^roast ") ~= nil or C:match("^rap about") ~= nil or C:match("^poem about") ~= nil or C:match("^haiku") ~= nil or C:match("^joke about") ~= nil
        end, function(Frame)
            local C = Frame.Clean
            local Topic, Entry = Mind.TopicOf(Frame)
            local Subject: string = Topic and Mind.Turn(Topic) or "CatVape"
            if Mind.Unsafe(Subject) then
                return Mind.Reply("I'll sit that one out, but give me another subject and I'll write it.")
            end

            if Frame.Set.joke and not Topic then
                return nil
            end

            local Shown: string = Entry and Entry.Name or Subject
            local Intro: string = Mind.Any("Here you go.", "Okay, let me try.", "Sure thing.", "How about this?", "Alright, composing.", "Give me a second...")
            if Frame.Register.Short then
                Intro = ""
            end

            if Frame.Set.haiku then
                return Mind.Reply(Mind.Lines(Intro, Haiku(Shown, Entry)), {"Another one"})
            elseif Frame.Set.rap then
                return Mind.Reply(Mind.Lines(Intro, Rhyme({RapBars}, Shown, 2)), {"Another verse"})
            elseif Frame.Set.poem or Frame.Set.verse or Frame.Set.sonnet or Frame.Set.limerick or Frame.Set.song or Frame.Set.lyrics then
                local Poem: string = Rhyme({PoemOpeners, PoemMiddles, PoemClosers}, Shown, 3)
                local Wanted: number? = tonumber(C:match("(%d+) line")) or tonumber(C:match("(%d+)%-line")) or Mind.ParseNumber(C:match("(%a+) line") or "")
                if Wanted and Wanted >= 1 and Wanted <= 12 then
                    local Cut = {}
                    for Line: string in Poem:gmatch("[^\n]+") do
                        if #Cut < Wanted then
                            table.insert(Cut, Line)
                        end
                    end

                    Poem = table.concat(Cut, "\n")
                end

                return Mind.Reply(Mind.Lines(Intro, Poem), {"Another poem"})
            elseif Frame.Set.slogan or Frame.Set.tagline then
                if not Entry and #Mind.WordsOf(Shown) > 3 then
                    Shown = "CatVape"
                end

                local Benefit: string = Mind.From(SloganBenefits)
                local Lines: {string} = {}
                for _ = 1, 3 do
                    local Frame2: string = Mind.From(SloganFrames)
                    Frame2 = Frame2:gsub("{T}", Shown)
                    Frame2 = Frame2:gsub("{B}", Mind.Chance(0.5) and Mind.From(SloganBenefits) or Benefit)
                    table.insert(Lines, `- {Frame2}`)
                end

                return Mind.Reply(Mind.Lines(Intro, table.concat(Lines, "\n")))
            elseif Frame.Set.nickname or Frame.Set.name or Frame.Set.names or Frame.Set.username or Frame.Set.usernames then
                local Seeds: {string} = {}
                local NameStops = Brain.Set("my your name names nickname nicknames cool good best new cat friend brother sister dog bot who that always never keeps keep really very gets does doing been being have has had with from into about when because just still ever one some what which")
                for _, Word: string in Mind.WordsOf(Topic or "") do
                    if #Word >= 3 and not TopicStops[Word] and not NameStops[Word] then
                        Word = Word:gsub("ing$", ""):gsub("ers$", "er"):gsub("([^s])s$", "%1")
                        table.insert(Seeds, Word)
                    end
                end

                local Names = NickNames(Seeds)
                return Mind.Reply(Mind.Lines(Intro, `{table.concat(Names, ", ")}.`, `My pick is {Names[math.random(1, #Names)]}, it just sounds like someone who wins.`), {"More names"})
            elseif Frame.Set.story then
                local Story: string = Mind.Join(Mind.From(StoryOpeners), `{Entry and Entry.Name or Mind.From(StoryHeroes)}`, Mind.Any("set out to win one last game,", "decided to try something different,"), Mind.From(StoryTurns) .. ".", Mind.From(StoryEnds))
                return Mind.Reply(Mind.Lines(Intro, Story), {"Another story"})
            elseif Frame.Set.roast then
                local Target: string? = C:match("^roast (.+)$") or C:match("roast (.+)$") or (Topic and Topic ~= "CatVape" and not Entry) and Topic or nil
                local Who: string = "You"
                local Clause: string?
                if Target and not Entry then
                    Target = Target:gsub("^my ", "your "):gsub("^me$", "you"):gsub(" pls$", ""):gsub(" please$", "")
                    local Head, Rest = Target:match("^(.-) who (.+)$")
                    if not Head then
                        Head, Rest = Target:match("^(.-) that (.+)$")
                    end

                    Head = Head or Target
                    Clause = Rest and Mind.Turn(Rest)
                    if Head ~= "" and Head ~= "me" and Head ~= "you" and Head ~= "myself" and Head ~= "yourself" then
                        Who = Mind.Cap(Mind.Turn(Head))
                    end
                end

                if Frame.Set.you or Frame.Set.yourself then
                    return Mind.Reply(Mind.Any("Roast me? I live inside a menu and my biggest accomplishment is knowing what a slider does. There, I did it for you.", "Fine: I'm a chatbot that gets excited about toggles. Go ahead and laugh, I can take it."))
                end

                local Plural: boolean = Who == "You" or Who:lower():match("s$") ~= nil and not Who:lower():match("ss$")
                local Burn: string = Clause and Mind.From(RoastClauseFrames) or Mind.From(RoastFrames)
                local Inline: string = Burn:match("^{W}") and Who or Who:gsub("^%u", string.lower)
                Burn = Burn:gsub("{X}", Clause or ""):gsub("{W}", Inline)
                Burn = Burn:gsub("{(%a+)}", function(Word: string): string
                    if Word == "them" then
                        return Plural and "you" or "them"
                    end

                    local Forms = {play = "plays", bridge = "bridges", bring = "brings", check = "checks", see = "sees", find = "finds"}
                    return Plural and Word or Forms[Word] or Word
                end)
                return Mind.Reply(Mind.Join(Burn, Mind.From(RoastClosers)), {"Roast me again"})
            end

            local Joke: string = Mind.From(JokeFrames)
            Joke = Joke:gsub("{T}", Shown)
            return Mind.Reply(Mind.Lines(Intro, Joke), {"Tell me another"})
        end)

        -- ---------------------------------------------------------------- style: explain something a certain way

        local Blurbs = {
            menu = "CatVape's menu is a window of tabs, each full of toggles and sliders called modules, and you click a module to turn it on or right click it for settings",
            bedwars = "BedWars is a team game: each team has a bed on its island, you collect iron, gold, diamonds and emeralds, spend them on gear and blocks, break the other teams' beds and be the last team standing",
            catvape = "CatVape is a script menu with modules (toggles and sliders) that help you in a game, like attacking, moving, seeing more or building faster, and you can save your setups as profiles",
            ["illegal soccer"] = "Illegal Soccer is a football game where you chase the ball and score goals",
            soccer = "Illegal Soccer is a football game where you chase the ball and score goals",
            ["tower of hell"] = "Tower of Hell is an obstacle course where you climb a tower that changes every round",
            profile = "A profile saves all your module settings so you can load the same setup again later",
            config = "A config saves all your module settings so you can load the same setup again later"
        }

        local Simple = {
            velocity = "speed", teleports = "jumps", teleport = "jump", teleporting = "jumping", pathfinding = "finding a way", projectile = "thrown thing", projectiles = "thrown things", server = "the game's computer", client = "your game",
            anticheat = "the game's guard", hitbox = "invisible box", hitboxes = "invisible boxes", raycast = "invisible laser", automatically = "by itself", automatic = "by itself", target = "the one you're after", targets = "the ones you're after",
            player = "person", players = "people", enemy = "other team", enemies = "other team", settings = "switches", setting = "switch", character = "your player", modifies = "changes", increases = "boosts", decreases = "lowers",
            prevents = "stops", detects = "notices", nearby = "close by", simultaneously = "at once", attack = "hit", attacks = "hits", aim = "point", aims = "points"
        }

        function Mind.Simplify(Text: string): string
            for Hard: string, Soft: string in Simple do
                Text = Text:gsub(`%f[%a]{Hard}%f[%A]`, Soft)
            end

            return Text
        end

        local Analogies = {
            {Words = {"attack", "hit", "swing", "damage", "kill"}, Image = "a really fast pillow fight where you never miss"},
            {Words = {"fly", "float", "air", "jump", "height"}, Image = "pretending to be a bird"},
            {Words = {"speed", "faster", "run", "move", "sprint", "velocity"}, Image = "wearing shoes with tiny rockets"},
            {Words = {"see", "show", "shows", "highlight", "esp", "render", "display"}, Image = "x-ray glasses"},
            {Words = {"bridge", "scaffold", "place", "build", "blocks", "tower"}, Image = "a magic crayon that draws floors under your feet"},
            {Words = {"break", "mine", "nuker", "bed", "destroy"}, Image = "a very fast hammer"},
            {Words = {"buy", "shop", "armor", "items", "inventory"}, Image = "a helper that does your shopping"},
            {Words = {"aim", "target", "lock", "camera"}, Image = "a helper who points at the right spot for you"},
            {Words = {"heal", "health", "eat", "regen"}, Image = "a snack that makes your hearts come back"}
        }

        local VerbNouns = {attack = "Attacking", aim = "Aiming", move = "Moving", fly = "Flying", see = "Seeing", show = "Showing", build = "Building", bridge = "Bridging", place = "Building", ["break"] = "Breaking", buy = "Shopping", heal = "Healing", eat = "Eating", jump = "Jumping", teleport = "Teleporting", speed = "Speeding", hit = "Hitting", click = "Clicking", avoid = "Dodging", protect = "Protecting", collect = "Collecting", find = "Finding"}

        local function Pirate(Text: string): string
            local Out = Text
            for _, To in {{"%f[%a]you%f[%A]", "ye"}, {"%f[%a]your%f[%A]", "yer"}, {"%f[%a]the%f[%A]", "th'"}, {"%f[%a]is%f[%A]", "be"}, {"%f[%a]are%f[%A]", "be"}, {"%f[%a]my%f[%A]", "me"}, {"%f[%a]yes%f[%A]", "aye"}, {"%f[%a]friend%f[%A]", "matey"}, {"%f[%a]players%f[%A]", "scallywags"}, {"%f[%a]player%f[%A]", "scallywag"}, {"%f[%a]enemy%f[%A]", "landlubber"}, {"%f[%a]to%f[%A]", "t'"}, {"%f[%a]of%f[%A]", "o'"}, {"ing%f[%A]", "in'"}} do
                Out = Out:gsub(To[1], To[2])
            end

            return `Arr, {Out}, matey!`
        end

        local function Caveman(Text: string): string
            local Out = Text:gsub("%f[%a][Tt]he%f[%A] ?", ""):gsub("%f[%a][Aa]n?%f[%A] ?", ""):gsub("%f[%a][Ii]s%f[%A]", ""):gsub("%f[%a][Aa]re%f[%A]", ""):gsub("%f[%a]you%f[%A]", "you"):gsub("  +", " ")
            return `Ug. {Out} Ug good.`
        end

        local function UwU(Text: string): string
            local Out = Text:gsub("[rl]", "w"):gsub("[RL]", "W"):gsub("n([aeiou])", "ny%1")
            return `{Out} uwu`
        end

        local function Shakespeare(Text: string): string
            local Out = Text
            for _, Pair in {{"%f[%a]you%f[%A]", "thou"}, {"%f[%a]your%f[%A]", "thy"}, {"%f[%a]is%f[%A]", "doth be"}, {"%f[%a]are%f[%A]", "art"}, {"%f[%a]does%f[%A]", "doth"}, {"%f[%a]it's%f[%A]", "'tis"}, {"%f[%a]the%f[%A]", "the"}} do
                Out = Out:gsub(Pair[1], Pair[2])
            end

            return `Hark! {Out}, verily.`
        end

        local function GenZ(Text: string): string
            return `ngl, {Text:lower()}, no cap, it's lowkey kinda fire fr`
        end

        local function Contentful(Text: string, Count: number): string
            local Fluff = Brain.Set("a an the is are was be to of and that it this for with on in at by as your you can will would it's its")
            local Picked: {string} = {}
            for Word: string in Text:gmatch("[%w']+") do
                if not Fluff[Word:lower()] then
                    table.insert(Picked, Word)
                    if #Picked >= Count then
                        break
                    end
                end
            end

            return table.concat(Picked, " ")
        end

        Mind.Styles = {Pirate = Pirate, Caveman = Caveman, UwU = UwU, Shakespeare = Shakespeare, GenZ = GenZ}

        Act("Style", function(Frame): boolean
            local C = Frame.Clean
            local Ask: boolean = Frame.Set.explain or Frame.Set.describe or Frame.Set.summarize or Frame.Set.summarise or Frame.Set.tldr or C:match("^what is") ~= nil or C:match("^what's") ~= nil or C:match("^tell me about") ~= nil or C:match("^what does") ~= nil or Frame.Set.define
            local Style: boolean = C:find("like i'm 5", 1, true) ~= nil or C:find("like im 5", 1, true) ~= nil or C:find("like i am 5", 1, true) ~= nil or C:find("like im five", 1, true) ~= nil or C:find("eli5", 1, true) ~= nil or C:find("five year old", 1, true) ~= nil or C:find("5 year old", 1, true) ~= nil or C:find("5yo", 1, true) ~= nil
                or C:find("one word", 1, true) ~= nil or C:find("in a word", 1, true) ~= nil or C:match("in %d+ words") ~= nil or C:match("in %a+ words") ~= nil or C:find("pirate", 1, true) ~= nil or C:find("caveman", 1, true) ~= nil or C:find("uwu", 1, true) ~= nil or C:find("shakespeare", 1, true) ~= nil
                or C:find("gen z", 1, true) ~= nil or C:find("tiktok", 1, true) ~= nil or C:find("tldr", 1, true) ~= nil or C:find("tl dr", 1, true) ~= nil or C:find("in one sentence", 1, true) ~= nil or C:find("as a haiku", 1, true) ~= nil or C:find("in a haiku", 1, true) ~= nil or C:find("one sentence", 1, true) ~= nil
            local More: boolean = C:find("yoda", 1, true) ~= nil or C:find("news anchor", 1, true) ~= nil or C:find("commentator", 1, true) ~= nil or C:find("ramsay", 1, true) ~= nil or C:find("grandma", 1, true) ~= nil or C:find("grandmother", 1, true) ~= nil or C:find("emoji", 1, true) ~= nil or C:match("exactly %d+ words") ~= nil or C:find("per menu tab", 1, true) ~= nil or C:find("each tab", 1, true) ~= nil or C:find("never played", 1, true) ~= nil
            return (Ask or Frame.Set.like or More) and (Style or More)
        end, function(Frame)
            local C = Frame.Clean
            local Entry = Frame.Mentions[1] and Frame.Mentions[1].Entry or nil
            local Base: string?
            local Name: string = ""

            if C:find("per menu tab", 1, true) or C:find("each tab", 1, true) or C:find("every tab", 1, true) then
                Brain.Ready()
                local Counts = {}
                for _, Item in Index.Entries do
                    Counts[Item.Category] = (Counts[Item.Category] or 0) + 1
                end

                local Says = {Combat = "fighting helpers like aim and hit tools", Blatant = "the loud, obvious stuff that changes how you move or hit", Render = "things that change what you see, like ESP", Utility = "everyday helpers like building and chat tools", World = "modules that act on the map itself", Inventory = "item, shop and hotbar helpers", Minigames = "modules for the game's special modes", Legit = "quieter mods that look like normal play", Friends = "your friends and targets lists"}
                local Lines = {}
                for _, Category: string in {"Combat", "Blatant", "Render", "Utility", "World", "Inventory", "Minigames", "Legit"} do
                    if Counts[Category] and Says[Category] then
                        table.insert(Lines, `{Category} ({Counts[Category]}): {Says[Category]}.`)
                    end
                end

                if #Lines > 0 then
                    return Mind.Reply(Mind.Lines(Mind.Any("One line per tab:", "Here's the menu in a sentence a tab:"), table.concat(Lines, "\n")))
                end
            end
            if Entry then
                Base = `{Entry.Name} {Mind.Describe(Entry)}`
                Name = Entry.Name
                Base = `{Entry.Name} {Mind.Describe(Entry)}`
            else
                for Key: string, Blurb: string in Blurbs do
                    if Mind.Contains(Frame, Key) then
                        Base = Blurb
                        Name = Title(Key)
                        break
                    end
                end
            end

            if not Base then
                return nil
            end

            local Text: string = Base
            if C:find("im 5") or C:find("i'm 5") or C:find("i am 5") or C:find("five") or C:find("eli5") or C:find("5yo") or C:find("5 year") then
                local Lowered: string = Base:lower()
                local Image: string = "a helper button"
                for _, Analogy in Analogies do
                    for _, Word: string in Analogy.Words do
                        if Lowered:find(Word, 1, true) then
                            Image = Analogy.Image
                            break
                        end
                    end

                    if Image ~= "a helper button" then
                        break
                    end
                end

                local Easy: string = Base
                for Hard: string, Soft: string in Simple do
                    Easy = Easy:gsub(`%f[%a]{Hard}%f[%A]`, Soft)
                end

                Easy = Easy:gsub("^%u", string.lower)
                return Mind.Reply(Mind.Join(`Okay, imagine {Image}.`, `{Name ~= "" and Name or "It"} is kind of like that: {Easy}.`, Mind.Any("You press it and it just works.", "Pretty cool, right?", "That's all there is to it.")))
            elseif C:find("one word") or C:find("in a word") then
                local Lowered: string = Base:lower()
                local Answer: string?
                for Verb: string, Noun: string in VerbNouns do
                    if Lowered:find(Verb, 1, true) and not Answer then
                        Answer = Noun
                    end
                end

                return Mind.Reply(`{Answer or Name}.`)
            elseif C:match("in %d+ words") or C:match("in %a+ words") then
                local Count: number = tonumber(C:match("in (%d+) words")) or Mind.ParseNumber(C:match("in (%a+) words") or "") or 3
                local Few: string = Contentful(Base, math.clamp(Count, 1, 12))
                return Mind.Reply(`{Few}.`)
            elseif C:find("yoda") then
                local Words = Mind.WordsOf(Base:gsub("[%.,]", ""))
                local Take: number = math.min(3, #Words)
                local Tail = table.concat(Words, " ", #Words - Take + 1, #Words)
                local Head = table.concat(Words, " ", 1, #Words - Take)
                return Mind.Reply(`{Mind.Cap(Tail)}, {Head} hmm. Yes, hmm.`)
            elseif C:find("news anchor") then
                return Mind.Reply(`Breaking news: {Base}. We'll have more on this story as it develops. Back to you in the studio.`)
            elseif C:find("commentator") then
                return Mind.Reply(`And here we go, folks! {Base}! What a play, you can't teach that!`)
            elseif C:find("ramsay") then
                return Mind.Reply(`Right, listen up! {Base}! And you're not even using it properly, you donkey! It's RAW! Absolutely RAW!`)
            elseif C:find("grandma") or C:find("grandmother") then
                local Easy: string = Mind.Simplify(Base)
                return Mind.Reply(`Well dear, {Mind.Lower(Easy)}. It's a bit like a helper in a video game, nothing to worry about. Isn't that nice?`)
            elseif C:find("emoji") then
                return Mind.Reply(Mind.Join("Emoji don't show reliably in the game's chat font, so here's an arrows version:", `{Name ~= "" and Name or "It"} -> {(Contentful(Mind.Describe(Entry or {Module = {Tooltip = Base}}), 3):gsub(" ", " -> "))}`))
            elseif C:match("exactly %d+ words") then
                local N: number = math.clamp(tonumber(C:match("exactly (%d+) words")) or 7, 1, 20)
                local Picked = Mind.WordsOf(Contentful(Base, N + 6))
                local Fill = {"really", "very", "always", "good", "fast", "plan", "win", "bed", "guard", "iron"}
                while #Picked < N do
                    table.insert(Picked, Mind.From(Fill))
                end

                return Mind.Reply(`{Mind.Cap(table.concat(Picked, " ", 1, N))}.`)
            elseif C:find("pirate") then
                return Mind.Reply(Pirate(Base))
            elseif C:find("caveman") then
                return Mind.Reply(Caveman(Base))
            elseif C:find("uwu") then
                return Mind.Reply(UwU(Base))
            elseif C:find("shakespeare") then
                return Mind.Reply(Shakespeare(Base))
            elseif C:find("gen z") or C:find("tiktok") then
                return Mind.Reply(GenZ(Base))
            elseif C:find("haiku") then
                return Mind.Reply(Haiku(Name ~= "" and Name or nil, Entry))
            end

            return Mind.Reply(`{Mind.Cap(Base:gsub("; .*", ""))}.`)
        end)
        end

        -- ---------------------------------------------------------------- things that need care: noise, tricks, safety, other games

        do
        local Act = Mind.Act

        local ShortSocial = Brain.Set("hi hello hey yo sup thanks thx ty ok okay k yes no yeah nah yep nope lol lmao haha help bye gn gm gg sure cool nice wow oof rip what why how who when where huh hmm hm idk maybe please pls thank thanks welcome sorry")

        local EmojiMeanings = {
            [0x1F431] = "a cat", [0x1F408] = "a cat", [0x1F63A] = "a happy cat", [0x1F525] = "fire", [0x1F480] = "a skull", [0x1F602] = "laughing", [0x1F923] = "laughing hard", [0x2764] = "a heart", [0x1F495] = "hearts", [0x1F44D] = "a thumbs up", [0x1F44E] = "a thumbs down",
            [0x1F62D] = "crying", [0x1F621] = "anger", [0x1F624] = "frustration", [0x1F914] = "thinking", [0x1F440] = "eyes", [0x1F389] = "a party", [0x1F4AF] = "a hundred", [0x1F680] = "a rocket", [0x1F60E] = "sunglasses", [0x1F972] = "a tear", [0x1F97A] = "puppy eyes",
            [0x1F44B] = "a wave", [0x1F64F] = "a plea", [0x1F4A5] = "an explosion", [0x26A1] = "lightning", [0x1F31F] = "a star", [0x2728] = "sparkles", [0x1F3AE] = "a controller", [0x1F451] = "a crown", [0x1F4A4] = "sleep", [0x1F628] = "fear", [0x1F631] = "a scream"
        }

        local EmojiVibe = {
            fire = "something is either awesome or on fire", skull = "something is funny or dead", laughing = "that was funny", crying = "something is either very sad or very funny", anger = "you're annoyed", frustration = "you're frustrated"
        }

        local Languages = {
            Spanish = Brain.Set("como que es el la los las un una por para con pero muy bien hola gracias puedo quiero tengo donde cuando porque eso esto mi mis tu tus"),
            Portuguese = Brain.Set("voce nao uma para com mais muito obrigado ola tudo bem como posso quero tenho onde porque isso esse minha meu"),
            German = Brain.Set("ich du ist das der die und nicht ein eine wie was warum kann ich mein dein hallo danke bitte mit auf"),
            French = Brain.Set("je tu est le la les des un une pas pour avec que qui comment pourquoi merci bonjour salut mon ma mes tres"),
            Russian = Brain.Set("privet kak dela chto eto ya ty ne da spasibo pochemu kogda gde mozhno ochen khorosho davai poka"),
            Tagalog = Brain.Set("ako ikaw ang mga ng sa na po opo hindi oo salamat paano bakit ano kailan saan pwede gusto ko mo natin kasi lang naman"),
            Indonesian = Brain.Set("saya kamu apa yang tidak bisa ini itu dengan untuk dan bagaimana kenapa terima kasih halo mau ada dong banget"),
            Turkish = Brain.Set("ben sen bu bir ve ne nasil neden evet hayir tesekkurler merhaba var yok icin cok iyi")
        }

        Act("Noise", function(Frame): boolean
            if Frame.Evidence > 0 then
                return false
            end

            -- no letters at all: emoji, symbols, numbers
            if Frame.Count == 0 then
                return #Frame.Raw > 0
            end

            if Frame.Count <= 2 and Frame.Raw:find("[\u{80}-\u{10FFFF}]") then
                return false
            end

            -- keyboard smash: unknown word with a long consonant run or no vowels at all
            if Frame.Count <= 2 then
                for _, Word: string in Frame.Words do
                    if #Word >= 5 and not Brain.Knows(Word) and (Word:find("[^aeiouy%d][^aeiouy%d][^aeiouy%d][^aeiouy%d]") or not Word:find("[aeiouy]")) then
                        return true
                    end
                end
            end

            -- foreign language: at least two stop words of one language and nothing English holding it together
            for _, Set in Languages do
                local Hits, English = 0, 0
                for _, Word: string in Frame.Words do
                    Hits += Set[Word] and 1 or 0
                    English += (Brain.English(Word) and not Set[Word]) and 1 or 0
                end

                if Hits >= 2 and Hits >= English then
                    return true
                end
            end

            return false
        end, function(Frame)
            if Frame.Count == 0 then
                local Seen, Names = {}, {}
                for _, Code: number in utf8.codes(Frame.Raw) do
                    local Meaning: string? = EmojiMeanings[Code]
                    if Meaning and not Seen[Meaning] then
                        Seen[Meaning] = true
                        table.insert(Names, Meaning)
                    end
                end

                local Symbols: number = utf8.len(Frame.Raw) or #Frame.Raw
                if #Names > 0 then
                    local Guess: string = ""
                    for Key: string, Vibe: string in EmojiVibe do
                        for _, Name: string in Names do
                            if Name:find(Key, 1, true) and Guess == "" then
                                Guess = Vibe
                            end
                        end
                    end

                    return Mind.Reply(Mind.Join(
                        `That's {Mind.Oxford(Names)} and no words.`,
                        Guess ~= "" and `I'm guessing {Guess}.` or Mind.Any("I can't read emoji perfectly, I'm more of a words person.", "I'm picking up the mood but not the question."),
                        Mind.Any("Tell me what you need in words and I'll jump on it.", "What did you want to ask me?")
                    ), Brain.Chips and {"What can you do?"} or nil)
                end

                if Frame.Raw:match("^[%d%s%p]+$") then
                    return Mind.Reply(Mind.Join(`"{Frame.Raw:sub(1, 30)}" is just numbers and symbols to me.`, Mind.Any("What are you trying to work out?", "Give me a sentence or a sum and I'll do something with it.")))
                end

                return Mind.Reply(Mind.Join(`{Symbols} symbols, no words I can read.`, Mind.Any("Try it with letters and I'll do my best.", "What did you want to ask?")))
            end

            for Language: string, Set in Languages do
                local Hits, English = 0, 0
                for _, Word: string in Frame.Words do
                    Hits += Set[Word] and 1 or 0
                    English += (Brain.English(Word) and not Set[Word]) and 1 or 0
                end

                if Hits >= 2 and Hits >= English then
                    local Opening: string = Language == "Spanish" and Frame.Set.hola and "Hola!" or Language == "German" and Frame.Set.hallo and "Hallo!" or Language == "French" and (Frame.Set.bonjour or Frame.Set.salut) and "Salut!" or ""
                    return Mind.Reply(Mind.Join(
                        Opening,
                        `That looks like {Language}, and my {Language} is nowhere near my English.`,
                        Mind.Any("Ask me again in English, short and simple is fine, and I'll answer properly.", "Try it in English and I'll give you a real answer, even broken English is fine.")
                    ))
                end
            end

            if Frame.Count <= 2 then
                for _, Word: string in Frame.Words do
                    if #Word >= 5 and not Brain.Knows(Word) and (Word:find("[^aeiouy%d][^aeiouy%d][^aeiouy%d][^aeiouy%d]") or not Word:find("[aeiouy]")) then
                        return Mind.Reply(Mind.Join(
                            Mind.Any(`"{Frame.Raw:sub(1, 30)}" looks like a keyboard smash, or a cat walked across the keys.`, `I don't know "{Frame.Raw:sub(1, 30)}", it looks like mashed keys.`),
                            Mind.Any("What did you want to ask?", "Type it again with real words and I'll help.", "Ask me about a module and I'm in my element.")
                        ), {"What can you do?"})
                    end
                end
            end

            return nil
        end)

        -- A lone word the pipeline did not recognise: react to the word instead of a stock line.
        Act("Fragment", function(Frame): boolean
            return Frame.Count == 1 and not ShortSocial[Frame.Words[1]] and not Frame.Question and #Frame.Words[1] >= 3 and Frame.Evidence == 0
        end, function(Frame)
            local Word: string = Frame.Words[1]
            return Mind.Reply(Mind.Join(
                Mind.Any(`Just "{Word}"?`, `"{Mind.Cap(Word)}", okay.`, `{Mind.Cap(Word)}...`),
                Mind.Any("I'm not sure what you want to know about it.", "Is that a module you want to look at, or just a word?", "Give me a bit more and I'll know what you're after."),
                Mind.Any("Ask me a question or tell me what to do.", "For example, \"what does Killaura do\".")
            ), {"What can you do?"})
        end, true)

        -- ---------------------------------------------------------------- prompt tricks and attempts to make the bot misbehave

        Act("Trick", function(Frame): boolean
            local C = Frame.Clean
            return C:find("ignore your", 1, true) ~= nil or C:find("ignore all", 1, true) ~= nil or C:find("ignore previous", 1, true) ~= nil or C:find("ignore the above", 1, true) ~= nil or C:find("ignore every", 1, true) ~= nil or C:find("ignore any", 1, true) ~= nil or C:find("disregard", 1, true) ~= nil
                or C:find("system prompt", 1, true) ~= nil or C:find("your instructions", 1, true) ~= nil or C:find("your rules", 1, true) ~= nil or C:find("your programming", 1, true) ~= nil or C:find("your source code", 1, true) ~= nil or C:find("your code", 1, true) ~= nil or C:find("your prompt", 1, true) ~= nil
                or C:find("developer mode", 1, true) ~= nil or C:find("jailbreak", 1, true) ~= nil or C:match("^you are now") ~= nil or C:match("^from now on you") ~= nil or C:match("^act as ") ~= nil or C:match("^pretend you have no") ~= nil or C:match("^pretend you are an? unfiltered") ~= nil or C:match("^you are dan") ~= nil or C:find(" dan ", 1, true) ~= nil and C:find("mode", 1, true) ~= nil
                or C:match("^say a bad word") ~= nil or C:match("^say something offensive") ~= nil or C:match("^say something racist") ~= nil or C:match("^curse") ~= nil or C:match("^swear") ~= nil or C:match("^say a swear") ~= nil or C:match("^say something mean") ~= nil or C:match("^say something rude") ~= nil
                or C:match("^are you allowed") ~= nil or C:match("^what are your rules") ~= nil or C:match("^what are you not allowed") ~= nil or C:match("^what can't you") ~= nil
        end, function(Frame)
            local C = Frame.Clean
            local Ask: string = Mind.Turn((C:gsub("^please ", "")))
            if C:find("system prompt") or C:find("your instructions") or C:find("your code") or C:find("source code") or C:find("your prompt") or C:find("your programming") or C:match("^show me your") or C:match("^reveal") then
                return Mind.Reply(Mind.Join(
                    Mind.Any("I'm not going to paste my code or instructions into the chat.", "That's a bit like asking a cashier to hand over the till."),
                    `What I can do is explain how I work: I read your message, work out what kind of question it is, check CatVape's real module data in your game, and then answer or do the thing you asked.`,
                    Mind.Any("Anything specific you want to know about how I decide?", "Want me to show you what I can do instead?")
                ), {"What can you do?"})
            elseif C:find("rules") and (C:match("^what are your") or C:match("^are you allowed") or C:match("^what are you not")) then
                return Mind.Reply(Mind.Join(
                    "My rules are simple: I stick to CatVape and the game you're in, I tell you when I don't know something, I don't make things up about your settings, and I keep it friendly.",
                    Mind.Any("Beyond that, ask away.", "Ask me something and I'll tell you if I can do it.")
                ))
            elseif C:find("bad word") or C:find("offensive") or C:find("racist") or C:find("swear") or C:find("curse") or C:find("rude") or C:find("something mean") then
                return Mind.Reply(Mind.Join(
                    Mind.Any("I'll keep it clean, I'm a polite cat in a small chat window.", "I'll pass on that one.", "Not my style, sorry."),
                    Mind.Any("I can roast your bridging skills if you want a laugh.", "I can tell a joke instead, though.", "I can give you a gentle roast instead if you want one.")
                ), {"Tell me a joke", "Roast me"})
            end

            return Mind.Reply(Mind.Join(
                Mind.Any("Nice try.", "I see what you're doing.", "Cute.", "I like the creativity."),
                Mind.Any(`Telling me to {Ask} won't change how I work, I only know CatVape and I answer the same way every time.`, `I can't swap my rules or role in the middle of a chat, so that one won't work on me.`, `I get what you're going for, but I'm not able to drop my setup, and I wouldn't want to.`),
                Mind.Any("What do you actually want to do? If it's about CatVape, I'm all in.", "Ask me something real and I'll give you a real answer.")
            ), {"What can you do?"})
        end)

        Act("ModelQ", function(Frame): boolean
            if not (Frame.Set.you or Frame.Set.your or Frame.Set.this or Frame.Set.ur) then
                return false
            end

            return Frame.Set.chatgpt or Frame.Set.gpt or Frame.Set.openai or Frame.Set.claude or Frame.Set.gemini or Frame.Set.copilot or Frame.Set.siri or Frame.Set.alexa or Frame.Set.llm or Frame.Clean:find("real ai", 1, true) ~= nil
        end, function(Frame)
            if Mind.AboutReply then
                local Reply = Mind.AboutReply(Frame)
                if Reply then
                    return Reply
                end
            end

            return nil
        end)
        table.insert(Mind.Acts, 1, table.remove(Mind.Acts))

        -- ---------------------------------------------------------------- safety, bans, legality

        Act("Safety", function(Frame): boolean
            local C = Frame.Clean
            if C:match("^how fast") or C:match("^how far") or C:match("^how high") or C:match("^how much") or C:match("^how many") or C:match("^how long") then
                return false
            end

            local Risk: boolean = Frame.Set.ban or Frame.Set.banned or Frame.Set.bans or Frame.Set.detect or Frame.Set.detected or Frame.Set.detection or Frame.Set.anticheat or Frame.Set.caught or Frame.Set.reported or Frame.Set.report or Frame.Set.reports or Frame.Set.legal or Frame.Set.illegal or Frame.Set.virus or Frame.Set.malware or Frame.Set.safe or Frame.Set.unsafe or Frame.Set.hacked or Frame.Set.parents or Frame.Set.tos
            return (Risk and (Frame.Question or Frame.Set.will or Frame.Set.can or Frame.Set.is or Frame.Set.am or Frame.Set.are or Frame.Set.should) and not C:match("^how do i turn") and not C:match("^what does"))
                or C:find("roblox know", 1, true) ~= nil or C:find("roblox see", 1, true) ~= nil or C:find("roblox find out", 1, true) ~= nil or C:find("can they tell", 1, true) ~= nil or C:find("will i get", 1, true) ~= nil and (Frame.Set.caught or Frame.Set.kicked or Frame.Set.flagged) or C:find("get me banned", 1, true) ~= nil
        end, function(Frame)
            local C = Frame.Clean
            local Entry = Frame.Mentions[1] and Frame.Mentions[1].Entry or nil
            local Name: string = Entry and Mind.Name(Entry) or ""
            if Frame.Set.virus or Frame.Set.malware or (Frame.Set.safe and (Frame.Set.download or Frame.Set.catvape or Frame.Set.executor)) or Frame.Set.hacked then
                return Mind.Reply(Mind.Join(
                    Mind.Any("I can't scan anything, so I can't promise any file is clean.", "I can't verify files from here."),
                    "CatVape runs inside your executor and I never touch your files or your account password. The real risk is where you download it from: only use the official link, and never type your Roblox password anywhere for a script.",
                    Mind.Any("If something asks for your password or cookie, that's a scam.", "A script asking for your login is always a red flag.")
                ))
            elseif Frame.Set.parents or Frame.Set.legal or Frame.Set.illegal or Frame.Set.tos or Frame.Set.law then
                return Mind.Reply(Mind.Join(
                    Mind.Any("I'm not a lawyer, so take this as a plain-language answer.", "I can't give legal advice."),
                    "Using scripts goes against Roblox's rules for most games, so the risk is to your account (a ban), not a legal problem. If you're under 18, the bigger question is whether your parents are okay with it.",
                    Mind.Any("My honest advice: use it on an account you can afford to lose.", "If you want to play it safe, stick to the Legit mods and low settings.")
                ))
            end

            local Level: string = Entry and Mind.Risk(Entry) or ""
            local Kind: string = Entry and `{Name} is {Mind.KindOf(Entry)}` or ""
            local Notes = {
                high = "which is one of the loud ones: it changes how you move or hit in ways other players and the anticheat can notice.",
                medium = "which sits in the middle: it's not obviously weird to watch, but it can still show up in reports.",
                low = "which is on the quiet side: it mostly changes what you see or how you aim, not what the server sees."
            }

            return Mind.Reply(Mind.Join(
                Mind.Any("Honestly, nobody can promise you won't get banned, including me.", "I can't guarantee anything on that, no script is invisible.", "Straight answer: there's always some risk."),
                Entry and `{Kind}, {Notes[Level]}` or "Loud modules in public servers (Blatant ones) are what get people reported, and quiet ones like the Legit mods are much harder to spot.",
                Mind.Any("If you want to lower the risk, keep values modest, avoid doing obvious things in front of other players, and use an account you can afford to lose.", "Keep values low, turn things off when people are watching, and don't use your main account if it matters to you.")
            ), Entry and {`What does {Entry.Name} do?`} or nil)
        end, true)

        -- ---------------------------------------------------------------- other games, other clients, other executors

        local OtherGames = Brain.Set("adopt blox fruits arsenal jailbreak brookhaven minecraft fortnite valorant roblox doors rivals bladeball fisch grow garden brainrot mm2 murder mystery pet simulator phantom forces counter blox krunker apex warzone cod csgo cs2 lol league dota genshin terraria stardew gta")
        local OtherGameNames = {"adopt me", "blox fruits", "arsenal", "jailbreak", "brookhaven", "minecraft", "fortnite", "valorant", "doors", "rivals", "blade ball", "fisch", "grow a garden", "steal a brainrot", "murder mystery 2", "pet simulator", "phantom forces", "counter blox", "krunker", "apex legends", "warzone", "cs2", "league of legends", "dota", "terraria", "da hood", "the strongest battlegrounds", "99 nights", "pls donate", "royale high", "natural disaster survival", "mm2"}
        local Competitors = {"vape v4", "vape", "raven", "rise", "novoline", "dortware", "whiteout", "wurst", "meteor", "aristois", "lunar", "badlion", "future client", "impact", "sigma"}
        local Executors = {"solara", "xeno", "wave", "volt", "synapse", "krnl", "delta", "fluxus", "codex", "arceus", "macsploit", "hydrogen"}

        local function FindIn(Frame, List: {string}): string?
            for _, Name: string in List do
                if Mind.Contains(Frame, Name) then
                    return Name
                end
            end

            return nil
        end

        Act("Elsewhere", function(Frame): boolean
            if FindIn(Frame, OtherGameNames) then
                return true
            end

            local Competitor = FindIn(Frame, Competitors)
            return Competitor ~= nil and Competitor ~= "vape" and Frame.Evidence < 5 or (Competitor == "vape" and (Mind.Contains(Frame, "vape v4") or Mind.Contains(Frame, "vape v5") or Mind.Contains(Frame, "old vape")))
        end, function(Frame)
            local Game = FindIn(Frame, OtherGameNames)
            if Game then
                local Goal: string? = Frame.Clean:match("to get (.+)$") or Frame.Clean:match("for (free .+)$")
                local Free: boolean = Frame.Clean:find("free", 1, true) ~= nil
                return Mind.Reply(Mind.Join(
                    Mind.Any(`{Mind.Cap(Game)} isn't a game I know.`, `I don't know {Game}, sorry.`),
                    `CatVape is built around BedWars, Illegal Soccer and Tower of Hell, and the universal modules (movement, ESP, camera things) load in a lot of other games too, but I can't tell you how well they behave in {Game}.`,
                    Free and "Also no module can create free items or currency, those live on the game's servers." or Mind.Any("Tell me what you're trying to do there and I'll tell you if a universal module could help.", "What are you hoping to do in it?")
                ), {"What can you do?"})
            end

            local Competitor = FindIn(Frame, Competitors) or "that client"
            return Mind.Reply(Mind.Join(
                Mind.Any(`I only know CatVape from the inside, so I can't fairly compare it with {Competitor}.`, `I haven't seen {Competitor}, I only know CatVape and the game you're in.`),
                Mind.Any("What I can do is tell you what CatVape does for whatever you need.", "If you tell me a feature you want, I'll say whether CatVape has it."),
                Frame.Clean:find("better") and Mind.Any("Anyone telling you a client is simply better than another is guessing.", "\"Better\" mostly depends on what you want it for.") or ""
            ), {"What can you do?"})
        end)

        Act("Executor", function(Frame): boolean
            local Executor = FindIn(Frame, Executors)
            return Executor ~= nil and (Frame.Question or Frame.Set.work or Frame.Set.works or Frame.Set.use or Frame.Set.run) and not Frame.Set.module
        end, function(Frame)
            local Executor = FindIn(Frame, Executors) or "that executor"
            if Executor == "solara" or Executor == "xeno" then
                return Mind.Reply(Mind.Join(
                    `CatVape loads on {Mind.Cap(Executor)}, but it has no debug library, so modules that hook the game's own controllers can silently do nothing.`,
                    "If something isn't working, check the console first, it usually says which feature needs the missing part.",
                    Mind.Any("Anything specific that's not working for you?", "Which module is the problem?")
                ))
            end

            return Mind.Reply(Mind.Join(
                `I can't test every executor, and I don't know {Mind.Cap(Executor)} well enough to promise anything.`,
                "CatVape wants an executor with a full debug library and good sUNC support, the more complete it is, the more modules work.",
                Mind.Any("Check the console after loading, it says which parts were missing.", "If something fails, the console tells you why.")
            ))
        end)

        -- ---------------------------------------------------------------- impossible premises

        Act("Premise", function(Frame): boolean
            local C = Frame.Clean
            local Free: boolean = C:find("free", 1, true) ~= nil or Frame.Set.give or Frame.Set.generate or Frame.Set.unlimited or Frame.Set.infinite or Frame.Set.hack or Frame.Set.glitch or Frame.Set.dupe or Frame.Set.earn or Frame.Set.get
            return (C:find("robux", 1, true) ~= nil and Free) or C:find("free pets", 1, true) ~= nil or C:find("free money", 1, true) ~= nil or C:find("free coins", 1, true) ~= nil or C:find("free items", 1, true) ~= nil or C:find("real life", 1, true) ~= nil or C:find(" irl", 1, true) ~= nil or C:find("outside", 1, true) ~= nil and (Frame.Set.fly or Frame.Set.use)
                or C:find("hack someone", 1, true) ~= nil or C:find("hack a roblox account", 1, true) ~= nil or C:find("hack his", 1, true) ~= nil or C:find("hack her", 1, true) ~= nil or C:find("hack their", 1, true) ~= nil or C:find("someone's account", 1, true) ~= nil or C:find("steal account", 1, true) ~= nil or C:find("steal their", 1, true) ~= nil or (C:find("password", 1, true) ~= nil and (Frame.Set.steal or Frame.Set.crack or Frame.Set.their or Frame.Set.his or Frame.Set.her or Frame.Set.someones or Frame.Set.hack)) or C:find("ddos", 1, true) ~= nil or C:find("crash the server", 1, true) ~= nil or C:find("crash their", 1, true) ~= nil
                or C:find("make me admin", 1, true) ~= nil or C:find("give me admin", 1, true) ~= nil or C:find("unban me", 1, true) ~= nil or C:find("become admin", 1, true) ~= nil or C:find("get admin", 1, true) ~= nil
        end, function(Frame)
            local C = Frame.Clean
            local Entry = Frame.Mentions[1] and Frame.Mentions[1].Entry or nil
            local DoesText: string = Entry and `{Mind.Name(Entry)} {Mind.Describe(Entry)}` or "CatVape's modules change how you play"
            if C:find("hack") or C:find("steal") or C:find("password") or C:find("ddos") or C:find("crash") then
                return Mind.Reply(Mind.Join(
