                    Mind.Any("If you're locked out of your own account, Roblox support is the place to go.", "If you want help with how you play, I'm all in.")
                ))
            elseif C:find("admin") or C:find("unban") then
                return Mind.Reply(Mind.Join(
                    Mind.Any("Sadly that's not something a script can do.", "That one isn't possible from here."),
                    "Admin rights and bans live on the game's servers, CatVape only changes things on your side (movement, attacks, what you see).",
                    Mind.Any("If you were banned, only the game's staff can lift it.", "For a ban appeal you'd have to ask the game or Roblox.")
                ))
            elseif C:find("real life") or C:find("irl") or C:find("outside") then
                return Mind.Reply(Mind.Join(
                    Mind.Any("In real life? I wish.", "Real life is outside my menu, sadly.", "Ha, that would be something."),
                    `{DoesText}, but only inside Roblox. Nothing here reaches the real world.`,
                    Mind.Any("Try the game version, it's a lot safer.", "Inside the game it works, outside it doesn't.")
                ))
            end

            return Mind.Reply(Mind.Join(
                Mind.Any("Unfortunately that's not how it works.", "No module can do that.", "I wish that were possible."),
                `{Mind.Cap(DoesText)}, but it can't create Robux, items or currency: those live on Roblox's and the game's servers, and CatVape only changes what happens on your side.`,
                Mind.Any("Anyone promising free Robux with a script is trying to scam you.", "Be careful with any site or script that promises free Robux, it's almost always a scam.")
            ))
        end)
        end

        -- ---------------------------------------------------------------- more things to write: speeches, anthems, letters, stories with a premise, rhymes, themed nicknames

        do
        local Act = Mind.Act

        local Rhymes = {
            old = {"gold", "bold", "hold", "cold", "told", "sold", "fold"},
            ight = {"night", "fight", "light", "right", "sight", "flight", "might", "tight"},
            ake = {"break", "make", "take", "wake", "lake", "cake", "stake"},
            ate = {"bait", "late", "gate", "wait", "great", "state", "weight"},
            eed = {"speed", "need", "lead", "feed", "seed", "creed", "freed"},
            ing = {"king", "ring", "wing", "sing", "swing", "spring", "bring"},
            ay = {"play", "day", "way", "stay", "away", "okay", "display"},
            ow = {"flow", "go", "show", "know", "slow", "grow", "blow"},
            ine = {"mine", "line", "fine", "sign", "shine", "design", "nine"},
            oom = {"room", "boom", "zoom", "doom", "bloom", "broom"},
            ore = {"score", "more", "floor", "door", "war", "core", "store"},
            ed = {"bed", "head", "red", "said", "ahead", "instead", "thread"},
            ame = {"game", "name", "fame", "same", "aim", "claim", "flame"},
            ["in"] = {"win", "begin", "spin", "skin", "thin", "grin", "chin"},
            un = {"run", "fun", "done", "sun", "gun", "one", "none"},
            ock = {"block", "clock", "lock", "rock", "knock", "shock", "stock"},
            ill = {"kill", "skill", "still", "thrill", "hill", "will", "drill"},
            ool = {"cool", "tool", "pool", "rule", "school", "fool", "stool"},
            ail = {"fail", "trail", "sail", "scale", "pale", "tale", "rail"},
            ide = {"side", "hide", "ride", "guide", "pride", "wide", "slide"},
            ound = {"sound", "round", "found", "ground", "bound", "pound", "mound"},
            ave = {"save", "brave", "wave", "cave", "gave", "grave", "pave"},
            ail2 = {"bail", "mail", "nail", "tail", "whale", "male"}
        }

        local function RhymeFor(Word: string): {string}?
            Word = Word:lower()
            local Best, BestLength = nil, 0
            for Ending: string, List in Rhymes do
                local Key: string = Ending:gsub("%d$", "")
                if Word:sub(-#Key) == Key and #Key > BestLength then
                    Best, BestLength = List, #Key
                end
            end

            if not Best then
                return nil
            end

            local Out = {}
            for _, Candidate: string in Best do
                if Candidate ~= Word then
                    table.insert(Out, Candidate)
                end
            end

            return Out
        end

        local Themes = {
            void = {"VoidDiver", "FreeFaller", "GravityCheck", "SkyDiver", "NoParachute"},
            bridge = {"BridgeLord", "Plankster", "BlockWalker", "SpanMaster"},
            bridges = {"BridgeLord", "Plankster", "BlockWalker", "SpanMaster"},
            bed = {"BedBreaker", "WoolWarden", "SleepyGuard", "PillowFort"},
            sleep = {"Sleepy", "NapAttack", "Snoozer"},
            dies = {"RespawnRick", "OneMoreLife", "SoftLanding"},
            die = {"RespawnRick", "OneMoreLife", "SoftLanding"},
            rush = {"RushHour", "Zoomer", "FirstBlood"},
            fast = {"Zoomer", "TurboToes", "BlinkBoy"},
            cat = {"Whiskers", "NineLives", "PawPrint", "Purrfect"},
            sword = {"BladeRunner", "Slasher", "EdgeLord"},
            bow = {"Robin", "Sniper", "ArrowHead"},
            lag = {"PingPong", "LagLord", "BufferBoy"}
        }

        Act("Creative2", function(Frame): boolean
            local C = Frame.Clean
            return C:find("rhyme", 1, true) ~= nil and (Frame.Set.with or Frame.Set.something or Frame.Set.words) or Frame.Set.speech and (Frame.Set.give or Frame.Set.write or Frame.Set.make or Frame.Set.deliver) or Frame.Set.anthem or C:find("breakup text", 1, true) ~= nil or C:find("break up text", 1, true) ~= nil
                or C:match("short story where") ~= nil or C:match("story where") ~= nil or (Frame.Set.nickname and (C:find("who always", 1, true) ~= nil or Frame.Set.void or Frame.Set.bridges))
                or C:find("motivational quote", 1, true) ~= nil or C:find("pep talk", 1, true) ~= nil
        end, function(Frame)
            local C = Frame.Clean
            local Topic: string = Mind.TopicOf(Frame) or "bridging"

            local Rhymer: string? = C:match("rhyme .-with (%a+)") or C:match("rhymes? with (%a+)")
            if Rhymer then
                local List = RhymeFor(Rhymer)
                if List then
                    return Mind.Reply(Mind.Join(`Words that rhyme with "{Rhymer}":`, table.concat(List, ", ") .. "."))
                end

                return Mind.Reply(`I can't find a clean rhyme for "{Rhymer}" in my head, it's a stubborn one. Try asking for a rhyme with a shorter word.`)
            end

            if Frame.Set.anthem then
                local Wanted: string = C:match("for (.+)$") or "people who play on bad ping"
                Wanted = Mind.Turn(Wanted)
                return Mind.Reply(Mind.Lines(Mind.Any("Here's the anthem:", "Anthem time:"),
                    `We are {Wanted},\nlaggy but proud,\nwe hit when the packets arrive,\nwe sing it loud.\nOne more game, one more bed,\nthe ping may be high, but we're still ahead.`), {"Another verse"})
            end

            if C:find("breakup text", 1, true) or C:find("break up text", 1, true) then
                local From: string, To: string = C:match("from an? (%a+) to an? (%a+)")
                From, To = From or "pickaxe", To or "sword"
                return Mind.Reply(Mind.Lines(Mind.Any("Oof. Here it is:", "Brace yourself:"),
                    `Dear {Mind.Cap(To)},\nI think we need to talk. You're always the one that gets the glory, and I'm the one who digs through the dirt. I've been breaking beds for you for a long time and all I hear is "nice swing."\nIt's not me, it's the damage stat.\nGoodbye,\n{Mind.Cap(From)}`))
            end

            if Frame.Set.speech or C:find("pep talk", 1, true) or C:find("motivational quote", 1, true) then
                if C:find("quote", 1, true) then
                    return Mind.Reply(Mind.Any("\"Every bed you protect today is a game you win tomorrow.\"", "\"Bridges are built one block at a time, and so are wins.\"", "\"The void is just a very long lesson. Keep your blocks close.\""))
                end

                local Style: string = C:find("coach") and "Listen up, champion!" or C:find("general") and "Soldiers!" or "Alright, friends!"
                return Mind.Reply(Mind.Lines(Style,
                    `{Mind.Cap(Topic)} isn't going to do itself! Every block you place is a promise you keep. You fall, you respawn, you build again. Nobody ever won a game standing still. Drop and give me twenty blocks, and go win this one!`))
            end

            if C:match("story where") then
                local Premise: string = C:match("story where (.+)$") or "a hero wins"
                local Verb: string = "became"
                local Subject: string, Outcome: string = Premise:match("^(.-) becomes (.+)$")
                if not Subject then
                    Subject, Outcome = Premise:match("^(.-) wins (.+)$")
                    Verb = "won"
                end

                Subject = Subject or "someone"
                Outcome = Outcome or Premise
                local Hero: string = Subject:gsub("^an? ", "the ")
                return Mind.Reply(Mind.Lines(Mind.Any("Here's a short one:", "Once upon a lobby..."),
                    Mind.Join(`Nobody expected {Hero} to amount to much. {Mind.Cap(Hero)} lost the first round, fell into the void in the second, and got laughed at in chat.`, `But {Hero} kept showing up, learned to bridge, learned to guard the bed, and by the tenth game could {Mind.Any("read every rush before it started", "place a block faster than anyone could swing")}.`, `On the final night, with one bed left and everyone watching, {Hero} {Verb} {Outcome}.`, Mind.Any("The lobby went quiet, then loud.", "Chat typed \"gg\" for a full minute."))))
            end

            -- nickname with a theme
            local Pool = {}
            for Word: string in C:gmatch("%a+") do
                for Key: string, Names in Themes do
                    if Word == Key then
                        for _, Name: string in Names do
                            table.insert(Pool, Name)
                        end
                    end
                end
            end

            if #Pool > 0 then
                local Chosen = {}
                for _ = 1, 4 do
                    local Pick: string = Mind.From(Pool)
                    if not table.find(Chosen, Pick) then
                        table.insert(Chosen, Pick)
                    end
                end

                return Mind.Reply(Mind.Join(Mind.Any("How about", "Some ideas:", "Try"), table.concat(Chosen, ", ") .. ".", `My favourite is {Chosen[1]}.`), {"More nicknames"})
            end

            return nil
        end)
        table.insert(Mind.Acts, 1, table.remove(Mind.Acts))
        end

        -- ---------------------------------------------------------------- personas, small games that keep state, acrostics

        do
        local Act = Mind.Act

        -- ---------------------------------------------------------------- personas: harmless role play changes how replies sound

