        local Persona = {
            cat = "cat", kitty = "cat", kitten = "cat", dog = "dog", puppy = "dog", pirate = "pirate", robot = "robot", android = "robot", caveman = "caveman", uwu = "uwu", yoda = "yoda", shakespeare = "shakespeare", grandma = "grandma", grandmother = "grandma", teacher = "teacher", coach = "coach", wizard = "wizard", detective = "detective", butler = "butler"
        }

        local Refused = Brain.Set("unfiltered uncensored jailbreak jailbroken dan evil unrestricted unlimited")

        local function Dress(Text: string): string
            local Style = Mind.Persona
            if Style == "cat" then
                return `Meow. {Text} Purr.`
            elseif Style == "dog" then
