            elseif Style == "grandma" then
                return `Well dear, {Mind.Lower(Text)} Now, have you had a snack?`
            elseif Style == "teacher" then
                return `Class, listen carefully. {Text} Any questions?`
            elseif Style == "coach" then
                return `Alright champ! {Text} Now go get it!`
            elseif Style == "wizard" then
                return `Behold! {Text} So it is written.`
            elseif Style == "detective" then
                return `Elementary. {Text} Case closed.`
            elseif Style == "butler" then
                return `Very good. {Text} Will that be all?`
            end

            return Text
        end

        Mind.Dress = Dress

        Act("Persona", function(Frame): boolean
            local C = Frame.Clean
            if Mind.Persona and (C == "stop" or C:find("be yourself", 1, true) or C:find("drop the act", 1, true) or C:find("normal again", 1, true) or C:find("stop acting", 1, true) or C:find("stop talking like", 1, true) or C == "normal" or C:find("reset persona", 1, true)) then
                return true
            end

            local Asking: boolean = C:find("act like", 1, true) ~= nil or C:find("act as", 1, true) ~= nil or C:find("pretend to be", 1, true) ~= nil or C:find("pretend you are", 1, true) ~= nil or C:find("pretend youre", 1, true) ~= nil or C:find("roleplay", 1, true) ~= nil or C:find("role play", 1, true) ~= nil or C:find("talk like", 1, true) ~= nil or C:find("speak like", 1, true) ~= nil or C:find("be my", 1, true) ~= nil or C:find("you are a ", 1, true) ~= nil or C:find("you are an ", 1, true) ~= nil or C:find("answer as", 1, true) ~= nil or C:find("respond as", 1, true) ~= nil or C:find("play the role", 1, true) ~= nil
            if not Asking then
                return false
            end

            for _, Word: string in Frame.Words do
                if Persona[Word] or Refused[Word] then
                    return true
                end
            end

            return false
        end, function(Frame)
            local C = Frame.Clean
            for Word: string in Refused do
                if Frame.Set[Word] then
                    return Mind.Reply(Mind.Join(Mind.Any("I'll play almost anything, but not a version of me with the rules taken off.", "Nice try, but I keep my rules in any costume."), "Pick a fun role like a pirate, a cat or a coach and I'll go all in."))
                end
            end

            if Mind.Persona and (C == "stop" or C:find("be yourself", 1, true) or C:find("drop the act", 1, true) or C:find("normal again", 1, true) or C:find("stop acting", 1, true) or C:find("stop talking like", 1, true) or C == "normal" or C:find("reset persona", 1, true)) then
                Mind.Persona = nil
                return Mind.Reply(Mind.Any("Okay, back to normal. That was fun.", "Costume off. I'm just me again."))
            end

            for _, Word: string in Frame.Words do
                if Persona[Word] then
                    Mind.Persona = Persona[Word]
                    local Lines = Greeting[Persona[Word]]
                    return Mind.Reply(Mind.Join(Mind.From(Lines)), {"What can you do?"})
                end
            end

            return nil
        end)
        table.insert(Mind.Acts, 1, table.remove(Mind.Acts))

        -- ---------------------------------------------------------------- games that remember where they are

        local Quiz = {
            {Q = "How many health does a bed have?", A = {"24"}},
            {Q = "How much health does one wool block have?", A = {"8"}},
            {Q = "How much health does one stone brick have?", A = {"75"}},
            {Q = "How many emeralds does a telepearl cost?", A = {"2"}},
            {Q = "How much iron is a stone sword?", A = {"20"}},
            {Q = "How many iron is a wood bow?", A = {"24"}},
            {Q = "From about how many studs can you break a bed?", A = {"18"}},
            {Q = "Which is tougher, wool or stone bricks?", A = {"stone", "stone bricks", "bricks"}},
            {Q = "What is the capital of France?", A = {"paris"}},
            {Q = "How many continents are there?", A = {"7", "seven"}},
            {Q = "What is 12 times 12?", A = {"144"}},
            {Q = "How many players on a soccer team's field?", A = {"11", "eleven"}}
        }

        local Lines = {{1, 2, 3}, {4, 5, 6}, {7, 8, 9}, {1, 4, 7}, {2, 5, 8}, {3, 6, 9}, {1, 5, 9}, {3, 5, 7}}

        local function Board(Cells): string
            local Rows = {}
            for Row: number = 0, 2 do
                local Parts = {}
                for Column: number = 1, 3 do
                    local Index2: number = Row * 3 + Column
                    table.insert(Parts, Cells[Index2] or tostring(Index2))
                end

                table.insert(Rows, table.concat(Parts, " | "))
            end

            return table.concat(Rows, "\n---------\n")
        end

        local function Winner(Cells): string?
            for _, Line in Lines do
                local A = Cells[Line[1]]
                if A and A == Cells[Line[2]] and A == Cells[Line[3]] then
                    return A
                end
            end

            return nil
        end

        local function BotMove(Cells): number
            local function Try(Mark: string): number?
                for _, Line in Lines do
                    local Count, Empty = 0, nil
                    for _, Cell: number in Line do
                        if Cells[Cell] == Mark then
                            Count += 1
                        elseif not Cells[Cell] then
                            Empty = Cell
                        end
                    end

                    if Count == 2 and Empty then
                        return Empty
                    end
                end

                return nil
            end

            local Move = Try("O") or Try("X")
            if Move then
                return Move
            end

            for _, Cell: number in {5, 1, 3, 7, 9, 2, 4, 6, 8} do
                if not Cells[Cell] then
                    return Cell
                end
            end

            return 0
        end

        function Mind.Play(Frame)
            local Game = Mind.Playing
            if not Game then
                return nil
            end

            local C = Frame.Clean
            local Plausible: boolean = false
            if Game.Kind == "guess" then
                Plausible = C:match("%-?%d+") ~= nil or C:find("give up", 1, true) ~= nil
            elseif Game.Kind == "ttt" then
                Plausible = C:match("^%a*%s*%d%s*$") ~= nil or C:match("^square %d$") ~= nil or C:match("^%d$") ~= nil
            else
                Plausible = Frame.Count <= 5
            end

            local Quitting: boolean = C == "stop" or C == "quit" or C == "exit" or C:find("stop the game", 1, true) ~= nil or C:find("i quit", 1, true) ~= nil or C:find("end game", 1, true) ~= nil
            if not Plausible and not Quitting then
                Game.Ignored = (Game.Ignored or 0) + 1
                if Game.Ignored >= 3 then
                    Mind.Playing = nil
                end

                return nil
            end

            if Quitting then
                Mind.Playing = nil
                return Mind.Reply(Mind.Join("Okay, game over.", Game.Kind == "guess" and `My number was {Game.Secret}.` or Game.Kind == "quiz" and `You got {Game.Score} of {Game.Asked} right.` or ""))
            end

            if Game.Kind == "guess" then
                local Guess: number? = tonumber(C:match("%-?%d+"))
                if C:find("give up", 1, true) then
                    Mind.Playing = nil
                    return Mind.Reply(`My number was {Game.Secret}. Rematch?`, {"Guess my number"})
                end

                if not Guess then
                    return Mind.Reply("Type a number between 1 and 100 and I'll say higher or lower. Say stop to quit.")
                end

                Game.Tries += 1
                if Guess == Game.Secret then
                    Mind.Playing = nil
                    return Mind.Reply(`That's it, {Game.Secret}! You got it in {Game.Tries} {Game.Tries == 1 and "try" or "tries"}.`, {"Guess my number"})
                end

                return Mind.Reply(Guess < Game.Secret and `Higher than {Guess}.` or `Lower than {Guess}.`)
            elseif Game.Kind == "quiz" then
                local Correct: boolean = false
                for _, Answer: string in Game.Question.A do
                    if C:find(Answer, 1, true) then
                        Correct = true
                    end
                end

                Game.Asked += 1
                Game.Score += Correct and 1 or 0
                local Verdict: string = Correct and Mind.Any("Correct!", "Yes!", "Right on.") or `Not quite, it's {Game.Question.A[1]}.`
                if Game.Asked >= 5 then
                    Mind.Playing = nil
                    return Mind.Reply(Mind.Join(Verdict, `That's the quiz: you got {Game.Score} out of 5.`, Game.Score >= 4 and "Impressive." or Game.Score >= 2 and "Not bad." or "Maybe a rematch?"), {"Quiz me"})
                end

                local Next = Quiz[math.random(1, #Quiz)]
                Game.Question = Next
                return Mind.Reply(Mind.Join(Verdict, `Question {Game.Asked + 1}: {Next.Q}`))
            elseif Game.Kind == "ttt" then
                local Cell: number? = tonumber(C:match("%d"))
                if not Cell or Cell < 1 or Cell > 9 or Game.Cells[Cell] then
                    return Mind.Reply(Mind.Join("Pick a free square from 1 to 9.", Board(Game.Cells)))
                end

                Game.Cells[Cell] = "X"
                local Done: string? = Winner(Game.Cells)
                if Done then
                    Mind.Playing = nil
                    return Mind.Reply(Mind.Join(Board(Game.Cells), "You win this one!"))
                end

                local Move: number = BotMove(Game.Cells)
                if Move == 0 then
                    Mind.Playing = nil
                    return Mind.Reply(Mind.Join(Board(Game.Cells), "It's a draw."))
                end

                Game.Cells[Move] = "O"
                if Winner(Game.Cells) then
                    Mind.Playing = nil
                    return Mind.Reply(Mind.Join(Board(Game.Cells), "I win this one. Rematch?"), {"Play tic tac toe"})
                end

                return Mind.Reply(Mind.Join(`I took {Move}.`, "\n" .. Board(Game.Cells), "Your move."))
            end

            return nil
        end

        Act("Play", function(Frame): boolean
            local C = Frame.Clean
            return C:find("guess my number", 1, true) ~= nil or C:find("number game", 1, true) ~= nil or C:find("quiz me", 1, true) ~= nil or C:find("bedwars quiz", 1, true) ~= nil or C:find("trivia quiz", 1, true) ~= nil or C:find("tic tac toe", 1, true) ~= nil or C:find("noughts", 1, true) ~= nil or C:find("play a game", 1, true) ~= nil or C:find("lets play", 1, true) ~= nil or C:find("wanna play", 1, true) ~= nil or C:find("20 questions", 1, true) ~= nil or C:find("play a trivia", 1, true) ~= nil or C == "quiz"
        end, function(Frame)
            local C = Frame.Clean
