                return Mind.Reply("I'm thinking of a number between 1 and 100. What's your guess? Say stop to quit.")
            elseif C:find("quiz") or C:find("trivia") then
                local First = Quiz[math.random(1, #Quiz)]
                Mind.Playing = {Kind = "quiz", Question = First, Asked = 0, Score = 0}
                return Mind.Reply(Mind.Join("Five questions, here we go.", `Question 1: {First.Q}`))
            elseif C:find("tic tac toe") or C:find("noughts") then
                Mind.Playing = {Kind = "ttt", Cells = {}}
                return Mind.Reply(Mind.Join("You're X and I'm O. Pick a square by number:", "\n" .. Board({})))
            elseif C:find("20 questions") then
                return Mind.Reply("I'm better at guessing games with numbers than at 20 questions. Try \"guess my number\", \"quiz me\" or \"tic tac toe\".", {"Guess my number", "Quiz me", "Play tic tac toe"})
            end

            return Mind.Reply(Mind.Join("I can play a few: guess my number, a BedWars quiz, tic tac toe, rock paper scissors, riddles or a coin flip.", "Pick one."), {"Guess my number", "Quiz me", "Play tic tac toe", "Rock paper scissors"})
        end)
        table.insert(Mind.Acts, 1, table.remove(Mind.Acts))

        -- ---------------------------------------------------------------- acrostics

        local Starters = {
            a = "Always guard the bed", b = "Bridge with care", c = "Cover every side", d = "Dodge the first hit", e = "Emeralds win late games", f = "Fight near your base", g = "Gather before you push",
            h = "Heal when you can", i = "Iron buys everything", j = "Jump before they swing", k = "Keep a few blocks spare", l = "Look behind you", m = "Move before they aim", n = "Never stand still",
            o = "Obsidian beats wool", p = "Pearl out of trouble", q = "Quit tilting early", r = "Rush only when ready", s = "Stay close to your team", t = "Trade resources wisely", u = "Upgrade early", v = "Void is closer than it looks",
            w = "Wool is cheap, use it", x = "Xtra blocks never hurt", y = "You win by planning", z = "Zoom out and think"
        }

        Act("Acrostic", function(Frame): boolean
            return Frame.Clean:find("acrostic", 1, true) ~= nil or Frame.Clean:find("first letters spell", 1, true) ~= nil or Frame.Clean:find("first letter of each line spells", 1, true) ~= nil or Frame.Clean:match("lines? that spell") ~= nil
        end, function(Frame)
            local Word: string? = Frame.Clean:match("spell (%a+)") or Frame.Clean:match("spells (%a+)") or Frame.Clean:match("acrostic of (%a+)") or Frame.Clean:match("acrostic for (%a+)") or Frame.Clean:match("acrostic (%a+)")
            if not Word or #Word < 2 or #Word > 12 then
                return Mind.Reply("Which word should the first letters spell? For example \"an acrostic that spells FLY\".")
            end

            local Out = {}
