        }

        local RoleAliases = {kitten = "cat", kitty = "cat", puppy = "dog", eagle = "bird", owl = "bird", parrot = "bird", shark = "fish", android = "robot", ai = "robot", spirit = "ghost", mayor = "president", rich = "millionaire", billionaire = "millionaire", invisibility = "invisible", person = "human", professor = "teacher", youtuber = "streamer", twitch = "streamer", queen = "king", batman = "superhero", superman = "superhero", mage = "wizard", witch = "wizard", viking = "pirate", samurai = "ninja", chicken = "bird", duck = "bird", pig = "cow", horse = "cow", ufo = "alien", martian = "alien"}

        local Wishes = {
