            teleport = "teleport onto the enemy bed and break it before anyone noticed",
            invisible = "walk through the lobby unseen",
            time = "rewind the game to the moment before my last mistake",
            money = "buy the best of everything and give half to my friends",
            power = "protect everyone's bed",
            wish = "wish for fair ping for everyone",
            superpower = "pick the power to rewind one fight",
            million = "put it all in diamonds and emeralds",
            lottery = "buy a very nice chair and a very nice keyboard"
        }

        Act("Hypothetical", function(Frame): boolean
            local C = Frame.Clean
            return (C:match("^if ") ~= nil and (C:find("how would", 1, true) ~= nil or C:find("what would", 1, true) ~= nil or C:find("what happens", 1, true) ~= nil or C:find("would anyone", 1, true) ~= nil or C:find("who wins", 1, true) ~= nil or C:find("would you", 1, true) ~= nil)) or C:match("^lets say ") ~= nil or C:match("^say you ") ~= nil or C:find("if you were", 1, true) ~= nil or C:find("if you could", 1, true) ~= nil or C:find("if you had", 1, true) ~= nil or C:find("if i were you", 1, true) ~= nil or C:find("would you rather", 1, true) ~= nil or C:find("what would you do", 1, true) ~= nil
                or C:match("^imagine ") ~= nil or C:match("^what if ") ~= nil or C:match("^suppose ") ~= nil or C:match("^pretend ") ~= nil or C:find("if you woke", 1, true) ~= nil or C:find("if you won", 1, true) ~= nil or C:find("if you found", 1, true) ~= nil or C:find("if you became", 1, true) ~= nil
        end, function(Frame)
            local C = Frame.Clean
            if C:find("would you rather") then
                local Rest: string = C:match("would you rather (.+)$") or ""
                local Options = {}
                for Part: string in (` {Rest} `):gsub(" or ", "|"):gmatch("[^|]+") do
                    Part = Mind.Trim(Part)
                    if Part ~= "" then
                        table.insert(Options, Part)
                    end
                end

                if #Options >= 2 then
                    local Chosen: string = Options[(Mind.Hash(C) % #Options) + 1]
                    local Echo: string = Mind.Turn(Chosen)
                    local Other: string = Mind.Turn(Options[Options[1] == Chosen and 2 or 1])
                    return Mind.Reply(Mind.Join(
                        Mind.Any("Ooh, tough.", "Okay, that's a real dilemma.", "I'll commit to an answer."),
                        Mind.Any(`My pick: {Echo}.`, `I'd go with the first... no, {Echo}.`, `Definitely this one: {Echo}.`),
                        Mind.Any(`The other one ({Other}) sounds like the bigger headache.`, `I can already see how "{Other}" goes wrong.`, "Gut feeling, no regrets.", `"{Mind.Cap(Other)}" has a catch I don't like.`)
                    ))
                end
            end

            if C:match("^if ") and (Frame.Set.you or Frame.Set.your) and (C:find("copy", 1, true) or C:find("clone", 1, true) or C:find("two of you", 1, true) or C:find("another pc", 1, true)) and Mind.AboutReply then
                return Mind.AboutReply(Frame)
            end

            local Role: string? = C:match("if you were (.+)$") or C:match("if you became (.+)$") or C:match("if you woke up as (.+)$") or C:match("imagine you were (.+)$") or C:match("imagine you are (.+)$") or C:match("pretend you are (.+)$") or C:match("pretend to be (.+)$")
            if Role then
                Role = Role:gsub("^an? ", ""):gsub("^the ", ""):gsub(" for .*$", ""):gsub(" for a day$", ""):gsub(" for one day$", ""):gsub(" for a week$", ""):gsub(" just for .*$", "")
                local Key: string = Role:match("(%a+)$") or Role
                Key = RoleAliases[Key] or Key
                local Doings = Roles[Key]
                local Time: string = Frame.Set.day and "for a day" or Frame.Set.week and "for a week" or ""
                if Doings then
                    local First: string = Mind.From(Doings)
                    local Second: string = Mind.From(Doings)
                    return Mind.Reply(Mind.Join(
                        Mind.Any("Ha, I like this question.", "Okay, let me think.", "Oh, this is a fun one."),
                        `If I were {Mind.Article(Role)} {Role}{Time ~= "" and " " .. Time or ""}, I'd {First}{Second ~= First and ", then probably " .. Second or ""}.`,
                        Mind.Any("After that I'd still check on your config now and then.", "And somewhere in between, I'd help someone fix a keybind.", "But I'd get bored and come back to the menu eventually.")
                    ), {"Ask me another"})
                end

                return Mind.Reply(Mind.Join(
                    Mind.Any("Interesting one.", "That's a big change from living in a menu.", "I'd have to think about that."),
                    `If I were {Mind.Article(Role)} {Role}, I'd probably spend the first hour just figuring out how it works, and the second showing everyone what I found.`,
                    Mind.Any("Then I'd try to be useful from there.", "I'd end up helping people with their setups anyway.", "Old habits.")
                ), {"What would you do?"})
            end

            local Wish: string? = C:match("if you could (.+)$") or C:match("if you had (.+)$") or C:match("if you won (.+)$") or C:match("if you found (.+)$")
            if Wish then
