                    Mind.Any("What about you?", "I'd probably tell you about it afterwards.", "Not that I'd keep it secret.")
                ))
            end

            local Premise: string? = C:match("^what if (.+)$") or C:match("^suppose (.+)$") or C:match("^imagine (.+)$") or C:match("^lets say (.+)$") or C:match("^say (.+)$") or C:match("^if (.+)$")
            if Premise then
