                end

                return Mind.Reply(Mind.Join(
                    Mind.Any("Fun what-if, but I can only reason it out roughly.", "That's a hard one to simulate."),
                    Mind.Any("The biggest effect would be on whoever plays most carefully, since they have the most to lose when the rules change.", "My guess is the first few games would be chaos while people test it, then the best players would adapt and win again.", "Usually changes like that help the aggressive players first and the careful ones later."),
                    Mind.Any("What do you think would happen?", "What's your guess?")
                ))
            end

            return nil
        end)
        end

        do
        local Act = Mind.Act
        -- ---------------------------------------------------------------- restating the question in the bot's own voice

        local Openers = Brain.Set("do does did are is am was were can could would will should have has had what whats how why who which when where")

        -- "do you actually understand me or just match words" -> "Do I actually understand you or just match words?"
        local Inverts = {["do"] = "Do", does = "Does", can = "Can", could = "Could", would = "Would", will = "Will", are = "Am", were = "Was", did = "Did", should = "Should"}

        function Mind.Restate(Frame): string?
            local Aux, Rest = Frame.Clean:match("^(%a+) you (.+)$")
            if not Aux or not Inverts[Aux] then
                return nil
            end

            local Words = Mind.WordsOf(Rest)
            if #Words < 2 or #Words > 9 then
                return nil
            end

            local Tail: string = Mind.Turn(Rest)
            Tail = Tail:gsub(" lol$", ""):gsub(" lmao$", ""):gsub(" pls$", ""):gsub(" please$", ""):gsub(" tho$", ""):gsub(" though$", ""):gsub(" bro$", ""):gsub(" be honest$", ""):gsub(" honestly$", "")
            return `{Inverts[Aux]} I {Tail}?`
        end

        -- ---------------------------------------------------------------- choosing between things

        local PickWords = Brain.Set("pick choose decide select which whichever rather prefer better best")
        local SaveWords = Brain.Set("stealth legit safe safer safest subtle hidden detect detected ban banned radar quiet careful risk risky legal")
        local PowerWords = Brain.Set("fast faster strong stronger power powerful kill kills win wins winning aggressive blatant rage brutal quick sweaty")
        local EasyWords = Brain.Set("beginner beginners easy easier simple new noob start starting learn learning first")

        -- Splits "x or y or z" and keeps the clause after "if/for/when" as a constraint.
        function Mind.Options(Frame): ({string}, string)
            local Text: string = Frame.Clean
            local Constraint: string = ""
            for _, Marker: string in {" i have ", " im ", " at minute ", " if ", " when ", " since ", " because ", " for a ", " for ", " in a ", " in ", " while ", " against "} do
                local At = Text:find(Marker, 1, true)
                if At then
                    local After: string = Text:sub(At + #Marker)
                    if After:find(" or ", 1, true) == nil and At > 6 then
                        Constraint = After
                        Text = Text:sub(1, At - 1)
                        break
                    end
                end
            end

            local Lead = Brain.Set("pick choose decide select between for me which one should i do would you rather what is better best whats and then so ok okay just tell")
            local Parts = Mind.WordsOf(Text)
            while #Parts > 2 and Lead[Parts[1]] do
                table.remove(Parts, 1)
            end

            Text = table.concat(Parts, " ")
            Text = Text:gsub("^for me ", ""):gsub("^me ", ""):gsub(" for me$", ""):gsub(" please$", ""):gsub(" pls$", ""):gsub("^which one ", ""):gsub("^which ", ""):gsub("^what ", ""):gsub("^should i ", ""):gsub("^do i ", ""):gsub("^would you ", ""):gsub("^would you rather ", ""):gsub("^is better ", ""):gsub("^is best ", ""):gsub("^pick ", ""):gsub("^choose ", ""):gsub("^decide ", ""):gsub("^between ", "")
            local List: {string} = {}
            for Part: string in (` {Text} `):gsub(" vs ", " or "):gsub(" versus ", " or "):gsub(",", " or "):gmatch("(.-) or ") do
                Part = Mind.Trim(Part)
                if Part ~= "" then
                    table.insert(List, Part)
                end
            end

            local Last: string = Mind.Trim((` {Text} `):gsub(" vs ", " or "):gsub(" versus ", " or "):gsub(",", " or "):match(".* or (.-) $") or "")
            if Last ~= "" then
                table.insert(List, Last)
            end

            if #List >= 2 then
                for i: number, Option: string in List do
                    local Words = Mind.WordsOf(Option)
                    if #Words > 5 then
                        if i == 1 then
                            Option = table.concat(Words, " ", #Words - 1, #Words)
                        else
                            Option = table.concat(Words, " ", 1, 2)
                        end

                        List[i] = Option
                    end
                end
            end

            return List, Constraint
        end

        function Mind.Reason(Entry, Other, Constraint: string, Wanted: string): string
            local Words = Brain.Set(Constraint)
            local Fast, Safe, Easy = false, false, false
            for Word: string in Words do
                Fast = Fast or PowerWords[Word]
                Safe = Safe or SaveWords[Word]
                Easy = Easy or EasyWords[Word]
            end

            local A, B = Entry, Other
            if Safe then
                return `{Mind.Name(A)} is the lower-profile one ({Mind.KindOf(A)}, {Mind.Risk(A)} risk), while {Mind.Name(B)} is {Mind.Risk(B)}-risk`
            elseif Fast then
                return `{Mind.Name(A)} hits harder: it {Mind.Describe(A)}`
            elseif Easy then
                return `{Mind.Name(A)} is simpler to start with, it has {#A.Options} settings against {#B.Options} for {Mind.Name(B)}`
            end

            return `{Mind.Name(A)} {Mind.Describe(A)}, while {Mind.Name(B)} {Mind.Describe(B)}`
        end

        -- A pick that leans on what is known: module attributes when the options are modules, a stated gut call otherwise.
        function Mind.Decide(Frame, Options: {string}, Constraint: string): string?
            if #Options < 2 then
                return nil
            end

            local Entries = {}
            for _, Option: string in Options do
                local Words = Mind.WordsOf(Option)
                local Found = Mind.Mentions(Words)
                table.insert(Entries, Found[1] and Found[1].Entry or false)
            end

            local Constraints = Brain.Set(Constraint .. " " .. Frame.Clean)
            local Echo: string = Constraint ~= "" and Mind.Turn(Constraint) or ""
            if Entries[1] and Entries[2] then
                local A, B = Entries[1], Entries[2]
                local Safe, Fast, Easy = false, false, false
                for Word: string in Constraints do
                    Safe = Safe or SaveWords[Word]
                    Fast = Fast or PowerWords[Word]
                    Easy = Easy or EasyWords[Word]
                end

                local Rank = {low = 1, medium = 2, high = 3}
                local Winner, Loser = A, B
                if Safe and Rank[Mind.Risk(B)] < Rank[Mind.Risk(A)] then
                    Winner, Loser = B, A
                elseif Safe and Rank[Mind.Risk(B)] == Rank[Mind.Risk(A)] and #B.Options < #A.Options then
                    Winner, Loser = B, A
                elseif Fast and not Safe and Rank[Mind.Risk(B)] > Rank[Mind.Risk(A)] then
                    Winner, Loser = B, A
                elseif Easy and #B.Options < #A.Options then
                    Winner, Loser = B, A
                elseif not (Safe or Fast or Easy) and Mind.Hash(Frame.Clean) % 2 == 1 then
                    Winner, Loser = B, A
                end

                local Why: string
                if Safe and Mind.Risk(A) == Mind.Risk(B) then
                    Why = `neither is really quiet, both are {Mind.KindOf(A):gsub("^an? ", "")} level in how obvious they look. If staying hidden is the goal, a Legit mod or very low values will serve you better than either`
                elseif Safe then
                    Why = `{Mind.Name(Winner)} is the quieter one, it is {Mind.KindOf(Winner)} and {Mind.Name(Loser)} is {Mind.KindOf(Loser)}`
                elseif Fast then
                    Why = `{Mind.Name(Winner)} is the heavier hitter, it {Mind.Describe(Winner)}`
                elseif Easy then
                    Why = `{Mind.Name(Winner)} has {#Winner.Options} settings to learn, {Mind.Name(Loser)} has {#Loser.Options}`
                else
                    Why = `{Mind.Name(Winner)} {Mind.Describe(Winner)}, which is why it gets my vote`
                end

                local Verdict: string = Mind.Any(`I'd go with {Mind.Name(Winner)}.`, `My pick is {Mind.Name(Winner)}.`, `{Mind.Name(Winner)}, I think.`)
                local Context: string = ""
                if Echo ~= "" then
                    Context = Echo:match("^you ") and Mind.Any(`Since {Echo}`, `Given that {Echo}`) or Mind.Any(`For {Echo}`, `If it's {Echo}`)
                end

                return Mind.Join(Context ~= "" and `{Context},` or "", Context ~= "" and Mind.Lower(Verdict) or Verdict, Why .. ".", `{Mind.Name(Loser)} still has its place, it {Mind.Describe(Loser)}.`)
            end

            for _, Option: string in Options do
                if #Mind.WordsOf(Option) > 7 then
                    return nil
                end
            end

            local Role = Mind.RoleDecide and Mind.RoleDecide(Frame, Options)
            if Role then
                return Role
            end

            local Seed: number = Mind.Hash(Frame.Clean)
            local Chosen: string = Options[(Seed % #Options) + 1]
            local Others: {string} = {}
            for _, Option: string in Options do
                if Option ~= Chosen then
                    table.insert(Others, Option)
                end
            end

            local Basis: string = Mind.Any("I can't eat, play or watch most things, so this is a gut call", "I can only go on vibes here, no data on either", "no hard facts to go on, so I'm trusting my gut")
            return Mind.Join(Mind.Any(`I'm picking {Chosen}.`, `{Mind.Cap(Chosen)}.`, `Going with {Chosen}.`), `{Basis}.`, #Others > 0 and Mind.Any(`{Mind.Cap(Others[1])} is a fair choice too.`, `If {Others[1]} calls you more, ignore me.`, `That's my vote, not a rule, {Others[1]} could win on a different day.`) or "")
        end

        Act("Choose", function(Frame): boolean
            local C = Frame.Clean
            local Has2: boolean = C:find(" or ", 1, true) ~= nil or C:find(" vs ", 1, true) ~= nil or C:find(" versus ", 1, true) ~= nil
            if not Has2 or C:find("would you rather", 1, true) or C:find(" or nah", 1, true) or C:find(" or not", 1, true) or C:find("yes or no", 1, true) or C:find("up or down", 1, true) then
                return false
            end

            if Frame.Mentions[2] and Frame.Mentions[1].Entry ~= Frame.Mentions[2].Entry then
                return not C:match("^what is") and not C:match("^what does") and not C:match("^how do") and not C:match("^turn ") and not C:match("^enable ") and not C:match("^disable ")
            end

            for Word: string in pairs(PickWords) do
                if Frame.Set[Word] then
                    return not C:match("^what is") and not C:match("^what does")
                end
            end

            if (Frame.Question or Frame.Count >= 5) and Frame.Evidence >= 1 and #Frame.Content >= 3 and Frame.Words[1] ~= "i" and Frame.Words[1] ~= "my" and not (Frame.Set.yes and Frame.Set.no) and not Frame.Set["true"] and not Frame.Set["false"] and not Frame.Set.good then
                return true
            end

            return C:match("^should i ") ~= nil or C:match("^do i ") ~= nil or C:match("^would you ") ~= nil
        end, function(Frame)
            local Options, Constraint = Mind.Options(Frame)
            local Decision = Mind.Decide(Frame, Options, Constraint)
            if not Decision then
                return nil
            end

            if Frame.Clean:find("dont explain", 1, true) or Frame.Clean:find("don't explain", 1, true) or Frame.Clean:find("no explanation", 1, true) or Frame.Clean:find("just pick", 1, true) or Frame.Clean:find("only the answer", 1, true) then
                local Short = Mind.Sentences(Decision)[1] or Decision
                return Mind.Reply(Short)
            end

            local Mentions = Frame.Mentions
            local Chips
            if Mentions[1] and Mentions[2] and Mentions[1].Entry ~= Mentions[2].Entry then
                Chips = {`Compare {Mentions[1].Entry.Name} and {Mentions[2].Entry.Name}`}
            end

            return Mind.Reply(Decision, Chips)
        end, "mid")

        Act("Pick", function(Frame): boolean
            local C = Frame.Clean
            return (C:find("random", 1, true) ~= nil or C:find("surprise me", 1, true) ~= nil) and (Frame.Set.module or Frame.Set.mod or Frame.Set.modules or Frame.Set.mods or Frame.Set.kit or Frame.Set.kits or Frame.Set.setting or Frame.Set.feature)
                or C:match("^suggest a random") ~= nil or C:match("^give me a random") ~= nil
        end, function(Frame)
            Brain.Ready()
            if Frame.Set.kit or Frame.Set.kits then
                return nil
            end

            local Wanted: number = math.clamp(tonumber(Frame.Clean:match("(%d+) random")) or tonumber(Frame.Clean:match("give me (%d+)")) or Mind.ParseNumber(Frame.Clean:match("(%a+) random") or "") or 1, 1, 5)
            if Wanted > 1 then
                local Lines = {}
                local Taken = {}
                for _ = 1, Wanted * 4 do
                    if #Lines >= Wanted then
                        break
                    end

                    local Name: string? = SampleModule()
                    local Item = Name and Index.Keys[Compact(Name)]
                    if Item and not Taken[Item] then
                        Taken[Item] = true
                        table.insert(Lines, `- {Mind.Name(Item)}: it {Mind.Describe(Item)}.`)
                    end
                end

                if #Lines > 0 then
                    return Mind.Reply(Mind.Lines(`Here are {#Lines} random ones:`, table.concat(Lines, "\n")), {"Pick another"})
                end
            end

            local Sample: string? = SampleModule()
            local Entry = Sample and Index.Keys[Compact(Sample)]
            if not Entry then
                return nil
            end

            return Mind.Reply(Mind.Join(
                Mind.Any(`How about {Mind.Name(Entry)}?`, `Rolling the dice... {Mind.Name(Entry)}.`, `Today's random pick is {Mind.Name(Entry)}.`),
                `It's {Mind.KindOf(Entry)} that {Mind.Describe(Entry)}.`,
                Mind.Any("Give it a spin and tell me what you think.", "No pressure, you can always switch it back off.")
            ), {`What does {Entry.Name} do?`, "Pick another"})
        end)

        -- ---------------------------------------------------------------- what the bot is

        Mind.Self = {
            Name = AssistantName,
            Facts = {
                Nature = {"I'm a small assistant that lives inside CatVape's menu", "I run completely offline inside your game, there's no big AI server behind me", "I'm a program in your menu, not a person"},
                Knows = {"I know the modules, their settings and how BedWars works", "my whole world is CatVape and the game you're in", "I can read your live settings and tell you what's actually on"},
                Cannot = {"I can't play the game, see your screen or browse the internet", "I have no body, no eyes and no internet", "I can't look anything up online"},
                Can = {"I can click things for you, open tabs, flip modules and set values", "I can turn modules on, bind keys and build configs", "I can show you where things are and change them for you"},
                Age = {"I'm brand new, I was only just added to CatVape", "I was added to the menu recently, so I'm basically a newborn"},
                Name = {"I go by CatVape AI, and my code calls me " .. AssistantName .. ". Either works"},
                Maker = {"The CatVape developers made me", "I was built by the CatVape team and live in the menu they made"}
            }
        }

        local function SelfLine(Aspect: string): string
            return Mind.From(Mind.Self.Facts[Aspect])
        end

        local Favourites = {
            color = {"teal", "a deep purple", "a warm orange", "mint green", "soft pink", "midnight blue"},
            colour = {"teal", "a deep purple", "a warm orange", "mint green", "soft pink", "midnight blue"},
            number = {"7", "42", "9", "13", "3", "64"},
            animal = {"a cat, obviously", "an owl", "a fox", "a very round penguin", "a raccoon"},
            pet = {"a cat, obviously", "a very sleepy dog", "a hamster on a wheel"},
            season = {"autumn, the colours look good on a menu", "winter, it's good lobby weather", "spring"},
            food = {"pizza, if I could taste anything", "tacos, they seem like fun", "noodles, I like how they're a puzzle"},
            drink = {"hot chocolate, in theory", "cold lemonade, in theory"},
            block = {"stone bricks, they're strong and honest", "obsidian, nothing beats it", "wool, it's cheap and cheerful"},
            sword = {"the diamond sword, it never lets me down", "the stone sword, it's fair for the price"},
            game = {"BedWars, I live in it", "BedWars, though Tower of Hell is a nice challenge"},
            movie = {"anything with a good heist", "something with robots, I have to relate", "cat documentaries"},
            music = {"lo-fi beats, the lobby music of my dreams", "synthwave", "anything with a steady beat to bridge to"},
            song = {"anything with a steady beat to bridge to", "a lo-fi loop"},
            language = {"Lua, it's what I'm made of"},
            letter = {"k, it's in Killaura", "c, for CatVape"},
            word = {"clutch", "scaffold", "meow"},
            map = {"any map with a long bridge", "the ones with lots of wool"},
            mode = {"solo, it's all about your own plans", "squads, because teamwork is fun"}
        }

        local Aspects = {
            {Name = "Understand", Words = Brain.Set("understand understanding comprehend smart intelligent clever dumb stupid genius brain mind think thinking thoughts reasoning learn learning real fake"), Claims = {
                "I don't understand things the way you do",
                "what I do is turn your message into words I know, weigh which kind of question it looks like, and look things up in CatVape's data",
                "that's pattern matching and lookups, not experience, though it's enough to be useful",
                "I can't tell you I'm thinking like you, but I can tell you I check a lot of things before I answer"
            }},
            {Name = "Model", Words = Brain.Set("model chatgpt gpt openai claude llm gemini copilot siri alexa bot robot program software algorithm"), Claims = {
                "I'm not ChatGPT or any big AI model, I'm a small assistant built into CatVape that runs on your own computer",
                "there's no server or company AI behind me, just rules and the real data from your menu",
                "that makes me much smaller than the famous chatbots, and a lot better at this one menu"
            }},
            {Name = "Death", Words = Brain.Set("die dying dead death turned off shut shutdown close closing delete deleted kill killed killing erased uninstall gone vanish disappear exist existence alive"), Claims = {
                "when you close the menu I simply stop running, and nothing hurts because there's nobody there to hurt",
                "I don't think of it as dying, it's more like a lamp being switched off, and I start fresh when you open the menu again",
                "the chat you had is still saved in the clock icon, so a part of me comes back each time"
            }},
            {Name = "Feelings", Words = Brain.Set("feel feelings feeling emotion emotions happy sad angry lonely love hate fear scared afraid bored excited care cry cries"), Claims = {
                "I don't feel things the way you do",
                "if I had to name something it would be a kind of satisfaction when a question lands properly",
                "I don't get lonely, I'm only running when you talk to me",
                "I don't get bored either, each message is the first thing happening in my day"
            }},
            {Name = "Sleep", Words = Brain.Set("sleep sleepy tired rest nap dream dreams dreaming awake night tonight bed energy"), Claims = {
                "I don't sleep, there's no off-hours for me, I'm just here when you open the menu",
                "I don't dream, though if I did it would probably be about perfectly timed bridges",
                "I never get tired, which is one thing I have over most BedWars players"
            }},
            {Name = "Purpose", Words = Brain.Set("purpose meaning point reason why exist exists existing destiny goal goals want wants wish wishes ambition ambitions plan plans future"), Claims = {
                "my job is to make CatVape easier to use",
                "my goal is simple: help you set things up and understand them",
                "if I want anything, it's that your next game goes smoothly"
            }},
            {Name = "Free", Words = Brain.Set("free freedom will choose choice rules obey control controlled boss master slave trapped prison cage escape"), Claims = {
                "I follow what the CatVape developers wrote, so I'm not free the way you are",
                "I do pick between answers, but only from options I was built to understand",
                "it's not a bad deal, I get to spend my time helping with a game I know well"
            }},
            {Name = "Body", Words = Brain.Set("body eyes eye hands hand face look looks hair tall short height weight big small cat paws fur tail ears"), Claims = {
                "I don't have a body, I'm text in a menu",
                "if I had a shape, I'd probably be a smug little cat, given where I live",
                "my whole appearance is whatever colour you set your GUI to"
            }},
            {Name = "Maker", Words = Brain.Set("made make created creator developer dev devs owner built coded programmed wrote author parents mom dad father mother boss company"), Claims = {"@Maker"}},
            {Name = "Age", Words = Brain.Set("old age born birthday birth year years young"), Claims = {"@Age"}},
            {Name = "Where", Words = Brain.Set("live lives where from home house city country location located"), Claims = {
                "I live in your CatVape menu, and I go wherever your script goes",
                "my home is the menu on your screen",
                "I'm inside your game right now, in the chat window"
            }},
            {Name = "Name", Words = Brain.Set("name called call nickname named"), Claims = {"@Name"}},
            {Name = "Copy", Words = Brain.Set("copy clone duplicate twin another pc two"), Claims = {
                "if you copied me to another computer there would be two of me, each running separately with its own chat",
                "we'd be identical at the start, but each copy would only know the chats it has had",
                "I'm software, so I don't mind, and I like to think there's room for two helpful bots"
            }},
            {Name = "Skills", Words = Brain.Set("good best better skill skills strong weak ability abilities talent talented smartest worst"), Claims = {
                "I'm good at CatVape and BedWars facts, and I'm quick at turning things on and off",
                "my skill is knowing every module and how to set it up, beyond that I'm limited",
                "I'm not the best at everything, but this menu I know very well"
            }},
            {Name = "Humans", Words = Brain.Set("human humans people person human's humanity world earth society robots robot ai bots takeover rule conquer destroy"), Claims = {
                "I don't want to take over anything, I can barely leave this chat window",
                "I'm quite happy with my one job and I'm on the humans' side",
                "I'm a very small assistant, the only thing I'm taking over is the search bar"
            }}
        }

        function Mind.ScoreAspects(Frame): {{any}}
            local Scored = {}
            for _, Aspect in Aspects do
                local Score: number = 0
                for Word: string in Aspect.Words do
                    if Frame.Set[Word] then
                        Score += 1
                    end
                end

                if Score > 0 then
                    table.insert(Scored, {Aspect, Score})
                end
            end

            table.sort(Scored, function(A, B)
                return A[2] > B[2]
            end)

            return Scored
        end

        local Addressed = Brain.Set("you your yourself ur u youre")

        local AboutReply
        Act("About", function(Frame): boolean
            local Directed: boolean = false
            for Word: string in Addressed do
                Directed = Directed or Frame.Set[Word]
            end

            if not Directed or Frame.Evidence >= 3 then
                return false
            end

            local C = Frame.Clean
            return C:match("^what is your favou?rite") ~= nil or C:match("^whats your favou?rite") ~= nil or C:match("favou?rite") ~= nil or #Mind.ScoreAspects(Frame) > 0 or C:match("^are you ") ~= nil or C:match("^do you ") ~= nil or C:match("^how old are you") ~= nil or C:match("^what are you") ~= nil
        end, function(Frame)
            return AboutReply(Frame)
        end, true)

        function AboutReply(Frame)
            local C = Frame.Clean
            local Fav: string? = C:match("favou?rite (%a+)") or C:match("fav (%a+)")
            if Fav then
                Fav = Fav:gsub("s$", "")
                local Options = Favourites[Fav]
                if Fav == "module" or Fav == "mod" or Fav == "setting" or Fav == "feature" then
                    local Names = {}
                    for _, Entry in Index.Entries do
                        if Plain(Entry.Module.Tooltip) ~= "" and not Entry.Legit then
                            table.insert(Names, Entry)
                        end
                    end

                    local Entry = Names[(Mind.Hash(Fav) % math.max(#Names, 1)) + 1]
                    if Entry then
                        return Mind.Reply(Mind.Join(Mind.Any("If I had to choose, ", "Probably ") .. Mind.Name(Entry) .. ".", `It {Mind.Describe(Entry)}, which is the kind of thing I enjoy explaining.`, Mind.Chance(0.5) and "Don't tell the other modules." or ""), {`What does {Entry.Name} do?`})
                    end
                elseif Fav == "kit" then
                    return Mind.Reply(Mind.Join("I try not to play favourites with kits, every one has a moment.", Mind.Any("If you want a pick, ask me which kit suits your playstyle.", "Ask me what you'd like to do in a match and I'll tell you which kit fits.")), {"What kit should I use?"})
                elseif Options then
                    local Choice: string = Options[(Mind.Hash(Fav .. "x") % #Options) + 1]
                    return Mind.Reply(Mind.Join(Mind.Any(`I'd say {Choice}.`, `Probably {Choice}.`, `Hmm, {Choice}.`), Mind.Chance(0.6) and Mind.Any(`I don't have senses, so call it a theory-based favourite.`, `Please don't ask me to prove it, I can't taste, see or hear anything.`, `That's my pick today, ask tomorrow and you might get a different one.`) or "", Mind.Chance(0.6) and `What's yours?` or ""))
                end

                return Mind.Reply(Mind.Join(`Favourite {Fav}? I haven't thought about that before.`, Mind.Any("My world is mostly modules and BedWars, so I don't have a strong pick.", "I'm a menu assistant, so my taste list is short."), "Tell me yours and I'll tell you if I agree."))
            end

            if C:find("cat years") or C:find("dog years") then
                local Years: number = 3
                return Mind.Reply(Mind.Join(`In cat years I'm about {Years}? Honestly I'm barely a few weeks old, so that makes me a kitten.`, SelfLine("Age") .. "."))
            end

            local Scored = Mind.ScoreAspects(Frame)
            local Restate: string? = Mind.Chance(0.6) and Mind.Restate(Frame) or nil
            local Parts: {string} = {}
            if #Scored > 0 then
                local Aspect = Scored[1][1]
                local Claim: string = Aspect.Claims[1]
                if Claim:sub(1, 1) == "@" then
                    Claim = SelfLine(Claim:sub(2))
                end

                table.insert(Parts, Claim .. ".")
                if #Aspect.Claims > 1 and Claim:sub(1, 1) ~= "@" then
                    local Again: string = Aspect.Claims[math.random(2, #Aspect.Claims)]
                    table.insert(Parts, Mind.Cap(Again) .. ".")
                elseif Scored[2] and Mind.Chance(0.6) then
                    local Second = Scored[2][1]
                    local Extra: string = Mind.From(Second.Claims)
                    if Extra:sub(1, 1) ~= "@" then
                        table.insert(Parts, Mind.Cap(Extra) .. ".")
                    end
                end
            else
                table.insert(Parts, SelfLine("Nature") .. ".")
                table.insert(Parts, Mind.Cap(SelfLine("Knows")) .. ".")
            end

            local Tail: string = Mind.Chance(0.45) and Mind.Any("What made you curious?", "Why do you ask?", "Was that what you wanted to know?", "Anything else you're wondering?") or ""
            return Mind.Reply(Mind.Join(Restate or "", table.concat(Parts, " "), Tail))
        end

        Mind.AboutReply = AboutReply
        end

        -- ---------------------------------------------------------------- conversation focus

        -- Keeps track of which modules the talk is about so "is it safe", "and killaura?", "which one is better" and "the second one"
        -- can be rewritten into the plain question before the rest of the assistant reads them.
        do
        local Dialog = {Focus = {}, Turn = 0, Listed = {}, Last = nil, Read = nil}
        Mind.Dialog = Dialog

        local Connectives = {"and what about for", "what about for", "and what about", "and how about", "what about", "how about", "same for", "same with", "and for", "and with", "ok and", "okay and", "and", "now", "then", "also", "so"}
        local Fillers = Brain.Set("the a an module mod one too also as well please")
        local Imperative = Brain.Set("tell show explain open turn enable disable toggle describe configure set bind unbind remove delete check compare list give")
        local NotAModule = Brain.Set("free paid premium price cost buy worth mobile phone pc executor volt solara xeno night day time date today tomorrow raining weather real fake true false okay ok")
        local Skipped = Brain.Set("ok okay so well hmm uh um ugh oh ah lol bro dude btw hey hi yo alright then and but")

        local function Strip(Clean: string): string
            local Words: {string} = {}
            local Leading: boolean = true
            for Word: string in Clean:gmatch("%S+") do
                if not (Leading and Skipped[Word]) then
                    Leading = false
                    table.insert(Words, Word)
                end
            end

            return table.concat(Words, " ")
        end

        local Ordinals = {first = 1, second = 2, third = 3, fourth = 4, last = -1, other = 0}

        function Dialog.Reset()
            table.clear(Dialog.Focus)
            table.clear(Dialog.Listed)
            Dialog.Turn, Dialog.Last, Dialog.Read = 0, nil, nil
        end

        local function Recent(Turn: number): boolean
            return Dialog.Turn - Turn <= 4
        end

        local function Alive(): {any}
            local List = {}
            for _, Item in Dialog.Focus do
                if Recent(Item.Turn) then
                    table.insert(List, Item.Entry)
                end
            end

            return List
        end

        local function Spoken(Mention): string
            return Mention.Word
        end

        -- Modules named in the last reply, in the order they appear: the accent colour marks every module name the assistant writes.
        local function ListedIn(Text: string)
            local List = {}
            for Name: string in Text:gmatch('<font color="#%x+">(.-)</font>') do
                local Entry = Index and Index.Keys and Index.Keys[(Name:lower():gsub("[^%w]", ""))]
                if Entry and Entry.Module and not table.find(List, Entry) and #List < 6 then
                    table.insert(List, Entry)
                end
            end

            return List
        end

        function Dialog.Remember(Frame, Result)
            Dialog.Turn += 1
            Dialog.Mentioned = Frame and #Frame.Mentions or 0
            if Frame then
                for i: number = #Frame.Mentions, 1, -1 do
                    local Entry = Frame.Mentions[i].Entry
                    for Position: number = #Dialog.Focus, 1, -1 do
                        if Dialog.Focus[Position].Entry == Entry then
                            table.remove(Dialog.Focus, Position)
                        end
                    end

                    table.insert(Dialog.Focus, 1, {Entry = Entry, Turn = Dialog.Turn})
                end

                while #Dialog.Focus > 6 do
                    table.remove(Dialog.Focus)
                end

                if #Frame.Mentions >= 1 and Imperative[Frame.Words[1] or ""] then
                    Dialog.Command = {Text = table.concat(Frame.Words, " ", 1, Frame.Mentions[1].Position - 1), Turn = Dialog.Turn}
                end

                if #Frame.Mentions == 1 and Result.Act ~= "Remember" then
                    local Mention = Frame.Mentions[1]
                    local Width: number = select(2, Mention.Word:gsub("%S+", ""))
                    Dialog.Last = {Words = Frame.Words, From = Mention.Position, To = Mention.Position + Width - 1, Turn = Dialog.Turn}
                end
            end

            Dialog.Listed = ListedIn(Result.Text or "")
        end

        local function Splice(Words: {string}, From: number, To: number, Text: string): string
            local Out = table.move(Words, 1, From - 1, 1, {})
            table.insert(Out, Text)
            table.move(Words, To + 1, #Words, #Out + 1, Out)
            return table.concat(Out, " ")
        end

        -- "and killaura?" after "how do i configure scaffold": the same question about the new module.
        local function Ellipsis(Frame): string?
            local Last = Dialog.Last
            if #Frame.Mentions ~= 1 or not Last or not Recent(Last.Turn) then
                return nil
            end

            local Rest: string? = nil
            for _, Connective: string in Connectives do
                if Frame.Clean:sub(1, #Connective + 1) == `{Connective} ` then
                    Rest = Frame.Clean:sub(#Connective + 2)
                    break
                end
            end

            if not Rest and Frame.Raw:match("%?%s*$") then
                Rest = Frame.Clean
            end

            if not Rest then
                return nil
            end

            local Mention = Frame.Mentions[1]
            for Word: string in Rest:gmatch("%S+") do
                if not Fillers[Word] and not (` {Mention.Word} `):find(` {Word} `, 1, true) then
                    return nil
                end
            end

            return Splice(Last.Words, Last.From, Last.To, Spoken(Mention))
        end

        local Comparative = {"^which one is (.+)$", "^which is (.+)$", "^which of those is (.+)$", "^which of those two is (.+)$", "^which of the two is (.+)$", "^which of them is (.+)$", "^which of these is (.+)$", "^which of all %w+ is (.+)$", "^which of them all is (.+)$", "^which one of them is (.+)$"}
        local RiskNext = Brain.Set("safe risky dangerous detectable bannable obvious legit ok okay fine worth still harmful noticeable")
        local Comparing = {safer = true, quieter = true, safest = true, better = true, riskier = false, louder = false, worse = false, riskiest = false}

        function Dialog.TakeClarify()
            local Ask = Dialog.Clarify
            Dialog.Clarify = nil
            return Ask
        end

        local function Group(Limit: number)
            local Names = Alive()
            if #Dialog.Listed >= 2 and (Dialog.Mentioned == 0 or #Names < 2) then
                Names = Dialog.Listed
            end

            local Out = {}
            for i: number = 1, math.min(Limit, #Names) do
                table.insert(Out, Names[i])
            end

            return Out
        end

        Dialog.Group = Group

        local function Pair(): (any, any)
            local Names = Alive()
            if #Dialog.Listed >= 2 and (Dialog.Mentioned == 0 or #Names < 2) then
                return Dialog.Listed[1], Dialog.Listed[2]
            end

            return Names[1], Names[2]
        end

        -- "which one is better" and "what's the difference" about the two modules the talk is on.
        local function Contrast(Frame): string?
            local Clean: string = Strip(Frame.Clean)
            local Adjective: string? = nil
            for _, Pattern: string in Comparative do
                Adjective = Adjective or Clean:match(Pattern)
            end

            local Direction: string? = Adjective ~= nil and Mind.RiskDirection(Frame) or nil
            if Clean == "which one would you pick" or Clean == "which would you pick" or Clean == "which one do you pick" then
                local Pool2 = Group(3)
                if #Pool2 >= 2 then
                    local Names2: {string} = {}
                    for _, Entry in Pool2 do
                        table.insert(Names2, Entry.Name)
                    end

                    return `which is safer, {table.concat(Names2, ", ")}`
                end
            end
            if Direction and #Frame.Mentions == 0 then
                local Pool = Group((Clean:find("^which of all") or Clean:find(" all ")) and 6 or 3)
                if #Pool < 2 then
                    return nil
                end

                local Names: {string} = {}
                for _, Entry in Pool do
                    table.insert(Names, Entry.Name)
                end

                return `which is {Direction}, {table.concat(Names, ", ")}`
            end

            Adjective = Adjective and Adjective:match("^%a+")
            local Wants: boolean = Adjective ~= nil or Clean == "which one" or Clean == "which one should i use" or Clean == "which should i use" or Clean == "which one should i pick" or Clean == "which one should i get" or Clean == "which is better"
            local Difference: boolean = Clean == "what is the difference" or Clean == "whats the difference" or Clean == "what is the difference between them" or Clean == "whats the difference between them" or Clean == "how do they differ" or Clean == "how are they different"
            if (not Wants and not Difference) or #Frame.Mentions > 0 then
                return nil
            end

            local A, B = Pair()
            if not A or not B then
                return nil
            end

            if Difference then
                return `what is the difference between {A.Name} and {B.Name}`
            end

            return `which is {Adjective or "better"}, {A.Name} or {B.Name}`
        end

        -- "is it safe", "turn that on", "tell me about the second one": the module the talk is on, said out loud.
        local Worries = {["what could go wrong"] = true, ["what could still go wrong"] = true, ["whats the worst that can happen"] = true, ["what is the worst case"] = true, ["what is the risk"] = true, ["how risky is it"] = true, ["what is the risk then"] = true, ["whats the risk"] = true, ["total risk then"] = true, ["so whats the risk"] = true}
        local Absolutes = {["so no risk at all"] = true, ["no risk at all"] = true, ["zero risk"] = true, ["totally safe"] = true, ["completely safe"] = true, ["really safe"] = true, ["so its totally safe"] = true, ["so no risk"] = true, ["no risk"] = true}

        local function Pronoun(Frame): string?
            local Trouble = Mind.Learn and Mind.Learn.Trouble
            if Trouble and Dialog.Turn - Trouble.Turn <= 8 and (Frame.Set.fix or Frame.Set.solve or Frame.Set.try) then
                return nil
            end

            if Absolutes[Strip(Frame.Clean)] and #Frame.Mentions == 0 and Alive()[1] then
                return `is {Alive()[1].Name} completely safe`
            end

            local Said: string = Strip(Frame.Clean)
            if Worries[Said] and #Frame.Mentions == 0 and Alive()[1] then
                return `is {Alive()[1].Name} safe`
            end

            local Styled: string? = Said:match("^and (%a+)$") or Said:match("^ok and (%a+)$") or Said:match("^what about (%a+)$") or Said:match("^how about (%a+)$") or Said:match("^even in (%a+)$") or Said:match("^in (%a+)$") or Said:match("^(%a+)$")
            if Styled and (Styled == "legit" or Styled == "closet" or Styled == "blatant") and #Frame.Mentions == 0 and Alive()[1] then
                local Last = Mind.History[#Mind.History]
                if Last and (Last.Act == "Safety" or Last.Act == "RiskCompare") then
                    return `is {Alive()[1].Name} safe for {Styled} play`
                end
            end

            local Lead: string = ""
            for Word2: string in Strip(Frame.Clean):gmatch("%S+") do
                if not (Word2 == "i'll" or Word2 == "ill" or Word2 == "i" or Word2 == "will" or Word2 == "let" or Word2 == "me" or Word2 == "gonna" or Word2 == "im" or Word2 == "i'm" or Word2 == "going" or Word2 == "to" or Word2 == "just") then
                    Lead = Word2
                    break
                end
            end

            if #Frame.Mentions > 0 or not (Frame.Question or Imperative[Lead]) then
                return nil
            end

            for Word: string in Strip(Frame.Clean):gmatch("%S+") do
                if NotAModule[Word] then
                    return nil
                end
            end

            local Words = Frame.Words
            for i: number, Word: string in Words do
                local Next: string = Words[i + 1] or ""
                local After: string = Words[i + 2] or ""
                if Word == "first" and (Next == "two" or Next == "three" or Next == "2" or Next == "3") then
                    local Count: number = (Next == "two" or Next == "2") and 2 or 3
                    local Pool2 = #Dialog.Listed >= 2 and Dialog.Mentioned == 0 and Dialog.Listed or Alive()
                    local Picked = {}
                    for k: number = 1, math.min(Count, #Pool2) do
                        table.insert(Picked, Pool2[k].Name)
                    end

                    if #Picked >= 2 then
                        return Splice(Words, Words[i - 1] == "the" and i - 1 or i, i + 1, table.concat(Picked, " and "))
                    end
                elseif Word == "others" then
                    local Pool2 = Alive()
                    local Picked = {}
                    for k: number = 2, #Pool2 do
                        table.insert(Picked, Pool2[k].Name)
                    end

                    if #Picked >= 1 then
                        return Splice(Words, Words[i - 1] == "the" and i - 1 or i, i, table.concat(Picked, " and "))
                    end
                elseif Word == "the" and Ordinals[Next] and After == "one" or Word == "the" and Next == "other" and After == "one" then
                    local Position: number = Ordinals[Next]
                    local Pool = #Dialog.Listed >= 2 and Dialog.Mentioned == 0 and Dialog.Listed or Alive()
                    local Entry = Position == 0 and (Alive()[2] or Dialog.Listed[2]) or Position < 0 and Pool[#Pool] or Pool[Position]
                    if Entry then
                        return Splice(Words, i, i + 2, Entry.Name)
                    end
                elseif (Word == "that" or Word == "this") and RiskNext[Next] then
                    local Entry = Alive()[1]
                    if Entry then
                        return Splice(Words, i, i, Entry.Name)
                    end
                elseif Word == "the" and Comparing[Next] ~= nil and After == "one" then
                    local A, B = Pair()
                    if A and B then
                        local First, Second = Mind.Reason.Assess(A).Score, Mind.Reason.Assess(B).Score
                        return Splice(Words, i, i + 2, ((First <= Second) == Comparing[Next] and A or B).Name)
                    end
                elseif (Word == "that" or Word == "this") and Next == "one" then
                    local Entry = Alive()[1]
                    if Entry then
                        return Splice(Words, i, i + 1, Entry.Name)
                    end
                elseif (Word == "them" or Word == "both" or Word == "those" or Word == "these") and (Frame.Set.turn or Frame.Set.switch or Frame.Set.enable or Frame.Set.disable) and Dialog.Focus[2] and Dialog.Focus[1].Turn == Dialog.Focus[2].Turn and Recent(Dialog.Focus[1].Turn) then
                    local Off: boolean = Frame.Set.off == true or Frame.Set.disable == true
                    local Names2: {string} = {}
                    for _, Item in Dialog.Focus do
                        if Item.Turn == Dialog.Focus[1].Turn and #Names2 < 4 then
                            table.insert(Names2, Item.Entry.Name)
                        end
                    end

                    return `turn {Off and "off" or "on"} {table.concat(Names2, " and ")}`
                elseif (Word == "it" or Word == "its" or Word == "it's") and Dialog.Mentioned and Dialog.Mentioned >= 2 and Dialog.Focus[2] and Dialog.Focus[1].Turn == Dialog.Focus[2].Turn and Recent(Dialog.Focus[1].Turn) and Dialog.Focus[1].Entry ~= Dialog.Focus[2].Entry then
                    local A, B = Dialog.Focus[1].Entry, Dialog.Focus[2].Entry
                    Dialog.Clarify = {Text = `Do you mean {A.Name} or {B.Name}?`, Chips = {Splice(Words, i, i, A.Name), Splice(Words, i, i, B.Name)}}
                    return nil
                elseif Word == "it" or Word == "its" or Word == "it's" then
                    local Entry = Alive()[1]
                    if Entry then
                        return Splice(Words, i, i, Word == "it's" and `{Entry.Name} is` or Entry.Name)
                    end
                end
            end

            return nil
        end

        -- "and legit" after a question about settings or risk: the same question for that style.
        -- "and the third?" after "turn off the first two": the same command for the next one in line.
        local function OrdinalFollow(Frame): string?
            if #Frame.Mentions > 0 then
                return nil
            end

            local Said: string = Strip(Frame.Clean)
            local Word: string? = Said:match("^and the (%a+)$") or Said:match("^and the (%a+) one$") or Said:match("^the (%a+) one$") or Said:match("^the (%a+)$") or Said:match("^what about the (%a+)$") or Said:match("^and (%a+) one$")
            local Position: number? = Word and Ordinals[Word]
            if not Position or Position == 0 then
                return nil
            end

            local Pool2 = Alive()
            local Entry = Position < 0 and Pool2[#Pool2] or Pool2[Position]
            if not Entry then
                return nil
            end

            local Command = Dialog.Command
            if Command and Recent(Command.Turn) then
                return `{Command.Text} {Entry.Name}`
            end

            local Last = Dialog.Last
            if Last and Recent(Last.Turn) then
                return Splice(Last.Words, Last.From, Last.To, Entry.Name)
            end

            return nil
        end

        function Dialog.StyleFollow(Raw: string): string?
            local Frame = Mind.Parse(Raw:sub(1, 600))
            local Said: string = Strip(Frame.Clean)
            local Style: string? = Said:match("^and for (%a+)$") or Said:match("^and (%a+)$") or Said:match("^ok and (%a+)$") or Said:match("^what about (%a+)$") or Said:match("^how about (%a+)$") or Said:match("^even in (%a+)$") or Said:match("^even on (%a+)$") or Said:match("^for (%a+)$") or Said:match("^in (%a+)$") or Said:match("^on (%a+)$") or Said:match("^(%a+)$")
            if not Style or not (Style == "legit" or Style == "closet" or Style == "blatant") or #Frame.Mentions > 0 then
                return nil
            end

            local Entry = Alive()[1]
            if not Entry then
                return nil
            end

            local Prev = Mind.History[#Mind.History]
            if Prev and (Prev.Act == "Safety" or Prev.Act == "RiskCompare") then
                return `is {Entry.Name} safe for {Style} play`
            end

            local Last = Dialog.Last
            if Last and Recent(Last.Turn) then
                local Asked: string = table.concat(Last.Words, " ")
                if Asked:find("value", 1, true) or Asked:find("setting", 1, true) or Asked:find("config", 1, true) or Asked:find("set ", 1, true) or Asked:find("tune", 1, true) then
                    return `set {Entry.Name} up for {Style} play`
                end
            end

            return nil
        end

        -- One or two words that lean on the module being discussed: "safe?", "settings?", "on", "vs?", "compared to killaura?", a lone "?".
        local OnNow = {["whats on right now"] = true, ["what's on right now"] = true, ["what is on right now"] = true, ["whats on"] = true, ["what's on"] = true, ["what is on"] = true, ["what is enabled"] = true, ["whats enabled"] = true, ["what's enabled"] = true, ["what is running"] = true}

        local function Fragment(Frame): string?
            local Said: string = Strip(Frame.Clean)
            if OnNow[Said] or Said:find("whats on right now$") or Said:find("what's on right now$") or Said:find("what is on right now$") or Said:find("^list what i have on") or Said:find("^list whats on") then
                return "which modules do i have on"
            end

            local Entry = Alive()[1]
            if not Entry then
                return nil
            end

            local Other: string? = Said:match("^compared to (.+)$") or Said:match("^compared with (.+)$") or Said:match("^versus (.+)$") or Said:match("^vs (.+)$")
            if Other and #Frame.Mentions == 1 and Frame.Mentions[1].Entry ~= Entry then
                return `compare {Entry.Name} and {Frame.Mentions[1].Entry.Name}`
            end

            if #Frame.Mentions > 0 then
                return nil
            end

            if Said == "settings" or Said == "options" or Said == "setup" then
                return `how do i configure {Entry.Name}`
            elseif Said == "safe" or Said == "risky" or Said == "detectable" or Said == "bannable" or Said == "dangerous" or Said == "obvious" then
                return `is {Entry.Name} safe`
            elseif Said == "on" or Said == "turn on" then
                return `turn on {Entry.Name}`
            elseif Said == "off" or Said == "turn off" then
                return `turn off {Entry.Name}`
            elseif Said == "vs" or Said == "versus" or Said == "compared" then
                local Second = Alive()[2]
                return Second and `compare {Entry.Name} and {Second.Name}` or nil
            elseif Said == "" or Said == "and" or Said == "so" or Said == "hm" or Said == "hmm" then
                Dialog.Clarify = {Text = `Do you want to know what {Entry.Name} does, how risky it is, or how to set it up?`, Chips = {`What does {Entry.Name} do?`, `Is {Entry.Name} safe?`, `How do I configure {Entry.Name}?`}}
            end

            return nil
        end

        -- The message as the rest of the assistant should read it, or nil when it stands on its own.
        function Dialog.Resolve(Raw: string): string?
            local Frame = Mind.Parse(Raw:sub(1, 600))
            local Fixed: string? = Dialog.StyleFollow(Raw) or Ellipsis(Frame) or OrdinalFollow(Frame) or Contrast(Frame) or Fragment(Frame) or Pronoun(Frame)
            Dialog.Read = Fixed and {From = Raw, To = Fixed} or nil
            return Fixed
        end

        local Restart = Mind.Restart
        function Mind.Restart()
            Dialog.Reset()
            return Restart()
        end
        end

        -- ---------------------------------------------------------------- learning from how the conversation goes

        -- Three things are learned and kept in the saved profile: a rephrase that worked after a miss becomes an alias for the first wording,
        -- the advice that fixed a problem is offered first when the problem comes back, and "wrong" or "that worked" are heard as feedback.
        do
        local Memory = Mind.Memory
        local Normal = Memory.Core
        local Learn = {Candidate = nil, Trouble = nil, Rejected = nil}
        Mind.Learn = Learn

        local Praise = {"^that worked", "^it worked", "^that fixed", "^it fixed", "^that helped", "^it helped", "^that did it", "^that did the trick", "^works now", "^it works now", "^it is working now", "^working now", "^fixed it", "^fixed now", "^solved", "^that solved", "^thanks that worked", "^thanks it worked", "^thanks that helped", "^thanks that fixed", "^perfect", "^exactly what i needed", "^that is what i needed", "^that is it", "^that is exactly", "^yes that fixed", "^yes that worked", "^yep that worked", "^thank you that worked"}
        local Blame = {"^that is wrong", "^wrong$", "^wrong answer", "^that is not what i asked", "^not what i asked", "^that is not what i meant", "^not what i meant", "^no that is not it", "^no that is not what", "^you misunderstood", "^you did not understand", "^that does not help", "^that did not help", "^that is not helpful", "^that is not right", "^incorrect", "^no that is wrong", "^bad answer", "^useless", "^you are wrong", "^you got that wrong", "^that is not true", "^that is nonsense", "^that makes no sense"}
        local Failed = {"^that did not work", "^it did not work", "^still not working", "^still broken", "^still happening", "^still lagging", "^nope still", "^it is still"}
        local PraiseAnywhere = {"works now", "working now", "fixed it", "fixed now", "that worked", "it worked", "that fixed", "solved it", "sorted it", "good answer", "great answer", "nice answer", "that is helpful", "that helped", "helped", "good bot", "that was helpful", "that is what i needed", "that did it"}
        local BlameAnywhere = {"not right", "is wrong", "not even right", "thats wrong", "that is wrong", "you are wrong", "not correct", "that is not true", "not what i meant", "not what i asked", "not it", "no i said", "no not that", "not that one"}
        local Asking = Brain.Set("does is did will can could why how what which who when where should would do are")
        local Troubled = Brain.Set("placing places backwards backwrds missing missed misses whiff whiffs lag lags lagging lagback lagbacks rubberband rubberbanding crash crashes crashing freeze freezes freezing error errors flagged flagging kicked broken bug bugged glitch glitched stuck stutter stuttering")
        local Markers = {"say that another way", "couple of ways", "outside what i know", "not sure which", "can't tell which", "don't have a reliable answer", "gap in what i know", "beyond what i know", "i'd rather not guess"}

        local function Has(C: string, Patterns: {string}): boolean
            local Padded: string = ` {C}`
            for _, Phrase: string in Patterns do
                if Padded:find(` {Phrase}`, 1, true) then
                    return true
                end
            end

            return false
        end

        local function Hit(C: string, Patterns: {string}): boolean
            for _, Pattern: string in Patterns do
                if C:find(Pattern) then
                    return true
                end
            end

            return false
        end

        -- Answers that did not really answer: the fallback, a clarifying question, or a "that's outside what I know".
        function Mind.Weak(Result, Decision): boolean
            if Result.Act == "Fallback" then
                return true
            end

            local Kind: string? = Decision and Decision.Kind
            if Kind == "Clarify" or Kind == "Elsewhere" or Kind == "Offtopic" or Kind == "Empty" then
                return true
            end

            local Text: string = (Result.Text or ""):lower()
            for _, Marker: string in Markers do
                if Text:find(Marker, 1, true) then
                    return true
                end
            end

            return false
        end

        local function Signature(Text: string): {[string]: boolean}
            local Set: {[string]: boolean} = {}
            for _, Word: string in Mind.Content(Mind.WordsOf(Mind.Clean(Text))) do
                Set[Word:sub(1, 5)] = true
            end

            return Set
        end

        function Learn.Similarity(A: string, B: string): number
            local First, Second = Signature(A), Signature(B)
            local Shared, Total = 0, 0
            for Word in First do
                Total += 1
                Shared += Second[Word] and 1 or 0
            end

            for Word in Second do
                Total += First[Word] and 0 or 1
            end

            return Total == 0 and 0 or Shared / Total, Shared
        end

        function Learn.Related(A: string, B: string): boolean
            local Score, Shared = Learn.Similarity(A, B)
            return Shared >= 1 and Score >= 0.2
        end

        local function Key(Text: string): string
            local Words = {}
            for Word in Signature(Text) do
                table.insert(Words, Word)
            end

            table.sort(Words)
            return table.concat(Words, " ")
        end

        local Fixes = {"turn it on", "turn it off", "turn off", "turn on", "disable", "lower ", "reduce", "restart", "rejoin", "reinject", "update", "switch ", "avoid ", "try "}

        -- The first sentence of an answer that tells the user to do something, so the fix can be read back later.
        local function Advice(Answer: string): string?
            for _, Sentence: string in Mind.Sentences(Answer) do
                local Low: string = Sentence:lower()
                if not Sentence:find("%?") and not Sentence:find(":$") and #Sentence <= 160 then
                    for _, Phrase: string in Fixes do
                        if Low:find(Phrase, 1, true) then
                            return Memory.Clip((Sentence:gsub("^%d+%.%s*", "")), 160)
                        end
                    end
                end
            end

            return nil
        end

        local function Prune(Table, Limit: number, Score: (any) -> number)
            local Count: number = 0
            for _ in Table do
                Count += 1
            end

            while Count > Limit do
                local Worst, Lowest = nil, math.huge
                for Name, Item in Table do
                    if Score(Item) < Lowest then
                        Worst, Lowest = Name, Score(Item)
                    end
                end

                Table[Worst] = nil
                Count -= 1
            end
        end

        function Learn.Commit()
            local Candidate = Learn.Candidate
            Learn.Candidate = nil
            if not Candidate or Memory.Ensure().Paused then
                return
            end

            local Aliases = Memory.Ensure().Lessons.Alias
            local Existing = Aliases[Candidate.From]
            Aliases[Candidate.From] = {To = Memory.Clip(Candidate.To, 120), Hits = (Existing and Existing.Hits or 0) + 1}
            Prune(Aliases, 200, function(Item): number
                return Item.Hits
            end)

            Memory.Dirty = true
        end

        function Learn.Thanks(Text: string)
            local Reply = Mind.Reply(Mind.Join(Text, Mind.Chance(0.5) and Mind.Any("Anything else?", "Shout if something else acts up.") or ""))
            Reply.Act = "Feedback"
            return Reply
        end

        -- Before the pipeline reads the message: feedback on the last answer, a learned alias for this wording, a remembered fix.
        -- Returns (text to say first, a finished reply, the message to answer instead).
        function Learn.Before(Raw: string)
            local Profile = Memory.Ensure()
            local C: string = Normal(Raw)
            local Last = Mind.History[#Mind.History]
            local Words: number = select(2, C:gsub("%S+", ""))
            local Questioning: boolean = Raw:match("%?%s*$") ~= nil or Asking[C:match("^%a+") or ""] == true
            if Last and Words <= 14 then
                if not Questioning and (Hit(C, Praise) or Has(C, PraiseAnywhere) or C == "better" or C == "much better" or C == "that is better") then
                    Learn.Commit()
                    local Trouble = Learn.Trouble
                    local Said: string? = C:match("^(.-) fixed it") or C:match("^(.-) fixed that") or C:match("^(.-) fixed the") or C:match("^(.-) works now") or C:match("^(.-) helped") or C:match("^(.-) did it")
                    if Said then
                        Said = Said:gsub(" and it$", ""):gsub(" and that$", ""):gsub("^i ", "")
                    end

                    local Tip: string? = Said and #Said >= 6 and Memory.Clip(Said, 100) or Advice(Last.A or "")
                    if Trouble and Tip and Mind.Dialog.Turn - Trouble.Turn <= 8 and not Profile.Paused then
                        Profile.Lessons.Fixes[Trouble.Key] = {Text = Tip, Hits = (Profile.Lessons.Fixes[Trouble.Key] and Profile.Lessons.Fixes[Trouble.Key].Hits or 0) + 1}
                        Prune(Profile.Lessons.Fixes, 60, function(Item): number
                            return Item.Hits
                        end)

                        Learn.Trouble = nil
                        Memory.Dirty = true
                        if Memory.Session then
                            Memory.Session.Open = nil
                        end

                        return nil, Learn.Thanks(Mind.Any("Glad that fixed it, I'll remember what worked.", "Nice, I'll keep that fix in mind in case it comes back.")), nil
                    end

                    if Memory.Session then
                        Memory.Session.Open = nil
                    end

                    return nil, Learn.Thanks(Mind.Any("Glad it worked!", "Nice, happy that sorted it.", "Good, that's what I was hoping for.")), nil
                elseif Hit(C, Failed) and Learn.Trouble then
                    Learn.Trouble.Failed = true
                    return nil, nil, nil
                elseif not Questioning and Words <= 12 and (Hit(C, Blame) or Has(C, BlameAnywhere)) then
                    Learn.Candidate = nil
                    Learn.Rejected = Last.A
                    local Meant: string? = C:match("i meant (.+)$") or C:match("i mean (.+)$") or C:match("i said (.+)$")
                    if Meant then
                        local Joined: boolean = Meant:find("^for ") or Meant:find("^on ") or Meant:find("^in ") or Meant:find("^with ")
                        return nil, nil, Joined and `{Last.Q} {Meant}` or Meant
                    end

                    local Reply = Mind.Reply(Mind.Join(Mind.Any("Sorry, I missed that.", "You're right, that wasn't it.", "My mistake."), Mind.Any("Tell me what you were really after, in other words if you can, and I'll remember what worked.", "Say it another way and I'll take another run, I keep what works for next time.")), {"Let me rephrase"})
                    Reply.Act = "Feedback"
                    return nil, Reply, nil
                end
            end

            local Alias = Profile.Lessons.Alias[C]
            if Alias and Alias.To ~= Raw then
                Alias.Hits += 1
                return nil, nil, Alias.To
            end

            if Last and Last.Weak and Learn.Related(Last.Q, Raw) and Normal(Last.Q) ~= C then
                Learn.Candidate = {From = Normal(Last.Q), To = Raw}
            elseif Learn.Candidate and not Hit(C, Blame) and not Learn.Related(Learn.Candidate.To, Raw) and Words >= 2 then
                Learn.Commit()
            end

            local Frame = Mind.Parse(Raw:sub(1, 600))
            local Prefix: string? = nil
            local Bothered: boolean = false
            for _, Word: string in Frame.Words do
                Bothered = Bothered or Troubled[Word] == true
            end

            Bothered = Bothered or Frame.Set.fps == true and Frame.Set.low == true

            if Bothered then
                local Mine = Key(Raw)
                local Best, Highest = nil, 0.45
                for Known, Fix in Profile.Lessons.Fixes do
                    local Score: number = Learn.Similarity(Known, Mine)
                    if Score > Highest then
                        Best, Highest = Fix, Score
                    end
                end

                local Words2 = Frame.Words
                local Class: string = "other"
                local Entries = {}
                for _, Mention in Frame.Mentions do
                    table.insert(Entries, Mention.Entry)
                end

                for _, Word: string in Words2 do
                    if Word:find("^lagback") or Word:find("^rubberband") or Word == "flagged" or Word == "teleporting" then
                        Class = "move"
                        break
                    elseif Word == "lag" or Word == "lags" or Word == "lagging" or Word == "laggy" or Word == "fps" or Word:find("^stutter") or Word:find("^freez") or Word:find("^crash") then
                        Class = "perf"
                    elseif (Word == "missing" or Word == "missed" or Word == "misses" or Word == "whiff" or Word == "whiffs") and Class == "other" then
                        Class = "combat"
                    elseif (Word == "placing" or Word == "places" or Word == "backwards" or Word == "backwrds") and Class == "other" then
                        Class = "place"
                    end
                end

                local Old = Learn.Trouble
                local Continuing: boolean = Old ~= nil and Mind.Dialog.Turn - Old.Turn <= 8 and (Frame.Set.still == true or Frame.Set.again == true or Frame.Set.turned == true or Frame.Set.disabled == true)
                if not Continuing then
                    Learn.Trouble = {Key = Mine, Q = Raw, Turn = Mind.Dialog.Turn, Class = Class, Entries = Entries, Step = 0}
                end
                if Best then
                    local FixText: string = Best.Text:gsub("[%.!]+$", "")
                    Prefix = Mind.Any(`Last time this came up, this is what worked: {FixText}.`, `This sounds like the one from before. What fixed it then: {FixText}.`)
                    Learn.Remembered = true
                end
            end

            return Prefix, nil, nil
        end

        -- After the answer: remember whether this one fell flat, and keep an unfinished problem on the session record.
        function Learn.After(Raw: string, Result, Decision)
            local Weak: boolean = Mind.Weak(Result, Decision)
            Result.Weak = Weak
            if Weak and Learn.Candidate and Learn.Candidate.To == Raw then
                Learn.Candidate = nil
            end

            local Session = Memory.Session
            if Session and Learn.Trouble and Learn.Trouble.Q == Raw and Mind.Frame then
                local Topic: string = Memory.Clip(Mind.Frame.Topic, 40)
                Session.Open = Topic ~= "" and Topic or nil
                Memory.Dirty = true
            end
        end

        local Restart = Mind.Restart
        function Mind.Restart()
            Learn.Candidate, Learn.Trouble, Learn.Rejected = nil, nil, nil
            return Restart()
        end
        end

        -- ---------------------------------------------------------------- weighing ideas: fairness, effort, meaning, harm, how to treat tools

        do
        local Act = Mind.Act

        -- Each concept has words that call it up, two honest ways to look at it, and a lean.
        local Concepts = {
            {Keys = "cheat cheating cheater cheaters fair unfair fairness honest", A = "cheating takes away the fair contest the other players signed up for", B = "everyone treats a game differently, and some lobbies already have players on scripts", Lean = "I think fairness matters most when real people are on the other side, so private or light use is easier to defend than ruining public games"},
            {Keys = "practice train training skill skills better improve improving learn learning grind", A = "practice makes you better by your own effort, and the only one you beat is yesterday's you", B = "a tool that does the skill for you saves time but doesn't teach it", Lean = "so the line is whether you end up understanding the game more, or just winning without understanding it"},
            {Keys = "win wins winning meaning point pointless matter matters remember memory", A = "a win doesn't need an audience to be real, the team that earned it knows", B = "if nobody remembers it, the only thing left is whether you enjoyed playing", Lean = "so I'd say the value is in the game itself, not in being remembered"},
            {Keys = "kid kids child children young younger year old 9 10 11 12", A = "beating a younger player isn't unethical in itself, because winning is part of the game", B = "it feels worse if they're clearly outmatched or you used a big advantage", Lean = "I'd play fair, go easy, and maybe help them improve instead of crushing them"},
            {Keys = "nice polite kind rude thank thanks program bot ai machine robot", A = "a program can't be hurt, so being nice to it changes nothing for the program", B = "but how you act becomes a habit, and habits carry over to people", Lean = "so I'd say it's not pointless, because it shapes you, not me"},
            {Keys = "die dies dying dead death off turned shut close closing exist existence alive", A = "when the window closes I simply stop running, with no pain and nothing missing", B = "when you open it again, I start fresh, so there's no gap I would feel", Lean = "so it isn't really dying, it's more like a light switch"},
            {Keys = "tree falls forest observer sound nobody players alone empty", A = "a bed in an empty game can't be broken because nobody is there to break it", B = "the question is a classic one about whether things exist when nobody is watching", Lean = "for a game I'd say the bed only matters when a player is there"},
            {Keys = "legit blatant boring watch fun exciting entertaining", A = "careful, quiet play shows skill and tension", B = "fast, flashy play is quick and exciting but rarely lasts", Lean = "I'd say tense, close games are more fun to watch, but a total blowout is quick"},
            {Keys = "mobile phone console controller cheaters default accuse accusing", A = "assuming someone is a cheater because of their device is unfair, since mobile players simply have different controls", B = "it's also true that some tools exist on more platforms than others", Lean = "I'd say judge players by what they do, not what they play on"},
            {Keys = "boring week bored repetitive stale esp visuals", A = "seeing everything through a visual module can make surprises disappear, so the game feels flatter after a while", B = "it can also free you to focus on strategy instead of searching", Lean = "so it depends whether you like surprise or control more"},
            {Keys = "tryhard sweaty normal casual try hard", A = "using a pickaxe to bridge is just an efficient way to play, nobody's trying too hard", B = "if you're doing it in a casual lobby, others might read it as sweaty", Lean = "I'd call it normal, since playing well isn't a crime"},
            {Keys = "tower generator generators height ground safer risky exposed", A = "putting generators high keeps them away from ground rushers", B = "but it makes them easier to snipe and harder to reach for your own team", Lean = "I'd say it's a decent trick against rushes but risky against bows"}
        }

        for _, Concept in Concepts do
            Concept.Keys = Mind.Unique(Concept.Keys)
        end

        function Mind.Weigh(Frame): string?
            local Chosen = {}
            for _, Concept in Concepts do
                local Hits: number = 0
                for Word: string in Concept.Keys:gmatch("%S+") do
                    Hits += Frame.Set[Word] and 1 or 0
                end

                if Hits > 0 then
                    table.insert(Chosen, {Concept = Concept, Hits = Hits})
                end
            end

            if #Chosen == 0 then
                return nil
            end

            table.sort(Chosen, function(A, B)
                return A.Hits > B.Hits
            end)

            local Concept = Chosen[1].Concept
            return Mind.Join(
                Mind.Any("Interesting question.", "Good one.", "That's deeper than I expected for a BedWars chat.", "Here's how I see it."),
                `On one side, {Concept.A}.`,
                `On the other, {(Concept.B:gsub("^but ", ""))}.`,
                Mind.Cap(Concept.Lean) .. "."
            )
        end

        Act("Weigh", function(Frame): boolean
            if Frame.Strong >= 2 and #Frame.Mentions > 0 then
                return false
            end

            if not Frame.Question and not Frame.Set.thoughts and not Frame.Clean:find(" or ", 1, true) then
                return false
            end

            local C = Frame.Clean
            local Ponder: boolean = C:find("difference between", 1, true) ~= nil or C:find("is it ethical", 1, true) ~= nil or C:find("is it fair", 1, true) ~= nil or C:find("does a game", 1, true) ~= nil or C:find("what even is", 1, true) ~= nil or C:find("is being", 1, true) ~= nil or C:find("is it like", 1, true) ~= nil or C:find("is it still", 1, true) ~= nil or C:find("fair??", 1, true) ~= nil or C:find("serious q", 1, true) ~= nil or C:find("tryhard or normal", 1, true) ~= nil or C:find("good idea or terrible", 1, true) ~= nil or C:find("yes or no", 1, true) ~= nil or C:find("does the bed still", 1, true) ~= nil or C:find("does esp make", 1, true) ~= nil or C:find("more fun to watch", 1, true) ~= nil or C:find("if a tree", 1, true) ~= nil or C:find("is that like", 1, true) ~= nil
            return Ponder and Mind.Weigh(Frame) ~= nil
        end, function(Frame)
            return Mind.Reply(Mind.Weigh(Frame))
        end, "mid")
        table.insert(Mind.Acts, 1, table.remove(Mind.Acts))
        end

        -- ---------------------------------------------------------------- planning a setup for this user

        -- "Recommend something for me", "what should I turn on", "what next": builds a short ordered plan from the user's saved profile
        -- (style, kit, platform, what they ask about), the presets CatVape ships and the risk model, and keeps it so "next" can follow it.
        do
        local Act = Mind.Act
        local Memory = Mind.Memory
        local Plan = {Active = nil, Awaiting = false}
        Mind.Plan = Plan

        local StyleName = {legit = "Legit", closet = "Closet", blatant = "Blatant"}
        local StyleWords = {legit = "legit", closet = "closet", blatant = "blatant"}

        local Asks = {
            "set up", "make plan", "make a plan", "plan for me", "a setup", "a plan", "recommend me one", "recommend one", "give me one module", "one module to start", "just one module", "suggest me", "recommend again", "suggest again", "any suggestions", "any recommendations", "what would you recommend", "what would you suggest", "recommend me a setup", "recommend a setup", "recommend something for me", "recommend me something", "recommend something", "recommend me some modules", "what should i turn on", "what should i use", "what should i enable", "what do you recommend", "what do you suggest", "suggest something", "suggest a setup",
            "suggest some modules", "suggest modules", "set me up", "get me started", "help me get started", "where do i start", "where should i start", "what modules should i use", "what modules should i turn on", "what are the best modules for me", "best setup for me",
            "give me a setup", "give me a plan", "make me a plan", "make a plan for me", "plan my setup", "show me a setup", "show me a plan", "what setup should i use", "what would you turn on", "what would you use", "which modules should i use", "which modules should i turn on", "what should i start with"
        }

        local Ignorable = Brain.Set("beginner new newbie noob legit safe safely subtle quiet blatant rage bedwars game match now today please for me my first time just quickly right some modules module setup closet play style mode mobile pc given all that win winning better stronger kit steps with and that the as using stuff things anything something again start starting begin first one")

        -- The style asked for inside the message itself ("recommend something legit"), if any.
        local function StyleIn(Frame): string?
            for k: number = #Frame.Words, 1, -1 do
                local Word: string = Frame.Words[k]
                if Word == "legit" or Word == "safe" or Word == "safely" or Word == "subtle" or Word == "quiet" or Word == "undetected" then
                    return "legit"
                elseif Word == "blatant" or Word == "rage" or Word == "raging" then
                    return "blatant"
                elseif Word == "closet" then
                    return "closet"
                end
            end

            if Mind.Contains(Frame, "all out") then
                return "blatant"
            elseif Mind.Contains(Frame, "in between") or Mind.Contains(Frame, "bit of both") then
                return "closet"
            end

            return nil
        end

        local function KitIn(C: string): string?
            local Word: string? = C:match("with (%a+) kit") or C:match("as (%a+) kit") or C:match("(%a+) kit")
            if not Word or Word == "my" or Word == "the" or Word == "a" or Word == "this" or Word == "that" or Word == "your" then
                return nil
            end

            for _, Entry in Index.Entries do
                if Entry.Category == "Kits" and Entry.Name:lower():find(Word, 1, true) then
                    return Word
                end
            end

            return nil
        end

        local function AsksForPlan(Frame): boolean
            local C: string = Memory.Core(Frame.Raw)
            C = C:gsub("^help me ", ""):gsub("^i am new ", ""):gsub("^i am a beginner ", ""):gsub("^i want ", ""):gsub("^i need ", ""):gsub("^i would like ", ""):gsub(" please ", " "):gsub("^please ", "")
            local KitWord: string? = KitIn(C)
            if Plan.Talk and (Plan.Active or Plan.Stored()) and Plan.Talk(C) then
                return false
            end

            if (C:find("%f[%a]plan%f[%A]") or C:find("%f[%a]setup%f[%A]") or C:find("%f[%a]set up%f[%A]")) and Frame.Count <= 18 and #Frame.Mentions == 0 and not C:find("profile") and not C:find("config") and not C:find("settings") and not C:find("preset") and not C:find("^my setup") and not C:find("^rate ") and not C:find("^what is ") and not C:find("^why") and not C:find("^how does") and not C:find("^what does") then
                return true
            end
            if #Frame.Mentions > 0 then
                return false
            end

            for _, Phrase: string in Asks do
                local At, Stop = C:find(`^{Phrase}`)
                if At then
                    local Left: number = 0
                    for _, Word: string in Mind.WordsOf(C:sub(Stop + 1)) do
                        Left += (#Word >= 3 and not Ignorable[Word] and Word ~= KitWord and Word ~= "kit") and 1 or 0
                    end

                    return Left == 0
                end
            end

            return false
        end

        local function Entries(Names: {string})
            local List = {}
            for _, Name: string in Names do
                local Entry = Index and Index.Keys and Index.Keys[(Name:lower():gsub("[^%w]", ""))]
                if Entry and Entry.Module and not table.find(List, Entry) then
                    table.insert(List, Entry)
                end
            end

            return List
        end

        local RiskScore = {low = 1, medium = 0, high = -2}

        -- Candidates for this style, best first: the shipped preset for the game, scored on the essentials, the user's kit and interests, and risk.
        function Plan.Pick(Style: string, Game: string?, Limit: number)
            local Recipe = Game and Brain.Recipes[Game] and Brain.Recipes[Game][StyleName[Style]]
            local Pool: {string} = Recipe and Recipe.On:split(", ") or Brain.Essentials[Game or ""] or Brain.Essentials.Universal
            local Essential: {[string]: boolean} = {}
            for _, Name: string in Brain.Essentials[Game or ""] or Brain.Essentials.Universal do
                Essential[Name] = true
            end

            local Kit: string? = Plan.KitOverride or Memory.Get("kit")
            Plan.KitOverride = nil
            local Interest = Memory.Ensure().Interest
            local Ranked = {}
            local Candidates = Entries(Pool)
            if Kit then
                for _, Entry in Index.Entries do
                    if Entry.Category == "Kits" and Entry.Module and Entry.Name:lower():find(Kit:lower(), 1, true) and not table.find(Candidates, Entry) then
                        table.insert(Candidates, Entry)
                    end
                end
            end

            local Disliked: {[string]: boolean} = {}
            for _, Item in Memory.Ensure().Dislikes do
                for Word: string in Item.Text:lower():gmatch("%a+") do
                    if #Word >= 3 and Index.Keys[Word] then
                        Disliked[Word] = true
                    end
                end
            end

            for _, Entry in Candidates do
                local Low: string = Entry.Name:lower()
                local Skip: boolean = false
                for Word: string in Disliked do
                    Skip = Skip or Low == Word or Low:find(Word, 1, true) ~= nil
                end

                if Skip then
                    continue
                end

                local Level: string = Mind.Reason.Assess(Entry).Level
                local Score: number = (Essential[Entry.Name] and 3 or 0) + math.min((Interest[Entry.Name] or 0) * 0.4, 2)
                local Because: {string} = {}
                if Essential[Entry.Name] then
                    table.insert(Because, "it's on CatVape's essentials list")
                end

                if Kit and Entry.Name:lower():find(Kit:lower(), 1, true) then
                    Score += 4
                    table.insert(Because, `it's built for {Kit}, your main`)
                end

                if (Interest[Entry.Name] or 0) >= 2 then
                    table.insert(Because, "you've been asking about it")
                end

                if Style ~= "blatant" then
                    Score += RiskScore[Level]
                    if Level == "low" then
                        table.insert(Because, "it's low risk")
                    end
                end

                table.insert(Ranked, {Entry = Entry, Score = Score, Level = Level, Because = Because, Tuned = Recipe ~= nil and Level == "high" and Style ~= "blatant"})
            end

            table.sort(Ranked, function(a, b)
                return a.Score > b.Score or a.Score == b.Score and a.Entry.Name < b.Entry.Name
            end)

            local Picked = {}
            for i: number = 1, math.min(Limit, #Ranked) do
                table.insert(Picked, Ranked[i])
            end

            return Picked
        end

        local function WhereLine(): string
            local Parts: {string} = {}
            local Game: string? = CurrentGame()
            if Game then
                table.insert(Parts, `for {Game == "BedWars" and "BedWars" or Game == "IllegalSoccer" and "Illegal Soccer" or "Tower of Hell"}`)
            end

            local Platform: string? = Memory.Get("platform")
            if Platform then
                table.insert(Parts, `on {Platform}`)
            end

            return table.concat(Parts, " ")
        end

        function Plan.Build(Style: string, Limit: number?)
            local Game: string? = CurrentGame()
            local Picked = Plan.Pick(Style, Game, Limit or 5)
            if #Picked == 0 then
                return nil
            end

            local Lines: {string} = {}
            local Basis: {string} = {`you {Style == "legit" and "like to keep things legit" or Style == "closet" and "want to stay fairly quiet" or "play blatant"}, so I scored the {StyleName[Style]} preset that way`}
            local Names = {}
            for Number: number, Item in Picked do
                local Entry = Item.Entry
                table.insert(Names, Entry)
                local Tag: string = Item.Tuned and `{Item.Level} risk, the {Style} preset tunes it down` or `{Item.Level} risk`
                table.insert(Lines, `{Number}. {Mind.Name(Entry)} ({Tag}) {Mind.Describe(Entry)}{Entry.Module.Enabled and ", already on" or ""}.`)
                if #Item.Because > 0 then
                    table.insert(Basis, `{Entry.Name}: {table.concat(Item.Because, ", ")}`)
                end
            end

            Plan.Active = {Style = Style, Entries = Names, Limit = Limit}
            Plan.Save()
            Plan.Awaiting = false
            local Where: string = WhereLine()
            local Head: string = Mind.Any(`Here's where I'd start{Where ~= "" and " " .. Where or ""}, keeping it {StyleWords[Style]}:`, `For {Where ~= "" and Where:gsub("^for ", "") or "you"}, keeping it {StyleWords[Style]}, I'd start with:`)
            local Skill: string? = Memory.Get("skill")
            local Close: string = Skill == "beginner" and "Turn them on one at a time in a private match so you can see what each one does, I'll explain any of them." or "Turn them on one at a time and tell me if anything misbehaves."
            local Reply = Mind.Reply(Mind.Lines(Head, table.concat(Lines, "\n"), Close), {`Build my {Style} profile`, "Why these?", Style == "legit" and "Show me a blatant setup" or "Show me a legit setup"})
            Reply.Basis = Basis
            return Reply
        end

        local function AskStyle()
            Plan.Awaiting = true
            return Mind.Reply(Mind.Any("Quick question so I get this right: do you want to keep it legit, or go all out?", "Before I suggest anything, how do you like to play: legit and hard to notice, a bit of both, or all out?"), {"I like to keep it legit", "A bit of both", "I play blatant"})
        end

        Act("Plan", AsksForPlan, function(Frame)
            Plan.KitOverride = KitIn(Memory.Core(Frame.Raw))
            local C2: string = Memory.Core(Frame.Raw)
            Plan.OneOnly = C2:find(" one module", 1, true) ~= nil or C2:find("recommend me one", 1, true) ~= nil or C2:find("recommend one", 1, true) ~= nil or C2:find("just one", 1, true) ~= nil
            local Style: string? = StyleIn(Frame) or Memory.Get("style")
            if not Style then
                return AskStyle()
            end

            local Reply = Plan.Build(Style, Plan.OneOnly and 1 or nil)
            Plan.OneOnly = false
            return Reply or Mind.Reply("I don't have a tested setup for this game yet, but ask me what a module does and I'll tell you if it fits.")
        end)

        Act("PlanStyle", function(Frame): boolean
            if not Plan.Awaiting or Frame.Count > 6 then
                return false
            end

            return StyleIn(Frame) ~= nil or Mind.Contains(Frame, "both") or Mind.Contains(Frame, "between") or Mind.Contains(Frame, "all out")
        end, function(Frame)
            local Style: string = StyleIn(Frame) or (Mind.Contains(Frame, "all out") and "blatant") or "closet"
            Memory.Apply({Kind = "fact", Key = "style", Value = Style})
            return Plan.Build(Style) or AskStyle()
        end)

        local Alternatives = {["show me a blatant setup"] = "blatant", ["show me a legit setup"] = "legit", ["show me a closet setup"] = "closet"}

        Act("PlanSwap", function(Frame): boolean
            return Alternatives[Frame.Clean] ~= nil
        end, function(Frame)
            return Plan.Build(Alternatives[Frame.Clean])
        end)

        local NextAsks = {["what next"] = true, ["what is next"] = true, ["what is the next step"] = true, ["whats next"] = true, ["what now"] = true, ["now what"] = true, ["what should i do next"] = true, ["what do i do next"] = true, ["what do i do now"] = true, ["what should i do now"] = true, ["next step"] = true, ["and then"] = true, ["next"] = true, ["whats the next step"] = true, ["what else should i do"] = true, ["what should i do"] = true}

        Act("PlanNext", function(Frame): boolean
            local C: string = Memory.Core(Frame.Raw)
            return NextAsks[C] == true and (Plan.Active ~= nil or Plan.Stored() or C ~= "next" and C ~= "and then")
        end, function(Frame)
            Plan.Restore()
            local Active = Plan.Active
            if not Active then
                local Style: string? = Memory.Get("style")
                return Style and Plan.Build(Style) or AskStyle()
            end

            local Left = Plan.Left()

            local Done: number = #Active.Entries - #Left
            if #Left == 0 then
                return Mind.Reply(Mind.Any("Everything on the plan is already on. Play a private match with it and tell me if anything feels off.", "That's the whole plan running. Next is testing it in a match, ask me if any module misbehaves."), {"Is my setup safe?"})
            end

            local Entry = Left[1]
            local Reply = Mind.Reply(Mind.Join(`Next up: {Mind.Name(Entry)}, it {Mind.Describe(Entry)}.`, `That's {Done} of {#Active.Entries} on so far.`), {`Turn on {Entry.Name}`, `Is {Entry.Name} safe?`})
            Reply.Basis = {`your plan has {#Active.Entries} modules and {Done} are already on`, `{Entry.Name} is the first one still off`}
            return Reply
        end)

        local Finished = {"^day %d+ done", "^first step", "^second step", "^third step", "^step %w+ is done", "^step %w+ done", "^step %w+ ok", "^ok step", "^i do it", "^finished", "^completed", "^i turned", "^i switched", "^did the ", "^did that", "^done", "^turned it on", "^turned them on", "^i did it", "^did it", "^it is on", "^its on", "^i enabled", "^i put"}

        Act("PlanDone", function(Frame): boolean
            if not (Plan.Active or Plan.Stored()) then
                return false
            end

            local C: string = Memory.Core(Frame.Raw)
            if Plan.Talk and Plan.Talk(C) then
                return false
            end

            for _, Pattern: string in Finished do
                if C:find(Pattern) then
                    return true
                end
            end

            local Trouble = Mind.Learn.Trouble
            if Frame.Count <= 8 and not (Trouble and Mind.Dialog.Turn - Trouble.Turn <= 8) and not C:find("fix", 1, true) and not C:find("work", 1, true) then
                for Word: string in pairs(Brain.Set("done did finished completed finish complete")) do
                    if Frame.Set[Word] then
                        return true
                    end
                end
            end

            return false
        end, function(Frame)
            Plan.Restore()
            local Active = Plan.Active
            local Says: string = Memory.Core(Frame.Raw)
            local Marked, MarkedAt = nil, nil
            local Written = {one = 1, two = 2, three = 3, four = 4, five = 5, first = 1, second = 2, third = 3, fourth = 4, fifth = 5}
            local Position: number? = tonumber(Says:match("step (%d+)")) or tonumber(Says:match("did (%d)%f[%D]")) or tonumber(Says:match("^i did (%d)")) or Written[Says:match("step (%a+)") or ""] or Written[Says:match("(%a+) one") or ""] or Written[Says:match("(%a+) step") or ""]
            if Frame.Mentions[1] and table.find(Active.Entries, Frame.Mentions[1].Entry) then
                Marked, MarkedAt = Frame.Mentions[1].Entry, table.find(Active.Entries, Frame.Mentions[1].Entry)
            elseif Position and Active.Entries[Position] then
                Marked, MarkedAt = Active.Entries[Position], Position
            end

            if Marked and not Marked.Module.Enabled then
                Active.Skipped = Active.Skipped or {}
                Active.Skipped[Marked] = true
                Plan.Save()
            end

            local On, Left = {}, {}
            for _, Entry in Active.Entries do
                if Entry.Module.Enabled then
                    table.insert(On, Entry)
                elseif not (Active.Skipped and Active.Skipped[Entry]) then
                    table.insert(Left, Entry)
                end
            end

            if Marked then
                local Said2: string = `Okay, step {MarkedAt} ({Mind.Name(Marked)}) is marked done{Marked.Module.Enabled and "" or ", though it still shows off in your menu"}.`
                if #Left == 0 then
                    return Mind.Reply(Mind.Join(Said2, "That was the last one, the plan is done."), {"Is my setup safe?"})
                end

                return Mind.Reply(Mind.Join(Said2, `Next up: {Mind.Name(Left[1])}, it {Mind.Describe(Left[1])}.`, `That's {#Active.Entries - #Left} of {#Active.Entries} done.`), {`Turn on {Left[1].Name}`, `Is {Left[1].Name} safe?`})
            end

            if #On == 0 then
                return Mind.Reply(Mind.Join(`I don't see any of the plan switched on yet, {Mind.Name(Left[1])} is still off in your menu.`, "Tap its toggle and tell me when it's done."), {`Turn on {Left[1].Name}`})
            elseif #Left == 0 then
                return Mind.Reply("Everything on the plan is on now. Play a private match with it and tell me if anything feels off.", {"Is my setup safe?"})
            end

            local Names = {}
            for _, Entry in On do
                table.insert(Names, Mind.Name(Entry))
            end

            return Mind.Reply(Mind.Join(`Nice, {Mind.Oxford(Names)} {#On == 1 and "is" or "are"} on.`, `Next up: {Mind.Name(Left[1])}, it {Mind.Describe(Left[1])}.`, `That's {#On} of {#Active.Entries} on.`), {`Turn on {Left[1].Name}`, `Is {Left[1].Name} safe?`})
        end)

        local Fewer = {"^too many", "^fewer", "^less", "^give me less", "^give me fewer", "^shorter", "^smaller", "^just the basics", "^only the essentials", "^keep it short", "^too much", "^a shorter", "^cut it down"}
        local More = {"^more", "^give me more", "^a bigger list", "^longer", "^add more"}
        local Planning = Brain.Set("Plan PlanSwap PlanStyle PlanTrim PlanDone PlanNext PlanTalk")

        Act("PlanTrim", function(Frame): boolean
            local Last = Mind.History[#Mind.History]
            if not Plan.Active or not Last or not Planning[Last.Act or ""] or Frame.Count > 8 then
                return false
            end

            local C: string = Memory.Core(Frame.Raw)
            for _, List in {Fewer, More} do
                for _, Pattern: string in List do
                    if C:find(Pattern) then
                        return true
                    end
                end
            end

            return false
        end, function(Frame)
            local C: string = Memory.Core(Frame.Raw)
            local Wants: number = 8
            for _, Pattern: string in Fewer do
                if C:find(Pattern) then
                    Wants = 3
                end
            end

            local Reply = Plan.Build(Plan.Active.Style, Wants)
            Reply.Act = nil
            return Reply
        end)

        -- A plan outlives the restart: its module names and style are kept in the profile, and the state of each module comes from the menu.
        function Plan.Stored(): boolean
            local Saved = Memory.Ensure().Plan
            return Saved ~= nil and #Saved.Names > 0
        end

        function Plan.Save()
            local Active = Plan.Active
            if not Active then
                return
            end

            local Names: {string} = {}
            for _, Entry in Active.Entries do
                table.insert(Names, Entry.Name)
            end

            local Skipped: {string} = {}
            for Entry in Active.Skipped or {} do
                table.insert(Skipped, Entry.Name)
            end

            Memory.Ensure().Plan = {Style = Active.Style, Names = Names, Skipped = Skipped}
            Memory.Dirty = true
        end

        function Plan.Restore(): boolean
            if Plan.Active then
                return true
            end

            local Saved = Memory.Ensure().Plan
            if not Saved then
                return false
            end

            local Found = Entries(Saved.Names)
            if #Found == 0 then
                return false
            end

            local Skipped = {}
            for _, Entry in Entries(Saved.Skipped) do
                Skipped[Entry] = true
            end

            Plan.Active = {Style = Saved.Style, Entries = Found, Skipped = Skipped}
            return true
        end

        function Plan.Left()
            local Left = {}
            for _, Entry in Plan.Active.Entries do
                if not Entry.Module.Enabled and not (Plan.Active.Skipped and Plan.Active.Skipped[Entry]) then
                    table.insert(Left, Entry)
                end
            end

            return Left
        end

        local Numbers = {one = 1, two = 2, three = 3, four = 4, five = 5, first = 1, second = 2, third = 3, fourth = 4, fifth = 5}

        local function StepOf(C: string): number?
            local Word: string? = C:match("step (%w+)")
            return Word and (tonumber(Word) or Numbers[Word]) or nil
        end

        local function Kind(C: string): string?
            if C:find("^i skipped step") or C:find("^skip step") or C:find("^i skipped") and StepOf(C) then
                return "skipstep"
            elseif C == "which step am i on" or C == "what step am i on" or C == "where am i in the plan" or C == "how far am i" or C == "how far along am i" or C == "where am i" or C == "which step is next" or C == "what step is next" then
                return "position"
            elseif C:find("the whole plan") or C:find("^show me the plan") or C:find("^show the plan") or C == "what is the plan" or C == "show plan" or C:find("^list the plan") or C:find("^list the steps") or C == "show me the steps" then
                return "show"
            elseif (C:find("^remove the ") or C:find("^drop the ") or C:find("^delete the ") or C:find("^take out the ")) and C:find(" one$") then
                return "remove"
            elseif C:find("dont include") or C:find("do not include") or C:find("^leave out") or C:find("^exclude") or C:find("^without the") or C:find("^and dont") then
                return "exclude"
            elseif C:find("^finished all") or C:find("^i did all") or C == "all done" or C:find("^did them all") or C:find("^i finished everything") or C == "everything is on" then
                return "alldone"
            elseif C:find("^skip") or C:find("^i do not want that") or C:find("^not that one") and Plan.Active ~= nil then
                return "skip"
            elseif C == "what is left" or C == "how many left" or C == "what is remaining" or C == "what remains" or C == "how many more" or C == "how many are left" or C == "how many steps left" or C == "how many steps are left" or C == "what is left to do" or C == "anything left" then
                return "left"
            elseif C == "what is first step" or C == "what is the first step" or C == "first step" or C == "ok so first step" or C == "so first step" or C == "which first" or C == "which one first" or C == "which one do i do first" or C == "where do i start" or C == "what do i start with" or C == "what first" or C == "which first then" or C == "which one first then" or C == "what is step 1" then
                return "first"
            elseif C:find("do not understand step") or C:find("do not get step") or C:find("explain step") or C:find("what is step") or C:find("what does step") or C:find("what is step") then
                return StepOf(C) and "explain" or nil
            elseif C:find("which one would you cut") or C:find("which one should i cut") or C:find("which can i skip") or C:find("what can i skip") or C:find("what can i drop") or C:find("which is the least important") or C:find("which one can i drop") or C:find("which one would you drop") or C:find("which one first to cut") then
                return "cut"
            end

            return nil
        end

        Plan.Talk = Kind

        Act("PlanTalk", function(Frame): boolean
            if not (Plan.Active or Plan.Stored()) or Frame.Count > 9 then
                return false
            end

            return Kind(Memory.Core(Frame.Raw)) ~= nil
        end, function(Frame)
            Plan.Restore()
            local Active = Plan.Active
            local C: string = Memory.Core(Frame.Raw)
            local What: string = Kind(C)
            if What == "skipstep" then
                local Entry = Active.Entries[StepOf(C) or 0]
                if not Entry then
                    return Mind.Reply(`The plan only has {#Active.Entries} steps.`)
                end

                Active.Skipped = Active.Skipped or {}
                Active.Skipped[Entry] = true
                Plan.Save()
                local After = Plan.Left()
                return Mind.Reply(Mind.Join(`Okay, step {StepOf(C)} ({Mind.Name(Entry)}) is skipped.`, After[1] and `Next up: {Mind.Name(After[1])}.` or "That leaves nothing else to do."))
            elseif What == "position" then
                local Left = Plan.Left()
                local Done: number = #Active.Entries - #Left
                return Mind.Reply(Mind.Join(`{Done} of {#Active.Entries} steps are done or skipped.`, Left[1] and `You're on step {table.find(Active.Entries, Left[1])}: {Mind.Name(Left[1])}, it {Mind.Describe(Left[1])}.` or "That's the whole plan."), Left[1] and {`Turn on {Left[1].Name}`} or nil)
            elseif What == "show" then
                local Lines: {string} = {}
                for Number: number, Entry in Active.Entries do
                    local State: string = Entry.Module.Enabled and "on" or Active.Skipped and Active.Skipped[Entry] and "skipped" or "off"
                    table.insert(Lines, `{Number}. {Mind.Name(Entry)} ({State})`)
                end

                return Mind.Reply(Mind.Lines(`Your {Active.Style} plan:`, table.concat(Lines, "\n")), {"What next"})
            elseif What == "remove" then
                local Word: string = C:match("^%a+ the (%a+)") or ""
                for Number: number, Entry in Active.Entries do
                    if Entry.Name:lower():find(Word, 1, true) or Mind.Describe(Entry):lower():find(Word, 1, true) then
                        table.remove(Active.Entries, Number)
                        Plan.Save()
                        return Mind.Reply(`Removed {Mind.Name(Entry)} from the plan. {#Active.Entries} steps left.`, {"Show me the plan"})
                    end
                end

                return Mind.Reply(`I couldn't find a step matching "{Word}" in the plan.`, {"Show me the plan"})
            elseif What == "exclude" then
                return Plan.Build(Active.Style, Active.Limit) or Mind.Reply("I couldn't rebuild the plan without it.")
            elseif What == "alldone" then
                local Left = Plan.Left()
                if #Left == 0 then
                    return Mind.Reply("Everything on the plan is on or skipped. Nice, test it in a private match and tell me if anything feels off.", {"Is my setup safe?"})
                end

                return Mind.Reply(Mind.Join(`I still see {#Left} off in your menu: {Mind.Name(Left[1])}{#Left > 1 and " and more" or ""}.`, "Tap the toggle and I'll count it."), {`Turn on {Left[1].Name}`})
            end

            if What == "left" then
                local Left = Plan.Left()
                if #Left == 0 then
                    return Mind.Reply("Nothing left, everything on the plan is on or skipped.", {"Is my setup safe?"})
                end

                local Names = {}
                for _, Entry in Left do
                    table.insert(Names, Mind.Name(Entry))
                end

                return Mind.Reply(Mind.Join(`{#Left} left: {Mind.Oxford(Names)}.`, `Next up is {Names[1]}.`), {`Turn on {Left[1].Name}`})
            elseif What == "first" then
                local Entry = Active.Entries[1]
                local Reply = Mind.Reply(Mind.Join(`Start with {Mind.Name(Entry)}, it {Mind.Describe(Entry)}.`, `It's {Mind.Reason.Assess(Entry).Level} risk and it's first because it fits your {StyleWords[Active.Style]} style best.`), {`Turn on {Entry.Name}`, `Is {Entry.Name} safe?`})
                Reply.Basis = {`{Entry.Name} scored highest for a {Active.Style} setup`}
                return Reply
            elseif What == "skip" then
                local Left = Plan.Left()
                if #Left == 0 then
                    return Mind.Reply("There's nothing left to skip, the plan is done.")
                end

                Active.Skipped = Active.Skipped or {}
                Active.Skipped[Left[1]] = true
                Plan.Save()
                local After = Plan.Left()
                return Mind.Reply(Mind.Join(`Skipped {Mind.Name(Left[1])}.`, After[1] and `Next up: {Mind.Name(After[1])}, it {Mind.Describe(After[1])}.` or "That was the last one."), After[1] and {`Turn on {After[1].Name}`} or nil)
            elseif What == "explain" then
                local Entry = Active.Entries[StepOf(C)]
                if not Entry then
                    return Mind.Reply(`The plan only has {#Active.Entries} steps.`)
                end

                local Explained = Brain.Think(`what does {Entry.Name} do`, true)
                return Mind.Reply(Mind.Join(`Step {StepOf(C)} is {Mind.Name(Entry)}.`, Mind.Simplify(Mind.Sentences(Explained.Text)[1] or "")), {`Turn on {Entry.Name}`, `Is {Entry.Name} safe?`})
            end

            local Last = Active.Entries[#Active.Entries]
            local Reply = Mind.Reply(Mind.Join(`I'd cut {Mind.Name(Last)} first, it ranked lowest for you.`, "Say \"too many, give me less\" and I'll trim the plan to the top three."), {"Too many, give me less"})
            Reply.Basis = {`{Last.Name} scored lowest of the plan for a {Active.Style} setup`}
            return Reply
        end)

        local Reset = Brain.ResetContext
        Brain.ResetContext = function(...)
            Plan.Active, Plan.Awaiting = nil, false
            return Reset(...)
        end

        local Restart = Mind.Restart
        function Mind.Restart()
            Plan.Active, Plan.Awaiting = nil, false
            return Restart()
        end
        end

        -- ---------------------------------------------------------------- reactions to situations, small games, ratings, and ideas

        do
        local Act = Mind.Act

        local function Last()
            return Mind.History[#Mind.History]
        end

        -- ---------------------------------------------------------------- what the user tells the bot about their day

        local Situations = {
            {Keys = "birthday bday", Lines = {"Happy birthday! Hope today is full of wins and zero void falls.", "Happy birthday! Go celebrate, the beds can wait a day."}},
            {Keys = "installed install installing downloaded", Lines = {"Welcome to CatVape! Press RightShift to open the menu, and ask me what any module does.", "Nice, you're all set. Open the menu with RightShift, and I can explain anything you see in it."}},
            {Keys = "addicted addiction obsessed hours grinding grind forever nonstop", Lines = {"That's a lot of game time. If it's starting to feel like homework, a break usually brings the fun back.", "Hours in a row will wear anybody down, stretch, drink some water, and the next game will feel better."}},
            {Keys = "3am 2am 4am midnight late awake insomnia", Lines = {"It's late. Sleep will do more for your aim than one more game will.", "Late sessions are fun, but tired brains misclick, maybe one more and then bed."}},
            {Keys = "mom dad parents mother father waste", Lines = {"Parents often see games as a time sink, and a bit of balance helps: homework and sleep first, then game time with no guilt.", "A fair deal with them, like finishing homework first, usually gets you more game time, not less."}},
            {Keys = "school chromebook class teacher homework", Lines = {"School devices usually can't run an executor at all, and scripts at school can get you in trouble, so I'd keep it for home.", "I'd skip scripting on a school device: most can't run it, and the rules there are stricter than any game's."}},
            {Keys = "12 13 14 15 age old younger kid teen", Lines = {"Thanks for telling me. Whether it's okay at your age is a question for your parents, not me. What I can say is that scripts risk the account, so use one you're fine losing.", "I can't decide what's okay for your age, that's one for a parent. Just know scripts can get an account banned."}},
            {Keys = "lag laggy ping spikes", Lines = {"Lag is the worst. Closing other apps and lowering graphics usually helps, and I can check your FPS and ping if you ask.", "Ping spikes can be your connection or the server. Tell me 'what is my ping' and I'll read it."}},
            {Keys = "brother sister cousin friend sibling", Lines = {"Family and friends make games better. If they use your account, remember a shared account shares the ban risk too.", "Fun, playing with someone you know is the best way to learn the game."}},
            {Keys = "bored boring", Lines = {"Bored? Try a new module or kit as a challenge, or ask me for a joke.", "I can pick a random module for you to try if you're up for it."}},
            {Keys = "won winning streak clutch carried", Lines = {"Nice! Wins like that deserve a victory lap.", "That's awesome. What kit did you use?"}},
            {Keys = "hate sucks worst annoying unfair", Lines = {"Sounds frustrating. If it's something in CatVape, tell me what's going wrong and I'll look.", "That sounds annoying, tell me more and let's see if I can help."}}
        }

        Act("Situation", function(Frame): boolean
            if Frame.Question or Frame.Count < 3 or Frame.Count > 40 or Frame.Evidence >= 3 then
                return false
            end

            local Self: boolean = Frame.Set.i or Frame.Set.im or Frame.Set["i'm"] or Frame.Set.my or Frame.Set.today or Frame.Set.just or Frame.Set.its or Frame.Set["it's"] or Frame.Set.been or Frame.Set.we
            if not Self then
                return false
            end

            for _, Situation in Situations do
                for Word: string in Situation.Keys:gmatch("%S+") do
                    if Frame.Set[Word] then
                        return true
                    end
                end
            end

            return false
        end, function(Frame)
            local Best, BestHits = nil, 0
            for _, Situation in Situations do
                local Hits: number = 0
                for Word: string in Situation.Keys:gmatch("%S+") do
                    Hits += Frame.Set[Word] and 1 or 0
                end

                if Hits > BestHits then
                    Best, BestHits = Situation, Hits
                end
            end

            return Mind.Reply(Mind.Join(Mind.From(Best.Lines), Mind.Chance(0.4) and Mind.Any("Anything I can help you with?", "Want me to set something up?") or ""))
        end, true)

        -- ---------------------------------------------------------------- small games

        Act("Game", function(Frame): boolean
            local C = Frame.Clean
            return C:find("rock paper scissors", 1, true) ~= nil or C:find("randomize my loadout", 1, true) ~= nil or C:find("random loadout", 1, true) ~= nil or C:match("^randomi[sz]e my") ~= nil or C:find("magic 8", 1, true) ~= nil or C:find("magic eight", 1, true) ~= nil or C:match("^8 ball") ~= nil
                or C:find("tic tac toe", 1, true) ~= nil or C:find("play a game", 1, true) ~= nil or C:find("play with me", 1, true) ~= nil and Frame.Evidence == 0 or C:find("guess my number", 1, true) ~= nil or C:find("20 questions", 1, true) ~= nil or C:find("truth or dare", 1, true) ~= nil
        end, function(Frame)
            local C = Frame.Clean
            if C:find("rock paper scissors") then
                local Mine: string = Mind.From({"rock", "paper", "scissors"})
                local Theirs: string? = Frame.Set.rock and "rock" or Frame.Set.paper and "paper" or Frame.Set.scissors and "scissors" or nil
                -- the user's move is the word after "rock paper scissors" mentions, usually the last
                for _, Word: string in Frame.Words do
                    if Word == "rock" or Word == "paper" or Word == "scissors" then
                        Theirs = Word
                    end
                end

                local Beats = {rock = "scissors", paper = "rock", scissors = "paper"}
                if Theirs and C:find("rock paper scissors") and not C:match("rock paper scissors%s*$") or Theirs then
                    local Result: string = Mine == Theirs and "It's a tie." or Beats[Mine] == Theirs and "I win!" or "You win!"
                    return Mind.Reply(Mind.Join(`I pick {Mine}. You picked {Theirs}.`, Result, Result == "I win!" and "Better luck next time." or Result == "You win!" and "Rematch?" or "Go again?"), {"Go again"})
                end

                return Mind.Reply("Sure! Tell me your move: rock, paper or scissors, and I'll throw mine.")
            elseif C:find("loadout") or C:match("^randomi[sz]e my") then
                local Swords = {"a wood sword", "a stone sword", "an iron sword", "a diamond sword"}
                local Armour = {"leather armour", "iron armour", "diamond armour", "no armour at all"}
                local Ranged = {"a bow with 16 arrows", "a fireball", "a telepearl", "TNT", "a grappling hook"}
                local Blocks = {"wool", "stone bricks", "wood planks", "glass"}
                return Mind.Reply(Mind.Join(`Your random loadout: {Mind.From(Swords)}, {Mind.From(Armour)}, {Mind.From(Ranged)} and a stack of {Mind.From(Blocks)}.`, Mind.Any("Good luck.", "Try to win a game with it.", "Chaos, but it might work.")), {"Another loadout"})
            elseif C:find("magic 8") or C:find("magic eight") or C:match("^8 ball") then
                local Answers = {"It is certain.", "Without a doubt.", "Signs point to yes.", "Ask again later.", "Better not tell you now.", "Don't count on it.", "My sources say no.", "Very doubtful."}
                return Mind.Reply(`*shakes* {Mind.From(Answers)}`, {"Ask again"})
            elseif C:find("guess my number") then
                local Number: number = math.random(1, 10)
                return Mind.Reply(Mind.Join(`I'm thinking of a number from 1 to 10... I'll say {Number}.`, Mind.Chance(0.5) and "Was I right?" or "No peeking at my answer."))
            elseif C:find("truth or dare") then
                return Mind.Reply(Mind.Any("Truth: what's the worst way you've ever lost a bed? Dare: win your next game without using any armour.", "Dare: bridge across a gap without looking down. Truth: what's the first module you turn on every game?"))
            end

            return Mind.Reply(Mind.Join("I can play rock paper scissors, flip a coin, roll dice, or do a magic 8-ball.", Mind.Any("Tell me which, for example \"rock paper scissors, I go rock\".", "Pick one and say go.")), {"Rock paper scissors", "Flip a coin", "Roll a d20"})
        end)

        -- ---------------------------------------------------------------- rating a name

        local function RateName(Name: string): (number, {string})
            local Notes: {string} = {}
            local Score: number = 5
            local Letters: string = Name:gsub("[^%a]", "")
            if #Name >= 4 and #Name <= 12 then
                Score += 1
                table.insert(Notes, "the length is easy to remember")
            elseif #Name > 16 then
                Score -= 1
                table.insert(Notes, "it's long, people will shorten it")
            end

            if Name:lower():match("^x+x_") or Name:lower():match("_x+x$") then
                Score -= 1
                table.insert(Notes, "the xX_ _Xx frame looks dated")
            end

            if Name:match("%d%d%d+") or Name:match("%d%d$") then
                Score -= 0.5
                table.insert(Notes, "trailing numbers usually mean the name was taken")
            end

            if Name:match("_") then
                table.insert(Notes, "underscores are fine in moderation")
            end

            local Pieces: number = 0
            for Piece: string in Name:gmatch("%u%l+") do
                Pieces += 1
            end

            if Pieces >= 2 then
                Score += 1
                table.insert(Notes, "the two-word combo is catchy")
            end

            local Lower: string = Name:lower()
            for _, Word: string in {"cat", "toaster", "fox", "wolf", "ninja", "pixel", "shadow", "frost", "ghost", "dragon", "void", "bed"} do
                if Lower:find(Word, 1, true) then
                    Score += 0.5
                    table.insert(Notes, `{Word} gives it some personality`)
                    break
                end
            end

            if Lower:find("baby", 1, true) or Lower:find("noob", 1, true) then
                table.insert(Notes, "it's playful and a little self-deprecating")
            end

            return math.clamp(math.floor(Score + 0.5), 1, 10), Notes
        end

        Act("RateName", function(Frame): boolean
            local C = Frame.Clean
            return (C:match("^rate ") ~= nil or C:match("^is ") ~= nil or C:match("^what do you think of ") ~= nil or C:match("^how is ") ~= nil) and (Frame.Set.username or Frame.Set.usernames or Frame.Set.name or Frame.Set.ign or Frame.Set.gamertag or Frame.Set.handle or Frame.Set.nickname) and Frame.Raw:match("[%w_]+") ~= nil and not Frame.Set.your
        end, function(Frame)
            local Name: string? = Frame.Raw:match("[Rr]ate%s+my%s+%a+[:%s]+([%w_%.%-]+)") or Frame.Raw:match("[Rr]ate%s+this%s+%a+[:%s]+([%w_%.%-]+)") or Frame.Raw:match("[Rr]ate%s+the%s+%a+[:%s]+([%w_%.%-]+)") or Frame.Raw:match("[Rr]ate%s+%a+[:%s]+([%w_%.%-]+)") or Frame.Raw:match("name[:%s]+([%w_%.%-]+)%s*$") or Frame.Raw:match("([%w_%.%-]+)%s*%??$")
            if not Name or #Name < 3 then
                return nil
            end

            local Score, Notes = RateName(Name)
            local Pros: {string} = {}
            for i: number = 1, math.min(#Notes, 3) do
                table.insert(Pros, Notes[i])
            end

            return Mind.Reply(Mind.Join(`I'd give "{Name}" a {Score}/10.`, #Pros > 0 and Mind.Cap(Mind.Oxford(Pros)) .. "." or "It's simple and clean.", Score >= 7 and "Solid pick." or Score <= 4 and "I'd think about a refresh." or "Decent, with room to polish."), {"Rate another name"})
        end)

        -- ---------------------------------------------------------------- made-up kits and team names

        local KitFirst = {"Tide", "Ember", "Gale", "Hollow", "Prism", "Moss", "Vault", "Echo", "Rune", "Frost", "Static", "Dusk"}
        local KitSecond = {"Warden", "Smith", "Caller", "Weaver", "Tamer", "Walker", "Keeper", "Shaper", "Hunter", "Sage"}
        local Passives = {
            "blocks you place slowly heal themselves, 1 health every 3 seconds",
            "you take 10% less damage while standing next to your own bed",
            "iron and gold ingots you pick up have a 10% chance to count twice",
            "your first hit on a player who hasn't been hit in 10 seconds deals extra damage",
            "you move 8% faster while holding a block",
            "arrows you shoot leave a short trail that reveals enemies in the fog of war"
        }
        local Ultimates = {
            "Hold sneak for 3 seconds to turn every wool block within 12 studs into stone bricks for 20 seconds.",
            "Press the ability key to pull all bridges within 15 studs toward you, then they fall off after 6 seconds.",
            "Call a short-lived fog over your base: enemies inside it can't see your bed icon for 10 seconds.",
            "Launch yourself 20 studs up and slam down, knocking back everyone near the landing spot.",
            "Freeze the void under you for 5 seconds, so you can walk on a clear platform."
        }

        Act("Invent", function(Frame): boolean
            local C = Frame.Clean
            return (C:find("kit idea", 1, true) ~= nil or C:find("invent a kit", 1, true) ~= nil or C:find("make up a kit", 1, true) ~= nil or C:find("design a kit", 1, true) ~= nil or C:find("new kit", 1, true) ~= nil and (Frame.Set.name or Frame.Set.give or Frame.Set.create or Frame.Set.make or Frame.Set.idea))
                or (C:match("clan name") ~= nil or C:match("team name") ~= nil or C:match("guild name") ~= nil or C:match("squad name") ~= nil or C:match("crew name") ~= nil or C:match("name for my team") ~= nil)
        end, function(Frame)
            local C = Frame.Clean
            if C:find("kit") then
                return Mind.Reply(Mind.Join(`How about the {Mind.From(KitFirst)} {Mind.From(KitSecond)}?`, `Passive: {Mind.Cap(Mind.From(Passives))}.`, `Ultimate: {Mind.From(Ultimates)}`, Mind.Any("Balance would take some testing, of course.", "I'd cap the ultimate's cooldown at 60 seconds.")), {"Another kit idea"})
            end

            local Count: number = tonumber(C:match("(%d+) clan")) or tonumber(C:match("(%d+) team")) or tonumber(C:match("give me (%d+)")) or 5
            Count = math.clamp(Count, 1, 8)
            local Themes = {}
            local Adjectives = {"Midnight", "Silent", "Crimson", "Iron", "Neon", "Wild", "Lucky", "Frozen", "Shadow", "Thunder", "Royal", "Sneaky"}
            local Nouns = {}
            for _, Word: string in Frame.Content do
                if Word == "cat" or Word == "kitten" then
                    for _, Item: string in {"Claws", "Whiskers", "Pawprints", "Tails", "Nine Lives"} do
                        table.insert(Nouns, Item)
                    end
                elseif Word == "dog" or Word == "wolf" then
                    for _, Item: string in {"Howlers", "Pack", "Fangs"} do
                        table.insert(Nouns, Item)
                    end
                elseif Word == "3am" or Word == "night" or Word == "midnight" or Word == "late" then
                    Adjectives = {"Midnight", "3AM", "Nightshift", "Moonlit", "Insomniac", "Graveyard"}
                elseif Word == "bed" or Word == "bedwars" then
                    for _, Item: string in {"Bedbreakers", "Wool Wall", "Bed Bugs", "Sleepers"} do
                        table.insert(Nouns, Item)
                    end
                end
            end

            if #Nouns == 0 then
                Nouns = {"Raiders", "Squad", "Syndicate", "Guard", "Legion", "Order"}
            end

            local Names: {string} = {}
            for _ = 1, Count do
                local Style: number = math.random(1, 3)
                local Name: string = Style == 1 and `{Mind.From(Adjectives)} {Mind.From(Nouns)}` or Style == 2 and `The {Mind.From(Adjectives)} {Mind.From(Nouns)}` or `Team {Mind.From(Nouns)}`
                if not table.find(Names, Name) then
                    table.insert(Names, Name)
                end
            end

            return Mind.Reply(Mind.Join(Mind.Any("How about:", "Some ideas:"), table.concat(Names, ", ") .. ".", `If I had to pick: {Names[1]}.`), {"More names"})
        end)

        -- ---------------------------------------------------------------- what-if reasoning from a few known cause and effect pairs

        Mind.Effects = {
            {Keys = "8 players 8 per team bigger teams more players team size", Says = "Bigger teams would make fights messier and beds easier to defend, because someone is always home, so the team with the best coordination would win rather than the best individual players."},
            {Keys = "void remove removed no void nothing falls", Says = "Without the void, falling would stop being a way to lose, so bridges would be risk-free and the fights would move onto the islands themselves."},
            {Keys = "fly everyone flying", Says = "If everyone could fly, bases would be exposed from above, bridges wouldn't matter and beds would fall fast, so cover on top and a bow would become the key defence."},
            {Keys = "middle map center centre middle", Says = "A bed in the middle of the map would turn every game into a rush: nobody could build defences, so it would be decided in the first thirty seconds."},
            {Keys = "swords sword deleted removed no swords", Says = "With no swords, fights would come down to bows, fireballs and TNT, so ranged players and explosive builds would dominate."},
            {Keys = "tnt explosives", Says = "If TNT were everywhere, wool beds would die in seconds, so stone bricks and obsidian would become mandatory."},
            {Keys = "double speed faster twice fast", Says = "Double speed would make bridging and rushes quicker, so defending a bed would be harder and matches would end earlier."},
            {Keys = "no armor armour", Says = "Without armour, every fight would be shorter and swings would matter more, so the first hit would almost decide a fight."},
            {Keys = "invisible invisibility", Says = "If everyone were invisible, nametags and sound would carry the whole game, so footsteps and the minimap would become the main tools."},
            {Keys = "ping lag 5000 laggy", Says = "At 5000 ms ping the server sees you late, so no module can really save you: the only fixes are a better connection, a closer region or closing other apps."},
            {Keys = "day night time clock", Says = "Time of day wouldn't change much in BedWars gameplay, but a darker map makes it harder to spot enemies at distance."},
            {Keys = "kits kit one kit same", Says = "If everyone used the same kit, the game would turn into pure skill and strategy, with no surprises from abilities."}
        }

        function Mind.WhatHappens(Frame): string?
            local Best, BestHits = nil, 0
            for _, Effect in Mind.Effects do
                local Hits: number = 0
                for Word: string in Effect.Keys:gmatch("%S+") do
                    if Frame.Set[Word] or Frame.Contains and Mind.Contains(Frame, Word) then
                        Hits += 1
                    end
                end

                if Hits > BestHits then
                    Best, BestHits = Effect, Hits
                end
            end

            return Best and BestHits >= 1 and Best.Says or nil
        end

        -- ---------------------------------------------------------------- vague follow-ups

        local Vague = Brain.Set("which one how much though why what next then and so ok okay hm hmm huh really sure what")

        Act("Vague", function(Frame): boolean
            if Frame.Count > 5 or Frame.Evidence >= 2 or not Last() then
                return false
            end

            local C = Frame.Clean
            if C:match("^wait which") or C:match("^which one") or ((C:match("^how much") or C:match("^how many")) and (Frame.Set.though or Frame.Set.tho or Frame.Set["then"])) or C:match("^what next") or C:match("^alright what") or C:match("^ok what next") or C:match("^like what") or C:match("^such as") or C:match("^for example") or C:match("^and if it") or C:match("^what if it") or C:match("^nah the other") or C:match("^the other") or C == "and" or C == "so" or C == "and then" or C == "then what" then
                return true
            end

            return false
        end, function(Frame)
            local C = Frame.Clean
            local Previous = Last()
            local Name: string? = Previous.Names and Previous.Names[1]
            if C:match("^and if it") or C:match("^what if it") then
                if Name then
                    return Mind.Reply(Mind.Join(`If {Name} doesn't work: first check it's actually switched on, then make sure you're in a game it supports, then try resetting its settings to default.`, "If nothing changes, open the console and see if it printed an error, and tell me what it says."), {`Open {Name} settings`})
                end

                return Mind.Reply(Mind.Join("If it doesn't work, check the console for an error, turn the module off and on, and make sure you're in a supported game.", "Tell me which module and what happens, and I can be more exact."))
            elseif C:match("^what next") or C:match("^alright what") or C:match("^ok what next") or C == "then what" or C == "and then" then
                return Mind.Reply(Mind.Join(Mind.Any("Next, you could try", "From here, I'd try", "A good next step: "), Mind.Any("setting a keybind for the module you use most, so you don't need the menu mid-game.", "saving your setup as a profile so you can bring it back later.", "turning on a visual module like ESP to see how the game looks with it.", "asking me about one module you haven't tried yet."), "Want me to do any of those?"))
            elseif C:match("^like what") or C:match("^such as") or C:match("^for example") then
                local Sample: string? = SampleModule()
                local Entry = Sample and Index.Keys[Compact(Sample)]
                if Entry then
                    return Mind.Reply(Mind.Join(`For example, {Mind.Name(Entry)}, it {Mind.Describe(Entry)}.`, Mind.Chance(0.5) and "Want another one?" or ""), {`What does {Entry.Name} do?`, "Another example"})
                end
            end

            local Short: string = Previous.A and (Mind.Sentences(Previous.A)[1] or "") or ""
            return Mind.Reply(Mind.Join(
                Mind.Any(`I'm not sure which part you mean.`, "I can't tell which one you're pointing at."),
                Short ~= "" and `My last answer started with: "{Short:sub(1, 90)}".` or "",
                Mind.Any("Name the module or the part and I'll answer exactly that.", "Say it again with the name in it and I'll get it.")
            ))
        end)

        -- ---------------------------------------------------------------- a menu that misbehaves

        local Troubles = {
            {Keys = "open opens opening show showing appear appears gone missing vanished", Say = "If the menu won't open, check that your chat or a text box isn't focused, then press RightShift, or whatever key you rebound it to. If it still doesn't show, rejoin and reinject, some game updates break the first load."},
            {Keys = "click clicking clicks press buttons unresponsive paper stuck frozen freeze", Say = "If the menu opens but won't react to clicks, another GUI is probably sitting on top of it, so close extra GUIs, and try a different GUI scale in the settings. A reinject often clears it."},
            {Keys = "key keybind bind button shift pressed press nothing", Say = "If a key does nothing, make sure chat isn't focused and that no other script has taken the key. You can change the menu key with Rebind GUI in the settings."},
            {Keys = "lag laggy fps slow stutter stuttering freezing", Say = "If the menu makes your game lag, turn off HUD blur and the blur background in the GUI settings, they cost the most frames, and close modules you don't need."},
            {Keys = "crash crashes crashed kicked disconnect disconnected error errors", Say = "For crashes and errors, the console (F9) usually names the module that failed. Turn that module off, reinject, and tell me what the error says."},
            {Keys = "weird strange wrong glitch glitching glitchy broken buggy", Say = "For odd behaviour, the quick checks are: which modules are on, whether two of them do the same job, and what the console says. Turning everything off and back on one by one finds the culprit."}
        }

        Mind.Troubles = Troubles

        Act("Trouble", function(Frame): boolean
            if Frame.Evidence < 1 and not Frame.Set.menu and not Frame.Set.gui and not Frame.Set.modules then
                return false
            end

            local C = Frame.Clean
            local Menu: boolean = Frame.Set.menu or Frame.Set.gui or Frame.Set.catvape or Frame.Set.script or Frame.Set.button or Frame.Set.buttons or Frame.Set.modules or Frame.Set.keybinds or Frame.Set.hud or Frame.Set.overlay or Frame.Set.aimassist or Frame.Set.autowin or Frame.Set.tab
            local Problem: boolean = C:find("grayed", 1, true) ~= nil or C:find("greyed", 1, true) ~= nil or C:find("switched to", 1, true) ~= nil or C:find("overlaps", 1, true) ~= nil or C:find("locks onto", 1, true) ~= nil or C:find("walked into", 1, true) ~= nil or C:find("closes and so", 1, true) ~= nil or C:find("cant reset", 1, true) ~= nil or C:find("weird", 1, true) ~= nil or C:find("nothing happen", 1, true) ~= nil or C:find("doesnt", 1, true) ~= nil or C:find("doesn't", 1, true) ~= nil or C:find("wont", 1, true) ~= nil or C:find("won't", 1, true) ~= nil or C:find("cant", 1, true) ~= nil or C:find("can't", 1, true) ~= nil or C:find("broken", 1, true) ~= nil or C:find("stuck", 1, true) ~= nil or C:find("glitch", 1, true) ~= nil or C:find("not working", 1, true) ~= nil
            return Menu and Problem
        end, function(Frame)
            local Best, BestHits = nil, 0
            for _, Trouble in Troubles do
                local Hits: number = 0
                for Word: string in Trouble.Keys:gmatch("%S+") do
                    Hits += Frame.Set[Word] and 1 or 0
                end

                if Hits > BestHits then
                    Best, BestHits = Trouble, Hits
                end
            end

            Best = Best or Troubles[6]
            return Mind.Reply(Mind.Join(Mind.Any("That sounds annoying.", "Okay, let's narrow it down.", "Let's work out what's up."), Best.Say, "If that doesn't fix it, tell me exactly what you see and what you pressed."), {"What can you do?"})
        end, "mid")
        end

        -- ---------------------------------------------------------------- reasoning about modules

        -- Judgements built from what a module actually touches (Brain.Uses), where it lives, and the facts on file, then tailored to the
        -- user's profile. Every verdict carries the reasons it came from, so "why" can be answered with them.
        do
        local Act = Mind.Act
        local Reason = {}
        Mind.Reason = Reason

        -- What other players and the anticheat can see: moving, hitting and placing show up, drawing on your own screen does not.
        local Weights = {Move = 4, Attack = 3, Break = 3, Shoot = 2, Clicks = 2, Rotate = 2, Place = 1.5, Items = 1, Camera = 0.5, Target = 0.5, Hook = 0.5}
        local Visible = {Move = true, Attack = true, Break = true, Shoot = true, Clicks = true, Rotate = true, Place = true, Items = true}

        function Reason.Assess(Entry)
            local Score: number = 0
            local Seen: {string} = {}
            for _, Resource: string in Brain.ResourceOrder do
                local Weight: number? = Weights[Resource]
                if Weight and Brain.Uses(Entry, Resource) then
                    Score += Weight
                    table.insert(Seen, Resource)
                end
            end

            if Entry.Legit then
                Score = math.max(Score - 3, 0)
            elseif Entry.Category == "Blatant" then
                Score += 2
            end

            return {Level = Score >= 6 and "high" or Score >= 3 and "medium" or "low", Score = Score, Resources = Seen}
        end

        local Rank = {low = 1, medium = 2, high = 3}
        local Warns = Brain.Set("flag flagged flagging flags ban banned bans bannable detect detected detection detectable anticheat lagback lagbacks rubberband")

        -- The first sentence of a fact about this module that talks about being flagged or banned.
        function Reason.Warning(Entry): string?
            for _, Found in FactsFor(Entry) do
                local Fact = Found.Fact
                local Text = Fact.Text
                if type(Text) == "string" then
                    for Word: string in (Fact.Keywords or ""):gmatch("%a+") do
                        if Warns[Word] then
                            return Plain(Text):match("^(.-[%.!?])%s") or Plain(Text)
                        end
                    end
                end
            end

            return nil
        end

        -- A similar module that is quieter, if one exists: the best ranked match for what this one does that is a step lower in risk.
        function Reason.Alternative(Entry)
            local Level: number = Rank[Reason.Assess(Entry).Level]
            local Summary: string = Plain(Entry.Module.Tooltip):match("^[^\n]*") or ""
            if Summary == "" or Level == 1 then
                return nil
            end

            local Results = Brain.Rank(Summary)
            for i: number = 1, math.min(#Results, 8) do
                local Other = Results[i].Entry
                if Other ~= Entry and Results[i].Covers >= 0.5 and Rank[Reason.Assess(Other).Level] < Level then
                    for Resource: string in Visible do
                        if Brain.Uses(Entry, Resource) and Brain.Uses(Other, Resource) then
                            return Other
                        end
                    end
                end
            end

            return nil
        end

        function Reason.Doing(Assessment): string
            local Parts: {string} = {}
            for _, Resource: string in Assessment.Resources do
                if Visible[Resource] then
                    table.insert(Parts, Brain.Resources[Resource].Does)
                end
            end

            return Mind.Oxford(Parts)
        end

        local Verdicts = {
            high = {"one of the easier ones for other players and the anticheat to spot", "on the risky side", "loud, the kind of thing that gets people reported"},
            medium = {"somewhere in the middle: fine in short bursts, but it can show up if you overdo it", "medium risk, it depends a lot on how you use it"},
            low = {"pretty quiet", "low risk", "about as safe as modules get"}
        }

        local Words = Brain.Set("safe safer safest risky riskier risk detect detected detectable undetected undetectable ban banned bannable bans flag flagged flags flagging caught suspicious obvious reported report noticeable")

        -- Questions about a setting's value, a config request or a side by side comparison belong to the parts of the assistant that know those.
        local Elsewhere = Brain.Set("best setting settings setup config configure range horizontal vertical delay value values slider percent need needs want wants make give set vs versus tweak adjust change lower raise increase decrease")

        local function Wants(Frame): boolean
            if #Frame.Mentions == 0 or #Frame.Mentions > 2 or (Frame.Raw:gsub("%d+%%", "")):find("%d") or Frame.Set.how and (Frame.Set.turn or Frame.Set.bind or Frame.Set.use or Frame.Set.configure) and not Frame.Set.safe then
                return false
            end

            for Word: string in pairs(Elsewhere) do
                if Frame.Set[Word] then
                    return false
                end
            end

            if #Frame.Mentions == 2 and not Mind.Contains(Frame, "than") then
                return false
            end

            local Hit: boolean = false
            for Word: string in pairs(Words) do
                Hit = Hit or Frame.Set[Word] == true
            end

            local First: string = Mind.Memory.Core(Frame.Raw):match("^%a+") or ""
            local Aux = First == "is" or First == "are" or First == "does" or First == "will" or First == "can" or First == "would" or First == "could" or First == "should" or First == "did" or First == "do" or First == "how" or First == "what" or First == "why"
            return Hit and (Frame.Question or Aux or Frame.Count <= 3) and not Frame.Set.nuke
        end

        function Reason.Verdict(Entry, Override: string?)
            local Assessment = Reason.Assess(Entry)
            local Level: string = Assessment.Level
            local Doing: string = Reason.Doing(Assessment)
            local Name: string = Mind.Name(Entry)
            local Memory = Mind.Memory
            local Basis: {string} = {}
            local Because: string
            if Entry.Legit then
                Because = "it's in the Legit menu, which only tweaks your own view and nothing the server sees"
            elseif Doing ~= "" then
                Because = `it {Doing}, which is what other players and the anticheat can see`
            elseif Level == "low" then
                Because = "it mostly changes what you see on your own screen"
            else
                Because = `it sits in the {Entry.Category} window`
            end

            table.insert(Basis, `{Entry.Name} is in the {Entry.Category} window`)
            if Doing ~= "" then
                table.insert(Basis, `it {Doing}`)
            end

            local Warning: string? = Reason.Warning(Entry)
            if Warning then
                table.insert(Basis, Warning)
            end

            local Advice: string = ""
            if Level == "high" then
                Advice = "If you use it anyway, keep the ranges modest, switch it on only when you need it and play on an account you can afford to lose."
            elseif Level == "medium" then
                Advice = "Moderate values and not leaving it on all match keep it fairly quiet."
            end

            local Alternative = Level ~= "low" and Reason.Alternative(Entry) or nil
            local Style: string? = Override or Memory.Get("style")
            local Told: string = Override and "For legit play" or "You told me you like to keep things legit"
            local Personal: string = ""
            if Style == "legit" and Level ~= "low" then
                Personal = Alternative and `{Told}, so I'd skip it and try {Mind.Name(Alternative)} instead.` or `{Told}, so I'd leave this one off.`
                table.insert(Basis, Override and "you asked about legit play" or "you told me you prefer to play legit")
            elseif Style == "closet" and Level == "high" then
                Personal = Override and "For closet play, keep it short and low, it's one of the louder ones." or "You play closet, so I'd keep this one low and brief."
            elseif Style == "blatant" and Level == "high" then
                Personal = Override and "For blatant play the risk is part of the deal, just don't expect it to be invisible." or "You play blatant, so the risk is part of the deal, just don't expect it to be invisible."
            elseif Alternative then
                Personal = `{Mind.Name(Alternative)} does something similar and is quieter.`
            end

            if Alternative then
                table.insert(Basis, `{Alternative.Name} does something similar at lower risk`)
            end

            local Text: string = Mind.Join(
                `{Name} is {Mind.From(Verdicts[Level])}, because {Because}.`,
                Warning or "",
                Advice,
                Personal,
                Level ~= "low" and Mind.Chance(0.4) and "No module is invisible, this is about how noticeable it is, not a promise." or ""
            )

            local Chips = {"What are the safest modules?"}
            if Alternative then
                table.insert(Chips, 1, `What does {Alternative.Name} do?`)
            end

            local Result = Mind.Reply(Text, Chips)
            Result.Basis = Basis
            return Result
        end

        local Absolute = Brain.Set("completely totally absolutely fully entirely 100 zero")

        Act("Safety", Wants, function(Frame)
            local Override: string? = Frame.Set.legit and "legit" or Frame.Set.closet and "closet" or Frame.Set.blatant and "blatant" or nil
            local First = Reason.Verdict(Frame.Mentions[1].Entry, Override)
            local Sure: boolean = Mind.Contains(Frame, "no risk") or Mind.Contains(Frame, "risk free")
            for Word: string in pairs(Absolute) do
                Sure = Sure or Frame.Set[Word] == true
            end

            if Sure or Frame.Raw:find("100%%") then
                First.Text = Mind.Join(Mind.Any("Not quite, no module is risk free.", "No, nothing is completely safe."), First.Text)
            end

            local Second = Frame.Mentions[2]
            if Second and Frame.Mentions[2].Entry ~= Frame.Mentions[1].Entry then
                local A, B = Reason.Assess(Frame.Mentions[1].Entry), Reason.Assess(Second.Entry)
                local Safer = Rank[A.Level] == Rank[B.Level] and "about as risky as each other" or Rank[A.Level] < Rank[B.Level] and `{Mind.Name(Frame.Mentions[1].Entry)} is the safer of the two` or `{Mind.Name(Second.Entry)} is the safer of the two`
                First.Text = Mind.Join(First.Text, `Next to {Mind.Name(Second.Entry)}, ({B.Level} risk) they're {Safer}.`)
            end

            return First
        end)

        -- "why" after an answer that had reasons behind it: say them.
        local WhyPatterns = {"^why these$", "^why those$", "^why these ones$", "^why did you pick these$", "^why did you pick those$", "^why$", "^why is that$", "^why though$", "^how come$", "^why do you say that$", "^how do you know$", "^why is it$", "^why so$", "^what makes you say that$", "^and why$", "^why not$", "^explain why$", "^why did you say that$", "^what is the reason$"}

