                local Lines = Brain.SettingLines(Entry, 3)
                if Step == 1 then
                    return `Look at {Mind.Name(Entry)}'s main settings: {Plain(table.concat(Lines, "; "))}. Too strict a range or target filter makes it look like it's missing.`
                elseif Step == 2 then
                    return `Make sure nothing else is doing the same job as {Mind.Name(Entry)} at the same time, two modules fighting over the same action cancel each other out. If you want a clean start, say "reset {Entry.Name} to default".`
                end
            end

            if Step <= 2 then
                return Entry and `Try turning {Mind.Name(Entry)} off and on again, then say "reset {Entry.Name} to default" if it still acts up.` or "Turn the module off and on again, then reset it to its default settings if it still acts up."
