            Guilt = {"It's good that you're thinking about it.", "That feeling usually means you care about being fair.", "Nobody's perfect, you're not the first to feel that."},
            Joy = {"Love that for you!", "That's great to hear.", "Nice, enjoy it."}
        }

        local Advice = {
            Tilt = {"Stand up, drink water, and take five minutes before the next queue, tilt makes you lose more.", "Try muting chat for a game or two, most rage comes from other people's words.", "Pick one small thing to improve next game instead of chasing the win."},
            Sad = {"If it's more than a gaming mood, talk to someone you trust, a friend or family member, it helps more than any game does.", "Maybe step away from the screen for a bit and do something small that feels good.", "I'm here if you just want to chat for a while."},
            Anxious = {"Slow breaths help, in for four, out for six, a few times.", "Break the thing into the very next step instead of the whole mountain.", "It might help to write it down and handle one piece at a time."},
            Bored = {"Try a new module or a new kit and treat it as a challenge.", "Set yourself a silly goal, like winning a game using only a bow.", "I can tell you a joke or pick a random module for you to try."},
            Tired = {"Sleep first, the game will be here tomorrow.", "A short break, water and a stretch beat grinding another game.", "If you're tired, stop at a win and go rest."},
            Doubt = {"Pick one skill, like bridging or hotbar swaps, and practice only that for a week, you'd be surprised how fast it moves.", "Watch how better players spend their first minute, setups beat aim.", "Play a few relaxed games with no goal except trying a new thing."},
            Guilt = {"If it bugs you, the simple fix is to keep it fair, play against people who know, or use lighter settings.", "You can always change how you use it, you're in control of that.", "Being honest with the people you play with usually clears the feeling."},
            Joy = {"Tell me about it, what happened?", "Keep that energy for the next game.", "Go enjoy it, and tell me how it goes."}
        }

        local Causes = {
            {Words = Brain.Set("streak lose losing lost losses"), Tip = "A losing streak mostly means variance and tilt, the next game is a fresh start."},
            {Words = Brain.Set("teammates teammate team randoms afk trolls"), Tip = "You can't control teammates, but you can control your bed and your own plan, that's where wins start."},
            {Words = Brain.Set("toxic flamed flaming insulted reported chat"), Tip = "Muting toxic chat is a free win, you don't owe anyone a reply."},
            {Words = Brain.Set("lag ping laggy fps"), Tip = "If lag is the issue, close other apps and lower graphics, and modules like the performance ones can help."},
            {Words = Brain.Set("friend friends quit left left'"), Tip = "Friends drifting away stings, a message to them or a new party often helps more than you'd think."},
            {Words = Brain.Set("school exam test homework"), Tip = "Schoolwork first, the queue can wait an hour."},
            {Words = Brain.Set("banned ban"), Tip = "Bans hurt, and I can't undo one, but you can appeal through the game or Roblox support."}
        }

        function Mind.MoodOf(Frame): string?
            for Name: string, Set in Moods do
                for Word: string in Set do
                    if Frame.Set[Word] then
                        return Name
                    end
                end
            end

            return nil
        end

        Act("Feeling", function(Frame): boolean
            local C = Frame.Clean
            if Frame.Evidence >= 3 then
                return false
            end

            local Mood = Mind.MoodOf(Frame)
            local Self: boolean = Frame.Set.i or Frame.Set.im or Frame.Set["i'm"] or Frame.Set.my or Frame.Set.me
            local Question: boolean = C:match("^do you") ~= nil or C:match("^are you") ~= nil or C:match("^how are you") ~= nil
            return Mood ~= nil and Self and not Question and not Frame.Set.you
        end, function(Frame)
            local Mood = Mind.MoodOf(Frame)
            local Tip: string = ""
            for _, Cause in Causes do
                for Word: string in Cause.Words do
                    if Frame.Set[Word] and Tip == "" then
                        Tip = Cause.Tip
                    end
                end
            end

            local Restated: string = ""
            if Frame.Count >= 5 and Frame.Count <= 22 then
                Restated = Mind.Chance(0.5) and `So {Mind.Turn(Frame.Clean)}.` or ""
            end

            return Mind.Reply(Mind.Join(
                Restated,
                Mind.From(Validate[Mood]),
                Tip,
                Mind.From(Advice[Mood])
            ), Mood == "Bored" and {"Tell me a joke", "Pick a random module"} or nil)
        end, true)

        -- ---------------------------------------------------------------- opinions

        local OpinionFrames = {
            good = {"depends on what you want from it", "it rewards the people who put time into it", "it's easy to like when it's working for you"},
            bad = {"most things get a bad name when they're used badly", "it's rarely the idea that's bad, usually the way it's used"},
            overrated = {"hype tends to run ahead of reality", "popular things are popular for a reason, but not always the reason people say"},
            underrated = {"quiet things often get overlooked", "the loud stuff gets all the attention, the useful stuff stays low-key"},
            dying = {"I can't see player counts, so I can't prove it either way", "games rarely die overnight, they thin out and change"},
            fun = {"fun is personal, but friends make almost anything better", "it's more fun when you pick a small goal each game"},
            cringe = {"cringe is mostly about who's watching", "what feels cringe in a lobby often feels fine in private"},
            toxic = {"most of that comes from the people, not the game", "a mute button fixes about half of it"},
            fair = {"fair mostly depends on whether everyone agrees to the rules", "it's fair when everyone involved knows what's going on"},
            easy = {"easy until you meet someone better", "everything's easy once you've practiced it"},
            hard = {"hard at first, and then one day it clicks", "it feels hard because the early part has no shortcuts"},
            worth = {"worth it if you'd use it more than once", "it's worth it when it fixes a problem you actually have"}
        }

        local OpinionAdjectives = {
            good = "good", great = "good", best = "good", amazing = "good", awesome = "good", op = "good", strong = "good", broken = "good", goated = "good",
            bad = "bad", trash = "bad", garbage = "bad", terrible = "bad", worst = "bad", useless = "bad", weak = "bad", mid = "bad",
            overrated = "overrated", underrated = "underrated", dead = "dying", dying = "dying", fun = "fun", boring = "fun",
            cringe = "cringe", embarrassing = "cringe", toxic = "toxic", sweaty = "toxic", unfair = "fair", fair = "fair", cheating = "fair", cheat = "fair",
            easy = "easy", simple = "easy", hard = "hard", difficult = "hard", worth = "worth", good_ = "good", rude = "cringe", wrong = "cringe", okay = "fair", ok = "fair", allowed = "fair"
        }

        local OpinionStart = {"do you think", "what do you think", "whats your opinion", "your opinion", "your take", "your thoughts", "how good is", "how bad is", "rate my", "rate this", "rate ", "be honest", "honestly is", "tell me honestly", "do you like", "do you hate", "what do you reckon", "how do you feel about"}

        Act("Opinion", function(Frame): boolean
            local C = Frame.Clean
            for _, Start: string in OpinionStart do
                if C:find(Start, 1, true) then
                    return true
                end
            end

            local Adjective: boolean = false
            for Word: string in Frame.Set do
                if OpinionAdjectives[Word] then
                    Adjective = true
                end
            end

            -- a plain claim about a module: "killaura is so op lol"
            if Adjective and not Frame.Question and Frame.Mentions[1] and (C:find(" is ", 1, true) or C:find(" are ", 1, true) or C:find(" feels ", 1, true)) and not Mind.Commandy(Frame) then
                return true
            end

            return Adjective and (C:match("^is ") ~= nil or C:match("^are ") ~= nil or C:match("^isn't ") ~= nil or C:match("^would it be") ~= nil or C:match("^is it") ~= nil) and Frame.Question
        end, function(Frame)
            local C = Frame.Clean
            local Entry = Frame.Mentions[1] and Frame.Mentions[1].Entry or nil
            local Axis: string = "good"
            for _, Word: string in Frame.Words do
                if OpinionAdjectives[Word] then
                    Axis = OpinionAdjectives[Word]
                    break
                end
            end

            local Subject: string = C:match("do you think (.+)$") or C:match("what do you think of (.+)$") or C:match("what do you think about (.+)$") or C:match("how do you feel about (.+)$") or C:match("^is (.+) %a+$") or C:match("^are (.+) %a+$") or C:match("rate (.+)$") or C:match("^is it %a+ to (.+)$") or C:match("^is it (.+)$") or C:match("your take on (.+)$") or C:match("your opinion on (.+)$") or C:match("do you like (.+)$") or C:match("do you hate (.+)$") or C:match("^how good is (.+)$") or Frame.Clean
            local Echo: string = Mind.Turn(Subject)
            local Note: string = Mind.From(OpinionFrames[Axis] or OpinionFrames.good)
