        local function WorldAnswer(Frame): string?
            local C = Frame.Clean
            local Country: string? = C:match("capital of (.+)$") or C:match("capital city of (.+)$") or C:match("capital for (.+)$")
            if Country then
                Country = Country:gsub("^the ", ""):gsub(" please$", ""):gsub(" pls$", "")
                local Parts = Mind.WordsOf(Country)
                local City: string? = Capitals[Country]
                for Length: number = math.min(3, #Parts), 1, -1 do
                    local Try: string = table.concat(Parts, " ", 1, Length)
                    if Capitals[Try] then
                        Country, City = Try, Capitals[Try]
                        break
                    end
                end

                if City then
                    return Mind.Any(`The capital of {Mind.Cap(Country)} is {City}.`, `That's {City}.`, `{City}, it's the capital of {Mind.Cap(Country)}.`)
                end
            end

            local Best, BestLength = nil, 0
            for _, Fact in WorldFacts do
                local Fits: boolean = true
                for Word: string in Fact.Keys:gmatch("%S+") do
                    if not C:find(Word, 1, true) then
                        Fits = false
                        break
                    end
                end

                if Fits and #Fact.Keys > BestLength then
                    Best, BestLength = Fact, #Fact.Keys
                end
            end

            return Best and Best.Answer or nil
        end

