        local function SolveLinear(Text: string): (number?, string?)
            local Left, Right = Text:match("(.-)=(.+)")
            if not Left then
                return nil
            end

            local A, B = Left:match("(%-?%d*%.?%d*)%s*x%s*([%+%-]%s*%d+%.?%d*)")
            if not A then
                A = Left:match("(%-?%d*%.?%d*)%s*x")
                B = "0"
            end

            if not A then
                return nil
            end

            local Slope: number = (A == "" or A == "+") and 1 or A == "-" and -1 or tonumber(A) or 0
            local Offset: number = tonumber((B:gsub("%s", ""))) or 0
            local Total: number? = tonumber((Right:gsub("%s", "")))
            if Slope == 0 or not Total then
                return nil
            end

            return (Total - Offset) / Slope, Left
        end

        local Pattern = "[%d%-%+x%.%s=]+[x=][%d%-%+x%.%s=]*"

        Act("Equation", function(Frame): boolean
            return Frame.Lower:find("x") ~= nil and Frame.Lower:find("=") ~= nil and Frame.Lower:match("%d") ~= nil and SolveLinear(Frame.Lower:match(Pattern) or "") ~= nil
        end, function(Frame)
            local Value = SolveLinear(Frame.Lower:match(Pattern) or "")
            local Shown: string = Value == math.floor(Value) and string.format("%d", Value) or (string.format("%.3f", Value):gsub("0+$", ""))
            return Mind.Reply(Mind.Join(`That works out to x = {Shown}.`, Mind.Any("Check it by putting it back in.", "Subtract the constant, then divide by the number in front of x.", "Quick check: plug it back in and both sides match.")))
        end)

        Act("Life", function(Frame): boolean
            if Frame.Evidence >= 2 then
                return false
            end

            if Frame.Lower:find("x") and Frame.Lower:find("=") and Frame.Lower:match("%d") then
                local Value = SolveLinear(Frame.Lower:match("[%d%-%+x%.%s=]+[x=][%d%-%+x%.%s=]*") or "")
                if Value then
                    return true
                end
            end

            for _, Group in Life do
                local Hits: number = 0
                for _, Word: string in Frame.Words do
                    Hits += Group.Words[Word] and 1 or 0
                end

                if Hits >= 1 and (Frame.Question or Frame.Set.help or Frame.Set.how or Frame.Set.can or Frame.Set.my or Frame.Set.i) then
                    return true
                end
            end

            return false
        end, function(Frame)
            local Equation: string? = Frame.Lower:match("[%d%-%+x%.%s=]+[x=][%d%-%+x%.%s=]*")
            if Equation then
                local Value = SolveLinear(Equation)
                if Value then
                    local Shown: string = Value == math.floor(Value) and string.format("%d", Value) or string.format("%.3f", Value):gsub("0+$", "")
                    return Mind.Reply(Mind.Join(`That works out to x = {Shown}.`, Mind.Any("Check it by putting it back in.", "Subtract the constant, then divide by the number in front of x.", "Quick check: plug it back in and both sides match.")))
                end
            end

            local Best, BestHits = nil, 0
            for _, Group in Life do
                local Hits: number = 0
                for _, Word: string in Frame.Words do
                    Hits += Group.Words[Word] and 1 or 0
                end

                if Hits > BestHits then
                    Best, BestHits = Group, Hits
                end
            end

            if not Best then
                return nil
            end

            local Topic: string? = nil
            for _, Word: string in Frame.Words do
                if Best.Words[Word] then
                    Topic = Word
                    break
                end
            end

            return Mind.Reply(Mind.Join(
                Topic and Frame.Count >= 4 and Mind.Any(`{Mind.Cap(Topic)}, that's a whole different world from BedWars.`, `That's about {Topic}, not something I'm built for.`) or "",
                Mind.From(Best.Lines),
                Mind.Any("I'm happy to help the moment it touches CatVape or the game.", "If you need anything in the game, I'm right here.", "Come back when you want a module explained.")
            ), {"What can you do?"})
        end, true)

        -- ---------------------------------------------------------------- rankings and superlatives

        local function Entries(Predicate: ((any) -> boolean)?): {any}
            local List = {}
            for _, Entry in Index.Entries do
                if Plain(Entry.Module.Tooltip) ~= "" and (not Predicate or Predicate(Entry)) then
                    table.insert(List, Entry)
                end
            end

            return List
        end

        local Counting = {one = 1, two = 2, three = 3, four = 4, five = 5, six = 6, seven = 7, eight = 8, nine = 9, ten = 10}

        Act("Ranking", function(Frame): boolean
            local C = Frame.Clean
            if not (C:match("^top ") or C:match("^best ") or C:match("^worst ") or C:match("^most ") or C:match("^least ") or C:match("^hardest ") or C:match("^easiest ") or C:match("^what is the best") or C:match("^what's the best") or C:match("^whats the best") or C:match("^what is the worst") or C:match("^which module has the most") or C:match("^which module has the least") or C:match("^which is the") or C:match("^list the") or C:match("^name the") or C:match("^name some") or C:match("^name a few") or C:match("^best thing about") or C:match("^what is the most") or C:match("^whats the most")) then
                return false
            end

            return Frame.Set.module or Frame.Set.modules or Frame.Set.mod or Frame.Set.mods or Frame.Set.kit or Frame.Set.kits or Frame.Set.catvape or Frame.Set.settings or Frame.Set.options or C:find("thing about catvape", 1, true) ~= nil
        end, function(Frame)
            local C = Frame.Clean
            Brain.Ready()
            local Count: number = Counting[C:match("top (%a+)") or ""] or tonumber(C:match("top (%d+)")) or 3
            Count = math.clamp(Count, 1, 6)
            if Frame.Set.kit or Frame.Set.kits then
                local Hard: boolean = C:find("hardest") ~= nil or C:find("worst") ~= nil
                return Mind.Reply(Mind.Join(
                    Mind.Any("I don't have kit stats to rank them with, so take this as a rule of thumb.", "Kit balance changes with every update and I can't see win rates, so I won't pretend to have a list."),
                    Hard and "Kits that need setup or placement (tamers, builders, traps) usually take longest to get good at, passive-buff kits are the easiest to start with." or "Pick the kit that matches how you already play, a simple one you know well beats a strong one you don't.",
                    "Ask me what you'd like to do in a match and I'll say which kit fits."
                ), {"What kit should I use?"})
            end

            if C:find("thing about catvape") or C:find("best part") then
                local Total: number = #Entries()
                return Mind.Reply(Mind.Join(
                    Mind.Any("I'm biased, but:", "Easy one, though I'm a bit biased:"),
                    `the sheer range. There are {Total} modules in one menu, you can save setups as profiles, and there's even an assistant that clicks things for you.`,
                    Mind.Any("What about you, what do you like most?", "Is there something you're hoping to find?")
                ))
            end

            local Least: boolean = C:find("least") ~= nil or C:find("fewest") ~= nil or C:find("useless") ~= nil or C:find("worst") ~= nil or C:find("weakest") ~= nil
            local Most: boolean = not Least and (C:find("most") ~= nil or C:find("best") ~= nil or C:find("top") ~= nil)
            local All = Entries(function(Entry) return not Entry.Legit end)
            table.sort(All, function(A, B)
                if #A.Options ~= #B.Options then
                    return #A.Options > #B.Options
                end
                return A.Name < B.Name
            end)

            local Names: {string} = {}
            if Least then
                for i: number = #All, math.max(#All - Count + 1, 1), -1 do
                    table.insert(Names, `{Mind.Name(All[i])} ({#All[i].Options})`)
                end

                return Mind.Reply(Mind.Join(
                    Mind.Any("\"Useless\" is a personal call, I can't judge what's useless for you.", "Whether something's useless depends on your playstyle."),
                    `What I can count is settings: the simplest modules, with the fewest options, are {Mind.Oxford(Names)}.`,
                    Mind.Any("Few settings usually means a narrow job, not a bad one.", "A module with one job done well isn't useless.")
                ))
            end

            for i: number = 1, math.min(Count, #All) do
                table.insert(Names, `{Mind.Name(All[i])} ({#All[i].Options})`)
            end

            return Mind.Reply(Mind.Join(
                Most and "By number of settings, the most customisable modules are" or "A few modules that stand out:",
                `{Mind.Oxford(Names)}.`,
                Mind.Any("The number in brackets is how many options each has.", "That's measured, not an opinion.")
            ))
        end)
        end

