            if not Language then
                return Mind.Reply("I only carry a tiny phrasebook: Spanish, French, German, Portuguese and Italian, for common phrases like \"good game\" or \"thank you\".")
            end

            for Phrase: string, Table in Phrases do
                if C:find(Phrase, 1, true) then
                    return Mind.Reply(Mind.Join(`In {Language}, "{Phrase}" is "{Table[Language]}".`, Mind.Chance(0.4) and "My phrasebook is tiny, so double-check anything important." or ""))
