        -- ---------------------------------------------------------------- word games

        local Letters = {
            k = {Adjectives = {"kind", "keen", "kooky"}, Nouns = {"kittens", "knights", "kings", "kids"}, Verbs = {"keep", "kick", "kiss", "know"}},
            b = {Adjectives = {"big", "brave", "brilliant"}, Nouns = {"beds", "bees", "bears", "builders"}, Verbs = {"break", "bridge", "build", "bounce"}},
            s = {Adjectives = {"sneaky", "swift", "silly"}, Nouns = {"swords", "snakes", "squads", "sheep"}, Verbs = {"swing", "sprint", "save", "scout"}},
            c = {Adjectives = {"clever", "cheerful", "crazy"}, Nouns = {"cats", "creepers", "chests", "clutches"}, Verbs = {"climb", "catch", "craft", "chase"}},
            m = {Adjectives = {"mighty", "messy", "magic"}, Nouns = {"mice", "monsters", "maps", "mobs"}, Verbs = {"mine", "move", "make", "melt"}},
            p = {Adjectives = {"purple", "proud", "playful"}, Nouns = {"pandas", "pearls", "pickaxes", "players"}, Verbs = {"place", "push", "protect", "pounce"}},
            t = {Adjectives = {"tiny", "tough", "tricky"}, Nouns = {"towers", "tigers", "teams", "traps"}, Verbs = {"take", "toss", "trade", "tower"}},
