            f = {Adjectives = {"fast", "fierce", "funny"}, Nouns = {"foxes", "fireballs", "friends", "forts"}, Verbs = {"fight", "fly", "find", "fall"}},
            g = {Adjectives = {"great", "gentle", "golden"}, Nouns = {"games", "guards", "geese", "generators"}, Verbs = {"guard", "grab", "gather", "glide"}},
            d = {Adjectives = {"dark", "daring", "dizzy"}, Nouns = {"dragons", "diamonds", "defenders", "ducks"}, Verbs = {"dodge", "dig", "defend", "dash"}},
            a = {Adjectives = {"awesome", "angry", "agile"}, Nouns = {"archers", "ants", "armour", "apples"}, Verbs = {"attack", "aim", "avoid", "arrive"}}
        }

        Act("Wordplay", function(Frame): boolean
            local C = Frame.Clean
            return (C:find("every word starts with", 1, true) ~= nil or C:find("every word begins with", 1, true) ~= nil or C:find("all words start with", 1, true) ~= nil) or C:match("^what comes after %a$") ~= nil or C:match("^what comes before %a$") ~= nil or C:match("^what letter comes after %a$") ~= nil or C:match("^what is the letter after %a$") ~= nil or C:find("empty message", 1, true) ~= nil or C:find("blank message", 1, true) ~= nil
        end, function(Frame)
            local C = Frame.Clean
            local Letter: string? = C:match("starts? with (%a)") or C:match("begins? with (%a)")
            if Letter then
                local Bank = Letters[Letter:lower()]
                if not Bank then
                    return Mind.Reply(`I don't have enough "{Letter}" words in my head yet, try another letter like k, b, s or t.`)
                end

                local Sentence: string = `{Mind.Cap(Mind.From(Bank.Adjectives))} {Mind.From(Bank.Nouns)} {Mind.From(Bank.Verbs)} {Mind.From(Bank.Adjectives)} {Mind.From(Bank.Nouns)}.`
                return Mind.Reply(Mind.Join(Sentence, Mind.Chance(0.5) and "Not Shakespeare, but every word fits." or ""))
            end

            local After: string? = C:match("^what comes after (%a)$") or C:match("^what letter comes after (%a)$") or C:match("^what is the letter after (%a)$")
            if After then
                if After:lower() == "z" then
                    return Mind.Reply("Nothing, Z is the last letter of the alphabet. In spreadsheets the column after Z is AA.")
                end

                return Mind.Reply(`After {After:upper()} comes {string.char(After:lower():byte() + 1):upper()}.`)
            end

            local Before: string? = C:match("^what comes before (%a)$")
            if Before then
                if Before:lower() == "a" then
                    return Mind.Reply("Nothing, A is the first letter.")
                end

                return Mind.Reply(`Before {Before:upper()} comes {string.char(Before:lower():byte() - 1):upper()}.`)
            end

            return Mind.Reply("(Here's your empty message, the best I can do is a blank line: .)")
        end)

        -- ---------------------------------------------------------------- risks and rules people ask about

        local Risks = {
            {Keys = "alt alts account accounts link linked", Say = "Roblox can connect accounts that share a device, an IP or payment details, so an alt is not a guarantee. If a main account matters to you, don't bet on that."},
            {Keys = "terminated termination banned ban bans private", Say = "A private match is quieter because fewer people can report you, but the game's checks and Roblox's own systems still see your account, so a ban is still possible."},
            {Keys = "youtubers youtuber youtube videos creators streamers", Say = "Showing scripts on video can cost a channel through reports and platform rules, and it can hurt the account on screen. Creators who do it usually use accounts they can afford to lose."},
            {Keys = "screen see watching spying devs developers record", Say = "CatVape doesn't send your screen anywhere. The game's server can see what your character does (moves, hits, placements), but not your actual screen."},
            {Keys = "undetectable undetected detect detectable legit safe", Say = "No script is undetectable. Legit mods are quieter because they look like normal play, but that lowers the risk, it doesn't remove it."},
