        end

        Act("Risk", function(Frame): boolean
            if Frame.Set.how and (Frame.Set.turn or Frame.Set.bind or Frame.Set.use) then
                return false
            end

            if Frame.Evidence < 1 and not (Frame.Set.ban or Frame.Set.banned or Frame.Set.script or Frame.Set.scripts or Frame.Set.cheat or Frame.Set.cheating or Frame.Set.hack or Frame.Set.hacks or Frame.Set.roblox or Frame.Set.catvape or Frame.Set.executor) then
                return false
            end

            local Hits: number = 0
            for _, Risk in Risks do
                local Local: number = 0
                for Word: string in Risk.Keys:gmatch("%S+") do
                    Local += Frame.Set[Word] and 1 or 0
                end

                Hits = math.max(Hits, Local)
            end

            return Hits >= 2 or (Hits >= 1 and (Frame.Set.undetectable or Frame.Set.detectable or Frame.Set.ban or Frame.Set.banned or Frame.Set.terminated or Frame.Set.youtubers) and Frame.Question)
        end, function(Frame)
