                end
            end

            return Mind.Reply(Mind.Join(Mind.Any("Honest answer:", "Straight up:", "Short version:"), Best.Say), {"What are the safest modules?"})
        end, "mid")

        -- ---------------------------------------------------------------- claims that cannot be true

