            end

            local Presuppose: boolean = Frame.Clean:match("^how come") ~= nil or Frame.Clean:match("^why did") ~= nil or Frame.Clean:match("^why does") ~= nil or Frame.Clean:match("^since ") ~= nil or Frame.Clean:match("^when did") ~= nil or Frame.Clean:match("^ok so after") ~= nil or Frame.Clean:match("^which module unlocks") ~= nil or Frame.Clean:find("lets me", 1, true) ~= nil or Frame.Clean:find("right$") ~= nil or Frame.Clean:match("^how do i turn off the part") ~= nil
            return Odd and Presuppose
        end, function(Frame)
