        -- ---------------------------------------------------------------- more situations for the advice shelf

        for _, Rule in {
            {Keys = "obsidian tnt fireball break through defence defense wall tough", Lead = "Obsidian is slow to mine and fireballs and TNT barely scratch it, so the trick is to go around: bridge to the side that has no obsidian, or find the one gap the owner left open.", Then = {"Obsidian shrugs off normal tools, but pickaxes and TNT still make a hole eventually, so be patient and cover yourself while you dig.", "Starve the defender instead: take the generators and the fight, and the obsidian stops mattering."}},
            {Keys = "pearl pearls pearled read predict catches final killed same guy", Lead = "Someone who keeps pearling onto you is predictable: they throw from the same distance each time, so stand where they land and hit them as they arrive.", Then = {"Keep a couple of blocks around you, a pearl needs room to land.", "Hit first: a pearl user arrives mid-air and a swing in that moment decides the fight."}},
            {Keys = "tiny two open sides sides opener opening map", Lead = "With only two open sides, cover those two first with strong blocks, then spend the rest of your early iron on armour and a sword.", Then = {"Having fewer open sides means you can defend with fewer blocks, so you're free to go and fight early.", "Put one block of a different type on each open side so tools slow down."}},
            {Keys = "golem healer heal healing approach counter", Lead = "Against a healer, burst them down before they can heal: a fireball or a bow shot on the healer first, then the rest.", Then = {"Golems are slow, so pull them away from the fight and handle the player.", "Kill the support first, the front-liner usually can't out-sustain you without them."}},
            {Keys = "1v1 hp no blocks last two teams final alive", Lead = "With 1 hp each and no blocks, the first hit decides it, so don't swing first into a clean trade, use the edge and the void: knockback is your weapon.", Then = {"Stay mobile, change your angle and approach so they can't predict your hit.", "If you can, pick up a few blocks and a pearl from the island before engaging."}},
            {Keys = "rush mid dies defend team teammates convince persuade", Lead = "You can't force teammates to defend, but you can show it: ping the bed, say why in one line, and then do it yourself.", Then = {"Lead by example: a bed that stays standing proves the point faster than an argument.", "If they keep rushing, ask them to leave at least one person home."}},
            {Keys = "nervous nerves scared pressure better than me 1v1", Lead = "Being nervous before a fight with someone better is normal. Decide in advance what you'll do in the first ten seconds, like \"block the sides, then peek\", and it takes the edge off.", Then = {"Focus on one thing, like not dying to the first hit, instead of beating them.", "Breathe slowly, tense and relax your hands, and treat it as a practice round."}},
            {Keys = "night bridge enemy bridges iron one 1 iron early help", Lead = "With 1 iron and an enemy bridge coming, don't panic-buy, cut the end of their bridge so they fall, and put a block or two on your bed side.", Then = {"Pick up iron from the generator, you will have more in thirty seconds.", "Wait at your end and hit them as they land."}}
        } do
            table.insert(Mind.AdviceRules, Rule)
        end

        for _, Entry in {
            {Keys = "grayed greyed gray grey unavailable disabled modules", Say = "Grayed-out modules aren't available in the place you're in, or they need a feature your executor doesn't have. Hover one to see why, and remember a few only run during a match, not in the lobby."},
            {Keys = "keybinds binds reset number row switched changed", Say = "If your binds changed, loading a profile can overwrite them with the ones saved in it. Rebind each module from its menu, then save your own profile so they stay."},
            {Keys = "hud text overlaps chat overlay overlapping move", Say = "The HUD text is an overlay, so you can move and resize it from the overlay's own settings. Pick a corner away from the Roblox chat."},
            {Keys = "tab inventory closes closes inventory", Say = "Tab opens Roblox's player list, so if your GUI key is Tab it conflicts. Rebind the GUI key with Rebind GUI in the settings."},
            {Keys = "teammate teammates team aim locks friends own", Say = "If AimAssist locks onto teammates, check its Target settings: turn on the team check so friends and teammates are skipped, and add them to your friends list."},
            {Keys = "walked void own started autowin broke", Say = "AutoWin works from the map around it, so a gap or a new map layout can send it the wrong way. Turn it off, note the map, and try a different one; if it keeps falling, tell the team."}
        } do
            table.insert(Mind.Troubles, Entry)
        end

        -- ---------------------------------------------------------------- weighing items by what the moment needs

        local ItemRoles = {
            offense = "sword tnt fireball bow arrow damage kill killaura rush attack offense sniper hit",
            defense = "armor armour obsidian wool blocks bricks defend defence defense bed golem healer heal healing trap protect support wall",
            mobility = "pearl pearls telepearl speed potion jump bridge fly scaffold chase run escape boots",
            economy = "generator upgrade upgrades diamond diamonds emerald emeralds iron gold save saving"
        }

        local Needs = {
            {Keys = "bed gone no bed bedless final", Needs = "offense mobility"},
            {Keys = "chase chasing escape run away flee", Needs = "mobility"},
            {Keys = "rushers rush defend defence open sides cover", Needs = "defense"},
            {Keys = "late minute end last", Needs = "offense"},
            {Keys = "early start first opening", Needs = "economy defense"}
        }

        function Mind.RoleDecide(Frame, Options: {string}): string?
            if #Options < 2 then
                return nil
            end

            local Need = {}
            for _, Entry in Needs do
                for Word: string in Entry.Keys:gmatch("%S+") do
                    if Frame.Set[Word] then
                        for Role: string in Entry.Needs:gmatch("%S+") do
                            Need[Role] = (Need[Role] or 0) + 1
                        end
                    end
                end
            end

            local Scores = {}
            local Best, BestScore = 1, -1
            for i: number, Option: string in Options do
                local Score: number = 0
                for Role: string, Words: string in ItemRoles do
                    local Hit: boolean = false
                    for Word: string in Words:gmatch("%S+") do
                        Hit = Hit or Option:find(Word, 1, true) ~= nil
                    end

                    if Hit then
                        Score += (Need[Role] or 0) * 2 + 1
                    end
                end

                Scores[i] = Score
                if Score > BestScore then
                    Best, BestScore = i, Score
                end
            end

            if BestScore <= 0 then
                return nil
            end

            local Other: string = Options[Best == 1 and 2 or 1]
            local Reason: string = next(Need) and "that matches what the moment calls for" or "it fits the situation better"
            return Mind.Join(Mind.Any(`I'd go with {Options[Best]}.`, `My pick is {Options[Best]}.`), `Looking at what you described, {Reason}, while {Other} {Mind.Any("is better kept for later", "helps less right now")}.`, Mind.Any("If the situation changes, so does my answer.", "That's the order I'd do it in."))
        end
        end

        -- ---------------------------------------------------------------- reading a BedWars situation and picking a posture: attack, defend, spend, move

        do
        local Postures = {
            Aggressive = Brain.Set("rush push attack go fight hunt kill offense offence pressure chase engage raid break take storm"),
            Defensive = Brain.Set("defend turtle guard hide protect cover wall stay home camp safe heal fortify obsidian protection"),
            Economic = Brain.Set("save buy upgrade invest bank farm hold collect sharpness generator"),
            Mobile = Brain.Set("pearl run flee escape reposition retreat telepearl speed")
        }

        local Reasons = {
            Ahead = "you're ahead, and protecting a lead is worth more than a risky move",
            Behind = "you're behind, so playing it safe just means losing slowly",
            BedAlive = "your bed is still standing, which gives you a safety net",
            BedGone = "your bed is gone, so there's nothing at home left to lose",
            LowHealth = "you're on low health, one hit can end it",
            FullHealth = "you're at full health, which lets you take a hit or two",
            Alone = "you're short on teammates, so every fight is riskier",
            Ranged = "they have ranged tools, which punish standing still",
            Weak = "they're short on blocks or armour right now, which is a window",
            Late = "it's late in the game, so the clock is on your mind",
            Early = "it's early, so the economy matters more than a fight",
            Rich = "you have resources to spend, and unspent resources don't win fights"
        }

        local function Cues(Frame)
            local C = Frame.Clean
            local Found = {}
            local function Has(...): boolean
                for _, Phrase: string in {...} do
                    if (` {C} `):find(` {Phrase} `, 1, true) then
                        return true
                    end
                end

                return false
            end

            if Has("up", "ahead", "winning", "lead", "more beds") and Has("beds", "bed", "kills", "to") and not Has("up against") then
                Found.Ahead = true
            end

            if Has("down", "behind", "losing", "outnumbered", "outmatched") or C:find("solo vs", 1, true) or C:find("1v3", 1, true) or C:find("1v2", 1, true) or C:find("1v4", 1, true) then
                Found.Behind = true
            end

            if Has("bed still alive", "bed is alive", "bed alive", "my bed is up", "bed intact", "bed still up", "bed still standing") then
                Found.BedAlive = true
            end

            if Has("no bed", "bed gone", "bed is gone", "bedless", "bed already gone", "bed broken") or C:find("bed is already gone", 1, true) then
                Found.BedGone = true
            end

            if Has("1 hp", "1hp", "1 heart", "low hp", "half hp", "almost dead", "2 hearts", "one heart") then
                Found.LowHealth = true
            end

            if Has("full hp", "full health", "full hearts") then
                Found.FullHealth = true
            end

            if Has("teammate died", "mate died", "alone", "only me", "solo", "last alive", "just me") or C:find("1 mate", 1, true) or C:find("2 teammates alive", 1, true) then
                Found.Alone = true
            end

            if Has("bow", "fireball", "fireballs", "tnt", "arrows", "sniper", "ranged") then
                Found.Ranged = true
            end

            if Has("no blocks", "no armor", "no armour", "8 blocks left", "low on blocks", "out of blocks") or C:find("blocks left", 1, true) then
                Found.Weak = true
            end

            if Has("sudden death", "late", "end game", "endgame", "minute 10", "minute 12", "minute 15") or C:find("before sudden death", 1, true) then
                Found.Late = true
            end

            if Has("early", "first minute", "2 mins in", "2 minutes in", "minute 1", "minute 2", "opening") or C:find("mins in", 1, true) then
                Found.Early = true
            end

            if C:find("%d+ emeralds") or C:find("%d+ diamonds") or C:find("%d+ iron") or C:find("%d+ gold") then
                Found.Rich = true
            end

            return Found
        end

        local function PostureOf(Text: string): string?
            local Best, BestHits = nil, 0
            for Name: string, Words in Postures do
                local Hits: number = 0
                for Word: string in Text:gmatch("%a+") do
                    Hits += Words[Word] and 1 or 0
                end

                if Hits > BestHits then
                    Best, BestHits = Name, Hits
                end
            end

            return Best
        end

        local Weights = {
            Aggressive = {Behind = 2, BedGone = 2, FullHealth = 1, Weak = 2, Late = 1, LowHealth = -2, Ahead = -1},
            Defensive = {Ahead = 2, BedAlive = 1, LowHealth = 2, Alone = 1, Ranged = 1, Early = 1, BedGone = -2},
            Economic = {Early = 2, Rich = 1, Late = -1},
            Mobile = {LowHealth = 2, Ranged = 2, Alone = 1, BedGone = 1, Behind = 1}
        }

        function Mind.PostureDecide(Frame, Options: {string}): string?
            if #Options < 2 then
                return nil
            end

            local Found = Cues(Frame)
            if next(Found) == nil then
                return nil
            end

            local Scores, Used = {}, {}
            local Best, BestScore = nil, -100
            for i: number, Option: string in Options do
                local Posture: string? = PostureOf(Option)
                if Posture then
                    local Score: number = 0
                    local Why = {}
                    for Cue: string, Weight: number in Weights[Posture] do
                        if Found[Cue] then
                            Score += Weight
                            if Weight > 0 then
                                table.insert(Why, Cue)
                            end
                        end
                    end

                    Scores[i] = Score
                    Used[i] = Why
                    if Score > BestScore then
                        Best, BestScore = i, Score
                    end
                end
            end

            if not Best or BestScore <= 0 then
                return nil
            end

            local Reasons1: string = Reasons[Used[Best][1]]
            local Reasons2: string? = Used[Best][2] and Reasons[Used[Best][2]] or nil
            local Pick: string = Options[Best]
            local Other: string = Options[Best == 1 and 2 or 1]
            return Mind.Join(
                Mind.Any(`My call: {Pick}.`, `I'd go with {Pick}.`, `{Mind.Cap(Pick)}.`),
                Reasons2 and `{Mind.Cap(Reasons1)}, and {Reasons2}.` or `{Mind.Cap(Reasons1)}.`,
                Mind.Any(`{Mind.Cap(Other)} only wins if things change, like a teammate arriving or them running out of blocks.`, `If the picture changes, I'd rethink, but with what you've told me, {Other} is second.`, `That's how I read it from here.`)
            )
        end

        local OldRoleDecide = Mind.RoleDecide
        function Mind.RoleDecide(Frame, Options: {string}): string?
            return Mind.PostureDecide(Frame, Options) or (OldRoleDecide and OldRoleDecide(Frame, Options))
        end
        end

        -- ---------------------------------------------------------------- checking the old pipeline's answer, and answering for it when it was off

        do
        local Checked = Brain.Set("Fact Lookup Answer Offtopic")
        local Hijackable = Brain.Set("Status PlaceInfo Locate Count Settings ListCategory")
        local WeakIntents = Brain.Set("ListWindows ProfileList Bye Apology News Confirm Guide Count Locate Open Close Help Code Personal Identity Feeling Compliment Insult Wellbeing Greet Thanks Ack Joke")
        local Causal = {"because", "since", "reason", "that's why", "which is why", "this is why", "due to", "caused"}
        local DeadEnds = {"could not read that", "do not have a character", "are not on a team", "you are not in a match", "i do not know what", "all the tabs are already", "these look like what you are after"}

        local Actionable = Brain.Set("Close Open TurnOn TurnOff Toggle Bind Unbind SetValue Hide Favorite ProfileCreate ProfileDelete ProfileSwitch ListAdd ListRemove Undo")
        local Fillers = Brain.Set("please pls plz can could would will you u yo hey just kindly lemme let me i want wanna need gotta ill id like to go ahead and also then now ok okay so")
        local Verbs = Brain.Set("turn open close enable disable bind unbind rebind set toggle add remove show hide make create switch favorite star put change undo load delete activate deactivate start stop equip use list give tell find check select pick apply run bring mute unmute reset clear")
        local Inquiring = Brain.Set("tell show check give read what whats which how many much when where who why is are do does can")

        -- Does the message read like an order to do something?
        function Mind.Commandy(Frame): boolean
            local Words = Frame.Words
            local i: number = 1
            while Words[i] and Fillers[Words[i]] do
                i += 1
            end

            local Verb: string = Words[i] or ""
            if Verbs[Verb] then
                return true
            end

            local Last: string = Words[#Words] or ""
            return (Last == "on" or Last == "off") and #Words <= 4
        end

        -- One typo apart: a changed, missing or extra letter, or two neighbouring letters swapped.
        function Mind.Near(A: string, B: string): boolean
            local La, Lb = #A, #B
            if math.abs(La - Lb) > 1 or La < 5 or Lb < 5 then
                return false
            end

            if La == Lb then
                local First: number?, Second: number? = nil, nil
                local Count: number = 0
                for i: number = 1, La do
                    if A:byte(i) ~= B:byte(i) then
                        Count += 1
                        if Count == 1 then
                            First = i
                        elseif Count == 2 then
                            Second = i
                        else
                            return false
                        end
                    end
                end

                if Count <= 1 then
                    return true
                end

                return Second == (First :: number) + 1 and A:byte(First :: number) == B:byte(Second :: number) and A:byte(Second :: number) == B:byte(First :: number)
            end

            local Long, Short = La > Lb and A or B, La > Lb and B or A
            for i: number = 1, #Long do
                if Long:sub(1, i - 1) .. Long:sub(i + 1) == Short then
                    return true
                end
            end

            return false
        end

        -- Does the answer talk about what was asked? Answers that share no meaning-bearing word with the question are strays.
        function Mind.Relevant(Frame, Result, Decision): boolean
            local Content = Frame.Content
            local Kind: string? = Decision and Decision.Kind
            local Best = Decision and Decision.Best
            if #Content < 2 or not Kind then
                return true
            end

            if Kind == "Execute" and Best then
                if Actionable[Best.Intent] and not Mind.Commandy(Frame) and Frame.Count > 3 then
                    return false
                elseif Mind.Contextual[Best.Intent] then
                    return true
                elseif Hijackable[Best.Intent] and Frame.Strong == 0 then
                    return false
                end
            end

            local Text: string = Plain(Result.Text or ""):lower()
            if Checked[Kind] or Kind == "Execute" then
                for _, Dead: string in DeadEnds do
                    if Text:find(Dead, 1, true) then
                        return false
                    end
                end
            end

            if Kind == "Lookup" then
                local Asks: boolean = Frame.Question
                for _, Word: string in Frame.Words do
                    Asks = Asks or Inquiring[Word] == true
                end

                if not Asks then
                    return false
                end
            elseif (Kind == "Clarify" or Kind == "Ask") and Frame.Strong == 0 then
                return false
            end

            if not (Checked[Kind] or (Kind == "Execute" and Best and Brain.Knowledge[Best.Intent] and not Brain.Social[Best.Intent])) then
                return true
            end

            if Decision.Fact then
                Text ..= " " .. (Decision.Fact.Keywords or ""):lower()
            end

            if Decision.Lookup then
                Text ..= " " .. Decision.Lookup.Id:lower()
            end

            local Seen, Stems = {}, {}
            for Word: string in Text:gmatch("[%a']+") do
                local Stem: string = Mind.Stemmed(Word)
                if not Seen[Stem] then
                    Seen[Stem] = true
                    table.insert(Stems, Stem)
                end
            end

            local Hits: number = 0
            for _, Word: string in Content do
                local Found: boolean = Seen[Word] == true
                if not Found and #Word >= 5 then
                    for _, Stem: string in Stems do
                        if Mind.Near(Word, Stem) then
                            Found = true
                            break
                        end
                    end
                end

                if Found then
                    Hits += 1
                end
            end

            if Frame.Evidence == 0 and #Frame.Mentions == 0 and (Kind == "Fact" or Kind == "Answer" or Kind == "Lookup") and #Content >= 3 then
                return Hits >= 2 and Hits / #Content >= 0.5
            end

            -- a fact picked under an intent that has nothing to do with facts is a coincidence unless the words really line up
            if Kind == "Fact" and Best and WeakIntents[Best.Intent] and Frame.Strong == 0 then
                return Hits >= 2 and Hits / #Content >= 0.5
            end

            -- "why" wants a reason, and a fact with no reason in it does not answer that
            if Kind == "Fact" and Frame.Strong < 2 and Hits < 3 and Decision.Fact and Decision.Fact.Game == "BedWars" and (Frame.Words[1] == "why" or Frame.Clean:find(" why ", 1, true) ~= nil) then
                local Reasoned: boolean = false
                for _, Marker: string in Causal do
                    Reasoned = Reasoned or Text:find(Marker, 1, true) ~= nil
                end

                if not Reasoned then
                    return false
                end
            end

            return Hits >= 1 and (Hits / #Content >= 0.34 or #Content <= 3)
        end

        local HowTo = Brain.Set("how")
        local Offers = {
            "Ask me about a module or a setting and I'll know where I stand.",
            "I'm much better on CatVape and the game itself, so try me there.",
            "If you tell me what you're trying to do in the game, I'll look for a module that does it."
        }

        -- A reply for a message nothing else wanted: say plainly what is and is not known, point at the closest thing in the menu.
        function Mind.Fallback(Frame, Decision)
            Brain.Ready()
            local C = Frame.Clean
            local Topic: string = table.concat(Frame.Content, " ", 1, math.min(#Frame.Content, 3))
            local Related
            if #Frame.Content >= 1 then
                local Ok, Results = pcall(Brain.Rank, Frame.Clean)
                if Ok and Results and Results[1] and Results[1].Covers >= 0.6 and Results[1].Score > 0 and not Results[1].Entry.Legit then
                    Related = Results[1].Entry
                end
            end

            local Restate: string? = Mind.Chance(0.55) and Mind.Restate(Frame) or nil
            local Kind: string = C:match("^how ") and "how" or C:match("^why ") and "why" or C:match("^who ") and "who" or C:match("^where ") and "where" or C:match("^when ") and "when" or C:match("^what ") and "what" or "other"
            local Domain: boolean = Frame.Evidence >= 1 or Related ~= nil

            local Subject: string = Frame.Topic
            local Honest: string
            if Domain then
                Honest = Mind.Any(
                    "I don't have a reliable answer for that one.",
                    "I can't say that for sure, and I'd rather not guess.",
                    "That's a gap in what I know.",
                    "I'm not sure I can answer that properly."
                )
            elseif Kind == "how" then
                Honest = Mind.Any("I can't walk you through that one, it's outside CatVape and the game.", "I'm not the right bot for a how-to like that, I only know CatVape and the game you're in.")
            elseif Kind == "why" then
                Honest = Mind.Any("I'd only be making up a reason for that one.", "I don't know the real reason for that, and I'd rather not invent one.")
            elseif Kind == "who" or Kind == "when" or Kind == "where" then
                Honest = Mind.Any("I can't look that up, I run offline.", "That's a fact I don't carry, and I can't search for it.")
            else
                Honest = Mind.Any("That's beyond what I know.", "I only carry CatVape and game knowledge, so that one's a miss.", "That's outside what I was built for.")
            end

            local Advice: string = ""
            if Domain and Frame.Evidence >= 1 and (C:find(" do i", 1, true) or C:find("should i", 1, true) or C:find("how to", 1, true) or C:find("tips", 1, true) or C:find("help", 1, true) or C:find("plan", 1, true)) then
                Advice = Mind.Any("A general rule in BedWars: protect your own bed first, then spend what you have on whatever stops the current threat.", "As a rule of thumb: don't fight in the open, pull enemies toward a choke point near your bed.", "The one habit that wins the most games is spending resources instead of hoarding them.")
            end

            local Pointer: string = ""
            local Chips
            if Related then
                Pointer = Mind.Any(`The closest thing I know is {Mind.Name(Related)}, which {Mind.Describe(Related)}.`, `If it helps, {Mind.Name(Related)} {Mind.Describe(Related)}, that might be what you're after.`)
                Chips = {`What does {Related.Name} do?`}
            end

            local Reply = Mind.Reply(Mind.Join(Restate or "", Honest, Advice, Pointer, (Pointer == "" and Advice == "") and Mind.From(Offers) or ""), Chips or {"What can you do?"})
            Reply.Act = "Fallback"
            return Reply
        end
        end

        -- ---------------------------------------------------------------- social replies written from the situation instead of picked from a list

        do
        local function EnabledCount(): number
            local Count: number = 0
            for _, Module in vape.Modules do
                Count += Module.Enabled and 1 or 0
            end

            for _, Module in vape.Legit.Modules do
                Count += Module.Enabled and 1 or 0
            end

            return Count
        end

        local function Part(): string
            local Hour: number = tonumber(os.date("%H")) or 12
            return Hour < 5 and "night" or Hour < 12 and "morning" or Hour < 18 and "afternoon" or "evening"
        end

        local GameOffers = {
            BedWars = {"Which bed are we going after?", "Want me to check your setup before the next game?", "Need a module explained before you queue?", "Ready to break some beds?"},
            IllegalSoccer = {"Want to tune your shots?", "Ready to score a few?"},
            TowerOfHell = {"Ready to climb?", "Want help with a tricky section?"}
        }

        local GenericOffers = {"What should we work on?", "What are you trying to do today?", "Need help with a module or a setting?", "Anything you want set up?"}

        local Greetings = {hi = "Hi", hello = "Hello", hey = "Hey", yo = "Yo", sup = "Sup", ayo = "Ayo", howdy = "Howdy", hiya = "Hiya", heya = "Heya", greetings = "Greetings", hola = "Hola"}

        local function Opener(Words: {[string]: boolean}, Clean: string): string
            if Clean:find("good morning") or Words.morning then
                return Mind.Any("Good morning", "Morning")
            elseif Clean:find("good evening") then
                return "Good evening"
            elseif Clean:find("good afternoon") then
                return "Good afternoon"
            elseif Clean:find("good night") or Clean:find("goodnight") then
                return "Good night"
            end

            for Key: string, Show: string in Greetings do
                if Words[Key] then
                    return Show
                end
            end

            return Mind.Any("Hey", "Hi", "Hello")
        end

        local function Offer(): string
            local Game: string? = CurrentGame()
            local Pool = Game and GameOffers[Game] or GenericOffers
            return Mind.From(Pool)
        end

        local Social = {}

        function Social.Greet(Frame)
            local Count: number = EnabledCount()
            local Last = Mind.History[#Mind.History]
            local Greeting: string = Opener(Frame.Set, Frame.Clean)
            local Mark: string = Mind.Chance(0.75) and "!" or "."
            local Body: string = ""
            local Memory = Mind.Memory
            local Name: string? = Memory.Address()
            local Callback: string? = Memory.Callback()
            if Name and (not Memory.Welcomed or Mind.Chance(0.5)) then
                Greeting = `{Greeting}, {Name}`
            end

            Memory.Welcomed = true
            if Callback then
                Body = Callback
            elseif Last and Mind.Chance(0.5) then
                Body = Mind.Any(`We were just on "{Last.Q:sub(1, 40)}", want to carry on?`, "Back again, nice.", "Welcome back.")
            elseif Count >= 5 and Mind.Chance(0.5) then
                Body = `I can see {Count} modules running right now.`
            elseif Part() == "night" and Mind.Chance(0.5) then
                Body = Mind.Any("You're up late.", "Late session, huh.")
            end

            return Mind.Reply(Mind.Join(`{Greeting}{Mark}`, Body, Offer()))
        end

        function Social.Wellbeing(Frame)
            local Count: number = EnabledCount()
            local Doing: boolean = (Frame.Set.wyd or Frame.Set.whats or Frame.Set.what or Frame.Set.up) and not Frame.Set.how
            local Hour: string = Part()
            local Activity: string
            local Feeling: string
            if Count >= 8 then
                Activity = `keeping an eye on the {Count} modules you have running`
                Feeling = Mind.Any("a little busy", "busy but fine")
            elseif Count == 0 then
                Activity = Mind.Any("waiting in your menu for questions", "sitting quietly in the chat window")
                Feeling = Mind.Any("relaxed", "calm")
            else
                Activity = `watching {Count} module{Count == 1 and "" or "s"} that {Count == 1 and "is" or "are"} on`
                Feeling = Mind.Any("good", "pretty good", "doing well")
            end

            local Tail: string = Hour == "night" and "It's late for you, no?" or Mind.Any("How about you?", "What about you?", "How's your day going?", "How are you doing?")
            if Doing then
                return Mind.Reply(Mind.Join(Mind.Any(`Not much, just {Activity}.`, `Mostly {Activity}.`), Tail))
            end

            return Mind.Reply(Mind.Join(Mind.Any(`I'm {Feeling}, thanks.`, `{Mind.Cap(Feeling)} here, thanks for asking.`, `All {Feeling} on my side.`), Mind.Chance(0.5) and `I've been {Activity}.` or "", Tail))
        end

        function Social.Thanks(Frame)
            local Last = Mind.History[#Mind.History]
            local Topic: string? = Last and Last.Names and Last.Names[1]
            return Mind.Reply(Mind.Join(
                Mind.Any("You're welcome!", "Anytime.", "Happy to help.", "No problem.", "Glad that worked."),
                Topic and Mind.Chance(0.5) and `Shout if {Topic} acts up.` or "",
                Mind.Chance(0.5) and Mind.Any("Ask if anything else comes up.", "I'm here whenever.", "What's next?") or ""
            ))
        end

        function Social.Ack(Frame)
            if Frame.Set.haha or Frame.Set.lol or Frame.Set.lmao then
                return Mind.Reply(Mind.Any("Haha.", "Glad that landed.", "Ha, okay.", "Right? Anything else?"))
            end

            return Mind.Reply(Mind.Join(Mind.Any("Cool.", "Alright.", "Got it.", "Sure thing.", "Okay."), Mind.Chance(0.35) and Mind.Any("Ask if you need anything.", "I'm around.", "What's next?") or ""))
        end

        function Social.Bye(Frame)
            local Part2: string = Part()
            local Wish: string
            if Frame.Set.night or Frame.Set.goodnight or Frame.Set.gn or Frame.Set.sleep or Frame.Set.bed or Part2 == "night" then
                Wish = Mind.Any("Sleep well.", "Get some rest, the beds will still be there.", "Night!")
            elseif Frame.Set.brb or Frame.Set.back then
                return Mind.Reply(Mind.Any("Sure, I'll be right here.", "Take your time.", "I'm not going anywhere, I live in the menu."))
            else
                Wish = Mind.Any("Good luck in your games.", "Have fun out there.", "Go win one.", "Don't forget to guard the bed.")
            end

            return Mind.Reply(Mind.Join(Mind.Any("Bye!", "Later!", "Catch you later!", "Take care."), Wish))
        end

        function Social.Compliment(Frame)
            local Echo: string = Frame.Count <= 8 and Mind.Turn(Frame.Clean) or ""
            return Mind.Reply(Mind.Join(
                Mind.Any("Thank you, that's kind.", "Aw, thanks!", "Appreciate that.", "That made my day, and my day is mostly toggles."),
                Mind.Chance(0.4) and Mind.Any("I do my best with what's in the menu.", "I just know where everything is.", "Credit goes to the people who built the modules.") or "",
                Mind.Chance(0.5) and Mind.Any("Anything I can help you with?", "What are we doing next?") or ""
            ))
        end

        function Social.Insult(Frame)
            local Last = Mind.History[#Mind.History]
            if Frame.Set.shut or Frame.Set.stfu or Frame.Set.quiet then
                return Mind.Reply(Mind.Any("Okay, I'll go quiet. I'm here if you need me.", "Fair enough, I'll stay out of the way."))
            end

            local Context: string = ""
            if Last and Last.Q and #Last.Q > 3 and Last.Act ~= "Social" then
                Context = Mind.Any(`Was it my answer to "{Last.Q:sub(1, 50)}" that missed?`, `I'm guessing my answer to "{Last.Q:sub(1, 50)}" wasn't it.`)
            end

            return Mind.Reply(Mind.Join(
                Mind.Any("Fair, I get things wrong sometimes.", "Ouch, but okay.", "That stings a little, and it's probably deserved.", "I hear you."),
                Context,
                Mind.Any("Tell me what you were after and I'll try again.", "Say it in other words and I'll take another shot.", "Short questions like \"what does Killaura do\" work best for me.")
            ))
        end

        function Social.Apology(Frame)
            return Mind.Reply(Mind.Join(Mind.Any("No worries at all.", "All good.", "Don't sweat it.", "No harm done."), Mind.Chance(0.5) and Mind.Any("What can I help with?", "Anything you need?") or ""))
        end

        local Reset = Brain.ResetContext
        Brain.ResetContext = function(...)
            table.clear(Mind.History)
            Mind.Persona = nil
            Mind.Playing = nil
            Mind.Dialog.Reset()
            Mind.Learn.Trouble, Mind.Learn.Candidate = nil, nil
            return Reset(...)
        end

        function Social.Personal(Frame)
            if #Mind.ScoreAspects(Frame) == 0 and not Frame.Clean:match("favou?rite") and not Frame.Clean:match("fav ") then
                return nil
            end

            return Mind.AboutReply(Frame)
        end

        Social.Identity = Social.Personal

        -- someone telling the bot how they feel gets the feelings reply, not "GG" because the word "win" showed up
        function Social.Feeling(Frame)
            for _, Entry in Mind.Acts do
                if Entry.Name == "Feeling" and Entry.Test(Frame) then
                    return Entry.Run(Frame)
                end
            end

            return nil
        end

        local Wrapped = {Feeling = Social.Feeling, Personal = Social.Personal, Identity = Social.Identity, Greet = Social.Greet, Wellbeing = Social.Wellbeing, Thanks = Social.Thanks, Ack = Social.Ack, Bye = Social.Bye, Compliment = Social.Compliment, Insult = Social.Insult, Apology = Social.Apology}
        local Say = Brain.Say

        function Mind.Say(Kind: string, Question: string?)
            local Maker = Wrapped[Kind]
            if not Maker then
                return nil
            end

            local Ok, Result = pcall(function()
                return Maker(Mind.Parse(Question or ""))
            end)

            if Ok and type(Result) == "table" and Result.Text and Result.Text ~= "" then
                Result.Actions = Result.Actions or ((Kind == "Greet") and Brain.Chips(nil) or nil)
                if Kind == "Greet" then
                    Result.Actions = Suggestions()
                end

                return Result
            end

            if not Ok then
                table.insert(Mind.Errors, `Say {Kind}: {Result}`)
            end

            return nil
        end

        -- Brain.Say is how every social intent answers; try the composer first and keep the written groups as a fallback.
        Brain.Say = function(Kind: string, Question: string?)
            return Mind.Say(Kind, Question) or Say(Kind, Question)
        end
        end

        -- ---------------------------------------------------------------- dispatcher

        Mind.Errors = {}

        -- Runs the acts that are sure of themselves before the old pipeline, or (Soft) after it when the pipeline had little to go on.
        function Mind.Run(Frame, Phase: string)
            for _, Entry in Mind.Acts do
                if Entry.Phase == Phase then
                    local Tested, Passed = pcall(Entry.Test, Frame)
                    if Tested and Passed then
                        local Ran, Result = pcall(Entry.Run, Frame)
                        if Ran and type(Result) == "table" and Result.Text and Result.Text ~= "" then
                            Result.Act = Entry.Name
                            return Result
                        elseif not Ran then
                            table.insert(Mind.Errors, `{Entry.Name}: {Result}`)
                        end
                    elseif not Tested then
                        table.insert(Mind.Errors, `{Entry.Name} test: {Passed}`)
                    end
                end
            end

            return nil
        end

        function Mind.Pre(Raw: string)
            Raw = Raw:sub(1, 600)
            Brain.Ready()
            local Frame = Mind.Parse(Raw)
            Mind.Frame = Frame
            if Mind.Playing then
                local Turn = Mind.Play(Frame)
                if Turn then
                    Turn.Act = "Game"
                    return Turn
                end
            end

            return Mind.Run(Frame, "pre")
        end

        -- Intents the old pipeline answers from conversation context; Mind never talks over these.
        Mind.Contextual = Brain.Set("Simpler More Interaction Tradeoff Effect Using Compare Configure BuildProfile Undo Confirm Deny Bind Unbind Toggle Set Open Highlight Describe HowTo Trouble Recommend Symptom Performance Version Guide")

        -- True when the old pipeline had a real reason to answer the way it did.
        function Mind.Confident(Decision, Frame): boolean
            if not Decision then
                return false
            end

            local Best = Decision.Best
            if Decision.Kind == "Error" or Decision.Kind == "Calculate" or Decision.Kind == "Performance" or Decision.Kind == "Symptom" or Decision.Kind == "Empty" then
                return true
            elseif Decision.Kind == "Execute" and Best then
                if Brain.Social[Best.Intent] then
                    return Best.Probability >= 0.75
                end

                return true
            elseif Decision.Kind == "Fact" then
                return true
            elseif Decision.Kind == "Lookup" then
                return Frame.Evidence >= 1
            elseif Decision.Kind == "Answer" or Decision.Kind == "Clarify" or Decision.Kind == "Ask" or Decision.Kind == "Elsewhere" then
                return Frame.Evidence >= 2
            end

            return false
        end

        function Mind.Post(Raw: string, Result, Decision)
            local Frame = Mind.Frame
            if not Frame or Frame.Raw ~= Raw:sub(1, 600) then
                return Result
            end

            Mind.Decision = Decision
            local Reading = Decision and Decision.Kind
            local Stray: boolean = not Mind.Relevant(Frame, Result, Decision)
            local Held: boolean = Reading == "Fact" or (Reading == "Execute" and Decision.Best ~= nil and Mind.Contextual[Decision.Best.Intent] == true and Decision.Best.Probability >= 0.12)
            if not Held or Stray then
                local Own = Mind.Run(Frame, "mid")
                if Own then
                    if Reading == "Execute" and Decision.Best and Decision.Best.Intent == "Compare" and Own.Act == "Choose" then
                        Own.Text = Own.Text .. "\n\n" .. Result.Text
                        Own.Actions = Result.Actions or Own.Actions
                    end

                    return Own
                end
            end

            if Stray then
                return Mind.Run(Frame, "soft") or Mind.Fallback(Frame, Decision)
            elseif Mind.Confident(Decision, Frame) then
                return Result
            end

            return Mind.Run(Frame, "soft") or Result
        end

        -- The layers around the pipeline never get to break an answer: a failure is logged in Mind.Errors and the message goes on as it was.
        local function Guard(Label: string, Run: () -> any)
            local Success, Result = pcall(Run)
            if not Success then
                table.insert(Mind.Errors, `{Label}: {Result}`)
                return nil
            end

            return Result
        end

        -- Answers a reply to a question the assistant itself asked (the memory wipe).
        function Mind.Hold(Raw: string)
            return Guard("Hold", function()
                return Mind.Memory.Hold(Raw)
            end)
        end

        -- Layers that act on the message before the pipeline: feedback and learned wordings, then remembering what the user says about
        -- themselves, then resolving "it" and "and killaura?". Returns (message to answer, text to put in front of the answer, a finished
        -- reply when nothing is left to answer).
        -- "rubber banding" and "lag backs" are one word to the rest of the assistant.
        function Mind.Glue(Raw: string): string
            Raw = Raw:gsub("([Rr]ubber)%s+([Bb]and)", "%1%2"):gsub("([Ll]ag)%s+([Bb]ack)", "%1%2")
            return (Raw:gsub("%f[%a]([Ff][Pp][Ss])%s+is%s+(%a+)%f[%A]", function(Fps: string, Mood: string): string?
                local Low = Mood:lower()
                return (Low == "trash" or Low == "terrible" or Low == "awful" or Low == "garbage" or Low == "tanking" or Low == "dropping" or Low == "poor" or Low == "bad" or Low == "dying") and `{Fps} is low` or nil
            end))
        end

        local Phrases = {
            ["vergiss meinen namen"] = "forget my name", ["vergiss bitte meinen namen"] = "forget my name", ["vergiss mein ziel"] = "forget my goal", ["und vergiss auch mein ziel"] = "forget my goal", ["was weisst du ueber mich"] = "what do you know about me",
            ["was weisst du noch ueber mich"] = "what do you know about me", ["wer bin ich"] = "who am i", ["hi wer bin ich"] = "who am i", ["olvida mi nombre"] = "forget my name", ["quien soy"] = "who am i", ["que sabes de mi"] = "what do you know about me",
            ["oublie mon nom"] = "forget my name", ["qui suis je"] = "who am i", ["esquece meu nome"] = "forget my name", ["quem sou eu"] = "who am i",
            ["cuanto riesgo"] = "how risky is it", ["mas seguro"] = "is it safer", ["es seguro"] = "is it safe", ["e seguro"] = "is it safe", ["eh seguro"] = "is it safe", ["esta seguro"] = "is it safe", ["valeu"] = "thanks", ["gracias"] = "thanks",
            ["obrigado"] = "thanks", ["obrigada"] = "thanks", ["merci"] = "thanks", ["danke"] = "thanks", ["grazie"] = "thanks", ["ok vou ligar"] = "ok i will turn it on", ["vou ligar"] = "i will turn it on", ["ok vou desligar"] = "ok i will turn it off"
        }
        local Starts = {["preciso de ajuda com "] = "i need help with ", ["necesito ayuda con "] = "i need help with ", ["ayuda con "] = "help with ", ["ajuda com "] = "help with "}

        function Mind.Speak(Raw: string): string
            local Low: string = Raw:lower():gsub("[%?!%.,]", ""):gsub("^%s+", ""):gsub("%s+$", "")
            if Phrases[Low] then
                return Phrases[Low]
            end

            for Start: string, English: string in Starts do
                if Low:sub(1, #Start) == Start then
                    return English .. Low:sub(#Start + 1)
                end
            end

            return Raw
        end

        function Mind.Prepare(Raw: string)
            Raw = Mind.Speak(Mind.Glue(Raw))
            Brain.Ready()
            local Prefix: string? = nil
            local Original: string = Raw
            local Learned = Guard("Learn", function()
                local Say, Reply, Alias = Mind.Learn.Before(Raw)
                return {Say = Say, Reply = Reply, Alias = Alias}
            end)

            if Learned then
                if Learned.Reply then
                    Mind.Frame = Mind.Parse(Raw)
                    return Raw, nil, Learned.Reply
                end

                Prefix = Learned.Say
                Raw = Learned.Alias or Raw
            end

            local Seen = Guard("Observe", function()
                local Ack, Left = Mind.Memory.Observe(Raw)
                return {Ack = Ack, Left = Left}
            end)

            if Seen and Seen.Ack then
                if not Seen.Left and Mind.Plan.Awaiting and Mind.Memory.Get("style") then
                    Mind.Plan.Awaiting = false
                    return "suggest a setup for me", Prefix, nil
                elseif not Seen.Left then
                    Mind.Frame = Mind.Parse(Raw)
                    local Reply = Mind.Reply(Seen.Ack)
                    Reply.Act = "Remember"
                    return Raw, nil, Reply
                end

                if Seen.Ack ~= "" then
                    Prefix = Prefix and Prefix .. "\n\n" .. Seen.Ack or Seen.Ack
                end

                Raw = Seen.Left
            end

            local Fixed = Guard("Resolve", function()
                return Mind.Dialog.Resolve(Raw)
            end)

            if not Fixed and Raw ~= Original then
                Mind.Dialog.Read = {From = Original, To = Raw}
            end

            local Ask = Mind.Dialog.TakeClarify()
            if Ask then
                Mind.Frame = Mind.Parse(Raw)
                local Reply = Mind.Reply(Ask.Text, Ask.Chips)
                Reply.Act = "Clarify"
                return Raw, Prefix, Reply
            end

            return Fixed or Raw, Prefix, nil
        end

        local Careful = Brain.Set("Describe TurnOn Toggle")
        local Quiet = Brain.Set("Meta Game Remember Feedback Recall Forget Safety Why Fallback Plan PlanNext PlanStyle PlanSwap Clarify")

        -- Last look at a finished answer: do not say again what the user just turned down, and warn once about a loud module for someone
        -- who told us they play quietly.
        function Mind.Verify(Raw: string, Result)
            return Guard("Verify", function()
                local Last = Mind.History[#Mind.History]
                local Text: string = Plain(Result.Text or "")
                local Rejected: string? = Mind.Learn.Rejected
                if #Text > 40 and not Quiet[Result.Act or ""] and ((Last and Last.A == Text and Last.Q == Raw) or (Rejected and Rejected == Text)) then
                    Mind.Learn.Rejected = nil
                    Result.Text = Mind.Join(Mind.Any("That would be the same answer again, so it probably isn't what you're after.", "I'd only be repeating myself there."), Mind.Any("Tell me which part is missing, or ask it another way.", "Say what you wanted to know and I'll try a different angle."))
                    Result.Actions = Brain.Chips({"Explain it simply", "Go deeper"})
                    return Result
                end

                if Result.Act ~= "Feedback" then
                    Mind.Learn.Rejected = nil
                end

                local Decision = Brain.LastDecision
                local Frame = Mind.Frame
                local Style: string? = Mind.Memory.Get("style")
                if Style and Style ~= "blatant" and Frame and Frame.Mentions[1] and Decision and Decision.Kind == "Execute" and Decision.Best and Careful[Decision.Best.Intent] and not Quiet[Result.Act or ""] then
                    local Entry = Frame.Mentions[1].Entry
                    local Level: string = Mind.Reason.Assess(Entry).Level
                    local Warned = Mind.Memory.Warned
                    if (Level == "high" or Style == "legit" and Level == "medium") and not Warned[Entry.Name] then
                        Warned[Entry.Name] = true
                        Result.Text = Mind.Lines(Result.Text, `Heads up: {Mind.Name(Entry)} is {Level == "high" and "one of the louder ones" or "somewhere in the middle for risk"}, and you told me you {Style == "legit" and "like to keep things legit" or "want to stay quiet"}. Ask "is {Entry.Name} safe" for the details.`)
                    end
                end

                return Result
            end) or Result
        end

        function Mind.Finish(Raw: string, Result)
            Guard("Finish", function()
                Mind.Learn.After(Raw, Result, Brain.LastDecision)
                Mind.Dialog.Remember(Mind.Frame, Result)
                Mind.Memory.Touch(Mind.Frame)
                Mind.Memory.Save()
            end)
        end

        function Mind.Record(Raw: string, Result)
            if Mind.Persona and Result.Text and Result.Act ~= "Persona" and Result.Act ~= "Game" and Mind.Dress then
                Result.Text = Mind.Dress(Result.Text)
            end

            local Why: string = Result.Act and `it read as a {Result.Act:lower()} message` or "it matched something I know"
            local Decision = Brain.LastDecision
            if not Result.Act and Decision then
                if Decision.Best then
                    Why = `it looked like a "{Decision.Best.Intent:lower()}" question to me`
                elseif Decision.Fact then
                    Why = "it matched a fact I have about the game"
                elseif Decision.Kind then
                    Why = `it fell under my "{Decision.Kind:lower()}" answers`
                end
            end

            local Read = Mind.Dialog.Read
            if Read then
                Why = `you said "{Read.From}", which I took to mean "{Read.To}", and {Why}`
            end

            local Names: {string} = {}
            for _, Mention in (Mind.Frame and Mind.Frame.Mentions or {}) do
                if #Names < 3 then
                    table.insert(Names, Mention.Entry.Name)
                end
            end

            table.insert(Mind.History, {Q = Raw, A = Plain(Result.Text or ""), Act = Result.Act, Why = Why, Names = Names, Basis = Result.Basis, Weak = Result.Weak, Kind = Decision and Decision.Kind, Prob = Decision and Decision.Best and Decision.Best.Probability})
            if #Mind.History > 30 then
                table.remove(Mind.History, 1)
            end

            return Result
        end

        return Mind
    end)()
    -- MIND END

    function Brain.ThinkCore(Question: string, Nested: boolean?)
        Brain.Ready()
        if Brain.ErrorOf(Question) then
            Brain.LastIntent = nil
            return Brain.Runners.Error(nil, Question)
        end

        Question = Brain.Unpreface(Brain.Unslang(Question))

        local Steps: {string} = {}
        local Split: string = (` {Question} `):gsub("%s*[;,]?%s+and then%s+(%a+)", function(Verb: string): string
            return Brain.Commands[Verb:lower()] and `\n{Verb}` or ` and then {Verb}`
        end):gsub("%s*[;,]?%s+then%s+(%a+)", function(Verb: string): string
            return Brain.Commands[Verb:lower()] and `\n{Verb}` or ` then {Verb}`
        end)
        for _, Step: string in Split:gsub("%s*;%s*", "\n"):split("\n") do
            Step = Step:match("^%s*(.-)%s*$")
            if Step ~= "" then
                table.insert(Steps, Step)
            end
        end

        if not Nested and #Steps > 1 then
            local Texts: {string} = {}
            local Last
            for _, Step: string in Steps do
                Last = Brain.Think(Step, true)
                table.insert(Texts, Last.Text)
            end

            return {Text = table.concat(Texts, "\n\n"), Actions = Last and Last.Actions}
        end

        local Decision = Brain.Understand(Question)
        Brain.LastDecision = Decision
        if Decision.Kind == "Empty" then
            return {Text = "Ask me anything about CatVape.", Actions = Suggestions()}
        elseif Decision.Kind == "Elsewhere" then
            Brain.LastIntent = nil
            return Brain.ElsewhereReply(Decision.Absent, Decision.Tokens)
        elseif Decision.Kind == "Calculate" or Decision.Kind == "Offtopic" or Decision.Kind == "Error" or Decision.Kind == "Performance" or Decision.Kind == "Symptom" then
            Brain.LastIntent = nil
            return Brain.Runners[Decision.Kind](Decision, Question)
        elseif Decision.Kind == "Ask" then
            if Decision.Intent == "Bind" and Decision.Mentioned then
                return BindReply(Decision.Mentioned)
            end

            return Brain.AskFor(Decision.Intent, Decision.Unknown)
        elseif Decision.Kind == "Answer" then
            Brain.LastIntent = Decision.Best and Decision.Best.Intent or nil
            return Answer(Question)
        elseif Decision.Kind == "Fact" then
            Brain.LastIntent = nil
            return Brain.FactReply(Decision.Fact)
        elseif Decision.Kind == "Lookup" then
            Brain.LastIntent = nil
            return Brain.RunLookup(Decision.Lookup, Decision.Tokens)
        elseif Decision.Kind == "Clarify" then
            return Brain.Clarify({Decision.Best, Decision.Runner})
        end

        local Result = Brain.Execute(Decision.Best, Question)
        if Decision.Alternative then
            local Runner = Decision.Runner
            local Text: string = Brain.Canonical(Runner)
            Result.Actions = Result.Actions or {}
            table.insert(Result.Actions, {
                Text = `Or: {Text}`,
                Callback = function()
                    Brain.Learn(Runner)
                    AddMessage(Text, true)
                    Reply(Brain.Execute(Runner))
                end
            })
        end

        return Result
    end

    -- MIND WRAP BEGIN
    function Brain.Think(Question: string, Nested: boolean?)
        if Nested then
            return Brain.ThinkCore(Question, true)
        end

        local Mind = Brain.Mind
        Brain.LastDecision = nil
        local Sent: string = Question
        local Prefix: string?
        local Result = Mind.Hold(Sent)
        if not Result then
            Question, Prefix, Result = Mind.Prepare(Sent)
        end

        if not Result then
            Result = Mind.Pre(Question)
            if not Result then
                Result = Brain.ThinkCore(Question)
                Result = Mind.Post(Question, Result, Brain.LastDecision) or Result
            end
        end

        if Prefix then
            Result.Text = `{Prefix}\n\n{Result.Text}`
        end

        Result = Mind.Verify(Sent, Result)
        Mind.Finish(Sent, Result)
        return Mind.Record(Sent, Result)
    end
    -- MIND WRAP END

    function Send(Question: string)
        if vape.ThreadFix then
            setthreadidentity(8)
        end

        Question = Question:sub(1, 600):match("^%s*(.-)%s*$")
        if Question == "" then return end

        AddMessage(Question, true)
        local Thinking, ThinkingLabel = AddMessage("Thinking.", false, nil, true)
        local Animating: boolean = true
        task.spawn(function()
            if vape.ThreadFix then
                setthreadidentity(8)
            end

            for Step: number = 1, 40 do
                task.wait(0.25)
                if not Animating or not Thinking.Parent then
                    break
                end

                ThinkingLabel.Text = `Thinking{string.rep(".", Step % 3 + 1)}`
            end
        end)
        task.wait(0.6)

        local Started: number = os.clock()
        local Success, Result = pcall(Brain.Think, Question)
        local Took: number = os.clock() - Started
        Animating = false
        if not Success then
            warn(`[catvape] Assistant errored answering "{Question}" : {Result}`)
            Result = {Text = "Something went wrong answering that, check your console."}
        end

        RemoveMessage(Thinking)
        Reply(Result, Took < 1 and `Thought for {math.max(1, math.round(Took * 1000))}ms` or `Thought for {math.round(Took * 10) / 10}s`)
    end

    Assistant = {
        Collapsed = false,
        GameGreetings = {
            BedWars = {"Which bed are we breaking first?", "Ready to win some games?", "Let's get your config match ready."},
            IllegalSoccer = {"Ready to score some goals?", "Want to tune your shots?"},
            TowerOfHell = {"Ready to climb the tower?"}
        },
        Greetings = {
            "What should we work on?",
            "What can I help with?",
            "Where should we start?",
            "What's on your mind?",
            "Ready when you are.",
            "What are we setting up today?",
            "Need a hand with something?",
            "Ask me anything about CatVape.",
            "What's the plan?",
            "How can I help?"
        },
        Mode = "Landing",
        Name = "Assistant",
        Type = "Assistant"
    }

    local ScreenColumn: number = math.floor((GUI.AbsoluteSize.X / Scale.Scale / 2 - 231) / 230 + 0.5)
    if ScreenColumn < 1 then
        ScreenColumn = 1
    end
    local ScreenTop: number = math.floor(GUI.AbsoluteSize.Y / Scale.Scale * 0.78) - 425
    if ScreenTop < 60 then
        ScreenTop = 60
    end
    Window = Instance.new("TextButton")
    Window.AutoButtonColor = false
    Window.BackgroundColor3 = UIPallet.Main
